function readSidebarCollapsedPreference() {
  try {
    return window.localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === "true";
  } catch {
    return false;
  }
}

function readRailHiddenPreference() {
  try {
    return window.localStorage.getItem(RAIL_HIDDEN_KEY) === "true";
  } catch {
    return false;
  }
}

function createClientSideId(prefix = "id") {
  try {
    return `${prefix}-${window.crypto?.randomUUID?.() ?? Math.random().toString(36).slice(2, 10)}`;
  } catch {
    return `${prefix}-${Math.random().toString(36).slice(2, 10)}`;
  }
}

function normalizeAppCapabilityStatus(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return APP_CAPABILITY_STATUS_VALUES.has(normalized) ? normalized : "planned_later";
}

function createEmptyAppCapabilityItem() {
  return {
    id: createClientSideId("app-capability-item"),
    title: "",
    status: "planned_later",
  };
}

function createEmptyAppCapabilityModule({ withItem = true } = {}) {
  return {
    id: createClientSideId("app-capability-module"),
    title: "",
    description: "",
    items: withItem ? [createEmptyAppCapabilityItem()] : [],
  };
}

function cloneAppCapabilityModules(modules = []) {
  return (Array.isArray(modules) ? modules : []).map((module) => ({
    id: String(module?.id || createClientSideId("app-capability-module")),
    title: String(module?.title || "").trim(),
    description: String(module?.description || "").trim(),
    items: (Array.isArray(module?.items) ? module.items : []).map((item) => ({
      id: String(item?.id || createClientSideId("app-capability-item")),
      title: String(item?.title || "").trim(),
      status: normalizeAppCapabilityStatus(item?.status),
    })),
  }));
}

function normalizeAppCapabilities(value = []) {
  return cloneAppCapabilityModules(value)
    .map((module) => {
      const title = String(module.title || "").trim();
      const description = String(module.description || "").trim();
      const items = module.items
        .map((item) => ({
          id: String(item.id || createClientSideId("app-capability-item")),
          title: String(item.title || "").trim(),
          status: normalizeAppCapabilityStatus(item.status),
        }))
        .filter((item) => item.title);

      if (!title && !description && items.length === 0) {
        return null;
      }

      return {
        id: String(module.id || createClientSideId("app-capability-module")),
        title: title || "Modul",
        description,
        items,
      };
    })
    .filter(Boolean);
}

function getAppCapabilityStatusConfig(status = "planned_later") {
  return APP_CAPABILITY_STATUS_OPTIONS.find((option) => option.value === normalizeAppCapabilityStatus(status))
    ?? APP_CAPABILITY_STATUS_OPTIONS[2];
}

function sanitizeAppCapabilitiesForSave(modules = []) {
  return normalizeAppCapabilities(modules);
}

function normalizePeopleWorkspaceTab(tab = "") {
  return PEOPLE_WORKSPACE_TAB_DEFINITIONS[tab] ? tab : "users";
}

function getPeopleWorkspaceTabConfig(tab = state.peopleWorkspaceTab) {
  return PEOPLE_WORKSPACE_TAB_DEFINITIONS[normalizePeopleWorkspaceTab(tab)] ?? PEOPLE_WORKSPACE_TAB_DEFINITIONS.users;
}

function getPeopleWorkspaceTabLabel(tab = state.peopleWorkspaceTab) {
  return getPeopleWorkspaceTabConfig(tab).label;
}

function normalizePeopleUserSheet(sheet = "") {
  return sheet === "inactive" ? "inactive" : "active";
}

function normalizeUserManagementScope(scope = "people") {
  return scope === "control-panel" ? "control-panel" : "people";
}

function getUserManagementScopeConfig(scope = state.userManagementScope) {
  return USER_MANAGEMENT_SCOPE_DEFINITIONS[normalizeUserManagementScope(scope)]
    ?? USER_MANAGEMENT_SCOPE_DEFINITIONS.people;
}

function isControlPanelUserManagementScope(scope = state.userManagementScope) {
  return normalizeUserManagementScope(scope) === "control-panel";
}

function setUserManagementScope(scope = "people") {
  state.userManagementScope = normalizeUserManagementScope(scope);
}

function setPeopleWorkspaceTab(tab = "users") {
  const nextTab = normalizePeopleWorkspaceTab(tab);
  const previousTab = normalizePeopleWorkspaceTab(state.peopleWorkspaceTab);

  state.peopleWorkspaceTab = nextTab;

  if (previousTab !== nextTab) {
    if (previousTab === "users") {
      state.userEditorOpen = false;
      syncUserEditorModal();
    }

    if (previousTab === "annual-leave" || previousTab === "sick-leave") {
      closeAbsenceEditor();
      closeAbsenceBalanceEditor();
    }
  }
}

function normalizeAuthView(view = "login") {
  if (view === "forgot-password" || view === "password-reset") {
    return view;
  }

  return "login";
}

function getEffectiveAuthView() {
  if (state.user?.mustChangePassword) {
    return "password-reset";
  }

  return normalizeAuthView(state.authView);
}

function setInlineMessage(target, message = "", type = "error") {
  if (!(target instanceof HTMLElement)) {
    return;
  }

  target.textContent = String(message ?? "");
  target.classList.toggle("is-success", type === "success" && Boolean(message));
}

function setAuthView(view = "login") {
  state.authView = normalizeAuthView(view);
  document.body.classList.remove("is-auth-leaving");
  renderAuthState();
}

function meetsPasswordPolicy(password = "") {
  const normalized = String(password ?? "");
  const digitMatches = normalized.match(/\d/g) ?? [];

  return normalized.length >= 8
    && /[A-Z]/.test(normalized)
    && digitMatches.length >= 2;
}

function getWorkOrderFilterFieldDefinition(fieldValue = "") {
  return WORK_ORDER_FILTER_FIELD_DEFINITIONS.find((field) => field.value === fieldValue)
    ?? WORK_ORDER_FILTER_FIELD_DEFINITIONS[0];
}

function getWorkOrderFilterOperatorOptions(fieldValue = "") {
  const field = getWorkOrderFilterFieldDefinition(fieldValue);
  return field.operators.map((value) => ({
    value,
    label: WORK_ORDER_FILTER_OPERATOR_LABELS[value] || value,
  }));
}

function getDefaultWorkOrderFilterOperator(fieldValue = "") {
  return getWorkOrderFilterOperatorOptions(fieldValue)[0]?.value || "is";
}

function createWorkOrderFilterRule(fieldValue = WORK_ORDER_FILTER_FIELD_DEFINITIONS[0]?.value || "status") {
  return {
    id: createClientSideId("wo-filter-rule"),
    field: fieldValue,
    operator: getDefaultWorkOrderFilterOperator(fieldValue),
    values: [],
  };
}

function normalizeWorkOrderFilterRuleState(rule = {}) {
  const field = getWorkOrderFilterFieldDefinition(rule.field);
  const operatorOptions = getWorkOrderFilterOperatorOptions(field.value).map((entry) => entry.value);
  const values = Array.isArray(rule.values)
    ? rule.values
    : typeof rule.value === "string"
      ? [rule.value]
      : [];

  return {
    id: String(rule.id || createClientSideId("wo-filter-rule")),
    field: field.value,
    operator: operatorOptions.includes(rule.operator) ? rule.operator : getDefaultWorkOrderFilterOperator(field.value),
    values: values
      .flatMap((value) => Array.isArray(value) ? value : [value])
      .map((value) => String(value ?? "").trim())
      .filter(Boolean),
  };
}

function createWorkOrderFilterGroup() {
  return {
    id: createClientSideId("wo-filter-group"),
    join: "AND",
    match: "AND",
    rules: [createWorkOrderFilterRule()],
  };
}

function normalizeWorkOrderFilterGroupState(group = {}, index = 0) {
  const rules = Array.isArray(group.rules)
    ? group.rules.map((rule) => normalizeWorkOrderFilterRuleState(rule))
    : [createWorkOrderFilterRule()];

  return {
    id: String(group.id || createClientSideId("wo-filter-group")),
    join: index === 0
      ? "AND"
      : ["AND", "OR"].includes(String(group.join || "").toUpperCase())
        ? String(group.join).toUpperCase()
        : "AND",
    match: ["AND", "OR"].includes(String(group.match || "").toUpperCase())
      ? String(group.match).toUpperCase()
      : "AND",
    rules: rules.length > 0 ? rules : [createWorkOrderFilterRule()],
  };
}

function normalizeWorkOrderFilterGroupsState(groups) {
  const normalizedGroups = Array.isArray(groups)
    ? groups.map((group, index) => normalizeWorkOrderFilterGroupState(group, index))
    : [];

  return normalizedGroups.length > 0 ? normalizedGroups : [createWorkOrderFilterGroup()];
}

function cloneWorkOrderFilterGroups(groups) {
  return normalizeWorkOrderFilterGroupsState(JSON.parse(JSON.stringify(groups ?? [])));
}

function normalizeWorkOrderFilterPresetState(preset = {}) {
  return {
    id: String(preset.id || createClientSideId("wo-filter-preset")),
    name: String(preset.name || "").trim() || "Spremljeni filter",
    query: String(preset.query || "").trim(),
    groups: normalizeWorkOrderFilterGroupsState(preset.groups),
  };
}

function readJsonFromLocalStorage(key, fallback) {
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function writeJsonToLocalStorage(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Ignore persistence failures.
  }
}

function getTargetElement(target) {
  if (target instanceof Element) {
    return target;
  }

  if (target instanceof Node) {
    return target.parentElement;
  }

  return null;
}

function getWorkOrderFilterStorageScope() {
  const organizationId = state.activeOrganizationId || "global";
  const userId = state.user?.id || "guest";
  return `${userId}:${organizationId}`;
}

function getWorkOrderFilterStateStorageKey() {
  return `${WORK_ORDER_FILTER_STATE_KEY_PREFIX}${getWorkOrderFilterStorageScope()}`;
}

function getWorkOrderFilterPresetsStorageKey() {
  return `${WORK_ORDER_FILTER_PRESETS_KEY_PREFIX}${getWorkOrderFilterStorageScope()}`;
}

function getWorkOrderTemplateStorageScope() {
  const organizationId = state.activeOrganizationId || "global";
  const userId = state.user?.id || "guest";
  return `${userId}:${organizationId}`;
}

function getWorkOrderTemplateStorageKey() {
  return `${WORK_ORDER_TEMPLATE_STORAGE_PREFIX}:${getWorkOrderTemplateStorageScope()}`;
}

function getNotificationsResolvedStorageScope() {
  const organizationId = state.activeOrganizationId || "global";
  const userId = state.user?.id || "guest";
  return `${userId}:${organizationId}`;
}

function getNotificationsResolvedStorageKey() {
  return `${NOTIFICATIONS_RESOLVED_KEY_PREFIX}${getNotificationsResolvedStorageScope()}`;
}

function loadResolvedNotifications() {
  const scope = getNotificationsResolvedStorageScope();
  if (state.notificationsResolved.scope === scope) {
    return;
  }

  const raw = readJsonFromLocalStorage(getNotificationsResolvedStorageKey(), []);
  const ids = Array.isArray(raw)
    ? raw.map((value) => String(value || "").trim()).filter(Boolean)
    : [];
  state.notificationsResolved.scope = scope;
  state.notificationsResolved.ids = new Set(ids);
}

function persistResolvedNotifications() {
  loadResolvedNotifications();
  writeJsonToLocalStorage(
    getNotificationsResolvedStorageKey(),
    Array.from(state.notificationsResolved.ids),
  );
}

function getPeriodicsPreferencesScope() {
  const organizationId = state.activeOrganizationId || "global";
  const userId = state.user?.id || "guest";
  return `${userId}:${organizationId}`;
}

function getPeriodicsFallbackPreferencesScope() {
  const userId = state.user?.id || "guest";
  return `${userId}:global`;
}

function getPeriodicsFiltersStorageKey(scope = getPeriodicsPreferencesScope()) {
  return `${PERIODICS_FILTERS_STORAGE_KEY_PREFIX}${scope}`;
}

function getPeriodicsExpandedGroupsStorageKey(scope = getPeriodicsPreferencesScope()) {
  return `${PERIODICS_EXPANDED_GROUPS_STORAGE_KEY_PREFIX}${scope}`;
}

function normalizePeriodicsStoredFilters(filters = {}) {
  return {
    query: String(filters?.query || "").trim(),
    horizon: String(filters?.horizon || "all").trim() || "all",
    inspectionGroup: normalizePeriodicsInspectionGroupMode(filters?.inspectionGroup || "item"),
    inspectionGroupKey: String(filters?.inspectionGroupKey || "").trim(),
  };
}

function normalizePeriodicsExpandedGroupsPreference(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(value)
      .map(([key, isExpanded]) => [String(key || "").trim(), Boolean(isExpanded)])
      .filter(([key]) => Boolean(key)),
  );
}

function hasStoredPeriodicsPreference(value) {
  return Boolean(value && typeof value === "object" && !Array.isArray(value) && Object.keys(value).length > 0);
}

function loadPeriodicsPreferences(force = false) {
  const scope = getPeriodicsPreferencesScope();
  if (!force && state.periodicsPreferencesScope === scope) {
    return;
  }

  const fallbackScope = getPeriodicsFallbackPreferencesScope();
  const storedFiltersRaw = readJsonFromLocalStorage(getPeriodicsFiltersStorageKey(scope), null);
  const fallbackFiltersRaw = scope === fallbackScope
    ? {}
    : readJsonFromLocalStorage(getPeriodicsFiltersStorageKey(fallbackScope), {});
  const storedFilters = normalizePeriodicsStoredFilters(
    hasStoredPeriodicsPreference(storedFiltersRaw) ? storedFiltersRaw : fallbackFiltersRaw,
  );
  const storedExpandedRaw = readJsonFromLocalStorage(getPeriodicsExpandedGroupsStorageKey(scope), null);
  const fallbackExpandedRaw = scope === fallbackScope
    ? {}
    : readJsonFromLocalStorage(getPeriodicsExpandedGroupsStorageKey(fallbackScope), {});
  state.periodicsFilters = {
    ...state.periodicsFilters,
    ...storedFilters,
  };
  state.periodicsInspectionExpandedGroups = normalizePeriodicsExpandedGroupsPreference(
    hasStoredPeriodicsPreference(storedExpandedRaw) ? storedExpandedRaw : fallbackExpandedRaw,
  );
  state.periodicsPreferencesScope = scope;
}

function persistPeriodicsPreferences() {
  const scope = state.periodicsPreferencesScope || getPeriodicsPreferencesScope();
  state.periodicsPreferencesScope = scope;
  const filters = normalizePeriodicsStoredFilters(state.periodicsFilters);
  writeJsonToLocalStorage(getPeriodicsFiltersStorageKey(scope), filters);
  writeJsonToLocalStorage(
    getPeriodicsExpandedGroupsStorageKey(scope),
    normalizePeriodicsExpandedGroupsPreference(state.periodicsInspectionExpandedGroups),
  );
  const fallbackScope = getPeriodicsFallbackPreferencesScope();
  if (fallbackScope !== scope) {
    writeJsonToLocalStorage(getPeriodicsFiltersStorageKey(fallbackScope), filters);
    writeJsonToLocalStorage(
      getPeriodicsExpandedGroupsStorageKey(fallbackScope),
      normalizePeriodicsExpandedGroupsPreference(state.periodicsInspectionExpandedGroups),
    );
  }
}

function isNotificationResolved(notificationId = "") {
  loadResolvedNotifications();
  return state.notificationsResolved.ids.has(String(notificationId || ""));
}

function setNotificationResolvedState(notificationId = "", isResolved = false) {
  const normalizedId = String(notificationId || "").trim();
  if (!normalizedId) {
    return;
  }

  loadResolvedNotifications();
  if (isResolved) {
    state.notificationsResolved.ids.add(normalizedId);
  } else {
    state.notificationsResolved.ids.delete(normalizedId);
  }
  persistResolvedNotifications();
}

function getWorkOrderFilterActiveRuleCount(groups = state.workOrderFilters.groups) {
  return (groups ?? []).reduce((count, group) => count + (group.rules ?? []).filter((rule) => {
    const field = getWorkOrderFilterFieldDefinition(rule.field);
    const values = (rule.values ?? []).filter(Boolean);

    if (field.type === "date") {
      return ["today", "yesterday", "tomorrow", "this_week", "last_week", "next_7_days", "last_7_days", "this_month", "last_month", "is_empty", "is_not_empty"].includes(rule.operator)
        || values.length > 0;
    }

    return ["is_empty", "is_not_empty"].includes(rule.operator) || values.length > 0;
  }).length, 0);
}

function loadWorkOrderFilterPreferences(force = false) {
  const nextScope = getWorkOrderFilterStorageScope();
  if (!force && state.workOrderFilters.storageScope === nextScope) {
    return;
  }

  const savedPresets = readJsonFromLocalStorage(getWorkOrderFilterPresetsStorageKey(), [])
    .map((preset) => normalizeWorkOrderFilterPresetState(preset));
  const storedState = readJsonFromLocalStorage(getWorkOrderFilterStateStorageKey(), {});
  const activePresetId = savedPresets.some((preset) => preset.id === storedState.activePresetId)
    ? storedState.activePresetId
    : "";

  state.workOrderFilters.storageScope = nextScope;
  state.workOrderFilters.builderOpen = false;
  state.workOrderFilters.presetToolsOpen = false;
  state.workOrderFilters.savedPresets = savedPresets;
  state.workOrderFilters.activePresetId = activePresetId;
  state.workOrderFilters.query = String(storedState.query || "").trim();
  state.workOrderFilters.groups = normalizeWorkOrderFilterGroupsState(storedState.groups);

  if (workOrderSearchInput) {
    workOrderSearchInput.value = state.workOrderFilters.query;
  }
}

function persistWorkOrderFilterState() {
  if (!state.workOrderFilters.storageScope) {
    return;
  }

  writeJsonToLocalStorage(getWorkOrderFilterStateStorageKey(), {
    query: state.workOrderFilters.query,
    activePresetId: state.workOrderFilters.activePresetId,
    groups: state.workOrderFilters.groups,
  });
}

function persistWorkOrderFilterPresets() {
  if (!state.workOrderFilters.storageScope) {
    return;
  }

  writeJsonToLocalStorage(getWorkOrderFilterPresetsStorageKey(), state.workOrderFilters.savedPresets);
}

function loadWorkOrderTemplateSettings(force = false) {
  const nextScope = getWorkOrderTemplateStorageScope();
  if (!force && state.workOrderTemplateSettings.storageScope === nextScope) {
    return;
  }

  const stored = readJsonFromLocalStorage(getWorkOrderTemplateStorageKey(), {});
  state.workOrderTemplateSettings = {
    storageScope: nextScope,
    selectedTemplateId: String(stored.selectedTemplateId || "").trim(),
    fileName: String(stored.fileName || "").trim(),
    updatedAt: String(stored.updatedAt || "").trim(),
  };
}

function persistWorkOrderTemplateSettings() {
  if (!state.workOrderTemplateSettings.storageScope) {
    return;
  }

  writeJsonToLocalStorage(getWorkOrderTemplateStorageKey(), {
    selectedTemplateId: state.workOrderTemplateSettings.selectedTemplateId,
    fileName: state.workOrderTemplateSettings.fileName,
    updatedAt: state.workOrderTemplateSettings.updatedAt,
  });
}

