function getWorkOrderListColumnMode() {
  return state.workOrderListDensity === "expanded" ? "expanded" : "collapsed";
}

function getWorkOrderColumnPanelStorageKey() {
  return [
    WORK_ORDER_COLUMN_PANEL_STORAGE_PREFIX,
    state.user?.id || "guest",
    state.activeOrganizationId || "global",
  ].join(":");
}

function getWorkOrderColumnStorageScope() {
  return `${state.user?.id || "guest"}:${state.activeOrganizationId || "global"}`;
}

function getWorkOrderColumnFields() {
  return WORK_ORDER_COLUMN_GROUPS.flatMap((group) => group.fields);
}

function getWorkOrderColumnFieldKeys() {
  return getWorkOrderColumnFields().map((field) => field.key);
}

function getWorkOrderColumnPreset(id = "operations") {
  return WORK_ORDER_COLUMN_PRESETS.find((preset) => preset.id === id)
    || WORK_ORDER_COLUMN_PRESETS[0];
}

function createWorkOrderColumnVisibilityFromColumns(columnKeys = []) {
  const allowedColumns = new Set(columnKeys);
  const visibility = {};
  getWorkOrderColumnFields().forEach((field) => {
    visibility[field.key] = allowedColumns.has(field.columnKey)
      || WORK_ORDER_COLUMN_ALWAYS_VISIBLE_KEYS.has(field.columnKey);
  });
  return visibility;
}

function getDefaultWorkOrderColumnVisibility() {
  return createWorkOrderColumnVisibilityFromColumns(getWorkOrderColumnPreset("operations").columns);
}

function normalizeWorkOrderColumnVisibility(value = {}) {
  const defaults = getDefaultWorkOrderColumnVisibility();
  return Object.fromEntries(getWorkOrderColumnFieldKeys().map((key) => [
    key,
    Object.prototype.hasOwnProperty.call(value, key) ? Boolean(value[key]) : defaults[key],
  ]));
}

function ensureWorkOrderColumnPanelSettingsLoaded(force = false) {
  const scope = getWorkOrderColumnStorageScope();
  if (!force && state.workOrderColumnPanel.storageScope === scope) {
    return;
  }

  const stored = readJsonFromLocalStorage(getWorkOrderColumnPanelStorageKey(), {});
  const activePreset = WORK_ORDER_COLUMN_PRESETS.some((preset) => preset.id === stored.activePreset)
    ? stored.activePreset
    : "operations";

  state.workOrderColumnPanel.storageScope = scope;
  state.workOrderColumnPanel.activePreset = activePreset;
  state.workOrderColumnPanel.visibility = normalizeWorkOrderColumnVisibility(
    stored.visibility || createWorkOrderColumnVisibilityFromColumns(getWorkOrderColumnPreset(activePreset).columns),
  );
}

function persistWorkOrderColumnPanelSettings() {
  ensureWorkOrderColumnPanelSettingsLoaded();
  writeJsonToLocalStorage(getWorkOrderColumnPanelStorageKey(), {
    activePreset: state.workOrderColumnPanel.activePreset,
    visibility: normalizeWorkOrderColumnVisibility(state.workOrderColumnPanel.visibility),
  });
}

function getVisibleWorkOrderColumnKeys() {
  ensureWorkOrderColumnPanelSettingsLoaded();
  const visibility = normalizeWorkOrderColumnVisibility(state.workOrderColumnPanel.visibility);
  const visibleColumnKeys = new Set(WORK_ORDER_COLUMN_ALWAYS_VISIBLE_KEYS);
  const fieldsByColumn = new Map();

  getWorkOrderColumnFields().forEach((field) => {
    if (!fieldsByColumn.has(field.columnKey)) {
      fieldsByColumn.set(field.columnKey, []);
    }
    fieldsByColumn.get(field.columnKey).push(field);
  });

  fieldsByColumn.forEach((fields, columnKey) => {
    if (WORK_ORDER_COLUMN_ALWAYS_VISIBLE_KEYS.has(columnKey)) {
      return;
    }
    if (fields.every((field) => visibility[field.key])) {
      visibleColumnKeys.add(columnKey);
    }
  });

  return visibleColumnKeys;
}

function getWorkOrderColumnFieldVisibility(fieldKey = "") {
  ensureWorkOrderColumnPanelSettingsLoaded();
  const visibility = normalizeWorkOrderColumnVisibility(state.workOrderColumnPanel.visibility);
  return Boolean(visibility[fieldKey]);
}

function resetWorkOrderColumnWidths() {
  workOrderListColumnWidths.collapsed = [];
  workOrderListColumnWidths.expanded = [];
}

function getWorkOrderListColumnLayout(mode = getWorkOrderListColumnMode()) {
  const baseLayout = WORK_ORDER_LIST_COLUMN_LAYOUTS[mode] || WORK_ORDER_LIST_COLUMN_LAYOUTS.collapsed;
  const visibleKeys = getVisibleWorkOrderColumnKeys();
  return baseLayout.filter((column) => visibleKeys.has(column.key));
}

function getWorkOrderListColumnStorageKey(mode = getWorkOrderListColumnMode()) {
  return [
    WORK_ORDER_LIST_COLUMN_STORAGE_PREFIX,
    state.user?.id || "guest",
    state.activeOrganizationId || "global",
    mode,
  ].join(":");
}

function loadWorkOrderListColumnWidths(mode = getWorkOrderListColumnMode()) {
  const layout = getWorkOrderListColumnLayout(mode);
  const storedWidths = readJsonFromLocalStorage(getWorkOrderListColumnStorageKey(mode), []);
  const values = Array.isArray(storedWidths) ? storedWidths : [];
  return layout.map((column, index) => {
    const nextWidth = Number(values[index]);
    if (!Number.isFinite(nextWidth)) {
      return column.defaultWidth;
    }
    return Math.max(column.minWidth, Math.round(nextWidth));
  });
}

function getWorkOrderListColumnWidths(mode = getWorkOrderListColumnMode()) {
  const layout = getWorkOrderListColumnLayout(mode);
  const widths = Array.isArray(workOrderListColumnWidths[mode])
    ? workOrderListColumnWidths[mode]
    : loadWorkOrderListColumnWidths(mode);

  workOrderListColumnWidths[mode] = layout.map((column, index) => Math.max(
    column.minWidth,
    Math.round(Number(widths[index]) || column.defaultWidth),
  ));

  return workOrderListColumnWidths[mode];
}

function persistWorkOrderListColumnWidths(mode = getWorkOrderListColumnMode()) {
  const layout = getWorkOrderListColumnLayout(mode);
  const widths = getWorkOrderListColumnWidths(mode);
  writeJsonToLocalStorage(
    getWorkOrderListColumnStorageKey(mode),
    layout.map((column, index) => Math.max(
      column.minWidth,
      Math.round(Number(widths[index]) || column.defaultWidth),
    )),
  );
}

function applyWorkOrderListColumnWidths(mode = getWorkOrderListColumnMode()) {
  if (!(workOrdersTableWrap instanceof HTMLElement)) {
    return;
  }

  const widths = getWorkOrderListColumnWidths(mode);
  const layout = getWorkOrderListColumnLayout(mode);
  const columnGap = 14;
  const template = layout.map((column, index) => {
    const width = Math.max(
      column.minWidth || 1,
      Math.round(Number(widths[index]) || column.defaultWidth || 1),
    );
    if (column.resizable === false) {
      return `${width}px`;
    }
    return `minmax(${Math.max(1, Number(column.minWidth) || 1)}px, ${width}fr)`;
  }).join(" ");
  const minWidth = layout.reduce((sum, column) => sum + Math.max(
    column.resizable === false ? column.defaultWidth : column.minWidth,
    1,
  ), 0) + Math.max(0, layout.length - 1) * columnGap;

  workOrdersTableWrap.style.setProperty("--work-order-list-grid-template", template);
  workOrdersTableWrap.style.setProperty("--work-order-list-min-width", `${minWidth}px`);
}

function startWorkOrderListColumnResize(mode, columnIndex, pointerX, pointerId, handle) {
  const layout = getWorkOrderListColumnLayout(mode);
  const column = layout[columnIndex];
  if (!column || column.resizable === false) {
    return;
  }

  const widths = getWorkOrderListColumnWidths(mode);
  workOrderListColumnResizeState = {
    mode,
    columnIndex,
    startX: pointerX,
    startWidth: widths[columnIndex] || column.defaultWidth,
  };
  handle?.setPointerCapture?.(pointerId);
  document.body.classList.add("is-resizing-work-order-column");
}

function updateWorkOrderListColumnResize(pointerX) {
  const resizeState = workOrderListColumnResizeState;
  if (!resizeState) {
    return;
  }

  const layout = getWorkOrderListColumnLayout(resizeState.mode);
  const column = layout[resizeState.columnIndex];
  if (!column) {
    return;
  }

  const widths = getWorkOrderListColumnWidths(resizeState.mode);
  widths[resizeState.columnIndex] = Math.max(
    column.minWidth,
    Math.round(resizeState.startWidth + (pointerX - resizeState.startX)),
  );
  applyWorkOrderListColumnWidths(resizeState.mode);
}

function stopWorkOrderListColumnResize() {
  if (!workOrderListColumnResizeState) {
    return;
  }

  const { mode } = workOrderListColumnResizeState;
  workOrderListColumnResizeState = null;
  document.body.classList.remove("is-resizing-work-order-column");
  persistWorkOrderListColumnWidths(mode);
}

function appendWorkOrderListColumnResizeHandle(cell, column, columnIndex, mode) {
  if (!column || column.resizable === false) {
    return;
  }

  const handle = document.createElement("button");
  handle.type = "button";
  handle.className = "work-order-column-resize-handle";
  handle.dataset.preventRowOpen = "true";
  handle.title = `Promijeni širinu kolone ${column.title}`;
  handle.setAttribute("aria-label", handle.title);
  handle.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    startWorkOrderListColumnResize(mode, columnIndex, event.clientX, event.pointerId, handle);
  });
  cell.append(handle);
}

function loadCompaniesColumnWidths() {
  const storedWidths = readJsonFromLocalStorage(COMPANIES_COLUMN_LAYOUT_STORAGE_KEY, []);
  const values = Array.isArray(storedWidths) ? storedWidths : [];
  return COMPANIES_COLUMN_LAYOUT.map((column, index) => {
    const nextWidth = Number(values[index]);
    if (!Number.isFinite(nextWidth)) {
      return column.defaultWidth;
    }
    return Math.max(column.minWidth, Math.round(nextWidth));
  });
}

function persistCompaniesColumnWidths() {
  if (companiesColumnWidths.length !== COMPANIES_COLUMN_LAYOUT.length) {
    return;
  }

  writeJsonToLocalStorage(
    COMPANIES_COLUMN_LAYOUT_STORAGE_KEY,
    COMPANIES_COLUMN_LAYOUT.map((column, index) => {
      const width = Number(companiesColumnWidths[index]);
      if (!Number.isFinite(width)) {
        return column.defaultWidth;
      }
      return Math.max(column.minWidth, Math.round(width));
    }),
  );
}

function applyCompaniesColumnWidths() {
  if (!(companiesTable instanceof HTMLTableElement)) {
    return;
  }

  const headers = Array.from(companiesTable.querySelectorAll("thead th"));
  let totalWidth = 0;

  COMPANIES_COLUMN_LAYOUT.forEach((column, index) => {
    const width = Math.max(column.minWidth, Math.round(
      Number(companiesColumnWidths[index]) || column.defaultWidth,
    ));
    companiesColumnWidths[index] = width;
    totalWidth += width;

    const header = headers[index];
    if (!(header instanceof HTMLTableCellElement)) {
      return;
    }

    header.style.width = `${width}px`;
    header.style.minWidth = `${column.minWidth}px`;
  });

  companiesTable.style.minWidth = `${totalWidth}px`;
}

function startCompaniesColumnResize(columnIndex, pointerX, pointerId, handle) {
  const column = COMPANIES_COLUMN_LAYOUT[columnIndex];
  if (!column) {
    return;
  }

  companiesColumnResizeState = {
    columnIndex,
    startX: pointerX,
    startWidth: companiesColumnWidths[columnIndex] || column.defaultWidth,
  };
  handle.setPointerCapture?.(pointerId);
  document.body.classList.add("is-resizing-companies-column");
}

function updateCompaniesColumnResize(pointerX) {
  const resizeState = companiesColumnResizeState;
  if (!resizeState) {
    return;
  }

  const column = COMPANIES_COLUMN_LAYOUT[resizeState.columnIndex];
  if (!column) {
    return;
  }

  const nextWidth = Math.max(
    column.minWidth,
    Math.round(resizeState.startWidth + (pointerX - resizeState.startX)),
  );

  if (companiesColumnWidths[resizeState.columnIndex] === nextWidth) {
    return;
  }

  companiesColumnWidths[resizeState.columnIndex] = nextWidth;
  applyCompaniesColumnWidths();
}

function stopCompaniesColumnResize() {
  if (!companiesColumnResizeState) {
    return;
  }

  companiesColumnResizeState = null;
  document.body.classList.remove("is-resizing-companies-column");
  persistCompaniesColumnWidths();
}

function initializeCompaniesColumnResize() {
  if (companiesColumnResizeInitialized || !(companiesTable instanceof HTMLTableElement)) {
    return;
  }

  companiesColumnResizeInitialized = true;
  companiesColumnWidths = loadCompaniesColumnWidths();

  const headers = Array.from(companiesTable.querySelectorAll("thead th"));
  headers.forEach((header, index) => {
    const column = COMPANIES_COLUMN_LAYOUT[index];
    if (!column || !(header instanceof HTMLTableCellElement)) {
      return;
    }

    header.classList.add("companies-column-header");
    const resizeHandle = document.createElement("button");
    resizeHandle.type = "button";
    resizeHandle.className = "companies-column-resize-handle";
    resizeHandle.setAttribute(
      "aria-label",
      `Promijeni širinu kolone ${String(header.textContent || "").trim() || column.key}`,
    );
    resizeHandle.addEventListener("pointerdown", (event) => {
      if (event.button !== 0) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      startCompaniesColumnResize(index, event.clientX, event.pointerId, resizeHandle);
    });

    header.append(resizeHandle);
  });

  applyCompaniesColumnWidths();
}

function hoistModalElementToBody(element) {
  if (!(element instanceof HTMLElement) || !document.body || element.parentElement === document.body) {
    return;
  }

  document.body.append(element);
}

hoistModalElementToBody(companyEditorBackdrop);
hoistModalElementToBody(companyEditorPanel);

