function normalizePeriodicsVisualSettings(value = {}) {
  const source = value && typeof value === "object"
    ? value
    : {};
  const fallback = DEFAULT_PERIODICS_VISUAL_SETTINGS;
  const criticalDays = normalizeNotificationDayValue(
    source.criticalDays ?? source.alertDays ?? source.criticalThresholdDays,
    fallback.criticalDays,
    { min: 1, max: 120 },
  );
  const warningDaysRaw = normalizeNotificationDayValue(
    source.warningDays ?? source.yellowDays ?? source.warningThresholdDays,
    fallback.warningDays,
    { min: 1, max: 365 },
  );
  const warningDays = Math.max(criticalDays, warningDaysRaw);
  return {
    criticalDays,
    warningDays,
    workOrderDefaultDueDays: normalizeOptionalDayValue(
      source.workOrderDefaultDueDays ?? source.workOrderDueDays ?? source.defaultWorkOrderDueDays,
      { min: 0, max: 365 },
    ),
  };
}

function getPeriodicsVisualSettings() {
  return normalizePeriodicsVisualSettings(state.periodicsVisualSettings);
}

function clampNumber(value = 0, min = 0, max = 100) {
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue)) {
    return min;
  }
  return Math.min(Math.max(numericValue, min), max);
}

function normalizeGlobalLoadingPhases(phases = []) {
  return (Array.isArray(phases) ? phases : [])
    .map((phase, index) => ({
      label: String(phase?.label || phase || `Faza ${index + 1}`).trim(),
      detail: String(phase?.detail || "").trim(),
      progress: clampNumber(Number(phase?.progress ?? ((index + 1) / Math.max(phases.length, 1)) * 92), 0, 99),
    }))
    .filter((phase) => phase.label);
}

function renderGlobalLoadingPhaseSteps() {
  if (!globalLoadingPhaseSteps) {
    return;
  }

  const phases = globalLoadingState.phases;
  globalLoadingPhaseSteps.replaceChildren(...phases.map((phase, index) => {
    const step = document.createElement("span");
    step.className = "global-loading-phase-step";
    if (index < globalLoadingState.phaseIndex) {
      step.classList.add("is-done");
    } else if (index === globalLoadingState.phaseIndex) {
      step.classList.add("is-active");
    }
    step.textContent = phase.label;
    return step;
  }));
}

function setGlobalLoadingPhase(index = 0, { progress = null, message = "" } = {}) {
  if (!globalLoadingPhase || globalLoadingState.phases.length === 0) {
    return;
  }

  const lastIndex = Math.max(0, globalLoadingState.phases.length - 1);
  globalLoadingState.phaseIndex = clampNumber(Number(index) || 0, 0, lastIndex);
  const phase = globalLoadingState.phases[globalLoadingState.phaseIndex] || globalLoadingState.phases[0];
  const safeProgress = clampNumber(
    Number(progress ?? phase.progress ?? ((globalLoadingState.phaseIndex + 1) / Math.max(globalLoadingState.phases.length, 1)) * 92),
    0,
    100,
  );

  globalLoadingPhase.hidden = false;
  if (globalLoadingPhaseBar) {
    globalLoadingPhaseBar.style.width = `${safeProgress}%`;
  }
  if (globalLoadingPhaseLabel) {
    globalLoadingPhaseLabel.textContent = phase.detail || phase.label;
  }
  if (globalLoadingPhasePercent) {
    globalLoadingPhasePercent.textContent = `${Math.round(safeProgress)}%`;
  }
  if (message && globalLoadingIndicatorCopy) {
    globalLoadingIndicatorCopy.textContent = message;
  }
  renderGlobalLoadingPhaseSteps();
}

function clearGlobalLoadingPhases() {
  if (globalLoadingState.phaseTimerId) {
    window.clearInterval(globalLoadingState.phaseTimerId);
    globalLoadingState.phaseTimerId = 0;
  }
  globalLoadingState.phaseIndex = 0;
  globalLoadingState.phases = [];
  if (globalLoadingPhase) {
    globalLoadingPhase.hidden = true;
  }
  if (globalLoadingPhaseBar) {
    globalLoadingPhaseBar.style.width = "0%";
  }
  if (globalLoadingPhaseSteps) {
    globalLoadingPhaseSteps.replaceChildren();
  }
}

function startGlobalLoadingPhases(phases = []) {
  const normalizedPhases = normalizeGlobalLoadingPhases(phases);
  clearGlobalLoadingPhases();
  if (normalizedPhases.length === 0) {
    return;
  }

  globalLoadingState.phases = normalizedPhases;
  setGlobalLoadingPhase(0);
  globalLoadingState.phaseTimerId = window.setInterval(() => {
    if (globalLoadingState.phases.length === 0) {
      return;
    }
    const nextIndex = Math.min(globalLoadingState.phaseIndex + 1, Math.max(0, globalLoadingState.phases.length - 2));
    setGlobalLoadingPhase(nextIndex);
  }, GLOBAL_LOADING_PHASE_ADVANCE_MS);
}

function createGlobalLoadingController({
  message = "Obrada je u tijeku...",
  phases = [],
} = {}) {
  beginGlobalLoading(message, { immediate: true, phases });
  let closed = false;
  return {
    setPhase(index = 0, options = {}) {
      if (!closed) {
        setGlobalLoadingPhase(index, options);
      }
    },
    complete(options = {}) {
      if (closed) {
        return;
      }
      const lastIndex = Math.max(0, globalLoadingState.phases.length - 1);
      setGlobalLoadingPhase(lastIndex, {
        progress: 100,
        message: options.message || "Dokument je spreman.",
      });
    },
    close() {
      if (closed) {
        return;
      }
      closed = true;
      endGlobalLoading();
    },
  };
}

function showGlobalLoadingIndicator(message = globalLoadingState.message) {
  if (!globalLoadingIndicator) {
    return;
  }

  globalLoadingState.visible = true;
  globalLoadingState.message = message || globalLoadingState.message;

  if (globalLoadingIndicatorCopy) {
    globalLoadingIndicatorCopy.textContent = globalLoadingState.message;
  }

  globalLoadingIndicator.hidden = false;
  document.body.classList.add("is-global-loading");

  requestAnimationFrame(() => {
    globalLoadingIndicator.classList.add("is-visible");
  });
}

function hideGlobalLoadingIndicator() {
  if (!globalLoadingIndicator) {
    return;
  }

  globalLoadingState.visible = false;
  clearGlobalLoadingPhases();
  globalLoadingIndicator.classList.remove("is-visible");
  document.body.classList.remove("is-global-loading");

  window.setTimeout(() => {
    if (!globalLoadingState.visible) {
      globalLoadingIndicator.hidden = true;
    }
  }, GLOBAL_LOADING_HIDE_DELAY_MS);
}

function beginGlobalLoading(message = "Učitavanje podataka...", { immediate = false, phases = null } = {}) {
  globalLoadingState.count += 1;
  globalLoadingState.message = message || globalLoadingState.message;

  if (globalLoadingIndicatorCopy) {
    globalLoadingIndicatorCopy.textContent = globalLoadingState.message;
  }

  if (globalLoadingTimerId) {
    window.clearTimeout(globalLoadingTimerId);
    globalLoadingTimerId = null;
  }

  if (Array.isArray(phases) && phases.length > 0) {
    startGlobalLoadingPhases(phases);
  } else if (globalLoadingState.count <= 1) {
    clearGlobalLoadingPhases();
  }

  if (globalLoadingState.visible) {
    return;
  }

  if (immediate) {
    showGlobalLoadingIndicator(globalLoadingState.message);
    return;
  }

  globalLoadingTimerId = window.setTimeout(() => {
    globalLoadingTimerId = null;
    if (globalLoadingState.count > 0) {
      showGlobalLoadingIndicator(globalLoadingState.message);
    }
  }, GLOBAL_LOADING_DELAY_MS);
}

function endGlobalLoading() {
  globalLoadingState.count = Math.max(0, globalLoadingState.count - 1);

  if (globalLoadingState.count > 0) {
    return;
  }

  if (globalLoadingTimerId) {
    window.clearTimeout(globalLoadingTimerId);
    globalLoadingTimerId = null;
  }

  hideGlobalLoadingIndicator();
}

async function withGlobalLoading(message, callback, options = {}) {
  beginGlobalLoading(message, options);

  try {
    return await callback();
  } finally {
    endGlobalLoading();
  }
}

function canManageRenderedUser(user) {
  if (getIsSuperAdmin()) {
    return true;
  }

  if (getIsAdmin()) {
    return !isSystemPrivilegedRole(user?.role);
  }

  return getCanManagePeople() && !isSystemPrivilegedRole(user?.role);
}

async function requestTokenRefresh() {
  const response = await fetch(`${API_BASE}/auth/refresh`, {
    method: "POST",
    credentials: "same-origin",
    headers: {
      "Content-Type": "application/json",
    },
  });

  return response.ok;
}

async function apiRequest(path, options = {}, retryOnAuthFailure = true) {
  const organizationHeader = state.activeOrganizationId
    ? { "X-Organization-Id": state.activeOrganizationId }
    : {};
  const response = await fetch(`${API_BASE}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...organizationHeader,
      ...(options.headers ?? {}),
    },
    credentials: "same-origin",
    ...options,
    body: options.body ? JSON.stringify(options.body) : undefined,
  });

  if (response.status === 401 && retryOnAuthFailure && !AUTH_RETRY_EXCLUDED_PATHS.has(path)) {
    if (hasSessionIdleExpired()) {
      runLogoutFlow(SESSION_IDLE_LOGOUT_MESSAGE);
    } else {
      const refreshed = await requestTokenRefresh();

      if (refreshed) {
        return apiRequest(path, options, false);
      }
    }
  }

  if (!response.ok) {
    const error = new Error(await readApiErrorMessage(response));
    error.statusCode = response.status;
    throw error;
  }

  const payload = await response.json().catch(() => ({}));
  return payload;
}

function getOpenAiIntegrationStatusLabel() {
  const status = state.openAiIntegration;
  if (status.status === "loading") {
    return "OpenAI veza: provjeravam...";
  }
  if (status.status === "error") {
    return status.error || "OpenAI veza: nije dostupna.";
  }
  if (!status.keyConfigured) {
    return "OpenAI veza: ključ nije postavljen.";
  }
  if (status.dryRun) {
    return "OpenAI veza spremna - dry-run, tokeni se ne troše.";
  }
  if (status.liveCallsEnabled) {
    return "OpenAI live pozivi su uključeni.";
  }
  return "OpenAI veza spremna - live pozivi su zaključani.";
}

function applyOpenAiIntegrationStatusClass(element) {
  if (!(element instanceof HTMLElement)) {
    return;
  }
  const status = state.openAiIntegration;
  element.classList.toggle("is-loading", status.status === "loading");
  element.classList.toggle("is-error", status.status === "error" || (!status.keyConfigured && status.status === "ready"));
  element.classList.toggle("is-ready", status.status === "ready" && status.keyConfigured);
  element.classList.toggle("is-dry-run", status.status === "ready" && status.dryRun);
}

function syncOpenAiIntegrationStatusTargets(...targets) {
  targets.forEach((target) => {
    if (!(target instanceof HTMLElement)) {
      return;
    }
    target.textContent = getOpenAiIntegrationStatusLabel();
    applyOpenAiIntegrationStatusClass(target);
  });
}

async function loadOpenAiIntegrationStatus({ force = false } = {}) {
  const isFresh = Date.now() - Number(state.openAiIntegration.loadedAt || 0) < 60000;
  if (!force && state.openAiIntegration.status === "ready" && isFresh) {
    syncOpenAiIntegrationStatusTargets(measurementAiConnectionStatus);
    return state.openAiIntegration;
  }

  state.openAiIntegration = {
    ...state.openAiIntegration,
    status: "loading",
    error: "",
  };
  syncOpenAiIntegrationStatusTargets(measurementAiConnectionStatus);

  try {
    const payload = await apiRequest("/ai/openai/status");
    state.openAiIntegration = {
      ...state.openAiIntegration,
      status: "ready",
      loadedAt: Date.now(),
      error: "",
      keyConfigured: Boolean(payload.keyConfigured),
      dryRun: Boolean(payload.dryRun),
      liveCallsEnabled: Boolean(payload.liveCallsEnabled),
      endpointReady: Boolean(payload.endpointReady),
      model: String(payload.model || ""),
      modelTiers: Array.isArray(payload.modelTiers) ? payload.modelTiers : [],
    };
  } catch (error) {
    state.openAiIntegration = {
      ...state.openAiIntegration,
      status: "error",
      loadedAt: Date.now(),
      error: error?.message || "OpenAI status nije dostupan.",
      keyConfigured: false,
      endpointReady: false,
    };
  }

  syncOpenAiIntegrationStatusTargets(measurementAiConnectionStatus);
  return state.openAiIntegration;
}

function parseResponseDownloadFileName(response, fallback = "download.bin") {
  const contentDisposition = String(response.headers.get("content-disposition") || "").trim();
  if (!contentDisposition) {
    return fallback;
  }

  const utfMatch = contentDisposition.match(/filename\*=UTF-8''([^;]+)/i);
  if (utfMatch?.[1]) {
    try {
      return decodeURIComponent(utfMatch[1].trim());
    } catch {
      return utfMatch[1].trim();
    }
  }

  const plainMatch = contentDisposition.match(/filename="?([^";]+)"?/i);
  return plainMatch?.[1]?.trim() || fallback;
}

function normalizeApiErrorText(value = "") {
  return String(value || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 320);
}

async function readApiErrorMessage(response) {
  const statusLabel = response?.status ? `HTTP ${response.status}` : "Request failed";
  const contentType = String(response?.headers?.get("content-type") || "").toLowerCase();

  if (contentType.includes("application/json")) {
    const payload = await response.json().catch(() => null);
    const jsonMessage = normalizeApiErrorText(payload?.error || payload?.message || "");
    return jsonMessage || statusLabel;
  }

  const textMessage = normalizeApiErrorText(await response.text().catch(() => ""));
  return textMessage || statusLabel;
}

async function apiBinaryRequest(path, options = {}, retryOnAuthFailure = true) {
  const organizationHeader = state.activeOrganizationId
    ? { "X-Organization-Id": state.activeOrganizationId }
    : {};
  const response = await fetch(`${API_BASE}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...organizationHeader,
      ...(options.headers ?? {}),
    },
    credentials: "same-origin",
    ...options,
    body: options.body ? JSON.stringify(options.body) : undefined,
  });

  if (response.status === 401 && retryOnAuthFailure && !AUTH_RETRY_EXCLUDED_PATHS.has(path)) {
    if (hasSessionIdleExpired()) {
      runLogoutFlow(SESSION_IDLE_LOGOUT_MESSAGE);
    } else {
      const refreshed = await requestTokenRefresh();

      if (refreshed) {
        return apiBinaryRequest(path, options, false);
      }
    }
  }

  if (!response.ok) {
    const error = new Error(await readApiErrorMessage(response));
    error.statusCode = response.status;
    throw error;
  }

  return {
    blob: await response.blob(),
    fileName: parseResponseDownloadFileName(response),
    contentType: String(response.headers.get("content-type") || "").trim(),
  };
}

