function clearSessionIdleTimer() {
  if (sessionIdleTimerId) {
    window.clearTimeout(sessionIdleTimerId);
    sessionIdleTimerId = null;
  }
}

function scheduleSessionIdleCheck() {
  if (!state.user || logoutInProgress) {
    clearSessionIdleTimer();
    return;
  }

  if (!sessionLastActivityAtMs) {
    sessionLastActivityAtMs = Date.now();
  }

  const elapsedMs = Date.now() - sessionLastActivityAtMs;

  if (elapsedMs >= SESSION_IDLE_TIMEOUT_MS) {
    runLogoutFlow(SESSION_IDLE_LOGOUT_MESSAGE);
    return;
  }

  clearSessionIdleTimer();
  sessionIdleTimerId = window.setTimeout(() => {
    sessionIdleTimerId = null;
    scheduleSessionIdleCheck();
  }, Math.max(250, SESSION_IDLE_TIMEOUT_MS - elapsedMs));
}

function handleSessionIdleActivity() {
  if (!state.user || logoutInProgress) {
    clearSessionIdleTimer();
    return;
  }

  sessionLastActivityAtMs = Date.now();
  scheduleSessionIdleCheck();
}

function verifySessionIdleOnVisibilityOrFocus() {
  if (!state.user || logoutInProgress) {
    clearSessionIdleTimer();
    return;
  }

  if (document.visibilityState && document.visibilityState !== "visible") {
    return;
  }

  scheduleSessionIdleCheck();
}

function bindSessionIdleTracking() {
  if (sessionIdleTrackingBound) {
    return;
  }

  sessionIdleTrackingBound = true;
  for (const eventName of SESSION_IDLE_ACTIVITY_EVENTS) {
    window.addEventListener(eventName, handleSessionIdleActivity, { passive: true });
  }
  window.addEventListener("focus", verifySessionIdleOnVisibilityOrFocus, { passive: true });
  document.addEventListener("visibilitychange", verifySessionIdleOnVisibilityOrFocus);
}

function syncSessionIdleTracking() {
  if (state.user) {
    bindSessionIdleTracking();
    if (!sessionLastActivityAtMs) {
      sessionLastActivityAtMs = Date.now();
    }
    scheduleSessionIdleCheck();
    return;
  }

  sessionLastActivityAtMs = 0;
  clearSessionIdleTimer();
}

function hasSessionIdleExpired() {
  if (!state.user || !sessionLastActivityAtMs) {
    return false;
  }

  return (Date.now() - sessionLastActivityAtMs) >= SESSION_IDLE_TIMEOUT_MS;
}

async function runMutation(callback, errorTarget, options = {}) {
  try {
    if (errorTarget) {
      setInlineMessage(errorTarget, "");
    }

    const payload = await callback();
    if (payload && typeof payload === "object" && Object.prototype.hasOwnProperty.call(payload, "storage")) {
      applySnapshot(payload, options);
    }
    return true;
  } catch (error) {
    if (error.statusCode === 401) {
      state.user = null;
      renderAuthState();
      setSyncError("");
      return false;
    }

    if (errorTarget) {
      setInlineMessage(errorTarget, error.message);
    } else {
      setSyncError(error.message);
    }

    return false;
  }
}

function createOption(value, label, selectedValue = "", data = {}) {
  const option = document.createElement("option");
  option.value = String(value ?? "");
  option.textContent = label;
  option.selected = String(selectedValue ?? "") === String(value ?? "");

  for (const [key, entryValue] of Object.entries(data)) {
    option.dataset[key] = String(entryValue ?? "");
  }

  return option;
}

function replaceSelectOptions(select, options, selectedValue = "") {
  select.replaceChildren(...options.map((option) => createOption(option.value, option.label, selectedValue, option.data)));

  const hasSelectedValue = options.some((option) => String(option.value) === String(selectedValue));
  if (hasSelectedValue) {
    select.value = String(selectedValue);
  } else if (options[0]) {
    select.value = String(options[0].value);
  } else {
    select.value = "";
  }
}

function getSelectOptionsSignature(options = []) {
  return options
    .map((option) => [
      option.value,
      option.label,
      option.data ? JSON.stringify(option.data) : "",
    ].map((value) => String(value ?? "")).join("::"))
    .join("||");
}

function replaceSelectOptionsIfChanged(select, options, selectedValue = "") {
  if (!(select instanceof HTMLSelectElement)) {
    return;
  }
  const signature = getSelectOptionsSignature(options);
  const selected = String(selectedValue ?? "");
  if (select.dataset.optionsSignature !== signature) {
    replaceSelectOptions(select, options, selected);
    select.dataset.optionsSignature = signature;
    return;
  }
  const hasSelectedValue = options.some((option) => String(option.value) === selected);
  select.value = hasSelectedValue ? selected : String(options[0]?.value ?? "");
}

function getPeopleTrainingStatusOption(status = "") {
  const normalized = String(status ?? "").trim().toLowerCase();
  return PERSON_TRAINING_STATUS_OPTIONS.find((option) => option.value === normalized)
    ?? PERSON_TRAINING_STATUS_OPTIONS[0];
}

function normalizePeopleTrainingDate(value = "") {
  const raw = String(value ?? "").trim();
  if (!raw) {
    return "";
  }
  const isoMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) {
    return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
  }
  const hrMatch = raw.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})\.?$/);
  if (hrMatch) {
    return `${hrMatch[3]}-${hrMatch[2].padStart(2, "0")}-${hrMatch[1].padStart(2, "0")}`;
  }
  const slashMatch = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (slashMatch) {
    return `${slashMatch[3]}-${slashMatch[2].padStart(2, "0")}-${slashMatch[1].padStart(2, "0")}`;
  }
  return "";
}

function getPeopleTrainingItemStatus(item = {}) {
  const explicitStatus = String(item?.status ?? "").trim().toLowerCase();
  if (explicitStatus === "not_required") {
    return "not_required";
  }

  const validUntil = normalizePeopleTrainingDate(item?.validUntil ?? item?.validTo ?? item?.expiresOn);
  const issuedOn = normalizePeopleTrainingDate(item?.issuedOn ?? item?.issuedDate);
  const passedOn = normalizePeopleTrainingDate(item?.passedOn ?? item?.passedDate);
  const certificateNumber = String(item?.certificateNumber ?? item?.documentNumber ?? item?.number ?? "").trim();
  const recordNumber = String(item?.recordNumber ?? item?.zapisnikNumber ?? "").trim();
  const hasCompletedEvidence = Boolean(issuedOn || passedOn || certificateNumber || recordNumber);
  if (!hasCompletedEvidence) {
    return "missing";
  }
  if (item?.validForever === true || String(item?.validForever) === "true") {
    return "valid";
  }
  if (!validUntil) {
    return "valid";
  }

  const today = new Date();
  const todayIso = [
    today.getFullYear(),
    String(today.getMonth() + 1).padStart(2, "0"),
    String(today.getDate()).padStart(2, "0"),
  ].join("-");
  if (validUntil < todayIso) {
    return "expired";
  }

  const due = new Date(`${validUntil}T00:00:00`);
  const now = new Date(`${todayIso}T00:00:00`);
  const days = Math.ceil((due.getTime() - now.getTime()) / 86400000);
  return days <= 60 ? "expiring" : "valid";
}

