function normalizeWorkOrderServiceProgressStatus(value = "", fallback = "pending") {
  const normalized = String(value || "").trim().toLowerCase();
  if (WORK_ORDER_SERVICE_PROGRESS_VALUES.has(normalized)) {
    return normalized;
  }
  const normalizedFallback = String(fallback || "").trim().toLowerCase();
  return WORK_ORDER_SERVICE_PROGRESS_VALUES.has(normalizedFallback) ? normalizedFallback : "pending";
}

function getWorkOrderServiceProgressStatus(item = {}) {
  return normalizeWorkOrderServiceProgressStatus(
    item?.serviceStatus ?? item?.progressStatus ?? item?.workStatus,
    item?.isCompleted ? "completed" : "pending",
  );
}

function getWorkOrderServiceProgressMeta(item = {}) {
  const status = getWorkOrderServiceProgressStatus(item);
  return WORK_ORDER_SERVICE_PROGRESS_OPTIONS.find((option) => option.value === status)
    || WORK_ORDER_SERVICE_PROGRESS_OPTIONS[0];
}

function withWorkOrderServiceProgressStatus(item = {}, status = "pending") {
  const normalizedStatus = normalizeWorkOrderServiceProgressStatus(status);
  return {
    ...item,
    serviceStatus: normalizedStatus,
    isCompleted: normalizedStatus === "completed",
  };
}

function summarizeWorkOrderServiceProgress(items = []) {
  const counts = { pending: 0, in_progress: 0, completed: 0 };
  (Array.isArray(items) ? items : []).forEach((item) => {
    const status = getWorkOrderServiceProgressStatus(item);
    counts[status] = (counts[status] || 0) + 1;
  });
  return counts;
}

function buildWorkOrderServiceItemSnapshot(service, current = null) {
  const linkedTemplateTitles = Array.isArray(service?.linkedTemplateTitles) && service.linkedTemplateTitles.length > 0
    ? service.linkedTemplateTitles
    : (service?.linkedTemplateIds ?? [])
      .map((templateId) => state.documentTemplates.find((item) => String(item.id) === String(templateId))?.title ?? "")
      .filter(Boolean);
  const linkedLearningTestTitles = Array.isArray(service?.linkedLearningTestTitles) && service.linkedLearningTestTitles.length > 0
    ? service.linkedLearningTestTitles
    : (service?.linkedLearningTestIds ?? [])
      .map((testId) => state.learningTests.find((item) => String(item.id) === String(testId))?.title ?? "")
      .filter(Boolean);

  return {
    serviceId: String(service?.id ?? current?.serviceId ?? ""),
    name: String(service?.name ?? current?.name ?? "").trim(),
    serviceCode: String(service?.serviceCode ?? current?.serviceCode ?? "").trim(),
    serviceType: String(service?.serviceType ?? current?.serviceType ?? (service?.isTraining ?? current?.isTraining ? "znr" : "inspection")).trim().toLowerCase() || "inspection",
    validityMonths: normalizeValidityMonthsValue(service?.validityMonths ?? current?.validityMonths ?? ""),
    linkedTemplateIds: Array.isArray(service?.linkedTemplateIds)
      ? service.linkedTemplateIds.map((value) => String(value ?? "").trim()).filter(Boolean)
      : Array.isArray(current?.linkedTemplateIds)
        ? current.linkedTemplateIds.map((value) => String(value ?? "").trim()).filter(Boolean)
        : [],
    linkedTemplateTitles: linkedTemplateTitles.map((value) => String(value ?? "").trim()).filter(Boolean),
    linkedLearningTestIds: Array.isArray(service?.linkedLearningTestIds)
      ? service.linkedLearningTestIds.map((value) => String(value ?? "").trim()).filter(Boolean)
      : Array.isArray(current?.linkedLearningTestIds)
        ? current.linkedLearningTestIds.map((value) => String(value ?? "").trim()).filter(Boolean)
        : [],
    linkedLearningTestTitles: linkedLearningTestTitles.map((value) => String(value ?? "").trim()).filter(Boolean),
    linkedQualificationKeys: getServiceCatalogQualificationKeys(service).length > 0
      ? getServiceCatalogQualificationKeys(service)
      : normalizeQualificationExamKeyList(current?.linkedQualificationKeys ?? current?.linkedQualificationExamKeys ?? []),
    isTraining: String(service?.serviceType ?? current?.serviceType ?? (service?.isTraining ?? current?.isTraining ? "znr" : "inspection")).trim().toLowerCase() === "znr",
    serviceStatus: normalizeWorkOrderServiceProgressStatus(
      current?.serviceStatus ?? current?.progressStatus ?? current?.workStatus,
      current?.isCompleted ? "completed" : "pending",
    ),
    isCompleted: normalizeWorkOrderServiceProgressStatus(
      current?.serviceStatus ?? current?.progressStatus ?? current?.workStatus,
      current?.isCompleted ? "completed" : "pending",
    ) === "completed",
  };
}

function normalizeServiceCatalogTypeUi(value = "", fallback = "inspection") {
  const normalized = String(value || "").trim().toLowerCase();
  if (SERVICE_CATALOG_TYPE_OPTIONS.some((option) => option.value === normalized)) {
    return normalized;
  }
  return String(fallback || "inspection").trim().toLowerCase() || "inspection";
}

function getServiceCatalogTypeLabel(value = "") {
  return getOptionLabel(SERVICE_CATALOG_TYPE_OPTIONS, normalizeServiceCatalogTypeUi(value));
}

function getWorkOrderServiceType(item = null) {
  return normalizeServiceCatalogTypeUi(item?.serviceType, item?.isTraining ? "znr" : "inspection");
}

function normalizeValidityMonthsValue(value = "") {
  const raw = String(value ?? "").trim().replace(/\s+/g, "").replace(",", ".");
  if (!raw) {
    return "";
  }

  const numeric = Math.round(Number(raw));
  if (!Number.isFinite(numeric) || numeric < 0) {
    return "";
  }

  return String(Math.min(600, numeric));
}

function getWorkOrderServiceValidityMonths(service = {}) {
  const catalogItem = getServiceCatalogItemForWorkOrderService(service);
  return normalizeValidityMonthsValue(catalogItem?.validityMonths)
    || normalizeValidityMonthsValue(service?.validityMonths);
}

function normalizeWorkOrderServiceValidityKey(value = "") {
  return String(value ?? "").trim().toLowerCase();
}

function normalizeWorkOrderServiceValidityMap(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }

  return Object.fromEntries(
    Object.entries(value)
      .map(([key, entryValue]) => [
        normalizeWorkOrderServiceValidityKey(key),
        normalizeValidityMonthsValue(entryValue),
      ])
      .filter(([key]) => Boolean(key)),
  );
}

function getWorkOrderServiceValidityKey(service = {}) {
  const catalogItem = getServiceCatalogItemForWorkOrderService(service);
  const serviceId = String(
    catalogItem?.id
    ?? service?.serviceId
    ?? service?.id
    ?? "",
  ).trim();
  if (serviceId) {
    return normalizeWorkOrderServiceValidityKey(`service:${serviceId}`);
  }

  const serviceCode = normalizeLooseName(catalogItem?.serviceCode ?? service?.serviceCode ?? "");
  if (serviceCode) {
    return normalizeWorkOrderServiceValidityKey(`code:${serviceCode}`);
  }

  const serviceName = normalizeLooseName(catalogItem?.name ?? service?.name ?? service?.serviceName ?? "");
  if (serviceName) {
    return normalizeWorkOrderServiceValidityKey(`name:${serviceName}`);
  }

  return "";
}

function getWorkOrderServiceValidityLabel(service = {}) {
  const catalogItem = getServiceCatalogItemForWorkOrderService(service);
  const serviceCode = String(catalogItem?.serviceCode ?? service?.serviceCode ?? "").trim();
  const serviceName = String(catalogItem?.name ?? service?.name ?? service?.serviceName ?? "").trim();
  if (serviceCode && serviceName && normalizeLooseName(serviceCode) !== normalizeLooseName(serviceName)) {
    return `${serviceCode} - ${serviceName}`;
  }
  return serviceName || serviceCode || "Ispitna usluga";
}

function createWorkOrderServiceValidityDefinition(service = {}) {
  const catalogItem = getServiceCatalogItemForWorkOrderService(service);
  const source = catalogItem ?? service;
  if (getWorkOrderServiceType(source) !== "inspection") {
    return null;
  }

  const key = getWorkOrderServiceValidityKey(service);
  if (!key) {
    return null;
  }

  return {
    key,
    label: getWorkOrderServiceValidityLabel(service),
    code: String(source?.serviceCode ?? service?.serviceCode ?? "").trim(),
    name: String(source?.name ?? service?.name ?? service?.serviceName ?? "").trim(),
    serviceId: String(source?.id ?? service?.serviceId ?? service?.id ?? "").trim(),
    validityMonths: getWorkOrderServiceValidityMonths(service),
  };
}

function getWorkOrderServiceValidityDefinitionsFromServices(services = []) {
  const definitions = new Map();
  (Array.isArray(services) ? services : []).forEach((service) => {
    const definition = createWorkOrderServiceValidityDefinition(service);
    if (!definition) {
      return;
    }
    const existing = definitions.get(definition.key);
    definitions.set(definition.key, {
      ...definition,
      validityMonths: existing?.validityMonths || definition.validityMonths,
    });
  });
  return [...definitions.values()];
}

function getWorkOrderDocumentServiceValidityDefinitions(workOrders = []) {
  return getWorkOrderServiceValidityDefinitionsFromServices(
    (Array.isArray(workOrders) ? workOrders : [])
      .flatMap((workOrder) => getWorkOrderDocumentWizardResolvedServiceItems(workOrder)),
  );
}

function getInspectionServiceCatalogValidityDefinitions() {
  return getWorkOrderServiceValidityDefinitionsFromServices(
    sortServiceCatalogItems(state.serviceCatalog ?? [])
      .filter((service) => getWorkOrderServiceType(service) === "inspection"),
  );
}

function getServiceCatalogItemByValidityKey(key = "") {
  const normalizedKey = normalizeWorkOrderServiceValidityKey(key);
  if (!normalizedKey) {
    return null;
  }

  return (state.serviceCatalog ?? []).find((service) => (
    getWorkOrderServiceValidityKey(service) === normalizedKey
  )) ?? null;
}

function findServiceItemByValidityKey(services = [], key = "") {
  const normalizedKey = normalizeWorkOrderServiceValidityKey(key);
  if (!normalizedKey) {
    return null;
  }

  return (Array.isArray(services) ? services : []).find((service) => (
    getWorkOrderServiceValidityKey(service) === normalizedKey
  )) ?? null;
}

function getWorkOrderServiceValiditySourceValue(kind = "SERVICE_VALIDITY_MONTHS", key = "") {
  const normalizedKind = String(kind || "SERVICE_VALIDITY_MONTHS").trim().toUpperCase();
  const normalizedKey = normalizeWorkOrderServiceValidityKey(key).toUpperCase();
  return normalizedKey ? `${normalizedKind}::${normalizedKey}` : normalizedKind;
}

function resolveServiceItemsDefaultValidityMonths(serviceItems = [], { fallback = "" } = {}) {
  const validityMonths = (Array.isArray(serviceItems) ? serviceItems : [])
    .map((item) => getWorkOrderServiceValidityMonths(item))
    .find(Boolean);

  return validityMonths || fallback;
}

function getWorkOrderSelectionServiceType(items = []) {
  const normalizedTypes = Array.from(new Set(
    (Array.isArray(items) ? items : [])
      .map((item) => getWorkOrderServiceType(item))
      .filter(Boolean),
  ));
  return normalizedTypes.length === 1 ? normalizedTypes[0] : "";
}

function getWorkOrderDocumentSelectionState(workOrders = []) {
  const serviceTypes = Array.from(new Set(
    (Array.isArray(workOrders) ? workOrders : [])
      .flatMap((workOrder) => getWorkOrderServiceItems(workOrder))
      .map((item) => getWorkOrderServiceType(item))
      .filter(Boolean),
  ));
  return {
    serviceTypes,
    mode: serviceTypes.length === 1 ? serviceTypes[0] : "",
    hasMixedTypes: serviceTypes.length > 1,
    hasServices: serviceTypes.length > 0,
  };
}

function resolveWorkOrderDocumentDefaultValidityMonths(workOrders = [], { fallback = "12" } = {}) {
  const serviceValidityValues = (Array.isArray(workOrders) ? workOrders : [])
    .flatMap((workOrder) => getWorkOrderDocumentWizardResolvedServiceItems(workOrder))
    .map((item) => getWorkOrderServiceValidityMonths(item))
    .filter(Boolean);

  return serviceValidityValues[0] || fallback;
}

function resolveWorkOrderDocumentValidityMonthsForWorkOrder(workOrder = {}, { fallback = "" } = {}) {
  return resolveServiceItemsDefaultValidityMonths(getWorkOrderDocumentWizardResolvedServiceItems(workOrder), { fallback });
}

