function renderProfileDialog() {
  const isOpen = Boolean(state.profileDialog.open && state.user);
  if (profileModalBackdrop) {
    profileModalBackdrop.hidden = !isOpen;
  }
  if (profileModal) {
    profileModal.hidden = !isOpen;
  }
  document.body.classList.toggle("is-profile-modal-open", isOpen);
}

function openProfileDialog() {
  if (!state.user) {
    return;
  }

  state.profileDialog.open = true;
  setUserMenuOpen(false);
  populateProfileForm();
  renderProfileDialog();
  window.requestAnimationFrame(() => {
    profileFirstNameInput?.focus({ preventScroll: true });
  });
}

function closeProfileDialog() {
  state.profileDialog.open = false;
  profileForm?.reset();
  profilePasswordForm?.reset();
  setInlineMessage(profileFeedback, "");
  setInlineMessage(profilePasswordFeedback, "");
  renderProfileDialog();
}

function buildProfilePayload() {
  const firstName = String(profileFirstNameInput?.value ?? "").trim();
  const lastName = String(profileLastNameInput?.value ?? "").trim();

  return {
    firstName,
    lastName,
    displayName: [firstName, lastName].filter(Boolean).join(" "),
    oib: String(profileOibInput?.value ?? "").trim(),
    phone: String(profilePhoneInput?.value ?? "").trim(),
    email: String(profileEmailInput?.value ?? "").trim(),
    education: String(profileEducationInput?.value ?? "").trim(),
    title: String(profileTitleInput?.value ?? "").trim(),
    address: String(profileAddressInput?.value ?? "").trim(),
    avatarDataUrl: String(profileAvatarDataUrlInput?.value ?? "").trim(),
  };
}

function buildProfileReportSchedulePayload() {
  return {
    enabled: Boolean(profileReportEnabledInput?.checked),
    time: String(profileReportTimeInput?.value || "07:00").trim() || "07:00",
  };
}

function setProfileFormBusy(isBusy) {
  profileForm?.classList.toggle("is-submitting", isBusy);
  profileForm?.querySelectorAll("input, textarea, button").forEach((control) => {
    control.disabled = isBusy;
  });

  if (profileSaveButton) {
    profileSaveButton.textContent = isBusy ? "Spremam..." : "Spremi profil";
  }
  if (!isBusy) {
    syncProfileReportScheduleControl();
  }
}

function setProfileReportBusy(isBusy) {
  if (profileSendReportButton) {
    profileSendReportButton.disabled = isBusy;
    profileSendReportButton.textContent = isBusy ? "Šaljem PDF..." : "Pošalji odmah";
  }
}

function setProfileReportScheduleBusy(isBusy) {
  if (profileReportSaveButton) {
    profileReportSaveButton.disabled = isBusy;
    profileReportSaveButton.textContent = isBusy ? "Spremam..." : "Spremi automatsko slanje";
  }
  if (profileReportEnabledInput) {
    profileReportEnabledInput.disabled = isBusy;
  }
  if (profileReportTimeInput) {
    profileReportTimeInput.disabled = isBusy || !profileReportEnabledInput?.checked;
  }
}

async function handleProfileSubmit(event) {
  event.preventDefault();
  const payload = buildProfilePayload();

  setInlineMessage(profileFeedback, "");

  if (!payload.email) {
    setInlineMessage(profileFeedback, "Email je obavezan.");
    return;
  }

  setProfileFormBusy(true);
  try {
    const success = await runMutation(() => apiRequest("/auth/profile", {
      method: "PATCH",
      body: payload,
    }), profileFeedback);

    if (success) {
      populateProfileForm();
      setInlineMessage(profileFeedback, "Profil je spremljen.", "success");
    }
  } finally {
    setProfileFormBusy(false);
    syncProfileAvatarPreview();
  }
}

async function handleProfileSendReport() {
  setInlineMessage(profileFeedback, "");
  setProfileReportBusy(true);

  try {
    const payload = await apiRequest("/auth/profile/report-email", {
      method: "POST",
    });
    setInlineMessage(profileFeedback, payload.message || "PDF izvještaj je poslan na email.", "success");
  } catch (error) {
    setInlineMessage(profileFeedback, error?.message || "Slanje izvještaja trenutno nije uspjelo.");
  } finally {
    setProfileReportBusy(false);
  }
}

async function handleProfileReportScheduleSave() {
  const payload = buildProfileReportSchedulePayload();
  setInlineMessage(profileFeedback, "");
  setProfileReportScheduleBusy(true);

  try {
    const success = await runMutation(() => apiRequest("/auth/profile/report-schedule", {
      method: "PATCH",
      body: payload,
    }), profileFeedback);

    if (success) {
      populateProfileForm();
      setInlineMessage(
        profileFeedback,
        payload.enabled
          ? `Automatsko slanje je uključeno svaki radni dan u ${payload.time} sati.`
          : "Automatsko slanje izvještaja je isključeno.",
        "success",
      );
    }
  } finally {
    setProfileReportScheduleBusy(false);
  }
}

function setProfilePasswordBusy(isBusy) {
  profilePasswordForm?.classList.toggle("is-submitting", isBusy);
  profilePasswordForm?.querySelectorAll("input, button").forEach((control) => {
    control.disabled = isBusy;
  });

  if (profilePasswordSubmitButton) {
    profilePasswordSubmitButton.textContent = isBusy ? "Spremam..." : "Promijeni lozinku";
  }
}

async function handleProfilePasswordSubmit(event) {
  event.preventDefault();

  const newPassword = String(profilePasswordNewInput?.value ?? "");
  const confirmPassword = String(profilePasswordConfirmInput?.value ?? "");
  const targetEmail = state.user?.email || String(profileEmailInput?.value ?? "").trim();
  setInlineMessage(profilePasswordFeedback, "");

  if (!newPassword) {
    setInlineMessage(profilePasswordFeedback, "Unesi novu lozinku.");
    return;
  }

  if (!meetsPasswordPolicy(newPassword)) {
    setInlineMessage(profilePasswordFeedback, PASSWORD_POLICY_MESSAGE);
    return;
  }

  if (newPassword !== confirmPassword) {
    setInlineMessage(profilePasswordFeedback, "Nova lozinka i potvrda moraju biti iste.");
    return;
  }

  setProfilePasswordBusy(true);

  try {
    await withGlobalLoading("Spremam novu lozinku...", async () => {
      const payload = await apiRequest("/auth/change-password", {
        method: "POST",
        body: {
          newPassword,
        },
      });

      closeProfileDialog();
      resetAuthenticatedWorkspaceState();
      if (loginEmailInput) {
        loginEmailInput.value = payload.email || targetEmail;
      }
      setInlineMessage(loginError, "Lozinka je promijenjena. Prijavi se ponovno novom lozinkom.", "success");
      renderAuthState();
    }, { immediate: true });
  } catch (error) {
    setInlineMessage(
      profilePasswordFeedback,
      error?.message || "Spremanje nove lozinke trenutno nije uspjelo. Pokušaj ponovno.",
    );
  } finally {
    setProfilePasswordBusy(false);
  }
}

function setUserPresenceMenuOpen(isOpen) {
  userPresenceMenuOpen = Boolean(isOpen && userMenuOpen && state.user);

  if (userMenuPresenceMenu) {
    userMenuPresenceMenu.hidden = !userPresenceMenuOpen;
  }

  if (userMenuPresenceButton) {
    userMenuPresenceButton.setAttribute("aria-expanded", userPresenceMenuOpen ? "true" : "false");
    userMenuPresenceButton.classList.toggle("is-open", userPresenceMenuOpen);
  }
}

function renderUserPresenceOptions(selectedPresence = readUserPresence()) {
  const selectedOption = USER_PRESENCE_OPTIONS.find((option) => option.value === selectedPresence) ?? USER_PRESENCE_OPTIONS[0];

  if (userMenuPresenceButton) {
    userMenuPresenceButton.dataset.presence = selectedOption.value;
  }

  if (userMenuPresenceLabel) {
    userMenuPresenceLabel.textContent = selectedOption.label;
  }

  if (!userMenuPresenceMenu) {
    return;
  }

  userMenuPresenceMenu.replaceChildren(...USER_PRESENCE_OPTIONS.map((option) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "user-presence-option";
    button.dataset.presence = option.value;
    button.classList.toggle("is-active", option.value === selectedPresence);
    button.setAttribute("role", "menuitemradio");
    button.setAttribute("aria-checked", option.value === selectedPresence ? "true" : "false");

    const dot = document.createElement("span");
    dot.className = "user-presence-dot";
    dot.setAttribute("aria-hidden", "true");

    const label = document.createElement("span");
    label.className = "user-presence-label";
    label.textContent = option.label;

    button.append(dot, label);
    button.addEventListener("click", () => {
      writeUserPresence(option.value);
      setUserPresenceMenuOpen(false);
      renderAuthState();
      void syncChatState({ silent: true, forcePresence: true });
    });
    return button;
  }));
}

function getChatPresenceValue() {
  return normalizeUserPresence(readUserPresence(state.user));
}

function clearChatPollTimer() {
  if (chatPollTimerId) {
    window.clearTimeout(chatPollTimerId);
    chatPollTimerId = null;
  }
}

function resetChatRenderSignatures() {
  chatConversationListRenderSignature = "";
  chatPeopleListRenderSignature = "";
  chatPeopleSummaryRenderSignature = "";
  chatThreadRenderSignature = "";
  chatThreadHeaderRenderSignature = "";
  chatPanelTabsRenderSignature = "";
  chatDesktopTabsRenderSignature = "";
  chatComposerRenderSignature = "";
  chatComposerSelectionRenderSignature = "";
  chatEmojiPickerRenderSignature = "";
}

function resetChatState() {
  clearChatPollTimer();
  chatSyncRequestSequence += 1;
  chatLastPresenceSyncAt = 0;
  chatLastPresenceValue = "";
  chatKnownMessageIds = new Set();
  chatNotificationBaselineReady = false;
  resetChatRenderSignatures();
  if (chatNotificationTimerId) {
    window.clearTimeout(chatNotificationTimerId);
    chatNotificationTimerId = null;
  }
  if (chatNotificationFadeTimerId) {
    window.clearTimeout(chatNotificationFadeTimerId);
    chatNotificationFadeTimerId = null;
  }
  if (chatToast) {
    chatToast.hidden = true;
    chatToast.classList.remove("is-hiding");
    chatToast.replaceChildren();
    chatToast.onclick = null;
  }
  state.chat.open = false;
  state.chat.tab = "people";
  state.chat.search = "";
  state.chat.conversations = [];
  state.chat.activeConversation = null;
  state.chat.users = [];
  state.chat.presenceByUserId = {};
  state.chat.activeConversationId = "";
  state.chat.dockedConversationIds = [];
  state.chat.archivedConversationIds = new Set();
  state.chat.hiddenDockConversationIds = new Set();
  state.chat.dockCollapsed = false;
  state.chat.panelMode = "hub";
  state.chat.composerOpen = false;
  state.chat.emojiPickerOpen = false;
  state.chat.contextMenu = null;
  state.chat.composerTitle = "";
  state.chat.composerParticipantIds = [];
  state.chat.unreadTotal = 0;
  state.chat.loaded = false;
  state.chat.loading = false;
  state.chat.sending = false;
  state.chat.error = "";
  state.chat.lastOrganizationId = "";
}

function setChatError(message = "") {
  state.chat.error = message;

  if (chatError) {
    chatError.textContent = message;
  }

  if (chatComposerError) {
    chatComposerError.textContent = message;
  }
}

function getChatConversationById(conversationId = state.chat.activeConversationId) {
  return state.chat.conversations.find((conversation) => String(conversation.id) === String(conversationId)) ?? null;
}

function getActiveChatConversation() {
  if (String(state.chat.activeConversation?.id ?? "") === String(state.chat.activeConversationId ?? "")) {
    return state.chat.activeConversation;
  }

  return null;
}

function updateActiveChatConversation(nextConversation) {
  state.chat.activeConversation = nextConversation && String(nextConversation.id ?? "")
    ? nextConversation
    : null;
}

function findChatConversationByParticipants(participantIds = []) {
  const signature = Array.from(new Set([state.user?.id, ...participantIds].filter(Boolean).map(String))).sort().join("|");
  return state.chat.conversations.find((conversation) => {
    const conversationSignature = Array.from(new Set((conversation.participantIds ?? []).map(String))).sort().join("|");
    return conversationSignature === signature;
  }) ?? null;
}

function formatChatTimestamp(value) {
  const parsedDate = parseDateValue(value);

  if (!parsedDate) {
    return "";
  }

  const nowDate = new Date();
  const sameDay = parsedDate.toDateString() === nowDate.toDateString();

  return sameDay
    ? new Intl.DateTimeFormat("hr-HR", { hour: "2-digit", minute: "2-digit" }).format(parsedDate)
    : formatCompactDate(value);
}

function buildChatPresenceLabel(status = "offline") {
  return USER_PRESENCE_OPTIONS.find((option) => option.value === status)?.label ?? "Offline";
}

function getChatPresenceSortRank(status = "offline") {
  const normalizedStatus = normalizeUserPresence(status);
  const optionIndex = USER_PRESENCE_OPTIONS.findIndex((option) => option.value === normalizedStatus);
  return optionIndex === -1 ? USER_PRESENCE_OPTIONS.length : optionIndex;
}

function getChatUserDisplayName(userLike = {}) {
  return String(userLike.fullName || userLike.email || "Kolega").trim() || "Kolega";
}

function getChatUserPresence(userId = "") {
  return state.chat.presenceByUserId[userId] ?? "offline";
}

function getChatConversationListSubtitle(conversation = {}, avatarPresence = "offline") {
  if (conversation.kind === "direct") {
    return buildChatPresenceLabel(avatarPresence);
  }

  return `${conversation.participants?.length ?? 0} sudionika`;
}

function createChatPresenceStatusLine(presence = "offline", className = "chat-person-status") {
  const line = document.createElement("div");
  line.className = className;
  line.dataset.presence = presence;
  line.textContent = buildChatPresenceLabel(presence);
  return line;
}

function groupChatUsersByPresence(people = []) {
  return USER_PRESENCE_OPTIONS
    .map((option) => ({
      key: option.value,
      label: option.label,
      items: people.filter((person) => getChatUserPresence(person.id) === option.value),
    }))
    .filter((section) => section.items.length > 0);
}

function createChatAvatar(userLike = {}, presence = "offline", className = "chat-person-avatar") {
  const avatar = document.createElement("span");
  avatar.className = className;
  renderAvatar(avatar, userLike);
  applyPresenceToAvatar(avatar, presence);
  return avatar;
}

function createChatChip(label) {
  const chip = document.createElement("span");
  chip.className = "chat-mini-chip";
  chip.textContent = label;
  return chip;
}

function applyEmojiShortcutsToChatInput() {
  if (!chatMessageInput) {
    return;
  }

  const originalValue = String(chatMessageInput.value ?? "");
  const selectionStart = chatMessageInput.selectionStart ?? originalValue.length;
  const selectionEnd = chatMessageInput.selectionEnd ?? originalValue.length;
  const normalizedValue = replaceEmojiShortcuts(originalValue)
    .replace(/\n{3,}/g, "\n\n");

  if (normalizedValue === originalValue) {
    return;
  }

  const normalizedStart = replaceEmojiShortcuts(originalValue.slice(0, selectionStart))
    .replace(/\n{3,}/g, "\n\n")
    .length;
  const normalizedEnd = replaceEmojiShortcuts(originalValue.slice(0, selectionEnd))
    .replace(/\n{3,}/g, "\n\n")
    .length;

  chatMessageInput.value = normalizedValue;
  chatMessageInput.setSelectionRange(normalizedStart, normalizedEnd);
}

function insertChatEmoji(emoji = "") {
  if (!chatMessageInput || !emoji) {
    return;
  }

  const start = chatMessageInput.selectionStart ?? chatMessageInput.value.length;
  const end = chatMessageInput.selectionEnd ?? start;
  const currentValue = String(chatMessageInput.value ?? "");
  const nextValue = `${currentValue.slice(0, start)}${emoji}${currentValue.slice(end)}`;
  chatMessageInput.value = nextValue;
  const nextCaret = start + emoji.length;
  chatMessageInput.focus();
  chatMessageInput.setSelectionRange(nextCaret, nextCaret);
  state.chat.emojiPickerOpen = false;
  renderChatDock();
}

function queueChatInputFocus({ moveCaretToEnd = true } = {}) {
  if (!chatMessageInput) {
    return;
  }

  if (chatInputFocusRafId) {
    window.cancelAnimationFrame(chatInputFocusRafId);
  }

  chatInputFocusRafId = window.requestAnimationFrame(() => {
    chatInputFocusRafId = window.requestAnimationFrame(() => {
      chatInputFocusRafId = 0;

      if (!state.chat.open || state.chat.panelMode !== "conversation") {
        return;
      }

      if (!state.chat.sending && chatMessageInput.disabled) {
        chatMessageInput.disabled = false;
      }

      if (chatMessageInput.disabled) {
        return;
      }

      chatMessageInput.focus({ preventScroll: true });

      if (moveCaretToEnd) {
        const cursor = chatMessageInput.value.length;
        chatMessageInput.setSelectionRange(cursor, cursor);
      }
    });
  });
}

function clearChatPanelInlinePosition() {
  if (!chatPanel) {
    return;
  }

  chatPanel.style.left = "";
  chatPanel.style.top = "";
  chatPanel.style.right = "";
  chatPanel.style.bottom = "";
}

function resolveChatPanelAnchorElement() {
  if (!state.chat.open) {
    return null;
  }

  if (state.chat.panelMode === "conversation" && state.chat.activeConversationId) {
    const activeConversationId = String(state.chat.activeConversationId);
    return chatDesktopTabs?.querySelector(".chat-desktop-tab.is-active")
      || Array.from(chatDesktopTabs?.querySelectorAll("[data-chat-conversation-id]") ?? [])
        .find((item) => String(item.dataset.chatConversationId) === activeConversationId)
      || chatLauncher;
  }

  return chatDesktopTabs?.querySelector(".chat-desktop-new-group") || chatLauncher;
}

function syncChatPanelPosition() {
  if (!chatPanel || chatPanel.hidden) {
    clearChatPanelInlinePosition();
    return;
  }

  if (window.innerWidth <= 640) {
    clearChatPanelInlinePosition();
    return;
  }

  const anchor = resolveChatPanelAnchorElement();
  if (!anchor) {
    clearChatPanelInlinePosition();
    return;
  }

  const anchorRect = anchor.getBoundingClientRect();
  const panelRect = chatPanel.getBoundingClientRect();
  const panelWidth = Math.max(panelRect.width, 320);
  const panelHeight = Math.max(panelRect.height, 320);
  const viewportPadding = 12;
  const preferredLeft = anchorRect.left + (anchorRect.width / 2) - (panelWidth / 2);
  const left = Math.min(
    window.innerWidth - panelWidth - viewportPadding,
    Math.max(viewportPadding, preferredLeft),
  );
  const top = Math.max(viewportPadding, anchorRect.top - panelHeight - 12);

  chatPanel.style.left = `${Math.round(left)}px`;
  chatPanel.style.top = `${Math.round(top)}px`;
  chatPanel.style.right = "auto";
  chatPanel.style.bottom = "auto";
}

function getChatDesktopTabsMaxScrollLeft(rail) {
  if (!rail) {
    return 0;
  }

  return Math.max(0, rail.scrollWidth - rail.clientWidth);
}

function getChatDesktopTabsStepSize(rail) {
  if (!rail) {
    return 0;
  }

  const firstTab = rail.querySelector(".chat-desktop-tab");
  const railStyles = window.getComputedStyle(rail);
  const gapValue = Number.parseFloat(railStyles.columnGap || railStyles.gap || "0") || 0;
  const tabWidth = firstTab?.getBoundingClientRect().width ?? 0;

  return Math.max(tabWidth + gapValue, rail.clientWidth * 0.72, 180);
}

function syncChatDesktopTabsNavState(rail) {
  if (!rail) {
    return;
  }

  const scroller = rail.closest(".chat-desktop-tabs-scroller");
  const previousButton = scroller?.querySelector('[data-chat-dock-nav="prev"]') ?? null;
  const nextButton = scroller?.querySelector('[data-chat-dock-nav="next"]') ?? null;
  const maxScrollLeft = getChatDesktopTabsMaxScrollLeft(rail);
  const canScroll = maxScrollLeft > 6;
  const currentScrollLeft = Math.min(maxScrollLeft, Math.max(0, rail.scrollLeft));

  scroller?.classList.toggle("is-scrollable", canScroll);

  if (previousButton) {
    previousButton.hidden = !canScroll;
    previousButton.disabled = !canScroll || currentScrollLeft <= 4;
  }

  if (nextButton) {
    nextButton.hidden = !canScroll;
    nextButton.disabled = !canScroll || currentScrollLeft >= maxScrollLeft - 4;
  }
}

function syncChatDesktopTabsScrollState(rail) {
  if (!rail) {
    return;
  }

  const maxScrollLeft = getChatDesktopTabsMaxScrollLeft(rail);
  chatDesktopTabsScrollLeft = Math.min(maxScrollLeft, Math.max(0, rail.scrollLeft));
  chatDesktopTabsPinnedToEnd = maxScrollLeft <= 6 || chatDesktopTabsScrollLeft >= maxScrollLeft - 4;
  syncChatDesktopTabsNavState(rail);
}

function restoreChatDesktopTabsRailPosition(rail, { ensureActive = false } = {}) {
  if (!rail) {
    return;
  }

  const maxScrollLeft = getChatDesktopTabsMaxScrollLeft(rail);
  rail.scrollLeft = chatDesktopTabsPinnedToEnd
    ? maxScrollLeft
    : Math.min(maxScrollLeft, Math.max(0, chatDesktopTabsScrollLeft));

  if (ensureActive) {
    const activeTab = rail.querySelector(".chat-desktop-tab.is-active");
    activeTab?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }

  syncChatDesktopTabsScrollState(rail);
}

function refreshChatDesktopTabsLayout(options = {}) {
  const rail = chatDesktopTabs?.querySelector(".chat-desktop-tabs-rail");
  if (!rail) {
    return;
  }

  restoreChatDesktopTabsRailPosition(rail, options);
}

function scrollChatDesktopTabs(rail, direction = 1) {
  if (!rail) {
    return;
  }

  const maxScrollLeft = getChatDesktopTabsMaxScrollLeft(rail);
  const nextScrollLeft = Math.min(
    maxScrollLeft,
    Math.max(0, rail.scrollLeft + (getChatDesktopTabsStepSize(rail) * direction)),
  );

  rail.scrollTo({
    left: nextScrollLeft,
    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth",
  });
}

function createChatDockNavButton(direction, rail) {
  const button = document.createElement("button");
  const isPrevious = direction < 0;

  button.type = "button";
  button.className = "chat-dock-nav";
  button.dataset.chatDockNav = isPrevious ? "prev" : "next";
  button.title = isPrevious ? "Prikaži starije razgovore" : "Prikaži novije razgovore";
  button.setAttribute("aria-label", button.title);
  button.innerHTML = `
    <svg class="icon-svg" viewBox="0 0 24 24" aria-hidden="true">
      <path d="${isPrevious ? "14.5 7l-5 5 5 5" : "9.5 7l5 5-5 5"}"></path>
    </svg>
  `;
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    scrollChatDesktopTabs(rail, isPrevious ? -1 : 1);
  });

  return button;
}

function queueChatPanelPositionSync() {
  if (chatPanelPositionRafId) {
    window.cancelAnimationFrame(chatPanelPositionRafId);
  }

  chatPanelPositionRafId = window.requestAnimationFrame(() => {
    chatPanelPositionRafId = 0;
    syncChatPanelPosition();
  });
}

function buildChatStorageScopeKey() {
  return [
    String(state.user?.id ?? "anonymous"),
    String(state.activeOrganizationId || state.chat.lastOrganizationId || "default"),
  ].join(":");
}

function getChatDockHiddenStorageKey() {
  return [CHAT_DOCK_HIDDEN_STORAGE_PREFIX, buildChatStorageScopeKey()].join(":");
}

function getChatDockedStorageKey() {
  return [CHAT_DOCKED_STORAGE_PREFIX, buildChatStorageScopeKey()].join(":");
}

function getChatArchivedStorageKey() {
  return [CHAT_ARCHIVED_STORAGE_PREFIX, buildChatStorageScopeKey()].join(":");
}

function getChatDockCollapsedStorageKey() {
  return [CHAT_DOCK_COLLAPSED_STORAGE_PREFIX, buildChatStorageScopeKey()].join(":");
}

function loadChatStorageArray(storageKey) {
  try {
    const rawValue = window.localStorage.getItem(storageKey);
    const parsed = rawValue ? JSON.parse(rawValue) : [];
    return Array.isArray(parsed)
      ? Array.from(new Set(parsed.map((value) => String(value || "").trim()).filter(Boolean)))
      : [];
  } catch {
    return [];
  }
}

function loadChatHiddenDockConversationIds() {
  return new Set(loadChatStorageArray(getChatDockHiddenStorageKey()));
}

function loadChatDockedConversationIds() {
  return loadChatStorageArray(getChatDockedStorageKey());
}

function loadChatArchivedConversationIds() {
  return new Set(loadChatStorageArray(getChatArchivedStorageKey()));
}

function loadChatDockCollapsedPreference() {
  try {
    return window.localStorage.getItem(getChatDockCollapsedStorageKey()) === "true";
  } catch {
    return false;
  }
}

function persistChatHiddenDockConversationIds() {
  try {
    window.localStorage.setItem(
      getChatDockHiddenStorageKey(),
      JSON.stringify(Array.from(state.chat.hiddenDockConversationIds ?? [])),
    );
  } catch {
    return;
  }
}

function persistChatDockedConversationIds() {
  try {
    window.localStorage.setItem(
      getChatDockedStorageKey(),
      JSON.stringify(state.chat.dockedConversationIds ?? []),
    );
  } catch {
    return;
  }
}

function persistChatDockCollapsedPreference() {
  try {
    window.localStorage.setItem(
      getChatDockCollapsedStorageKey(),
      state.chat.dockCollapsed ? "true" : "false",
    );
  } catch {
    return;
  }
}

function persistChatArchivedConversationIds() {
  try {
    window.localStorage.setItem(
      getChatArchivedStorageKey(),
      JSON.stringify(Array.from(state.chat.archivedConversationIds ?? [])),
    );
  } catch {
    return;
  }
}

function setChatDockCollapsed(isCollapsed, { render = true } = {}) {
  const nextValue = Boolean(isCollapsed);

  if (state.chat.dockCollapsed === nextValue) {
    return;
  }

  state.chat.dockCollapsed = nextValue;
  persistChatDockCollapsedPreference();
  resetChatRenderSignatures();

  if (render) {
    renderChatDock();
  }
}

function normalizeChatConversationIdList(values = []) {
  return Array.from(new Set(
    values.map((value) => String(value || "").trim()).filter(Boolean),
  ));
}

function pruneChatDockedConversationIds() {
  const availableConversationIds = new Set(
    state.chat.conversations
      .map((conversation) => String(conversation.id || "").trim())
      .filter(Boolean),
  );
  const nextDockedConversationIds = normalizeChatConversationIdList(state.chat.dockedConversationIds)
    .filter((conversationId) => (
      availableConversationIds.has(conversationId)
      && !state.chat.archivedConversationIds.has(conversationId)
    ));

  if (nextDockedConversationIds.join(",") === normalizeChatConversationIdList(state.chat.dockedConversationIds).join(",")) {
    return;
  }

  state.chat.dockedConversationIds = nextDockedConversationIds;
  persistChatDockedConversationIds();
}

function ensureChatConversationDocked(conversationId, { render = false } = {}) {
  const normalizedConversationId = String(conversationId ?? "");

  if (!normalizedConversationId) {
    return;
  }

  state.chat.archivedConversationIds.delete(normalizedConversationId);
  state.chat.dockedConversationIds = normalizeChatConversationIdList([
    ...state.chat.dockedConversationIds,
    normalizedConversationId,
  ]);
  persistChatArchivedConversationIds();
  persistChatDockedConversationIds();
  resetChatRenderSignatures();

  if (render) {
    renderChatDock();
  }
}

function removeChatConversationFromDock(conversationId, { render = true } = {}) {
  const normalizedConversationId = String(conversationId ?? "");

  if (!normalizedConversationId) {
    return;
  }

  const nextDockedConversationIds = state.chat.dockedConversationIds
    .map(String)
    .filter((conversationId) => conversationId !== normalizedConversationId);

  if (nextDockedConversationIds.length === state.chat.dockedConversationIds.length) {
    return;
  }

  state.chat.dockedConversationIds = nextDockedConversationIds;
  persistChatDockedConversationIds();

  if (String(state.chat.activeConversationId) === normalizedConversationId) {
    state.chat.activeConversationId = "";
    updateActiveChatConversation(null);
    state.chat.panelMode = "hub";
    state.chat.open = false;
  }

  resetChatRenderSignatures();

  if (render) {
    renderChatDock();
  }
}

function archiveChatConversationLocally(conversationId, { archived = true, render = true } = {}) {
  const normalizedConversationId = String(conversationId ?? "");

  if (!normalizedConversationId) {
    return;
  }

  if (archived) {
    state.chat.archivedConversationIds.add(normalizedConversationId);
    state.chat.dockedConversationIds = state.chat.dockedConversationIds
      .map(String)
      .filter((conversationId) => conversationId !== normalizedConversationId);
    if (String(state.chat.activeConversationId) === normalizedConversationId) {
      state.chat.activeConversationId = "";
      updateActiveChatConversation(null);
      state.chat.panelMode = "hub";
      state.chat.open = false;
    }
  } else {
    state.chat.archivedConversationIds.delete(normalizedConversationId);
  }

  persistChatArchivedConversationIds();
  persistChatDockedConversationIds();
  resetChatRenderSignatures();

  if (render) {
    renderChatDock();
  }
}

function getDockedChatConversations() {
  const conversationsById = new Map(
    state.chat.conversations.map((conversation) => [String(conversation.id), conversation]),
  );

  return normalizeChatConversationIdList(state.chat.dockedConversationIds)
    .map((conversationId) => conversationsById.get(conversationId))
    .filter(Boolean);
}

function buildChatConversationSignature(conversation = {}) {
  const lastMessage = conversation.lastMessage ?? {};
  return [
    conversation.id,
    conversation.kind,
    conversation.title,
    conversation.updatedAt,
    conversation.unreadCount,
    lastMessage.id,
    lastMessage.body,
    lastMessage.createdAt,
    (conversation.participantIds ?? []).join(","),
  ].join("|");
}

function groupChatConversations(conversations = []) {
  return [
    {
      key: "groups",
      label: "Grupe",
      items: conversations.filter((conversation) => conversation.kind === "group"),
    },
    {
      key: "direct",
      label: "Direktni razgovori",
      items: conversations.filter((conversation) => conversation.kind === "direct"),
    },
  ].filter((section) => section.items.length > 0);
}

function collectChatMessageIds(conversations = []) {
  const messageIds = new Set();

  conversations.forEach((conversation) => {
    if (conversation.lastMessage?.id) {
      messageIds.add(String(conversation.lastMessage.id));
    }
  });

  return messageIds;
}

function getLatestIncomingChatNotification(conversations = []) {
  const currentUserId = String(state.user?.id ?? "");
  let latestNotification = null;
  let latestTime = 0;

  conversations.forEach((conversation) => {
    const isVisibleActiveConversation = state.chat.open
      && String(conversation.id) === String(state.chat.activeConversationId);

    if (isVisibleActiveConversation) {
      return;
    }

    const message = conversation.lastMessage ?? null;
    const messageId = String(message?.id ?? "");

    if (!messageId || chatKnownMessageIds.has(messageId) || String(message?.authorId ?? "") === currentUserId) {
      return;
    }

    const messageTime = parseDateValue(message?.createdAt)?.getTime() ?? Date.now();
    if (messageTime >= latestTime) {
      latestTime = messageTime;
      latestNotification = { conversation, message };
    }
  });

  return latestNotification;
}

function hideChatNotificationToast() {
  if (chatNotificationTimerId) {
    window.clearTimeout(chatNotificationTimerId);
    chatNotificationTimerId = null;
  }
  if (chatNotificationFadeTimerId) {
    window.clearTimeout(chatNotificationFadeTimerId);
    chatNotificationFadeTimerId = null;
  }

  if (!chatToast) {
    return;
  }

  chatToast.hidden = true;
  chatToast.classList.remove("is-hiding");
  chatToast.replaceChildren();
  chatToast.onclick = null;
}

function showChatNotificationToast(notification) {
  if (!chatToast || !notification) {
    return;
  }

  const { conversation, message } = notification;
  const author = state.chat.users.find((user) => String(user.id) === String(message.authorId))
    ?? { id: message.authorId, fullName: message.authorName, avatarDataUrl: message.authorAvatarDataUrl };
  const avatar = createChatAvatar(author, state.chat.presenceByUserId[message.authorId] ?? "online", "chat-toast-avatar");

  const copy = document.createElement("span");
  copy.className = "chat-toast-copy";

  const titleRow = document.createElement("span");
  titleRow.className = "chat-toast-title-row";
  const title = document.createElement("strong");
  title.textContent = conversation.kind === "direct"
    ? (message.authorName || conversation.title || "Nova poruka")
    : `${message.authorName || "Kolega"} u ${conversation.title || "grupi"}`;
  titleRow.append(title);

  const unreadCount = Math.max(1, Number(conversation.unreadCount ?? 0));
  const count = document.createElement("span");
  count.className = "chat-toast-count";
  count.textContent = String(unreadCount);
  count.title = unreadCount === 1 ? "1 nova poruka" : `${unreadCount} novih poruka`;
  titleRow.append(count);

  const body = document.createElement("span");
  body.textContent = normalizeChatPreviewText(message.body || "Nova poruka");

  copy.append(titleRow, body);
  chatToast.replaceChildren(avatar, copy);
  chatToast.classList.remove("is-hiding");
  chatToast.hidden = false;
  chatToast.onclick = () => {
    hideChatNotificationToast();
    activateChatConversation(conversation.id);
  };

  if (chatNotificationTimerId) {
    window.clearTimeout(chatNotificationTimerId);
  }
  if (chatNotificationFadeTimerId) {
    window.clearTimeout(chatNotificationFadeTimerId);
    chatNotificationFadeTimerId = null;
  }

  chatNotificationTimerId = window.setTimeout(() => {
    if (!chatToast || chatToast.hidden) {
      hideChatNotificationToast();
      return;
    }

    chatToast.classList.add("is-hiding");
    chatNotificationFadeTimerId = window.setTimeout(() => {
      hideChatNotificationToast();
    }, 260);
  }, 5600);
}

function playChatNotificationSound() {
  const AudioContextConstructor = window.AudioContext || window.webkitAudioContext;

  if (!AudioContextConstructor) {
    return;
  }

  try {
    chatAudioContext = chatAudioContext || new AudioContextConstructor();

    const playTone = () => {
      const nowValue = chatAudioContext.currentTime;
      const oscillator = chatAudioContext.createOscillator();
      const gain = chatAudioContext.createGain();

      oscillator.type = "sine";
      oscillator.frequency.setValueAtTime(660, nowValue);
      oscillator.frequency.exponentialRampToValueAtTime(920, nowValue + 0.08);
      oscillator.frequency.setValueAtTime(760, nowValue + 0.16);
      gain.gain.setValueAtTime(0.0001, nowValue);
      gain.gain.exponentialRampToValueAtTime(0.18, nowValue + 0.025);
      gain.gain.exponentialRampToValueAtTime(0.0001, nowValue + 0.32);
      oscillator.connect(gain);
      gain.connect(chatAudioContext.destination);
      oscillator.start(nowValue);
      oscillator.stop(nowValue + 0.34);
    };

    if (chatAudioContext.state === "suspended") {
      chatAudioContext.resume().then(playTone).catch(() => {});
      return;
    }

    playTone();
  } catch {
    return;
  }
}

function handleChatIncomingNotifications(nextConversations = []) {
  const nextMessageIds = collectChatMessageIds(nextConversations);
  const shouldNotify = chatNotificationBaselineReady && state.chat.loaded;
  const notification = shouldNotify ? getLatestIncomingChatNotification(nextConversations) : null;

  chatKnownMessageIds = nextMessageIds;
  chatNotificationBaselineReady = true;

  if (!notification) {
    return;
  }

  showChatNotificationToast(notification);
  playChatNotificationSound();
}

function applyChatSnapshot(payload = {}) {
  const nextConversations = payload.conversations ?? [];
  const nextActiveConversation = payload.activeConversation ?? null;
  const nextOrganizationId = payload.organizationId ?? state.activeOrganizationId;

  if (String(state.chat.lastOrganizationId ?? "") !== String(nextOrganizationId ?? "")) {
    state.chat.dockedConversationIds = loadChatDockedConversationIds();
    state.chat.archivedConversationIds = loadChatArchivedConversationIds();
    state.chat.hiddenDockConversationIds = loadChatHiddenDockConversationIds();
    state.chat.dockCollapsed = loadChatDockCollapsedPreference();
    updateActiveChatConversation(null);
    resetChatRenderSignatures();
  }

  let archiveVisibilityChanged = false;
  nextConversations.forEach((conversation) => {
    if (Number(conversation.unreadCount ?? 0) > 0 && state.chat.archivedConversationIds.has(String(conversation.id))) {
      state.chat.archivedConversationIds.delete(String(conversation.id));
      archiveVisibilityChanged = true;
    }
  });

  if (archiveVisibilityChanged) {
    persistChatArchivedConversationIds();
    resetChatRenderSignatures();
  }

  const visibleConversations = nextConversations.filter((conversation) => (
    !state.chat.archivedConversationIds.has(String(conversation.id))
  ));

  handleChatIncomingNotifications(visibleConversations);

  state.chat.conversations = visibleConversations;
  state.chat.users = payload.users ?? [];
  state.chat.presenceByUserId = payload.presenceByUserId ?? {};
  state.chat.loaded = true;
  state.chat.lastOrganizationId = nextOrganizationId;
  state.chat.unreadTotal = state.chat.conversations.reduce((sum, conversation) => sum + Number(conversation.unreadCount ?? 0), 0);
  pruneChatDockedConversationIds();

  const hasActiveConversation = state.chat.conversations.some((conversation) => String(conversation.id) === String(state.chat.activeConversationId));

  if (!hasActiveConversation) {
    state.chat.activeConversationId = "";
  }

  const activeSummary = getChatConversationById(state.chat.activeConversationId);
  if (nextActiveConversation && String(nextActiveConversation.id ?? "") === String(state.chat.activeConversationId ?? "")) {
    updateActiveChatConversation({
      ...(activeSummary ?? {}),
      ...nextActiveConversation,
    });
  } else if (String(state.chat.activeConversation?.id ?? "") !== String(state.chat.activeConversationId ?? "")) {
    updateActiveChatConversation(null);
  } else if (state.chat.activeConversation && activeSummary) {
    updateActiveChatConversation({
      ...activeSummary,
      ...state.chat.activeConversation,
    });
  }

  renderChatDock();

  const activeConversation = getChatConversationById();
  if (state.chat.open && activeConversation && Number(activeConversation.unreadCount ?? 0) > 0) {
    void markChatConversationRead(activeConversation.id);
  }
}

function scheduleChatPoll(delay = CHAT_POLL_INTERVAL_MS) {
  clearChatPollTimer();

  if (!state.user || !state.activeOrganizationId) {
    return;
  }

  chatPollTimerId = window.setTimeout(() => {
    void syncChatState({ silent: true });
  }, delay);
}

async function syncChatState({
  silent = false,
  forcePresence = false,
  force = false,
  activeConversationId = state.chat.open ? state.chat.activeConversationId : "",
} = {}) {
  if (!state.user || !state.activeOrganizationId || (state.chat.loading && !force)) {
    return;
  }

  const requestSequence = ++chatSyncRequestSequence;
  state.chat.loading = true;

  const presenceValue = getChatPresenceValue();
  const normalizedActiveConversationId = String(activeConversationId ?? "").trim();
  const activeConversationQuery = normalizedActiveConversationId
    ? `?activeConversationId=${encodeURIComponent(normalizedActiveConversationId)}`
    : "";
  const shouldSyncPresence = forcePresence
    || !state.chat.loaded
    || state.chat.lastOrganizationId !== state.activeOrganizationId
    || presenceValue !== chatLastPresenceValue
    || (Date.now() - chatLastPresenceSyncAt) >= CHAT_PRESENCE_HEARTBEAT_MS;

  try {
    const payload = shouldSyncPresence
      ? await apiRequest("/chat/presence", {
        method: "POST",
        body: {
          status: presenceValue,
          activeConversationId: normalizedActiveConversationId,
        },
      })
      : await apiRequest(`/chat/bootstrap${activeConversationQuery}`);

    if (requestSequence !== chatSyncRequestSequence) {
      return;
    }

    if (shouldSyncPresence) {
      chatLastPresenceSyncAt = Date.now();
      chatLastPresenceValue = presenceValue;
    }

    setChatError("");
    applyChatSnapshot(payload);
  } catch (error) {
    if (requestSequence !== chatSyncRequestSequence) {
      return;
    }

    if (error.statusCode === 401) {
      resetChatState();
      state.user = null;
      renderAuthState();
      return;
    }

    if (!silent) {
      setChatError(error.message);
      renderChatDock();
    }
  } finally {
    if (requestSequence === chatSyncRequestSequence) {
      state.chat.loading = false;
      scheduleChatPoll();
    }
  }
}

function ensureChatContext() {
  if (!state.user || !state.activeOrganizationId) {
    resetChatState();
    renderChatDock();
    return;
  }

  if (!state.chat.loaded || state.chat.lastOrganizationId !== state.activeOrganizationId) {
    void syncChatState({ silent: true, forcePresence: true });
    return;
  }

  renderChatDock();
  scheduleChatPoll();
}

async function markChatConversationRead(conversationId = state.chat.activeConversationId) {
  const conversation = getChatConversationById(conversationId);

  if (!conversation || Number(conversation.unreadCount ?? 0) === 0) {
    return;
  }

  try {
    const payload = await apiRequest(`/chat/conversations/${conversation.id}/read`, {
      method: "POST",
      body: {
        activeConversationId: String(conversation.id ?? ""),
      },
    });
    applyChatSnapshot(payload);
  } catch {
    return;
  }
}

async function archiveChatConversation(conversationId = state.chat.activeConversationId) {
  const conversation = getChatConversationById(conversationId);

  if (!conversation) {
    return;
  }

  archiveChatConversationLocally(conversation.id, { render: true });

  try {
    const payload = await apiRequest(`/chat/conversations/${conversation.id}/archive`, {
      method: "POST",
      body: {
        archived: true,
      },
    });
    applyChatSnapshot(payload);
  } catch (error) {
    archiveChatConversationLocally(conversation.id, { archived: false, render: false });
    setChatError(error.message);
    renderChatDock();
  }
}

async function clearChatConversationHistory(conversationId = state.chat.activeConversationId) {
  const conversation = getChatConversationById(conversationId);

  if (!conversation) {
    return;
  }

  try {
    const payload = await apiRequest(`/chat/conversations/${conversation.id}/clear-history`, {
      method: "POST",
      body: {},
    });
    applyChatSnapshot(payload);
  } catch (error) {
    setChatError(error.message);
    renderChatDock();
  }
}

async function deleteChatConversation(conversationId = state.chat.activeConversationId) {
  const conversation = getChatConversationById(conversationId);

  if (!conversation) {
    return;
  }

  const isDeletingActiveConversation = String(conversation.id) === String(state.chat.activeConversationId);

  try {
    const payload = await apiRequest(`/chat/conversations/${conversation.id}`, {
      method: "DELETE",
      body: {},
    });
    applyChatSnapshot(payload);
    if (isDeletingActiveConversation) {
      state.chat.panelMode = "hub";
      state.chat.tab = "conversations";
      renderChatDock();
    }
  } catch (error) {
    setChatError(error.message);
    renderChatDock();
  }
}

function bindChatConversationDeleteShortcut(target, conversation) {
  if (!(target instanceof HTMLElement) || !conversation?.id) {
    return;
  }

  target.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openChatConversationMenu({
      conversationId: conversation.id,
      pointerX: event.clientX,
      pointerY: event.clientY,
    });
  });
}

function hideChatConversationMenu() {
  if (!chatConversationMenu) {
    return;
  }

  chatConversationMenu.hidden = true;
  chatConversationMenu.style.left = "";
  chatConversationMenu.style.top = "";
  chatConversationMenu.replaceChildren();
}

function closeChatConversationMenu({ render = true } = {}) {
  if (!state.chat.contextMenu) {
    hideChatConversationMenu();
    return;
  }

  state.chat.contextMenu = null;

  if (render) {
    renderChatDock();
    return;
  }

  hideChatConversationMenu();
}

function openChatConversationMenu({ conversationId = "", pointerX = 0, pointerY = 0 } = {}) {
  const conversation = getChatConversationById(conversationId);

  if (!conversation) {
    closeChatConversationMenu();
    return;
  }

  state.chat.contextMenu = {
    conversationId: String(conversation.id),
    x: Number(pointerX) || 0,
    y: Number(pointerY) || 0,
  };
  renderChatDock();
}

function renderChatConversationMenu() {
  if (!chatConversationMenu) {
    return;
  }

  const menuState = state.chat.contextMenu;
  if (!menuState) {
    hideChatConversationMenu();
    return;
  }

  const conversation = getChatConversationById(menuState.conversationId);
  if (!conversation) {
    state.chat.contextMenu = null;
    hideChatConversationMenu();
    return;
  }

  const body = document.createElement("div");
  body.className = "chat-conversation-menu-body";

  const kicker = document.createElement("span");
  kicker.className = "chat-conversation-menu-kicker";
  kicker.textContent = "Razgovor";

  const title = document.createElement("strong");
  title.className = "chat-conversation-menu-title";
  title.textContent = conversation.title || "Razgovor";

  const copy = document.createElement("p");
  copy.className = "chat-conversation-menu-copy";
  copy.textContent = "Stara povijest ovog razgovora maknut ce se samo tebi.";

  body.append(kicker, title, copy);

  const actions = document.createElement("div");
  actions.className = "chat-conversation-menu-actions";

  const cancelButton = document.createElement("button");
  cancelButton.type = "button";
  cancelButton.className = "ghost-button ghost-button-tiny";
  cancelButton.textContent = "Odustani";
  cancelButton.addEventListener("click", () => {
    closeChatConversationMenu();
  });

  const deleteButton = document.createElement("button");
  deleteButton.type = "button";
  deleteButton.className = "card-button card-danger ghost-button-tiny chat-conversation-menu-delete";
  deleteButton.textContent = "Izbrisi razgovor";
  deleteButton.addEventListener("click", () => {
    closeChatConversationMenu({ render: false });
    void deleteChatConversation(conversation.id);
  });

  actions.append(cancelButton, deleteButton);
  chatConversationMenu.replaceChildren(body, actions);
  chatConversationMenu.hidden = false;

  const viewportPadding = 12;
  const preferredLeft = (Number(menuState.x) || 0) + 10;
  const preferredTop = (Number(menuState.y) || 0) + 10;
  const menuRect = chatConversationMenu.getBoundingClientRect();
  const left = Math.max(
    viewportPadding,
    Math.min(preferredLeft, window.innerWidth - menuRect.width - viewportPadding),
  );
  const top = Math.max(
    viewportPadding,
    Math.min(preferredTop, window.innerHeight - menuRect.height - viewportPadding),
  );

  chatConversationMenu.style.left = `${Math.round(left)}px`;
  chatConversationMenu.style.top = `${Math.round(top)}px`;
}

function setChatComposerOpen(isOpen, { render = true } = {}) {
  state.chat.composerOpen = Boolean(isOpen);
  state.chat.emojiPickerOpen = false;
  state.chat.contextMenu = null;

  if (!state.chat.composerOpen) {
    state.chat.composerTitle = "";
    state.chat.composerParticipantIds = [];
    setChatError("");
  }

  if (render) {
    renderChatDock();
  }
}

function setChatOpen(isOpen) {
  state.chat.open = Boolean(isOpen);
  state.chat.emojiPickerOpen = false;
  state.chat.contextMenu = null;

  if (!state.chat.open) {
    setChatComposerOpen(false, { render: false });
    renderChatDock();
    return;
  }

  hideChatNotificationToast();

  if (!state.chat.loaded) {
    void syncChatState({
      silent: true,
      forcePresence: true,
      force: true,
      activeConversationId: state.chat.activeConversationId,
    });
  } else if (state.chat.activeConversationId) {
    const activeConversation = getChatConversationById(state.chat.activeConversationId);
    if (Number(activeConversation?.unreadCount ?? 0) > 0) {
      void markChatConversationRead(state.chat.activeConversationId);
    } else {
      void syncChatState({
        silent: true,
        force: true,
        activeConversationId: state.chat.activeConversationId,
      });
    }
  }

  renderChatDock();

  if (state.chat.panelMode === "conversation") {
    queueChatInputFocus();
  }
}

function openChatHub(tab = state.chat.tab || "people") {
  state.chat.tab = tab;
  state.chat.panelMode = "hub";
  state.chat.emojiPickerOpen = false;
  state.chat.contextMenu = null;
  setChatOpen(true);
}

function activateChatConversation(conversationId, { openPanel = true, markAsRead = true } = {}) {
  const conversation = getChatConversationById(conversationId);

  if (!conversation) {
    return;
  }

  ensureChatConversationDocked(conversation.id);
  state.chat.activeConversationId = conversation.id;
  state.chat.tab = "conversations";
  state.chat.panelMode = "conversation";
  state.chat.open = Boolean(openPanel);
  state.chat.emojiPickerOpen = false;
  state.chat.contextMenu = null;
  state.chat.composerOpen = false;
  state.chat.composerTitle = "";
  state.chat.composerParticipantIds = [];
  if (String(state.chat.activeConversation?.id ?? "") !== String(conversation.id)) {
    updateActiveChatConversation({
      ...conversation,
      messages: [],
    });
  }
  hideChatNotificationToast();
  renderChatDock();
  queueChatInputFocus();

  if (markAsRead && Number(conversation.unreadCount ?? 0) > 0) {
    void markChatConversationRead(conversation.id);
    return;
  }

  void syncChatState({
    silent: true,
    force: true,
    activeConversationId: conversation.id,
  });
}

function getFilteredChatConversations() {
  const query = state.chat.search.trim().toLowerCase();
  const baseConversations = state.chat.conversations.filter((conversation) => (
    !state.chat.archivedConversationIds.has(String(conversation.id))
  ));

  if (!query) {
    return baseConversations;
  }

  return baseConversations.filter((conversation) => {
    const haystack = [
      conversation.title,
      conversation.lastMessage?.body,
      ...(conversation.participants ?? []).map((participant) => participant.fullName || participant.email),
    ]
      .join(" ")
      .toLowerCase();

    return haystack.includes(query);
  });
}

function getFilteredChatUsers() {
  const query = state.chat.search.trim().toLowerCase();

  return state.chat.users
    .filter((user) => String(user.id) !== String(state.user?.id))
    .filter((user) => {
      if (!query) {
        return true;
      }

      const haystack = [user.fullName, user.email].join(" ").toLowerCase();
      return haystack.includes(query);
    })
    .sort((left, right) => {
      const leftPresence = getChatUserPresence(left.id);
      const rightPresence = getChatUserPresence(right.id);
      const leftRank = getChatPresenceSortRank(leftPresence);
      const rightRank = getChatPresenceSortRank(rightPresence);

      if (leftRank !== rightRank) {
        return leftRank - rightRank;
      }

      return getChatUserDisplayName(left).localeCompare(getChatUserDisplayName(right), "hr");
    });
}

function renderChatConversationList() {
  if (!chatConversationsView) {
    return;
  }

  const conversations = getFilteredChatConversations();
  const renderSignature = [
    state.chat.search,
    state.chat.activeConversationId,
    state.chat.tab,
    state.chat.dockedConversationIds.join(","),
    Array.from(state.chat.archivedConversationIds ?? []).sort().join(","),
    conversations.map((conversation) => [
      buildChatConversationSignature(conversation),
      (conversation.participants ?? [])
        .map((participant) => `${participant.id}:${getChatUserPresence(participant.id)}`)
        .join(","),
    ].join("|")).join("::"),
  ].join("~~");

  if (renderSignature === chatConversationListRenderSignature) {
    return;
  }

  chatConversationListRenderSignature = renderSignature;

  if (conversations.length === 0) {
    const empty = document.createElement("div");
    empty.className = "chat-empty-inline";
    empty.textContent = state.chat.search ? "Nema razgovora za zadani pojam." : "Još nema aktivnih razgovora.";
    chatConversationsView.replaceChildren(empty);
    return;
  }

  const nodes = [];

  groupChatConversations(conversations).forEach((section) => {
    const sectionHeader = document.createElement("div");
    sectionHeader.className = "chat-list-section-heading";
    sectionHeader.innerHTML = `<span>${section.label}</span><strong>${section.items.length}</strong>`;
    nodes.push(sectionHeader);

    section.items.forEach((conversation) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "chat-list-card";
      button.classList.toggle("is-active", String(conversation.id) === String(state.chat.activeConversationId));
      button.classList.toggle("is-unread", Number(conversation.unreadCount ?? 0) > 0);
      button.classList.toggle("is-docked", state.chat.dockedConversationIds.includes(String(conversation.id)));
      button.title = `Otvori ${conversation.title || "razgovor"} (desni klik za opcije)`;

      const head = document.createElement("div");
      head.className = "chat-list-card-head";

      const avatarSeed = conversation.participants.find((participant) => String(participant.id) !== String(state.user?.id))
        ?? conversation.participants[0]
        ?? { fullName: conversation.title };
      const avatarPresence = conversation.kind === "direct"
        ? (state.chat.presenceByUserId[avatarSeed.id] ?? "offline")
        : "online";
      const avatar = createChatAvatar(avatarSeed, avatarPresence, "chat-participant-avatar");

      const copy = document.createElement("div");
      copy.className = "chat-list-card-copy";

      const title = document.createElement("strong");
      title.textContent = conversation.title;

      const subtitle = document.createElement("span");
      subtitle.textContent = getChatConversationListSubtitle(conversation, avatarPresence);

      copy.append(title, subtitle);
      head.append(avatar, copy);

      if (conversation.unreadCount > 0) {
        const unread = document.createElement("span");
        unread.className = "chat-unread-badge";
        unread.textContent = String(conversation.unreadCount);
        head.append(unread);
      }

      const preview = document.createElement("p");
      preview.className = "chat-list-card-preview";
      preview.textContent = conversation.lastMessage?.body || "Bez poruka za sada.";

      button.append(head, preview);
      button.addEventListener("click", () => {
        activateChatConversation(conversation.id);
      });
      bindChatConversationDeleteShortcut(button, conversation);
      nodes.push(button);
    });
  });

  chatConversationsView.replaceChildren(...nodes);
}

function renderChatPeopleSummary() {
  if (!chatPeopleSummary) {
    return;
  }
  chatPeopleSummaryRenderSignature = "hidden";
  chatPeopleSummary.hidden = true;
  chatPeopleSummary.replaceChildren();
}

function renderChatPeopleList() {
  if (!chatPeopleView) {
    return;
  }

  const people = getFilteredChatUsers();
  const renderSignature = [
    state.chat.search,
    state.chat.tab,
    people.map((person) => [
      person.id,
      getChatUserDisplayName(person),
      getChatUserPresence(person.id),
    ].join("|")).join("::"),
  ].join("~~");

  if (renderSignature === chatPeopleListRenderSignature) {
    return;
  }

  chatPeopleListRenderSignature = renderSignature;

  if (people.length === 0) {
    const empty = document.createElement("div");
    empty.className = "chat-empty-inline";
    empty.textContent = state.chat.search ? "Nema kolega za taj pojam." : "Nema dostupnih kolega u organizaciji.";
    chatPeopleView.replaceChildren(empty);
    return;
  }

  const nodes = people.map((person) => {
    const presence = getChatUserPresence(person.id);
    const button = document.createElement("button");
    button.type = "button";
    button.className = "chat-person-card";
    button.dataset.presence = presence;
    button.title = `Pokreni chat s ${getChatUserDisplayName(person)}`;

    const head = document.createElement("div");
    head.className = "chat-person-card-head";
    head.append(createChatAvatar(person, presence, "chat-person-avatar"));

    const copy = document.createElement("div");
    copy.className = "chat-person-card-copy";
    const title = document.createElement("strong");
    title.textContent = getChatUserDisplayName(person);
    copy.append(title, createChatPresenceStatusLine(presence));
    head.append(copy);

    button.append(head);
    button.addEventListener("click", () => {
      void startDirectChatWithUser(person.id);
    });
    return button;
  });

  chatPeopleView.replaceChildren(...nodes);
}

function renderChatThread() {
  if (!chatThreadEmpty || !chatThreadView || !chatThreadMessages) {
    return;
  }

  const conversation = getActiveChatConversation();
  const messages = conversation?.messages ?? [];
  const lastMessage = messages[messages.length - 1] ?? {};
  const participantsPresenceSignature = (conversation?.participants ?? [])
    .map((participant) => `${participant.id}:${state.chat.presenceByUserId[participant.id] ?? "offline"}`)
    .join(",");
  const headerSignature = [
    conversation?.id ?? "",
    conversation?.title ?? "",
    participantsPresenceSignature,
  ].join("~~");
  const renderSignature = [
    conversation?.id ?? "",
    messages.length,
    lastMessage.id ?? "",
    lastMessage.createdAt ?? "",
  ].join("~~");

  chatThreadEmpty.hidden = Boolean(conversation);
  chatThreadView.hidden = !conversation;
  if (chatThreadArchiveButton) {
    chatThreadArchiveButton.disabled = !conversation;
  }
  if (chatThreadClearButton) {
    chatThreadClearButton.disabled = !conversation;
  }
  if (chatThreadMinimizeButton) {
    chatThreadMinimizeButton.disabled = !conversation;
  }

  if (!conversation) {
    if (renderSignature !== chatThreadRenderSignature) {
      chatThreadMessages.replaceChildren();
      chatThreadRenderSignature = renderSignature;
    }
    chatThreadHeaderRenderSignature = "";
    return;
  }

  if (headerSignature !== chatThreadHeaderRenderSignature) {
    if (chatThreadTitle) {
      chatThreadTitle.textContent = conversation.title;
    }

    if (chatThreadMeta) {
      const onlineCount = (conversation.participants ?? [])
        .filter((participant) => (state.chat.presenceByUserId[participant.id] ?? "offline") === "online")
        .length;
      chatThreadMeta.textContent = `${conversation.participants.length} sudionika · ${onlineCount} online`;
    }

    if (chatThreadArchiveButton) {
      chatThreadArchiveButton.title = `Arhiviraj ${conversation.title || "razgovor"}`;
      chatThreadArchiveButton.setAttribute("aria-label", `Arhiviraj ${conversation.title || "razgovor"}`);
    }

    if (chatThreadClearButton) {
      chatThreadClearButton.title = `Ocisti staru povijest za ${conversation.title || "razgovor"}`;
      chatThreadClearButton.setAttribute("aria-label", `Ocisti staru povijest za ${conversation.title || "razgovor"}`);
    }

    chatThreadHeaderRenderSignature = headerSignature;
  }

  if (renderSignature === chatThreadRenderSignature) {
    if (chatMessageInput) {
      chatMessageInput.disabled = state.chat.sending;
    }

    if (chatEmojiButton) {
      chatEmojiButton.disabled = state.chat.sending;
    }

    if (chatSendButton) {
      chatSendButton.disabled = state.chat.sending;
    }

    return;
  }

  const [previousConversationId = "", , previousLastMessageId = ""] = chatThreadRenderSignature.split("~~");
  const currentConversationId = String(conversation.id ?? "");
  const currentLastMessageId = String(lastMessage.id ?? "");
  const previousScrollTop = chatThreadMessages.scrollTop;
  const isNearBottom = (chatThreadMessages.scrollHeight - chatThreadMessages.scrollTop - chatThreadMessages.clientHeight) <= 72;
  const shouldAutoScroll = previousConversationId !== currentConversationId
    || (previousLastMessageId !== currentLastMessageId
      && (isNearBottom || String(lastMessage.authorId ?? "") === String(state.user?.id ?? "")));

  chatThreadRenderSignature = renderSignature;

  chatThreadMessages.replaceChildren(...messages.map((message) => {
    const row = document.createElement("div");
    row.className = "chat-message-row";
    const isOwn = String(message.authorId) === String(state.user?.id);
    row.classList.toggle("is-own", isOwn);

    if (!isOwn) {
      const author = state.chat.users.find((user) => String(user.id) === String(message.authorId))
        ?? { id: message.authorId, fullName: message.authorName, avatarDataUrl: message.authorAvatarDataUrl };
      row.append(createChatAvatar(author, state.chat.presenceByUserId[message.authorId] ?? "offline", "chat-participant-avatar"));
    }

    const bubble = document.createElement("div");
    bubble.className = "chat-message-bubble";

    const meta = document.createElement("div");
    meta.className = "chat-message-meta";
    const authorName = document.createElement("strong");
    authorName.textContent = isOwn ? "Vi" : (message.authorName || "Kolega");
    const time = document.createElement("span");
    time.textContent = formatChatTimestamp(message.createdAt);
    meta.append(authorName, time);

    const body = document.createElement("p");
    body.className = "chat-message-body";
    body.textContent = message.body;

    bubble.append(meta, body);
    row.append(bubble);
    return row;
  }));

  if (chatMessageInput) {
    chatMessageInput.disabled = state.chat.sending;
  }

  if (chatEmojiButton) {
    chatEmojiButton.disabled = state.chat.sending;
  }

  if (chatSendButton) {
    chatSendButton.disabled = state.chat.sending;
  }

  if (shouldAutoScroll) {
    window.requestAnimationFrame(() => {
      chatThreadMessages.scrollTop = chatThreadMessages.scrollHeight;
    });
  } else {
    window.requestAnimationFrame(() => {
      chatThreadMessages.scrollTop = previousScrollTop;
    });
  }
}

function createChatConversationTabNode(conversation, { desktop = false } = {}) {
  const item = document.createElement("div");
  item.className = desktop ? "chat-desktop-tab" : "chat-thread-tab";
  item.dataset.chatConversationId = String(conversation.id ?? "");
  item.classList.toggle("is-active", String(conversation.id) === String(state.chat.activeConversationId));
  item.classList.toggle("is-unread", Number(conversation.unreadCount ?? 0) > 0);

  const openButton = document.createElement("button");
  openButton.type = "button";
  openButton.className = desktop ? "chat-desktop-tab-main" : "chat-thread-tab-main";
  openButton.title = conversation.title || "Razgovor";

  const icon = document.createElement("span");
  icon.className = `${desktop ? "chat-desktop-tab-icon" : "chat-thread-tab-icon"} is-${conversation.kind || "group"}`;
  icon.textContent = conversation.kind === "direct" ? "1:1" : "G";

  const copy = document.createElement("span");
  copy.className = desktop ? "chat-desktop-tab-copy" : "chat-thread-tab-copy";
  const title = document.createElement("strong");
  title.textContent = conversation.title || "Razgovor";
  const subtitle = document.createElement("span");
  subtitle.textContent = conversation.lastMessage
    ? normalizeChatPreviewText(conversation.lastMessage.body || formatChatTimestamp(conversation.lastMessage.createdAt))
    : `${conversation.participants?.length ?? 0} sudionika`;
  copy.append(title, subtitle);
  openButton.append(icon, copy);
  openButton.addEventListener("click", () => {
    const isCurrentConversation = String(conversation.id) === String(state.chat.activeConversationId);
    if (desktop && isCurrentConversation && state.chat.open && state.chat.panelMode === "conversation") {
      setChatOpen(false);
      return;
    }
    activateChatConversation(conversation.id);
  });

  item.append(openButton);

  if (Number(conversation.unreadCount ?? 0) > 0) {
    const unread = document.createElement("span");
    unread.className = desktop ? "chat-desktop-tab-unread" : "chat-thread-tab-unread";
    unread.textContent = String(conversation.unreadCount);
    item.append(unread);
  }

  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = desktop ? "chat-desktop-tab-close" : "chat-thread-tab-close";
  closeButton.setAttribute("aria-label", `Makni ${conversation.title || "razgovor"} iz donje trake`);
  closeButton.title = "Makni iz donje trake";
  closeButton.textContent = "×";
  closeButton.addEventListener("click", (event) => {
    event.stopPropagation();
    removeChatConversationFromDock(conversation.id);
  });
  item.append(closeButton);
  bindChatConversationDeleteShortcut(item, conversation);

  return item;
}

function renderChatConversationTabs() {
  const dockedConversations = getDockedChatConversations();
  const signatureParts = [
    state.chat.activeConversationId,
    state.chat.dockCollapsed ? "collapsed" : "expanded",
    state.chat.dockedConversationIds.join(","),
    dockedConversations.map(buildChatConversationSignature).join("::"),
  ];

  if (chatThreadTabs) {
    const panelSignature = signatureParts.join("~~");

    if (dockedConversations.length === 0) {
      chatThreadTabs.hidden = true;
      if (chatPanelTabsRenderSignature !== panelSignature) {
        chatThreadTabs.replaceChildren();
        chatPanelTabsRenderSignature = panelSignature;
      }
    } else if (panelSignature !== chatPanelTabsRenderSignature) {
      chatThreadTabs.hidden = false;

      const label = document.createElement("span");
      label.className = "chat-thread-tabs-label";
      label.textContent = "Razgovori";

      const rail = document.createElement("div");
      rail.className = "chat-thread-tabs-rail";
      rail.addEventListener("scroll", queueChatPanelPositionSync, { passive: true });
      dockedConversations.forEach((conversation) => {
        rail.append(createChatConversationTabNode(conversation));
      });

      chatThreadTabs.replaceChildren(label, rail);
      chatPanelTabsRenderSignature = panelSignature;
    } else {
      chatThreadTabs.hidden = false;
    }
  }

  if (!chatDesktopTabs) {
    return;
  }

  const desktopSignature = signatureParts.join("~~");

  if (dockedConversations.length === 0 || state.chat.dockCollapsed) {
    chatDesktopTabs.hidden = true;
    if (chatDesktopTabsRenderSignature !== desktopSignature) {
      if (dockedConversations.length === 0) {
        chatDesktopTabs.replaceChildren();
        chatDesktopTabsScrollLeft = 0;
        chatDesktopTabsPinnedToEnd = true;
      }
      chatDesktopTabsRenderSignature = desktopSignature;
    }
    return;
  }

  if (desktopSignature === chatDesktopTabsRenderSignature) {
    chatDesktopTabs.hidden = false;
    window.requestAnimationFrame(() => {
      refreshChatDesktopTabsLayout({ ensureActive: true });
    });
    return;
  }

  const rail = document.createElement("div");
  rail.className = "chat-desktop-tabs-rail";
  rail.addEventListener("scroll", () => {
    syncChatDesktopTabsScrollState(rail);
    queueChatPanelPositionSync();
  }, { passive: true });
  dockedConversations.forEach((conversation) => {
    rail.append(createChatConversationTabNode(conversation, { desktop: true }));
  });

  const previousButton = createChatDockNavButton(-1, rail);
  const nextButton = createChatDockNavButton(1, rail);
  const scroller = document.createElement("div");
  scroller.className = "chat-desktop-tabs-scroller";
  scroller.append(previousButton, rail, nextButton);

  const newGroupButton = document.createElement("button");
  newGroupButton.type = "button";
  newGroupButton.className = "chat-desktop-new-group";
  newGroupButton.textContent = "+ Grupa";
  newGroupButton.addEventListener("click", () => {
    state.chat.tab = "people";
    state.chat.panelMode = "hub";
    state.chat.open = true;
    setChatDockCollapsed(false, { render: false });
    setChatComposerOpen(true);
  });

  const dockToggleButton = document.createElement("button");
  dockToggleButton.type = "button";
  dockToggleButton.className = "chat-dock-toggle";
  dockToggleButton.title = "Sakrij donju traku razgovora";
  dockToggleButton.setAttribute("aria-label", "Sakrij donju traku razgovora");
  dockToggleButton.innerHTML = `
    <svg class="icon-svg" viewBox="0 0 24 24" aria-hidden="true">
      <path d="M7 10l5 5 5-5"></path>
    </svg>
  `;
  dockToggleButton.addEventListener("click", (event) => {
    event.stopPropagation();
    setChatDockCollapsed(true);
  });

  const actions = document.createElement("div");
  actions.className = "chat-desktop-tabs-actions";
  actions.append(newGroupButton, dockToggleButton);

  chatDesktopTabs.hidden = false;
  chatDesktopTabs.replaceChildren(scroller, actions);
  chatDesktopTabsRenderSignature = desktopSignature;
  window.requestAnimationFrame(() => {
    restoreChatDesktopTabsRailPosition(rail, { ensureActive: true });
    queueChatPanelPositionSync();
  });
}

function renderChatComposer() {
  if (!chatComposer) {
    return;
  }

  chatComposer.hidden = !state.chat.composerOpen;

  if (!state.chat.composerOpen) {
    chatComposerRenderSignature = "";
    return;
  }

  if (chatComposerTitleInput && chatComposerTitleInput.value !== state.chat.composerTitle) {
    chatComposerTitleInput.value = state.chat.composerTitle;
  }

  if (chatComposerCreateButton) {
    chatComposerCreateButton.disabled = state.chat.composerParticipantIds.length === 0;
  }

  if (!chatComposerUsers) {
    return;
  }

  const availableUsers = state.chat.users.filter((user) => String(user.id) !== String(state.user?.id));
  const renderSignature = availableUsers.map((user) => [
    user.id,
    user.fullName,
    user.email,
    user.avatarDataUrl,
    state.chat.presenceByUserId[user.id] ?? "offline",
  ].join("|")).join("::");

  if (renderSignature === chatComposerRenderSignature) {
    syncChatComposerSelectionState(availableUsers);
    return;
  }

  chatComposerRenderSignature = renderSignature;
  chatComposerSelectionRenderSignature = "";
  const previousScrollTop = chatComposerUsers.scrollTop;

  if (availableUsers.length === 0) {
    const empty = document.createElement("div");
    empty.className = "chat-empty-inline";
    empty.textContent = "Trenutno nema drugih korisnika u aktivnoj organizaciji.";
    chatComposerUsers.replaceChildren(empty);
    return;
  }

  const selectedCount = state.chat.composerParticipantIds.length;
  const summary = document.createElement("div");
  summary.className = "chat-composer-users-summary";
  summary.innerHTML = `<strong>${selectedCount}</strong> odabrano od ${availableUsers.length} dostupnih korisnika`;

  const userCards = availableUsers.map((user) => {
    const label = document.createElement("label");
    label.className = "chat-composer-user";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.value = user.id;
    checkbox.addEventListener("change", () => {
      const nextIds = new Set(state.chat.composerParticipantIds);
      if (checkbox.checked) {
        nextIds.add(user.id);
      } else {
        nextIds.delete(user.id);
      }
      state.chat.composerParticipantIds = Array.from(nextIds);
      syncChatComposerSelectionState(availableUsers);
    });

    const checkMark = document.createElement("span");
    checkMark.className = "chat-composer-check";
    checkMark.textContent = "✓";

    const avatar = createChatAvatar(user, state.chat.presenceByUserId[user.id] ?? "offline", "chat-person-avatar");
    const copy = document.createElement("span");
    copy.className = "chat-composer-user-copy";
    const title = document.createElement("strong");
    title.textContent = getChatUserDisplayName(user);
    const subtitle = document.createElement("span");
    subtitle.textContent = buildChatPresenceLabel(getChatUserPresence(user.id));
    copy.append(title, subtitle);

    label.append(checkbox, checkMark, avatar, copy);
    return label;
  });

  chatComposerUsers.replaceChildren(summary, ...userCards);
  chatComposerUsers.scrollTop = previousScrollTop;
  syncChatComposerSelectionState(availableUsers);
}

function syncChatComposerSelectionState(availableUsers = state.chat.users.filter((user) => String(user.id) !== String(state.user?.id))) {
  if (!chatComposerUsers || !chatComposerCreateButton) {
    return;
  }

  const selectedIds = new Set(state.chat.composerParticipantIds.map(String));
  const selectionSignature = [
    availableUsers.length,
    Array.from(selectedIds).sort().join(","),
  ].join("~~");

  if (selectionSignature === chatComposerSelectionRenderSignature) {
    chatComposerCreateButton.disabled = state.chat.composerParticipantIds.length === 0;
    return;
  }

  chatComposerSelectionRenderSignature = selectionSignature;

  const summary = chatComposerUsers.querySelector(".chat-composer-users-summary");
  if (summary) {
    summary.innerHTML = `<strong>${selectedIds.size}</strong> odabrano od ${availableUsers.length} dostupnih korisnika`;
  }

  chatComposerUsers.querySelectorAll(".chat-composer-user").forEach((label) => {
    const userId = String(label.querySelector("input")?.value ?? "");
    const isSelected = selectedIds.has(userId);
    label.classList.toggle("is-selected", isSelected);
    const checkbox = label.querySelector("input");
    if (checkbox) {
      checkbox.checked = isSelected;
    }
  });

  chatComposerCreateButton.disabled = state.chat.composerParticipantIds.length === 0;
}

function renderChatEmojiPicker() {
  if (!chatEmojiPicker) {
    return;
  }

  const shouldShow = state.chat.open
    && state.chat.panelMode === "conversation"
    && Boolean(getActiveChatConversation())
    && state.chat.emojiPickerOpen;

  chatEmojiPicker.hidden = !shouldShow;

  if (!shouldShow) {
    chatEmojiPickerRenderSignature = "";
    return;
  }

  const renderSignature = CHAT_EMOJI_SHORTCUTS
    .map((entry) => `${entry.emoji}:${entry.label}:${entry.shortcuts.join(",")}`)
    .join("::");

  if (renderSignature === chatEmojiPickerRenderSignature) {
    return;
  }

  chatEmojiPicker.replaceChildren(...CHAT_EMOJI_SHORTCUTS.map((entry) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "chat-emoji-option";
    button.title = entry.shortcuts.length > 0
      ? `${entry.label} (${entry.shortcuts.join(", ")})`
      : entry.label;

    const emoji = document.createElement("span");
    emoji.className = "chat-emoji-option-symbol";
    emoji.textContent = entry.emoji;

    const label = document.createElement("span");
    label.className = "chat-emoji-option-label";
    label.textContent = entry.label;

    button.append(emoji, label);
    button.addEventListener("click", () => {
      insertChatEmoji(entry.emoji);
    });
    return button;
  }));

  chatEmojiPickerRenderSignature = renderSignature;
}

function renderChatDock() {
  const authenticated = Boolean(state.user);

  if (chatDock) {
    chatDock.hidden = !authenticated;
  }

  if (!authenticated) {
    return;
  }

  const currentPresence = getChatPresenceValue();
  const dockedConversations = getDockedChatConversations();
  const hasDockedConversations = dockedConversations.length > 0;
  const canExpandCollapsedDock = hasDockedConversations && state.chat.dockCollapsed;

  if (chatLauncherPresence) {
    chatLauncherPresence.dataset.presence = currentPresence;
  }

  if (chatLauncherCaption) {
    chatLauncherCaption.textContent = state.chat.unreadTotal > 0
      ? `${state.chat.unreadTotal} novih poruka`
      : "Chat aktivan";
  }

  if (chatLauncherUnread) {
    chatLauncherUnread.hidden = state.chat.unreadTotal <= 0;
    chatLauncherUnread.textContent = String(state.chat.unreadTotal);
  }

  if (chatLauncher) {
    chatLauncher.setAttribute("aria-expanded", state.chat.open ? "true" : "false");
    chatLauncher.classList.toggle("has-unread", state.chat.unreadTotal > 0);
    chatLauncher.classList.toggle("is-dock-collapsed", canExpandCollapsedDock);
    chatLauncher.title = canExpandCollapsedDock
      ? "Prosiri donju traku razgovora"
      : state.chat.open
        ? "Minimiziraj chat"
        : hasDockedConversations
          ? "Otvori communicator"
          : "Otvori chat";
    chatLauncher.setAttribute("aria-label", chatLauncher.title);
  }

  if (chatPanel) {
    chatPanel.hidden = !state.chat.open;
    chatPanel.dataset.mode = state.chat.panelMode || "hub";
  }

  if (chatCloseButton) {
    chatCloseButton.setAttribute("aria-label", "Minimiziraj chat");
    chatCloseButton.title = "Minimiziraj";
  }

  chatTabButtons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.chatTab === state.chat.tab);
  });

  if (chatConversationsView) {
    chatConversationsView.hidden = state.chat.tab !== "conversations";
  }

  if (chatPeopleView) {
    chatPeopleView.hidden = state.chat.tab !== "people";
  }

  if (chatSearchInput && chatSearchInput.value !== state.chat.search) {
    chatSearchInput.value = state.chat.search;
  }

  if (chatSearchInput) {
    const nextPlaceholder = state.chat.tab === "people"
      ? "Pretraži korisnike"
      : "Pretraži razgovore";
    chatSearchInput.placeholder = nextPlaceholder;
    chatSearchInput.setAttribute("aria-label", nextPlaceholder);
  }

  if (chatListCaption) {
    chatListCaption.textContent = state.chat.tab === "people"
      ? "Tko je online, away, busy ili offline i kome možeš odmah pisati."
      : "Aktivni razgovori i zadnje poruke tima.";
  }

  const isConversationMode = state.chat.panelMode === "conversation";
  const shouldRenderPanelContents = state.chat.open || state.chat.composerOpen;
  setChatError(state.chat.error);
  renderChatConversationTabs();
  renderChatConversationMenu();

  if (!shouldRenderPanelContents) {
    if (chatPeopleSummary) {
      chatPeopleSummary.hidden = true;
    }
    if (chatEmojiPicker) {
      chatEmojiPicker.hidden = true;
    }
    queueChatPanelPositionSync();
    return;
  }

  if (!isConversationMode) {
    renderChatPeopleSummary();
    renderChatConversationList();
    renderChatPeopleList();
  }
  if (isConversationMode) {
    renderChatThread();
  }
  renderChatComposer();
  if (isConversationMode) {
    renderChatEmojiPicker();
  } else if (chatEmojiPicker) {
    chatEmojiPicker.hidden = true;
  }
  queueChatPanelPositionSync();
}

async function startDirectChatWithUser(userId) {
  try {
    setChatError("");
    const payload = await apiRequest("/chat/conversations", {
      method: "POST",
      body: {
        participantIds: [userId],
      },
    });
    applyChatSnapshot(payload);
    const conversation = payload.activeConversation
      ?? findChatConversationByParticipants([userId]);
    if (conversation) {
      activateChatConversation(conversation.id, { markAsRead: false });
    }
  } catch (error) {
    setChatError(error.message);
    renderChatDock();
  }
}

async function createChatGroupConversation() {
  try {
    setChatError("");
    const payload = await apiRequest("/chat/conversations", {
      method: "POST",
      body: {
        title: state.chat.composerTitle,
        participantIds: state.chat.composerParticipantIds,
      },
    });
    applyChatSnapshot(payload);
    const participantSignature = Array.from(new Set([state.user?.id, ...state.chat.composerParticipantIds].filter(Boolean).map(String))).sort().join("|");
    const conversation = payload.activeConversation
      ?? state.chat.conversations.find((item) => Array.from(new Set((item.participantIds ?? []).map(String))).sort().join("|") === participantSignature)
      ?? state.chat.conversations[0]
      ?? null;
    setChatComposerOpen(false);
    if (conversation) {
      activateChatConversation(conversation.id, { markAsRead: false });
    } else {
      setChatOpen(true);
      renderChatDock();
    }
  } catch (error) {
    setChatError(error.message);
    renderChatDock();
  }
}

async function sendChatMessage() {
  const conversation = getChatConversationById();
  const messageBody = normalizeChatMessageBody(chatMessageInput?.value ?? "");

  if (!conversation || !messageBody) {
    return;
  }

  state.chat.sending = true;
  state.chat.emojiPickerOpen = false;
  renderChatDock();

  try {
    const payload = await apiRequest(`/chat/conversations/${conversation.id}/messages`, {
      method: "POST",
      body: { body: messageBody },
    });
    if (chatMessageInput) {
      chatMessageInput.value = "";
    }
    applyChatSnapshot(payload);
  } catch (error) {
    setChatError(error.message);
    if (chatMessageInput) {
      chatMessageInput.value = messageBody;
    }
  } finally {
    state.chat.sending = false;
    renderChatDock();
    queueChatInputFocus();
  }
}

