function createBadge(text, className = "") {
  const badge = document.createElement("span");
  badge.className = ["badge", className].filter(Boolean).join(" ");
  badge.textContent = text;
  return badge;
}

function joinParts(values, separator = " | ") {
  return values.filter(Boolean).join(separator);
}

function isClosedWorkOrder(status) {
  return ["Gotov RN", "Ovjeren RN", "Fakturiran RN", "Storno RN"].includes(String(status ?? ""));
}

function isOverdueWorkOrder(item) {
  if (!item?.dueDate || isClosedWorkOrder(item.status)) {
    return false;
  }

  return item.dueDate < new Date().toISOString().slice(0, 10);
}

function getOptionLabel(options, value) {
  return options.find((option) => option.value === value)?.label ?? value;
}

function resetWorkOrderActivityState() {
  state.workOrderActivity = {
    workOrderId: "",
    loading: false,
    items: [],
    error: "",
  };
  if (workOrderActivityCommentInput) {
    workOrderActivityCommentInput.value = "";
  }
  if (workOrderActivityMentionUserInput) {
    workOrderActivityMentionUserInput.value = "";
  }
  if (workOrderActivityCommentError) {
    workOrderActivityCommentError.textContent = "";
    workOrderActivityCommentError.hidden = true;
  }
  renderWorkOrderActivity();
}

function renderWorkOrderActivityCommentControls() {
  const hasWorkOrder = Boolean(state.workOrderActivity.workOrderId || workOrderIdInput?.value);

  if (workOrderActivityMentionUserInput instanceof HTMLSelectElement) {
    const currentValue = workOrderActivityMentionUserInput.value;
    const userOptions = (state.users ?? [])
      .filter((user) => user?.isActive !== false)
      .slice()
      .sort((left, right) => getUserDisplayLabel(left).localeCompare(getUserDisplayLabel(right), "hr"))
      .map((user) => ({
        value: String(user.id),
        label: `@${getUserDisplayLabel(user)}`,
      }));
    replaceSelectOptions(workOrderActivityMentionUserInput, [
      { value: "", label: "Bez taga" },
      ...userOptions,
    ], currentValue);
    workOrderActivityMentionUserInput.disabled = !hasWorkOrder || userOptions.length === 0;
  }

  if (workOrderActivityCommentInput) {
    workOrderActivityCommentInput.disabled = !hasWorkOrder;
    workOrderActivityCommentInput.placeholder = hasWorkOrder
      ? "Napiši komentar... koristi @ime za tagiranje"
      : "Prvo otvori ili spremi RN za komentare.";
  }

  if (workOrderActivityCommentAddButton) {
    workOrderActivityCommentAddButton.disabled = !hasWorkOrder;
  }
}

function getWorkOrderActivityMentionUserId(message = "") {
  const normalizedMessage = normalizeLooseName(String(message || "").replace(/@/g, " mention "));
  if (!normalizedMessage.includes("mention ")) {
    return "";
  }

  const activeUsers = (state.users ?? [])
    .filter((user) => user?.isActive !== false)
    .sort((left, right) => getUserDisplayLabel(right).length - getUserDisplayLabel(left).length);

  for (const user of activeUsers) {
    const label = normalizeLooseName(getUserDisplayLabel(user));
    const firstToken = label.split(" ")[0] || "";
    const emailToken = normalizeLooseName(user.email || "");
    const candidates = [label, firstToken, emailToken]
      .filter(Boolean)
      .map((candidate) => `mention ${candidate}`);
    if (candidates.some((candidate) => normalizedMessage.includes(candidate))) {
      return String(user.id || "");
    }
  }

  return "";
}

function appendWorkOrderActivityTextWithMentions(target, text = "") {
  const source = String(text || "");
  const fragment = document.createDocumentFragment();
  const mentionPattern = /(@[\p{L}\p{N}._-]+(?:\s+[\p{L}\p{N}._-]+)?)/gu;
  let cursor = 0;

  source.replace(mentionPattern, (match, _mention, offset) => {
    if (offset > cursor) {
      fragment.append(document.createTextNode(source.slice(cursor, offset)));
    }
    const mention = document.createElement("span");
    mention.className = "work-order-activity-mention";
    mention.textContent = match;
    fragment.append(mention);
    cursor = offset + match.length;
    return match;
  });

  if (cursor < source.length) {
    fragment.append(document.createTextNode(source.slice(cursor)));
  }

  target.replaceChildren(fragment);
}

function getWorkOrderActivityExpandedSummary(entry = {}) {
  if (entry.actionType === "comment") {
    return "";
  }

  const actor = String(entry.actorLabel || "SafeNexus").trim();
  const fieldLabel = String(entry.fieldLabel || "podatak").trim().toLocaleLowerCase("hr-HR");
  const oldValue = String(entry.oldValue || "").trim();
  const newValue = String(entry.newValue || "").trim();

  if (oldValue && newValue) {
    return `${actor} ažurirao ${fieldLabel}, iz ${oldValue} u ${newValue}.`;
  }

  if (newValue) {
    return `${actor} postavio ${fieldLabel} na ${newValue}.`;
  }

  if (oldValue) {
    return `${actor} uklonio ${fieldLabel}, prije je bilo ${oldValue}.`;
  }

  return `${actor} ažurirao ${fieldLabel}.`;
}

function renderWorkOrderActivity() {
  if (!workOrderActivityList || !workOrderActivityEmpty || !workOrderActivityLoading || !workOrderActivityError) {
    return;
  }

  const { workOrderId, loading, items, error } = state.workOrderActivity;
  renderWorkOrderActivityCommentControls();
  if (workOrderActivityCount) {
    workOrderActivityCount.textContent = "";
  }
  workOrderActivityLoading.hidden = !loading;
  workOrderActivityError.hidden = !error;
  workOrderActivityError.textContent = error;
  workOrderActivityList.replaceChildren();

  const emptyMessage = !workOrderId
    ? "Otvori radni nalog da vidi? promjene i status timeline."
    : "Još nema zabilježenih promjena za ovaj RN.";
  workOrderActivityEmpty.textContent = emptyMessage;
  workOrderActivityEmpty.hidden = loading || Boolean(error) || items.length > 0;

  items.forEach((entry) => {
    const item = document.createElement("article");
    item.className = "work-order-activity-item";
    item.classList.toggle("is-comment", entry.actionType === "comment");

    const avatar = document.createElement("span");
    avatar.className = "work-order-activity-avatar";
    avatar.textContent = getUserInitials({ fullName: entry.actorLabel });

    const body = document.createElement("div");
    body.className = "work-order-activity-item-body";

    const top = document.createElement("div");
    top.className = "work-order-activity-item-top";

    const description = document.createElement("strong");
    description.className = "work-order-activity-description";
    description.textContent = entry.description || "Ažuriranje radnog naloga";

    const time = document.createElement("span");
    time.className = "work-order-activity-time";
    time.textContent = formatDateTime(entry.createdAt);

    const expandButton = document.createElement("button");
    expandButton.type = "button";
    expandButton.className = "work-order-activity-expand";
    expandButton.textContent = "+";
    expandButton.setAttribute("aria-label", "Prikaži detalje aktivnosti");
    expandButton.addEventListener("click", (event) => {
      event.stopPropagation();
      const expanded = item.classList.toggle("is-expanded");
      expandButton.textContent = expanded ? "−" : "+";
      expandButton.setAttribute("aria-label", expanded ? "Sažmi aktivnost" : "Prikaži detalje aktivnosti");
    });

    top.append(description, time, expandButton);

    const meta = document.createElement("div");
    meta.className = "work-order-activity-meta";

    const actor = document.createElement("span");
    actor.className = "work-order-activity-actor";
    actor.textContent = entry.actorLabel || "SafeNexus";
    meta.append(actor);

    if (entry.fieldLabel) {
      const field = document.createElement("span");
      field.className = "work-order-activity-field";
      field.textContent = entry.fieldLabel;
      meta.append(field);
    }

    if (entry.actionType === "comment") {
      const comment = document.createElement("p");
      comment.className = "work-order-activity-comment-text";
      appendWorkOrderActivityTextWithMentions(comment, entry.newValue || entry.description || "Komentar");
      body.append(top, meta, comment);
    } else {
      const expandedSummaryText = getWorkOrderActivityExpandedSummary(entry);
      const expandedSummary = document.createElement("p");
      expandedSummary.className = "work-order-activity-expanded-summary";
      expandedSummary.textContent = expandedSummaryText;

      if (entry.oldValue || entry.newValue) {
        const diff = document.createElement("div");
        diff.className = "work-order-activity-diff";
        const hasOldValue = Boolean(entry.oldValue);
        const hasNewValue = Boolean(entry.newValue);

        if (hasOldValue) {
          const previous = document.createElement("span");
          previous.className = "work-order-activity-old";
          previous.textContent = entry.oldValue;
          diff.append(previous);
        }

        if (hasOldValue && hasNewValue) {
          const arrow = document.createElement("span");
          arrow.className = "work-order-activity-arrow";
          arrow.textContent = "->";
          diff.append(arrow);
        }

        if (hasNewValue) {
          const next = document.createElement("span");
          next.className = "work-order-activity-new";
          next.textContent = entry.newValue;
          diff.append(next);
        }

        body.append(top, meta, expandedSummary, diff);
      } else {
        body.append(top, meta, expandedSummary);
      }
    }

    body.addEventListener("dblclick", () => {
      const expanded = item.classList.toggle("is-expanded");
      expandButton.textContent = expanded ? "−" : "+";
      expandButton.setAttribute("aria-label", expanded ? "Sažmi aktivnost" : "Prikaži detalje aktivnosti");
    });

    item.append(avatar, body);
    workOrderActivityList.append(item);
  });
}

async function loadWorkOrderActivity(workOrderId) {
  if (!workOrderId) {
    resetWorkOrderActivityState();
    return;
  }

  state.workOrderActivity = {
    workOrderId: String(workOrderId),
    loading: true,
    items: [],
    error: "",
  };
  renderWorkOrderActivity();

  try {
    const payload = await apiRequest(`/work-orders/${workOrderId}/activity`);

    if (state.workOrderActivity.workOrderId !== String(workOrderId)) {
      return;
    }

    state.workOrderActivity = {
      workOrderId: String(workOrderId),
      loading: false,
      items: payload.items ?? [],
      error: "",
    };
  } catch (error) {
    if (state.workOrderActivity.workOrderId !== String(workOrderId)) {
      return;
    }

    state.workOrderActivity = {
      workOrderId: String(workOrderId),
      loading: false,
      items: [],
      error: error.message,
    };
  }

  renderWorkOrderActivity();
}

async function submitWorkOrderActivityComment() {
  const workOrderId = state.workOrderActivity.workOrderId || workOrderIdInput?.value || "";
  const message = String(workOrderActivityCommentInput?.value || "").trim();
  const mentionUserId = String(workOrderActivityMentionUserInput?.value || "").trim()
    || getWorkOrderActivityMentionUserId(message);

  if (!workOrderId) {
    if (workOrderActivityCommentError) {
      workOrderActivityCommentError.textContent = "Prvo spremi ili otvori RN.";
      workOrderActivityCommentError.hidden = false;
    }
    return;
  }

  if (!message) {
    if (workOrderActivityCommentError) {
      workOrderActivityCommentError.textContent = "Komentar ne može biti prazan.";
      workOrderActivityCommentError.hidden = false;
    }
    return;
  }

  if (workOrderActivityCommentAddButton) {
    workOrderActivityCommentAddButton.disabled = true;
  }

  try {
    const payload = await apiRequest(`/work-orders/${workOrderId}/activity`, {
      method: "POST",
      body: {
        message,
        mentionUserId,
      },
    });
    state.workOrderActivity = {
      workOrderId: String(workOrderId),
      loading: false,
      items: payload.items ?? [],
      error: "",
    };
    if (workOrderActivityCommentInput) {
      workOrderActivityCommentInput.value = "";
    }
    if (workOrderActivityMentionUserInput) {
      workOrderActivityMentionUserInput.value = "";
    }
    if (workOrderActivityCommentError) {
      workOrderActivityCommentError.textContent = "";
      workOrderActivityCommentError.hidden = true;
    }
  } catch (error) {
    if (workOrderActivityCommentError) {
      workOrderActivityCommentError.textContent = error?.message || "Komentar nije spremljen.";
      workOrderActivityCommentError.hidden = false;
    }
  } finally {
    renderWorkOrderActivity();
  }
}

function resetWorkOrderDocumentsState() {
  state.workOrderDocuments = {
    workOrderId: "",
    loading: false,
    uploading: false,
    busyId: "",
    items: [],
    error: "",
  };
  renderWorkOrderDocuments();
}

function getWorkOrderDocumentExtension(fileName = "", fileType = "") {
  const normalizedName = String(fileName ?? "").trim();

  if (normalizedName.includes(".")) {
    return normalizedName.split(".").pop().toUpperCase();
  }

  const normalizedType = String(fileType ?? "").trim().toUpperCase();
  return normalizedType.includes("/") ? normalizedType.split("/").pop() : (normalizedType || "FILE");
}

function getWorkOrderDocumentSourceLabel(sourceType = "editor") {
  if (sourceType === "activity") {
    return "Activity";
  }

  if (sourceType === "list") {
    return "ListRN";
  }

  if (sourceType === "pdf") {
    return "Automatski PDF";
  }

  return "Otvaranje";
}

function getWorkOrderDocumentCategoryLabel(value = "") {
  const normalized = String(value || "").trim();
  return WORK_ORDER_DOCUMENT_CATEGORY_OPTIONS.find((option) => option.value === normalized)?.label
    || normalized;
}

function formatFileSize(value) {
  const size = Number(value);

  if (!Number.isFinite(size) || size <= 0) {
    return "0 KB";
  }

  if (size >= 1024 * 1024) {
    return `${(size / (1024 * 1024)).toFixed(size >= 10 * 1024 * 1024 ? 0 : 1)} MB`;
  }

  return `${Math.max(1, Math.round(size / 1024))} KB`;
}

function createWorkOrderDocumentCard(item, { compact = false } = {}) {
  const card = document.createElement("article");
  card.className = compact ? "work-order-document-card is-compact" : "work-order-document-card";
  const isBusy = state.workOrderDocuments.busyId === String(item.id);

  const badge = document.createElement("span");
  badge.className = "work-order-document-badge";
  badge.textContent = getWorkOrderDocumentExtension(item.fileName, item.fileType);

  const body = document.createElement("div");
  body.className = "work-order-document-card-body";

  const nameInput = document.createElement("input");
  nameInput.className = "work-order-document-name-input";
  nameInput.type = "text";
  nameInput.value = item.fileName || "";
  nameInput.placeholder = "Naziv dokumenta";
  nameInput.disabled = isBusy;

  const descriptionInput = document.createElement("textarea");
  descriptionInput.className = "work-order-document-description-input";
  descriptionInput.rows = compact ? 2 : 3;
  descriptionInput.value = item.description || "";
  descriptionInput.placeholder = "Opis dokumenta";
  descriptionInput.disabled = isBusy;

  const meta = document.createElement("span");
  meta.className = "work-order-document-meta";
  meta.textContent = [
    getWorkOrderDocumentCategoryLabel(item.documentCategory),
    formatFileSize(item.fileSize),
    getWorkOrderDocumentSourceLabel(item.sourceType),
    formatDateTime(item.createdAt),
  ].filter(Boolean).join(" · ");

  body.append(nameInput, descriptionInput, meta);

  const actions = document.createElement("div");
  actions.className = "work-order-document-actions";

  const saveButton = document.createElement("button");
  saveButton.type = "button";
  saveButton.className = "ghost-button work-order-document-button";
  saveButton.textContent = isBusy ? "Spremam..." : "Spremi";
  saveButton.disabled = isBusy;
  saveButton.addEventListener("click", () => {
    void saveWorkOrderDocument(item.id, {
      fileName: nameInput.value,
      description: descriptionInput.value,
    });
  });

  const link = document.createElement("a");
  link.className = "ghost-button work-order-document-link";
  link.href = item.dataUrl || "#";
  link.target = "_blank";
  link.rel = "noreferrer";
  link.download = item.fileName || "dokument";
  link.textContent = "Otvori";
  link.setAttribute("aria-disabled", String(isBusy));

  const deleteButton = document.createElement("button");
  deleteButton.type = "button";
  deleteButton.className = "ghost-button work-order-document-button is-danger";
  deleteButton.textContent = isBusy ? "..." : "Makni";
  deleteButton.disabled = isBusy;
  deleteButton.addEventListener("click", () => {
    void deleteWorkOrderDocument(item.id, item.fileName);
  });

  actions.append(saveButton, link, deleteButton);

  card.append(badge, body, actions);
  return card;
}

function syncWorkOrderDocumentDropzone(dropzone, uploading, defaultTitle, defaultSubtitle) {
  if (!dropzone) {
    return;
  }

  dropzone.disabled = uploading;
  dropzone.dataset.uploading = uploading ? "true" : "false";
  const title = dropzone.querySelector(".work-order-document-dropzone-copy strong");
  const subtitle = dropzone.querySelector(".work-order-document-dropzone-copy span");

  if (title) {
    title.textContent = uploading ? "Upload u tijeku..." : defaultTitle;
  }

  if (subtitle) {
    subtitle.textContent = uploading ? "Datoteke se upravo spremaju na RN." : defaultSubtitle;
  }
}

function renderWorkOrderDocuments() {
  const {
    workOrderId,
    loading,
    uploading,
    items,
    error,
  } = state.workOrderDocuments;

  if (
    !workOrderDocumentList
    || !workOrderDocumentEmpty
    || !workOrderDocumentLoading
    || !workOrderDocumentError
    || !workOrderActivityDocumentList
    || !workOrderActivityDocumentEmpty
    || !workOrderActivityDocumentLoading
    || !workOrderActivityDocumentError
  ) {
    return;
  }

  const visibleItems = items.filter((item) => (
    String(item?.documentCategory || "").trim() !== GENERATED_WORK_ORDER_PDF_CATEGORY
  ));

  if (workOrderDocumentCount) {
    workOrderDocumentCount.textContent = String(visibleItems.length);
  }

  if (workOrderActivityDocumentCount) {
    workOrderActivityDocumentCount.textContent = String(visibleItems.length);
  }

  workOrderDocumentLoading.hidden = !loading;
  workOrderActivityDocumentLoading.hidden = !loading;
  workOrderDocumentError.hidden = !error;
  workOrderActivityDocumentError.hidden = !error;
  workOrderDocumentError.textContent = error;
  workOrderActivityDocumentError.textContent = error;
  workOrderDocumentList.replaceChildren();
  workOrderActivityDocumentList.replaceChildren();

  syncWorkOrderDocumentDropzone(
    workOrderDocumentDropzone,
    uploading,
    "Dodaj dokumente u RN",
    "Povuci mailove, PDF, slike, Word, Excel i slične fajlove ili klikni. Drag and drop radi i bilo gdje u lijevom dijelu prozora.",
  );
  syncWorkOrderDocumentDropzone(
    workOrderActivityDropzone,
    uploading,
    "Dodaj iz activityja",
    "Povuci ili klikni za upload. Drag and drop radi i bilo gdje u desnom activity dijelu.",
  );

  visibleItems.forEach((item) => {
    workOrderDocumentList.append(createWorkOrderDocumentCard(item));
    workOrderActivityDocumentList.append(createWorkOrderDocumentCard(item, { compact: true }));
  });

  const editorEmptyMessage = !workOrderId
    ? "Povuci dokumente ovdje. Ako je RN nov, prvo spremimo osnovne podatke pa dokument vežemo uz njega."
    : "Još nema dokumenata za ovaj RN.";
  const activityEmptyMessage = !workOrderId
    ? "Dokumenti ?e se pojaviti kad RN bude spremljen."
    : "Još nema dokumenata u activity prikazu.";

  workOrderDocumentEmpty.textContent = editorEmptyMessage;
  workOrderActivityDocumentEmpty.textContent = activityEmptyMessage;
  workOrderDocumentEmpty.hidden = loading || Boolean(error) || visibleItems.length > 0;
  workOrderActivityDocumentEmpty.hidden = loading || Boolean(error) || visibleItems.length > 0;
}

function resetWorkOrderDocumentCategoryDialogState() {
  state.workOrderDocumentCategoryDialog = {
    open: false,
    title: "",
    helper: "",
    files: [],
    entries: [],
    error: "",
    resolve: null,
  };
}

function renderWorkOrderDocumentCategoryDialog() {
  const dialog = state.workOrderDocumentCategoryDialog;
  const isOpen = Boolean(dialog.open);

  document.body.classList.toggle("is-work-order-document-category-open", isOpen);

  if (workOrderDocumentCategoryBackdrop) {
    workOrderDocumentCategoryBackdrop.hidden = !isOpen;
  }

  if (workOrderDocumentCategoryPanel) {
    workOrderDocumentCategoryPanel.hidden = !isOpen;
    workOrderDocumentCategoryPanel.setAttribute("aria-hidden", String(!isOpen));
  }

  if (!isOpen) {
    return;
  }

  if (workOrderDocumentCategoryTitle) {
    workOrderDocumentCategoryTitle.textContent = dialog.title || "Vrsta dokumenta";
  }

  if (workOrderDocumentCategoryHelper) {
    workOrderDocumentCategoryHelper.textContent = dialog.helper || "Odaberi što je svaka datoteka prije spremanja.";
  }

  if (workOrderDocumentCategoryError) {
    workOrderDocumentCategoryError.textContent = dialog.error || "";
    workOrderDocumentCategoryError.hidden = !dialog.error;
  }

  if (!workOrderDocumentCategoryList) {
    return;
  }

  workOrderDocumentCategoryList.replaceChildren();

  dialog.entries.forEach((entry, index) => {
    const row = document.createElement("article");
    row.className = "work-order-document-category-row";

    const icon = document.createElement("span");
    icon.className = "work-order-document-category-row-icon";
    icon.innerHTML = getWorkOrderIconMarkup("document");

    const copy = document.createElement("div");
    copy.className = "work-order-document-category-row-copy";

    const name = document.createElement("strong");
    name.textContent = entry.fileName || `Dokument ${index + 1}`;

    const meta = document.createElement("span");
    meta.textContent = [
      getWorkOrderDocumentExtension(entry.fileName, entry.fileType),
      formatFileSize(entry.fileSize),
    ].filter(Boolean).join(" · ");

    copy.append(name, meta);

    const select = document.createElement("select");
    select.className = "work-order-document-category-select";
    select.setAttribute("aria-label", `Vrsta dokumenta ${entry.fileName || index + 1}`);
    WORK_ORDER_DOCUMENT_CATEGORY_OPTIONS.forEach((option) => {
      const node = document.createElement("option");
      node.value = option.value;
      node.textContent = option.label;
      select.append(node);
    });
    select.value = entry.documentCategory || DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY;
    select.addEventListener("change", () => {
      state.workOrderDocumentCategoryDialog.entries = state.workOrderDocumentCategoryDialog.entries.map((item, itemIndex) => (
        itemIndex === index ? { ...item, documentCategory: select.value } : item
      ));
    });

    row.append(icon, copy, select);
    workOrderDocumentCategoryList.append(row);
  });
}

function closeWorkOrderDocumentCategoryDialog(result = null) {
  const resolver = state.workOrderDocumentCategoryDialog.resolve;
  resetWorkOrderDocumentCategoryDialogState();
  renderWorkOrderDocumentCategoryDialog();

  if (typeof resolver === "function") {
    resolver(result);
  }
}

function confirmWorkOrderDocumentCategoryDialog() {
  const dialog = state.workOrderDocumentCategoryDialog;

  if (!dialog.open) {
    return;
  }

  const entries = dialog.entries.map((entry) => ({
    ...entry,
    documentCategory: entry.documentCategory || DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY,
  }));

  if (entries.some((entry) => !entry.documentCategory)) {
    state.workOrderDocumentCategoryDialog.error = "Odaberi vrstu za svaki dokument.";
    renderWorkOrderDocumentCategoryDialog();
    return;
  }

  const result = dialog.files.map((file, index) => ({
    file,
    documentCategory: entries[index]?.documentCategory || DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY,
  }));
  closeWorkOrderDocumentCategoryDialog(result);
}

function openWorkOrderDocumentCategoryDialog(files, {
  title = "",
  helper = "",
} = {}) {
  const selectedFiles = Array.from(files ?? []).filter((file) => file instanceof File);

  if (!selectedFiles.length) {
    return Promise.resolve(null);
  }

  return new Promise((resolve) => {
    state.workOrderDocumentCategoryDialog = {
      open: true,
      title,
      helper,
      files: selectedFiles,
      entries: selectedFiles.map((file) => ({
        fileName: file.name,
        fileType: file.type,
        fileSize: file.size,
        documentCategory: DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY,
      })),
      error: "",
      resolve,
    };
    renderWorkOrderDocumentCategoryDialog();
    requestAnimationFrame(() => {
      workOrderDocumentCategoryPanel?.querySelector("select, button")?.focus({ preventScroll: true });
    });
  });
}

async function loadWorkOrderDocuments(workOrderId) {
  if (!workOrderId) {
    resetWorkOrderDocumentsState();
    return;
  }

  state.workOrderDocuments = {
    workOrderId: String(workOrderId),
    loading: true,
    uploading: state.workOrderDocuments.uploading,
    busyId: state.workOrderDocuments.busyId,
    items: [],
    error: "",
  };
  renderWorkOrderDocuments();

  try {
    const payload = await apiRequest(`/work-orders/${workOrderId}/documents`);

    if (state.workOrderDocuments.workOrderId !== String(workOrderId)) {
      return;
    }

    state.workOrderDocuments = {
      workOrderId: String(workOrderId),
      loading: false,
      uploading: state.workOrderDocuments.uploading,
      busyId: state.workOrderDocuments.busyId,
      items: payload.items ?? [],
      error: "",
    };
  } catch (error) {
    if (state.workOrderDocuments.workOrderId !== String(workOrderId)) {
      return;
    }

    state.workOrderDocuments = {
      workOrderId: String(workOrderId),
      loading: false,
      uploading: state.workOrderDocuments.uploading,
      busyId: state.workOrderDocuments.busyId,
      items: [],
      error: error.message,
    };
  }

  renderWorkOrderDocuments();
}

function isWorkOrderDocumentFileAllowed(file) {
  const extension = String(file?.name ?? "").trim().includes(".")
    ? String(file.name).trim().split(".").pop().toLowerCase()
    : "";

  if (extension && WORK_ORDER_DOCUMENT_ALLOWED_EXTENSIONS.has(extension)) {
    return true;
  }

  const mimeType = String(file?.type ?? "").trim().toLowerCase();
  return mimeType.startsWith("image/")
    || mimeType === "application/pdf"
    || mimeType === "message/rfc822"
    || mimeType === "application/vnd.ms-outlook"
    || mimeType === "application/msword"
    || mimeType === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    || mimeType === "application/vnd.openxmlformats-officedocument.wordprocessingml.template"
    || mimeType === "application/vnd.ms-excel"
    || mimeType === "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    || mimeType === "text/csv"
    || mimeType === "text/plain";
}

async function ensureWorkOrderReadyForDocumentUpload() {
  const requiresSave = !workOrderIdInput.value || state.workOrderAutoSave.dirty;

  if (!requiresSave) {
    return String(workOrderIdInput.value || "");
  }

  const success = await persistWorkOrderAutoSave({ immediate: true });

  if (!success || !workOrderIdInput.value) {
    state.workOrderDocuments.error = workOrderError.textContent || "Prvo spremi radni nalog prije uploada dokumenata.";
    renderWorkOrderDocuments();
    return "";
  }

  return String(workOrderIdInput.value || "");
}

async function buildWorkOrderDocumentUploadPayload(files, metadataEntries = []) {
  const uploadFiles = Array.from(files ?? []).filter((file) => file instanceof File);
  const metadataList = Array.from(metadataEntries ?? []);
  const metadataByFile = new Map();

  metadataList.forEach((entry) => {
    if (entry?.file instanceof File) {
      metadataByFile.set(entry.file, entry);
    }
  });

  if (!uploadFiles.length) {
    return [];
  }

  for (const file of uploadFiles) {
    if (!isWorkOrderDocumentFileAllowed(file)) {
      throw new Error(`Format ${file.name} nije podrzan. Dozvoljeno: ${WORK_ORDER_DOCUMENT_ACCEPT_LABEL}`);
    }

    if (file.size > WORK_ORDER_DOCUMENT_MAX_SIZE_BYTES) {
      throw new Error(`Datoteka ${file.name} mora biti manja od 12 MB.`);
    }
  }

  return Promise.all(uploadFiles.map(async (file, index) => {
    const metadata = metadataByFile.get(file) || metadataList[index] || {};
    const documentCategory = getWorkOrderDocumentCategoryLabel(
      metadata.documentCategory || metadata.category || DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY,
    ) || DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY;

    return {
      fileName: file.name,
      fileType: file.type,
      fileSize: file.size,
      documentCategory,
      description: String(metadata.description || "").trim(),
      dataUrl: await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`),
    };
  }));
}

function findWorkOrderById(workOrderId) {
  return state.workOrders.find((item) => String(item.id) === String(workOrderId)) ?? null;
}

function getWorkOrderDocumentDialogTitle(workOrderId = "", workOrder = null) {
  const item = workOrder || findWorkOrderById(workOrderId);
  const number = String(item?.workOrderNumber || workOrderEditorTitle?.textContent || "").trim();
  return number ? `Dokumentacija za RN ${number}` : "Dokumentacija za RN";
}

async function handleWorkOrderDocumentSelection(files, sourceType = "editor", options = {}) {
  const selectedFiles = Array.from(files ?? []).filter((file) => file instanceof File);
  workOrderEditorMain?.classList.remove("is-document-panel-active");
  workOrderActivityPanel?.classList.remove("is-document-panel-active");

  if (
    !selectedFiles.length
    || state.workOrderDocuments.uploading
    || state.workOrderDocuments.busyId
    || state.workOrderDocumentCategoryDialog.open
  ) {
    return;
  }

  state.workOrderDocuments.error = "";
  renderWorkOrderDocuments();

  try {
    const workOrderId = options.workOrderId
      ? String(options.workOrderId)
      : await ensureWorkOrderReadyForDocumentUpload();

    if (!workOrderId) {
      return;
    }

    const workOrder = options.workOrder || findWorkOrderById(workOrderId);
    const selectedCategories = options.askCategory === true
      ? await openWorkOrderDocumentCategoryDialog(selectedFiles, {
        title: options.title || getWorkOrderDocumentDialogTitle(workOrderId, workOrder),
        helper: options.helper || "Odaberi vrstu za svaku datoteku. Ako ih je više, svaka dobiva svoj red.",
      })
      : selectedFiles.map((file) => ({
        file,
        documentCategory: options.documentCategory || DEFAULT_WORK_ORDER_DOCUMENT_CATEGORY,
      }));

    if (!selectedCategories) {
      return;
    }

    state.workOrderDocuments.uploading = true;
    renderWorkOrderDocuments();

    const payloadFiles = await buildWorkOrderDocumentUploadPayload(selectedFiles, selectedCategories);
    await apiRequest(`/work-orders/${workOrderId}/documents`, {
      method: "POST",
      body: {
        sourceType,
        files: payloadFiles,
      },
    });
    workOrderError.textContent = "";
    const isOpenWorkOrder = String(state.workOrderDocuments.workOrderId || workOrderIdInput?.value || "") === String(workOrderId);

    if (isOpenWorkOrder) {
      await Promise.all([
        loadWorkOrderDocuments(workOrderId),
        loadWorkOrderActivity(workOrderId),
      ]);
    }
  } catch (error) {
    state.workOrderDocuments.error = error.message;
    workOrderError.textContent = error.message;
  } finally {
    state.workOrderDocuments.uploading = false;
    renderWorkOrderDocuments();

    if (workOrderDocumentFileInput) {
      workOrderDocumentFileInput.value = "";
    }

    if (workOrderActivityFileInput) {
      workOrderActivityFileInput.value = "";
    }

    if (workOrderRowDocumentFileInput) {
      workOrderRowDocumentFileInput.value = "";
    }
  }
}

function openWorkOrderRowDocumentPicker(workOrder) {
  if (!workOrder?.id || !workOrderRowDocumentFileInput || state.workOrderDocuments.uploading) {
    return;
  }

  state.workOrderRowDocumentTargetId = String(workOrder.id);
  workOrderRowDocumentFileInput.value = "";
  workOrderRowDocumentFileInput.click();
}

function bindWorkOrderRowDocumentDropTarget(rowCard, workOrder = {}) {
  if (!rowCard || !workOrder?.id || !getCanEditOperationalData()) {
    return;
  }

  let dragDepth = 0;
  const resetDragState = () => {
    dragDepth = 0;
    rowCard.classList.remove("is-document-drag-over");
  };

  rowCard.addEventListener("dragenter", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    dragDepth += 1;
    rowCard.classList.add("is-document-drag-over");
  });

  rowCard.addEventListener("dragover", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    rowCard.classList.add("is-document-drag-over");
  });

  rowCard.addEventListener("dragleave", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    dragDepth = Math.max(0, dragDepth - 1);
    if (dragDepth === 0) {
      rowCard.classList.remove("is-document-drag-over");
    }
  });

  rowCard.addEventListener("drop", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    resetDragState();
    void handleWorkOrderDocumentSelection(event.dataTransfer?.files, "list", {
      workOrderId: workOrder.id,
      workOrder,
      title: getWorkOrderDocumentDialogTitle(workOrder.id, workOrder),
      helper: "Dokumenti su dodani s retka RN-a. Odaberi vrstu za svaku datoteku.",
    });
  });
}

async function saveWorkOrderDocument(documentId, patch = {}) {
  const workOrderId = state.workOrderDocuments.workOrderId || workOrderIdInput.value;

  if (!workOrderId || state.workOrderDocuments.busyId) {
    return;
  }

  state.workOrderDocuments.busyId = String(documentId);
  state.workOrderDocuments.error = "";
  renderWorkOrderDocuments();

  try {
    await apiRequest(`/work-orders/${workOrderId}/documents/${documentId}`, {
      method: "PATCH",
      body: {
        fileName: String(patch.fileName ?? "").trim(),
        description: String(patch.description ?? "").trim(),
      },
    });
    workOrderError.textContent = "";
    await Promise.all([
      loadWorkOrderDocuments(workOrderId),
      loadWorkOrderActivity(workOrderId),
    ]);
  } catch (error) {
    state.workOrderDocuments.error = error.message;
    workOrderError.textContent = error.message;
  } finally {
    state.workOrderDocuments.busyId = "";
    renderWorkOrderDocuments();
  }
}

async function deleteWorkOrderDocument(documentId, fileName = "") {
  const workOrderId = state.workOrderDocuments.workOrderId || workOrderIdInput.value;

  if (!workOrderId || state.workOrderDocuments.busyId) {
    return;
  }

  if (!window.confirm(`Maknuti dokument ${fileName || "bez naziva"}?`)) {
    return;
  }

  state.workOrderDocuments.busyId = String(documentId);
  state.workOrderDocuments.error = "";
  renderWorkOrderDocuments();

  try {
    await apiRequest(`/work-orders/${workOrderId}/documents/${documentId}`, {
      method: "DELETE",
    });
    workOrderError.textContent = "";
    await Promise.all([
      loadWorkOrderDocuments(workOrderId),
      loadWorkOrderActivity(workOrderId),
    ]);
  } catch (error) {
    state.workOrderDocuments.error = error.message;
    workOrderError.textContent = error.message;
  } finally {
    state.workOrderDocuments.busyId = "";
    renderWorkOrderDocuments();
  }
}

function isFileDragEvent(event) {
  return Array.from(event.dataTransfer?.types ?? []).includes("Files");
}

function bindWorkOrderDocumentDropzone(dropzone, fileInput, sourceType) {
  if (!dropzone || !fileInput) {
    return;
  }

  let dragDepth = 0;

  dropzone.addEventListener("click", () => {
    if (!state.workOrderDocuments.uploading) {
      fileInput.click();
    }
  });

  fileInput.addEventListener("change", () => {
    void handleWorkOrderDocumentSelection(fileInput.files, sourceType);
  });

  dropzone.addEventListener("dragenter", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    dragDepth += 1;
    dropzone.classList.add("is-drag-over");
  });

  dropzone.addEventListener("dragover", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    dropzone.classList.add("is-drag-over");
  });

  dropzone.addEventListener("dragleave", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    dragDepth = Math.max(0, dragDepth - 1);

    if (dragDepth === 0) {
      dropzone.classList.remove("is-drag-over");
    }
  });

  dropzone.addEventListener("drop", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();
    dragDepth = 0;
    dropzone.classList.remove("is-drag-over");
    void handleWorkOrderDocumentSelection(event.dataTransfer?.files, sourceType);
  });
}

function bindWorkOrderDocumentPanelTarget(target, sourceType) {
  if (!target) {
    return;
  }

  let dragDepth = 0;

  target.addEventListener("dragenter", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    dragDepth += 1;
    target.classList.add("is-document-panel-active");
  });

  target.addEventListener("dragover", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    target.classList.add("is-document-panel-active");
  });

  target.addEventListener("dragleave", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    dragDepth = Math.max(0, dragDepth - 1);

    if (dragDepth === 0) {
      target.classList.remove("is-document-panel-active");
    }
  });

  target.addEventListener("drop", (event) => {
    if (!isFileDragEvent(event)) {
      return;
    }

    event.preventDefault();
    dragDepth = 0;
    target.classList.remove("is-document-panel-active");
    void handleWorkOrderDocumentSelection(event.dataTransfer?.files, sourceType);
  });
}

function syncWorkOrderEditorModal() {
  const isOpen = state.workOrderEditorOpen && state.activeView === "selfdash" && Boolean(state.user);

  workOrderEditorPanel?.classList.toggle("is-modal-open", isOpen);
  document.body.classList.toggle("is-work-order-editor-open", isOpen);

  if (workOrderEditorPanel) {
    workOrderEditorPanel.hidden = !isOpen;
    workOrderEditorPanel.setAttribute("aria-hidden", String(!isOpen));
  }

  if (workOrderEditorBackdrop) {
    workOrderEditorBackdrop.hidden = !isOpen;
  }

  if (workOrderEditorCloseButton) {
    workOrderEditorCloseButton.hidden = !isOpen;
  }

  if (isOpen) {
    requestAnimationFrame(() => {
      scrollWorkOrderEditorToTop();
      workOrderEditorBody?.focus({ preventScroll: true });
      window.setTimeout(() => {
        scrollWorkOrderEditorToTop();
      }, 0);
    });
  }
}

