function setDocumentTemplateFieldDrafts(fields = [], { ensureOne = false } = {}) {
  invalidateDocumentTemplateDraftCache();
  const nextDrafts = Array.isArray(fields)
    ? fields
      .map((field, index) => createEmptyDocumentTemplateFieldDraft(field, index))
    : [];
  documentTemplateFieldDrafts = nextDrafts.length > 0
    ? nextDrafts
    : (ensureOne ? [createEmptyDocumentTemplateFieldDraft({}, 0)] : []);
}

function setDocumentTemplateEquipmentDrafts(items = [], { ensureOne = false } = {}) {
  invalidateDocumentTemplateDraftCache();
  const nextDrafts = Array.isArray(items) ? items.map((item, index) => createEmptyDocumentTemplateEquipmentDraft(item, index)) : [];
  documentTemplateEquipmentDrafts = nextDrafts.length > 0
    ? nextDrafts
    : (ensureOne ? [createEmptyDocumentTemplateEquipmentDraft({}, 0)] : []);
}

function setDocumentTemplateSectionDrafts(sections = [], { ensureDefault = true } = {}) {
  invalidateDocumentTemplateDraftCache();
  if (Array.isArray(sections) && sections.length > 0) {
    documentTemplateSectionDrafts = sections.map((section, index) => createEmptyDocumentTemplateSectionDraft(section, index));
    return;
  }

  documentTemplateSectionDrafts = ensureDefault ? createDefaultDocumentTemplateSectionDrafts() : [];
}

function buildDocumentTemplateSheetGroups(fields = documentTemplateFieldDrafts) {
  const source = Array.isArray(fields) ? fields : [];
  const pages = [{
    index: 0,
    id: "template-layout-1",
    title: "A4 stranica 1",
    breakField: null,
    breakIndex: -1,
    fields: [],
  }];

  source.forEach((field, index) => {
    if (!field) {
      return;
    }

    if (String(field.type || "").trim().toLowerCase() === "page_break") {
      const pageNumber = pages.length + 1;
      pages.push({
        index: pages.length,
        id: String(field.id || `template-layout-${pageNumber}`),
        title: field.label || `A4 stranica ${pageNumber}`,
        breakField: field,
        breakIndex: index,
        fields: [],
      });
      return;
    }

    pages[pages.length - 1].fields.push({
      field,
      index,
    });
  });

  return pages;
}

function clampDocumentTemplateSheetIndex(pages = buildDocumentTemplateSheetGroups()) {
  if (!Array.isArray(pages) || pages.length === 0) {
    activeDocumentTemplateSheetIndex = 0;
    return 0;
  }

  activeDocumentTemplateSheetIndex = Math.max(0, Math.min(activeDocumentTemplateSheetIndex, pages.length - 1));
  return activeDocumentTemplateSheetIndex;
}

function getDocumentTemplateSheetInsertIndex(pageIndex = activeDocumentTemplateSheetIndex) {
  const pages = buildDocumentTemplateSheetGroups();
  const safePageIndex = Math.max(0, Math.min(pageIndex, pages.length - 1));
  const nextPage = pages[safePageIndex + 1];
  return Number.isInteger(nextPage?.breakIndex) ? nextPage.breakIndex : documentTemplateFieldDrafts.length;
}

function insertDocumentTemplateFieldDraft(draft, { pageIndex = activeDocumentTemplateSheetIndex } = {}) {
  const insertIndex = getDocumentTemplateSheetInsertIndex(pageIndex);
  documentTemplateFieldDrafts = [
    ...documentTemplateFieldDrafts.slice(0, insertIndex),
    draft,
    ...documentTemplateFieldDrafts.slice(insertIndex),
  ];
}

function insertDocumentTemplateFieldDraftRelative(draft, targetFieldId, { placement = "after" } = {}) {
  const targetIndex = documentTemplateFieldDrafts.findIndex((field) => String(field?.id || "") === String(targetFieldId || ""));
  if (targetIndex < 0) {
    insertDocumentTemplateFieldDraft(draft);
    return;
  }

  const insertIndex = placement === "before" ? targetIndex : targetIndex + 1;
  documentTemplateFieldDrafts = [
    ...documentTemplateFieldDrafts.slice(0, insertIndex),
    draft,
    ...documentTemplateFieldDrafts.slice(insertIndex),
  ];
}

function removeDocumentTemplateSheet(pageIndex) {
  const pages = buildDocumentTemplateSheetGroups();
  const targetPage = pages[pageIndex];

  if (!targetPage?.breakField?.id) {
    return;
  }

  documentTemplateFieldDrafts = documentTemplateFieldDrafts.filter((field) => field.id !== targetPage.breakField.id);
  activeDocumentTemplateSheetIndex = Math.max(0, Math.min(pageIndex - 1, buildDocumentTemplateSheetGroups().length - 1));
}

function moveDocumentTemplateFieldDraftToPageEnd(draggedFieldId, pageIndex = activeDocumentTemplateSheetIndex) {
  const safeDraggedId = String(draggedFieldId || "");
  if (!safeDraggedId) {
    return false;
  }

  const draggedIndex = documentTemplateFieldDrafts.findIndex((field) => String(field?.id || "") === safeDraggedId);
  const draggedField = draggedIndex >= 0 ? documentTemplateFieldDrafts[draggedIndex] : null;
  if (!draggedField || String(draggedField.type || "").trim().toLowerCase() === "page_break") {
    return false;
  }

  const nextDrafts = documentTemplateFieldDrafts.filter((field) => String(field?.id || "") !== safeDraggedId);
  const originalDrafts = documentTemplateFieldDrafts;
  documentTemplateFieldDrafts = nextDrafts;
  const pages = buildDocumentTemplateSheetGroups();
  const safePageIndex = Math.max(0, Math.min(pageIndex, pages.length - 1));
  const insertIndex = getDocumentTemplateSheetInsertIndex(safePageIndex);
  documentTemplateFieldDrafts = [
    ...nextDrafts.slice(0, insertIndex),
    draggedField,
    ...nextDrafts.slice(insertIndex),
  ];

  if (documentTemplateFieldDrafts.length !== originalDrafts.length) {
    documentTemplateFieldDrafts = originalDrafts;
    return false;
  }

  activeDocumentTemplateSheetIndex = safePageIndex;
  return true;
}

function moveDocumentTemplateFieldDraft(
  draggedFieldId,
  targetFieldId,
  {
    pageIndex = activeDocumentTemplateSheetIndex,
    placement = "before",
  } = {},
) {
  const safeDraggedId = String(draggedFieldId || "");
  const safeTargetId = String(targetFieldId || "");

  if (!safeDraggedId || !safeTargetId || safeDraggedId === safeTargetId) {
    return false;
  }

  const nextDrafts = [...documentTemplateFieldDrafts];
  const draggedIndex = nextDrafts.findIndex((field) => String(field.id) === safeDraggedId);
  const targetIndex = nextDrafts.findIndex((field) => String(field.id) === safeTargetId);

  if (draggedIndex < 0 || targetIndex < 0 || draggedIndex === targetIndex) {
    return false;
  }

  if (String(nextDrafts[draggedIndex]?.type || "").trim().toLowerCase() === "page_break") {
    return false;
  }

  const [draggedField] = nextDrafts.splice(draggedIndex, 1);
  let nextTargetIndex = nextDrafts.findIndex((field) => String(field.id) === safeTargetId);

  if (nextTargetIndex < 0) {
    return false;
  }

  if (placement === "after") {
    nextTargetIndex += 1;
  }

  nextDrafts.splice(nextTargetIndex, 0, draggedField);
  documentTemplateFieldDrafts = nextDrafts;
  const pages = buildDocumentTemplateSheetGroups();
  activeDocumentTemplateSheetIndex = Math.max(0, Math.min(pageIndex, pages.length - 1));
  return true;
}

function getDocumentTemplateDraggedToolFromEvent(event) {
  if (!event?.dataTransfer) {
    return "";
  }

  return String(event.dataTransfer.getData(DOCUMENT_TEMPLATE_TOOL_DRAG_MIME) || "").trim().toLowerCase();
}

function hasDocumentTemplateToolDrag(event) {
  const types = Array.from(event?.dataTransfer?.types ?? []);
  return types.includes(DOCUMENT_TEMPLATE_TOOL_DRAG_MIME)
    || Boolean(getDocumentTemplateDraggedToolFromEvent(event));
}

function focusDocumentTemplateFieldLabel(fieldId = "") {
  if (!fieldId || !documentTemplateCustomFields) {
    return;
  }

  activeDocumentTemplateInspectorFieldId = String(fieldId || "").trim();
  documentTemplateInspectorModalOpen = true;
  if (!isDocumentTemplateRuntimeFillMode()) {
    renderDocumentTemplateFieldRows();
  }

  requestAnimationFrame(() => {
    const target = documentTemplateCustomFields.querySelector(
      `[data-template-field-id="${CSS.escape(String(fieldId))}"] [data-template-field-app-label], #document-template-field-inspector [data-template-field-app-label]`,
    );

    if (!(target instanceof HTMLInputElement)) {
      return;
    }

    target.scrollIntoView({ block: "nearest", inline: "nearest" });
    target.focus({ preventScroll: true });
    target.select();
  });
}

function clearDocumentTemplateFieldDragState() {
  draggedDocumentTemplateFieldId = "";
  documentTemplateCustomFields?.querySelectorAll(".document-template-item-card").forEach((item) => {
    item.classList.remove("is-dragging", "is-drop-before", "is-drop-after");
  });
}

function rememberDocumentTemplateTextTarget(target, name = "") {
  if (!(target instanceof HTMLInputElement) && !(target instanceof HTMLTextAreaElement)) {
    activeDocumentTemplateTextTarget = null;
    activeDocumentTemplateSectionTarget = "";
    return;
  }

  activeDocumentTemplateTextTarget = target;
  activeDocumentTemplateSectionTarget = name || target.dataset.templateTarget || target.id || "";
}

function insertTextIntoDocumentTemplateTarget(text) {
  const target = activeDocumentTemplateTextTarget;

  if (target && documentTemplateEditorPanel?.contains(target)) {
    const start = target.selectionStart ?? target.value.length;
    const end = target.selectionEnd ?? target.value.length;
    target.setRangeText(text, start, end, "end");
    target.dispatchEvent(new Event("input", { bubbles: true }));
    target.focus({ preventScroll: true });
    return;
  }

  if (navigator.clipboard?.writeText) {
    void navigator.clipboard.writeText(text);
    setDocumentTemplateMessage("Placeholder je kopiran u clipboard.", { type: "success" });
    window.setTimeout(() => {
      if (documentTemplateError?.textContent === "Placeholder je kopiran u clipboard.") {
        setDocumentTemplateMessage("");
      }
    }, 1600);
  }
}

function normalizeDocumentTemplateHtmlBuilderAlign(value = "") {
  const normalized = String(value || "").trim().toLowerCase();
  return ["left", "center", "right"].includes(normalized) ? normalized : "left";
}

function getDocumentTemplateHtmlBuilderTypeLabel(type = "") {
  const labels = {
    heading: "Naslov",
    paragraph: "Tekst",
    placeholder: "Placeholder",
    columns: "2 stupca",
    table: "Tablica",
    signature: "Potpis",
    divider: "Linija",
    spacer: "Razmak",
    page_break: "Nova stranica",
  };
  return labels[String(type || "").trim().toLowerCase()] || "Element";
}

function getDocumentTemplateHtmlBuilderTokenOptions(template = buildDocumentTemplateDraft()) {
  const definitions = getDocumentTemplatePlaceholderDefinitions(template);
  const seen = new Set();
  return definitions
    .map((entry) => ({
      value: String(entry.token || "").trim(),
      label: `${entry.label || entry.token} ${entry.token || ""}`.trim(),
    }))
    .filter((entry) => {
      if (!entry.value || seen.has(entry.value)) {
        return false;
      }
      seen.add(entry.value);
      return true;
    });
}

function getDocumentTemplateHtmlBuilderFallbackToken() {
  return getDocumentTemplateHtmlBuilderTokenOptions()[0]?.value || "{{DOCUMENT_TITLE}}";
}

function getDocumentTemplateBuilderLogoDataUrl() {
  if (settingsOrganizationLogoDraftTouched && settingsOrganizationLogoDataUrlInput) {
    return settingsOrganizationLogoDataUrlInput.value || "";
  }

  return getActiveOrganization()?.logoDataUrl
    || "";
}

function syncDocumentTemplateHtmlBuilderBranding({ force = false } = {}) {
  if (!documentTemplateHtmlBuilderEngine?.refreshBranding) {
    return;
  }

  documentTemplateHtmlBuilderEngine.refreshBranding({ force });
}

function ensureDocumentTemplateHtmlBuilderEngine() {
  if (documentTemplateHtmlBuilderEngine) {
    return documentTemplateHtmlBuilderEngine;
  }
  if (!(documentTemplateHtmlBuilderCanvas instanceof HTMLElement)) {
    return null;
  }

  documentTemplateHtmlPlaceholderPalette
    ?.closest(".document-template-html-token-panel")
    ?.setAttribute("hidden", "");

  const legacyActions = documentTemplateHtmlBuilderDuplicateButton?.closest(".document-template-html-builder-actions") || null;
  documentTemplateHtmlBuilderEngine = createDocumentReportBuilder({
    mount: documentTemplateHtmlBuilderCanvas,
    legacyToolbox: documentTemplateHtmlBuilderToolbox,
    legacyActions,
    getTokenOptions: () => getDocumentTemplateHtmlBuilderTokenOptions(),
    getLogoDataUrl: () => getDocumentTemplateBuilderLogoDataUrl(),
    onMessage: (message, options) => setDocumentTemplateMessage(message, options),
    onSave: ({ document: builderDocument, html }) => {
      invalidateDocumentTemplateDraftCache();
      documentTemplateHtmlBuilderBlocks = createLegacyBlocksFromBuilderDocument(builderDocument);
      selectedDocumentTemplateHtmlBuilderBlockIds = new Set();
      if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement && documentTemplateHtmlCodeInput.value !== html) {
        documentTemplateHtmlCodeInput.value = html;
      }
      documentTemplateHtmlCodeDirty = false;
      syncDocumentTemplateReferenceDocumentFromCurrentHtml({ render: true, force: true });
      void persistDocumentTemplateDraft({
        successMessage: "Template i HTML builder su spremljeni.",
        scrollToTop: false,
      });
    },
    onChange: ({ document: builderDocument, html }) => {
      invalidateDocumentTemplateDraftCache();
      documentTemplateHtmlBuilderBlocks = createLegacyBlocksFromBuilderDocument(builderDocument);
      selectedDocumentTemplateHtmlBuilderBlockIds = new Set();
      if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement && documentTemplateHtmlCodeInput.value !== html) {
        documentTemplateHtmlCodeInput.value = html;
      }
      documentTemplateHtmlCodeDirty = false;
      if (!state.documentTemplateHtmlPreviewCollapsed) {
        renderDocumentTemplateHtmlPreviewContent();
      }
    },
    onExportPdf: async (html) => {
      const baseName = sanitizeDocumentTemplateFileName(
        documentTemplateTitleInput?.value || documentTemplateOutputFileNameInput?.value || "safenexus-template",
        "safenexus-template",
      ).replace(/\.(html?|pdf)$/i, "");
      const response = await apiBinaryRequest("/document-templates/export-html-preview-pdf", {
        method: "POST",
        body: {
          html,
          fileName: `${baseName}.html`,
          title: documentTemplateTitleInput?.value || "SafeNexus template",
        },
      });
      triggerBlobDownload(response.blob, response.fileName || `${baseName}.pdf`);
    },
  });
  return documentTemplateHtmlBuilderEngine;
}

function createDocumentTemplateHtmlBuilderBlock(type = "paragraph", initial = {}) {
  const normalizedType = String(type || "paragraph").trim().toLowerCase();
  const fallbackToken = getDocumentTemplateHtmlBuilderFallbackToken();
  const id = String(initial.id || crypto.randomUUID());
  const base = {
    id,
    type: normalizedType,
    align: normalizeDocumentTemplateHtmlBuilderAlign(initial.align),
  };

  if (normalizedType === "heading") {
    return {
      ...base,
      text: String(initial.text || "Naslov zapisnika").trim(),
    };
  }

  if (normalizedType === "placeholder") {
    return {
      ...base,
      label: String(initial.label || "Podatak").trim(),
      token: String(initial.token || fallbackToken).trim(),
    };
  }

  if (normalizedType === "columns") {
    return {
      ...base,
      leftLabel: String(initial.leftLabel || "Podatak 1").trim(),
      leftToken: String(initial.leftToken || fallbackToken).trim(),
      rightLabel: String(initial.rightLabel || "Podatak 2").trim(),
      rightToken: String(initial.rightToken || fallbackToken).trim(),
    };
  }

  if (normalizedType === "table") {
    return {
      ...base,
      title: String(initial.title || "Tablica").trim(),
      token: String(initial.token || fallbackToken).trim(),
    };
  }

  if (normalizedType === "signature") {
    return {
      ...base,
      leftText: String(initial.leftText || "Izradio").trim(),
      rightText: String(initial.rightText || "Odobrio").trim(),
    };
  }

  if (normalizedType === "divider" || normalizedType === "page_break" || normalizedType === "spacer") {
    return base;
  }

  return {
    ...base,
    type: "paragraph",
    text: String(initial.text || "Tekst zapisnika").trim(),
  };
}

function normalizeDocumentTemplateHtmlBuilderBlocks(blocks = []) {
  return (Array.isArray(blocks) ? blocks : [])
    .map((block) => createDocumentTemplateHtmlBuilderBlock(block?.type || "paragraph", block))
    .filter((block) => block.id);
}

function encodeDocumentTemplateHtmlBuilderMetadata(blocks = []) {
  try {
    return window.btoa(encodeURIComponent(JSON.stringify(normalizeDocumentTemplateHtmlBuilderBlocks(blocks))));
  } catch {
    return "";
  }
}

function decodeDocumentTemplateHtmlBuilderMetadata(payload = "") {
  try {
    return normalizeDocumentTemplateHtmlBuilderBlocks(JSON.parse(decodeURIComponent(window.atob(String(payload || "")))));
  } catch {
    return [];
  }
}

function parseDocumentTemplateHtmlBuilderBlocksFromCode(html = "") {
  const match = String(html || "").match(/<!--\s*SAFE_NEXUS_HTML_BUILDER:([A-Za-z0-9+/=]+)\s*-->/);
  return match ? decodeDocumentTemplateHtmlBuilderMetadata(match[1]) : [];
}

function getDocumentTemplateHtmlBuilderSelectedBlocks() {
  if (documentTemplateHtmlBuilderEngine) {
    return documentTemplateHtmlBuilderEngine.getSelectedBlocks();
  }
  const selected = documentTemplateHtmlBuilderBlocks.filter((block) => selectedDocumentTemplateHtmlBuilderBlockIds.has(String(block.id)));
  return selected.length > 0 ? selected : [];
}

function buildDocumentTemplateHtmlBuilderBlockHtml(block = {}) {
  const align = normalizeDocumentTemplateHtmlBuilderAlign(block.align);
  const alignStyle = `text-align:${align};`;
  const token = String(block.token || "").trim();

  if (block.type === "heading") {
    return `<h1 style="${alignStyle}">${escapeHtml(block.text || "Naslov zapisnika")}</h1>`;
  }

  if (block.type === "paragraph") {
    return `<p style="${alignStyle}">${escapeHtml(block.text || "Tekst zapisnika").replace(/\n/g, "<br>")}</p>`;
  }

  if (block.type === "placeholder") {
    return `
      <div class="sn-html-placeholder" style="${alignStyle}">
        ${block.label ? `<span>${escapeHtml(block.label)}</span>` : ""}
        <strong>${escapeHtml(token || "{{DOCUMENT_TITLE}}")}</strong>
      </div>`;
  }

  if (block.type === "columns") {
    return `
      <div class="sn-html-columns">
        <div class="sn-html-column">
          <span>${escapeHtml(block.leftLabel || "Podatak 1")}</span>
          <strong>${escapeHtml(block.leftToken || "{{DOCUMENT_TITLE}}")}</strong>
        </div>
        <div class="sn-html-column">
          <span>${escapeHtml(block.rightLabel || "Podatak 2")}</span>
          <strong>${escapeHtml(block.rightToken || "{{BROJ_RADNOG_NALOGA}}")}</strong>
        </div>
      </div>`;
  }

  if (block.type === "table") {
    return `
      <section class="sn-html-table-block" style="${alignStyle}">
        <h2>${escapeHtml(block.title || "Tablica")}</h2>
        ${escapeHtml(token || "{{DOCUMENT_TITLE}}")}
      </section>`;
  }

  if (block.type === "signature") {
    return `
      <div class="sn-html-signatures">
        <div><span>${escapeHtml(block.leftText || "Izradio")}</span><em></em></div>
        <div><span>${escapeHtml(block.rightText || "Odobrio")}</span><em></em></div>
      </div>`;
  }

  if (block.type === "divider") {
    return `<hr class="sn-html-divider" />`;
  }

  if (block.type === "spacer") {
    return `<div class="sn-html-spacer"></div>`;
  }

  if (block.type === "page_break") {
    return `<div class="sn-html-page-break"></div>`;
  }

  return "";
}

function buildDocumentTemplateHtmlFromBuilderBlocks(blocks = documentTemplateHtmlBuilderBlocks) {
  if (documentTemplateHtmlBuilderEngine && blocks === documentTemplateHtmlBuilderBlocks) {
    return documentTemplateHtmlBuilderEngine.toHtml();
  }
  if (blocks !== documentTemplateHtmlBuilderBlocks) {
    return buildBuilderHtmlFromDocument(createBuilderDocumentFromLegacyBlocks(blocks));
  }
  const normalizedBlocks = normalizeDocumentTemplateHtmlBuilderBlocks(blocks);
  const metadata = encodeDocumentTemplateHtmlBuilderMetadata(normalizedBlocks);
  const body = normalizedBlocks.map((block) => buildDocumentTemplateHtmlBuilderBlockHtml(block)).join("\n");
  if (!body.trim()) {
    return "";
  }

  return `<!-- ${DOCUMENT_TEMPLATE_HTML_BUILDER_METADATA_PREFIX}${metadata} -->
<style>
  .sn-html-document { display: grid; gap: 14px; color: #172033; font-family: Arial, sans-serif; }
  .sn-html-document h1 { margin: 0 0 8px; font-size: 24px; line-height: 1.2; }
  .sn-html-document h2 { margin: 0 0 8px; font-size: 16px; line-height: 1.25; }
  .sn-html-document p { margin: 0; line-height: 1.55; }
  .sn-html-placeholder { display: grid; gap: 4px; padding: 10px 12px; border: 1px solid #d8e2ef; border-radius: 10px; background: #f8fafc; }
  .sn-html-placeholder span, .sn-html-column span { color: #64748b; font-size: 12px; }
  .sn-html-placeholder strong, .sn-html-column strong { color: #172033; font-size: 14px; }
  .sn-html-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
  .sn-html-column { display: grid; gap: 4px; padding: 10px 12px; border: 1px solid #d8e2ef; border-radius: 10px; background: #fff; }
  .sn-html-table-block { display: grid; gap: 8px; }
  .sn-html-signatures { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 32px; margin-top: 24px; }
  .sn-html-signatures div { min-height: 80px; display: grid; align-content: end; gap: 8px; }
  .sn-html-signatures em { display: block; border-top: 1px solid #94a3b8; height: 1px; }
  .sn-html-divider { border: 0; border-top: 1px solid #cbd5e1; margin: 8px 0; }
  .sn-html-spacer { height: 24px; }
  .sn-html-page-break { break-before: page; page-break-before: always; height: 0; }
  @media print { .sn-html-page-break { break-before: page; page-break-before: always; } }
</style>
<section class="sn-html-document">
${body}
</section>`;
}

function syncDocumentTemplateHtmlBuilderCode({ renderPreview = true } = {}) {
  ensureDocumentTemplateHtmlBuilderEngine();
  if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement) {
    documentTemplateHtmlCodeInput.value = buildDocumentTemplateHtmlFromBuilderBlocks();
  }
  if (renderPreview && !state.documentTemplateHtmlPreviewCollapsed) {
    renderDocumentTemplateHtmlPreviewContent();
  }
}

function setDocumentTemplateHtmlBuilderBlocks(blocks = [], { syncCode = false } = {}) {
  const engine = ensureDocumentTemplateHtmlBuilderEngine();
  documentTemplateHtmlBuilderBlocks = normalizeDocumentTemplateHtmlBuilderBlocks(blocks);
  selectedDocumentTemplateHtmlBuilderBlockIds = new Set(
    [...selectedDocumentTemplateHtmlBuilderBlockIds].filter((id) => (
      documentTemplateHtmlBuilderBlocks.some((block) => String(block.id) === String(id))
    )),
  );
  engine?.loadDocument(createBuilderDocumentFromLegacyBlocks(documentTemplateHtmlBuilderBlocks));
  if (!engine) {
    renderDocumentTemplateHtmlBuilderCanvas();
  }
  if (syncCode) {
    syncDocumentTemplateHtmlBuilderCode();
  }
}

function hydrateDocumentTemplateHtmlBuilderFromCode(html = "") {
  const engine = ensureDocumentTemplateHtmlBuilderEngine();
  const builderDocument = parseBuilderDocumentFromHtml(html);
  if (engine && builderDocument) {
    engine.loadDocument(builderDocument);
    documentTemplateHtmlBuilderBlocks = createLegacyBlocksFromBuilderDocument(builderDocument);
    return;
  }
  setDocumentTemplateHtmlBuilderBlocks(parseDocumentTemplateHtmlBuilderBlocksFromCode(html), { syncCode: false });
}

function addDocumentTemplateHtmlBuilderBlock(type = "paragraph", { token = "", insertIndex = null } = {}) {
  const engine = ensureDocumentTemplateHtmlBuilderEngine();
  if (engine) {
    engine.addBlock(type, token);
    return;
  }
  const block = createDocumentTemplateHtmlBuilderBlock(type, token ? { token } : {});
  const safeIndex = Number.isInteger(insertIndex)
    ? Math.max(0, Math.min(insertIndex, documentTemplateHtmlBuilderBlocks.length))
    : documentTemplateHtmlBuilderBlocks.length;
  documentTemplateHtmlBuilderBlocks = [
    ...documentTemplateHtmlBuilderBlocks.slice(0, safeIndex),
    block,
    ...documentTemplateHtmlBuilderBlocks.slice(safeIndex),
  ];
  selectedDocumentTemplateHtmlBuilderBlockIds = new Set([block.id]);
  renderDocumentTemplateHtmlBuilderCanvas();
  syncDocumentTemplateHtmlBuilderCode();
}

function moveDocumentTemplateHtmlBuilderBlock(blockId = "", insertIndex = documentTemplateHtmlBuilderBlocks.length) {
  const currentIndex = documentTemplateHtmlBuilderBlocks.findIndex((block) => String(block.id) === String(blockId));
  if (currentIndex < 0) {
    return;
  }
  const [block] = documentTemplateHtmlBuilderBlocks.splice(currentIndex, 1);
  const safeIndex = Math.max(0, Math.min(insertIndex > currentIndex ? insertIndex - 1 : insertIndex, documentTemplateHtmlBuilderBlocks.length));
  documentTemplateHtmlBuilderBlocks.splice(safeIndex, 0, block);
  renderDocumentTemplateHtmlBuilderCanvas();
  syncDocumentTemplateHtmlBuilderCode();
}

function getDocumentTemplateHtmlBuilderDropIndex(event) {
  const targetCard = event.target instanceof HTMLElement
    ? event.target.closest("[data-html-builder-block-id]")
    : null;
  if (!(targetCard instanceof HTMLElement) || !documentTemplateHtmlBuilderCanvas?.contains(targetCard)) {
    return documentTemplateHtmlBuilderBlocks.length;
  }
  const blockId = String(targetCard.dataset.htmlBuilderBlockId || "");
  const index = documentTemplateHtmlBuilderBlocks.findIndex((block) => String(block.id) === blockId);
  return index >= 0 ? index : documentTemplateHtmlBuilderBlocks.length;
}

function createDocumentTemplateHtmlBuilderTokenSelect(value = "", onChange = null) {
  const select = document.createElement("select");
  const options = getDocumentTemplateHtmlBuilderTokenOptions();
  const normalizedValue = String(value || options[0]?.value || "{{DOCUMENT_TITLE}}").trim();
  const finalOptions = options.some((option) => option.value === normalizedValue)
    ? options
    : [{ value: normalizedValue, label: normalizedValue }, ...options];
  replaceSelectOptions(select, finalOptions.length > 0 ? finalOptions : [{ value: "{{DOCUMENT_TITLE}}", label: "{{DOCUMENT_TITLE}}" }], normalizedValue);
  select.addEventListener("change", () => {
    onChange?.(select.value);
    syncDocumentTemplateHtmlBuilderCode();
  });
  return select;
}

function createDocumentTemplateHtmlBuilderTextInput(value = "", onInput = null, { multiline = false } = {}) {
  const input = multiline ? document.createElement("textarea") : document.createElement("input");
  input.value = String(value || "");
  if (multiline) {
    input.rows = 3;
  }
  input.addEventListener("input", () => {
    onInput?.(input.value);
    syncDocumentTemplateHtmlBuilderCode();
  });
  return input;
}

function renderDocumentTemplateHtmlBuilderCanvas() {
  if (!(documentTemplateHtmlBuilderCanvas instanceof HTMLElement)) {
    return;
  }
  const engine = ensureDocumentTemplateHtmlBuilderEngine();
  if (engine) {
    engine.render();
    return;
  }

  if (documentTemplateHtmlBuilderBlocks.length === 0) {
    const empty = document.createElement("div");
    empty.className = "document-template-html-builder-empty";
    empty.textContent = "Povuci element ili placeholder ovdje.";
    documentTemplateHtmlBuilderCanvas.replaceChildren(empty);
    return;
  }

  const nodes = documentTemplateHtmlBuilderBlocks.map((block, index) => {
    const card = document.createElement("article");
    card.className = `document-template-html-builder-card${selectedDocumentTemplateHtmlBuilderBlockIds.has(block.id) ? " is-selected" : ""}`;
    card.dataset.htmlBuilderBlockId = block.id;
    card.draggable = true;

    const head = document.createElement("div");
    head.className = "document-template-html-builder-card-head";

    const select = document.createElement("input");
    select.type = "checkbox";
    select.checked = selectedDocumentTemplateHtmlBuilderBlockIds.has(block.id);
    select.addEventListener("change", () => {
      if (select.checked) {
        selectedDocumentTemplateHtmlBuilderBlockIds.add(block.id);
      } else {
        selectedDocumentTemplateHtmlBuilderBlockIds.delete(block.id);
      }
      renderDocumentTemplateHtmlBuilderCanvas();
    });

    const handle = document.createElement("span");
    handle.className = "document-template-html-builder-handle";
    handle.textContent = "⋮⋮";

    const title = document.createElement("strong");
    title.textContent = `${index + 1}. ${getDocumentTemplateHtmlBuilderTypeLabel(block.type)}`;

    const align = document.createElement("select");
    replaceSelectOptions(align, [
      { value: "left", label: "Lijevo" },
      { value: "center", label: "Centar" },
      { value: "right", label: "Desno" },
    ], block.align || "left");
    align.addEventListener("change", () => {
      block.align = normalizeDocumentTemplateHtmlBuilderAlign(align.value);
      syncDocumentTemplateHtmlBuilderCode();
    });

    const remove = createActionButton("×", "ghost-button", () => {
      documentTemplateHtmlBuilderBlocks = documentTemplateHtmlBuilderBlocks.filter((item) => String(item.id) !== String(block.id));
      selectedDocumentTemplateHtmlBuilderBlockIds.delete(block.id);
      renderDocumentTemplateHtmlBuilderCanvas();
      syncDocumentTemplateHtmlBuilderCode();
    });
    remove.title = "Obriši blok";

    head.append(select, handle, title, align, remove);

    const body = document.createElement("div");
    body.className = "document-template-html-builder-card-body";

    if (block.type === "heading") {
      body.append(createDocumentTemplateHtmlBuilderTextInput(block.text, (value) => { block.text = value; }));
    } else if (block.type === "paragraph") {
      body.append(createDocumentTemplateHtmlBuilderTextInput(block.text, (value) => { block.text = value; }, { multiline: true }));
    } else if (block.type === "placeholder") {
      body.append(
        createDocumentTemplateHtmlBuilderTextInput(block.label, (value) => { block.label = value; }),
        createDocumentTemplateHtmlBuilderTokenSelect(block.token, (value) => { block.token = value; }),
      );
    } else if (block.type === "columns") {
      const grid = document.createElement("div");
      grid.className = "document-template-html-builder-field-grid";
      grid.append(
        createDocumentTemplateHtmlBuilderTextInput(block.leftLabel, (value) => { block.leftLabel = value; }),
        createDocumentTemplateHtmlBuilderTokenSelect(block.leftToken, (value) => { block.leftToken = value; }),
        createDocumentTemplateHtmlBuilderTextInput(block.rightLabel, (value) => { block.rightLabel = value; }),
        createDocumentTemplateHtmlBuilderTokenSelect(block.rightToken, (value) => { block.rightToken = value; }),
      );
      body.append(grid);
    } else if (block.type === "table") {
      body.append(
        createDocumentTemplateHtmlBuilderTextInput(block.title, (value) => { block.title = value; }),
        createDocumentTemplateHtmlBuilderTokenSelect(block.token, (value) => { block.token = value; }),
      );
    } else if (block.type === "signature") {
      body.append(
        createDocumentTemplateHtmlBuilderTextInput(block.leftText, (value) => { block.leftText = value; }),
        createDocumentTemplateHtmlBuilderTextInput(block.rightText, (value) => { block.rightText = value; }),
      );
    } else {
      const meta = document.createElement("p");
      meta.className = "helper-copy module-copy";
      meta.textContent = getDocumentTemplateHtmlBuilderTypeLabel(block.type);
      body.append(meta);
    }

    card.append(head, body);
    return card;
  });

  documentTemplateHtmlBuilderCanvas.replaceChildren(...nodes);
}

function getDocumentTemplateBuilderInspectorFieldId(visibleFields = []) {
  const safeFields = Array.isArray(visibleFields) ? visibleFields : [];
  const hasActive = safeFields.some((field) => String(field?.id || "") === String(activeDocumentTemplateInspectorFieldId || ""));
  if (hasActive) {
    return String(activeDocumentTemplateInspectorFieldId || "");
  }
  return String(safeFields[0]?.id || "").trim();
}

function syncDocumentTemplateInspectorModal() {
  const shouldShow = Boolean(
    documentTemplateInspectorModalOpen
    && activeDocumentTemplateInspectorFieldId
    && !isDocumentTemplateRuntimeFillMode(),
  );
  const activeInspectorField = shouldShow
    ? documentTemplateFieldDrafts.find((field) => (
      String(field?.id || "") === String(activeDocumentTemplateInspectorFieldId || "")
    ))
    : null;
  const isExcelInspector = String(activeInspectorField?.type || "").trim().toLowerCase() === "measurement_table";

  if (documentTemplateBuilderInspector) {
    documentTemplateBuilderInspector.hidden = !shouldShow;
    documentTemplateBuilderInspector.classList.toggle("is-open", shouldShow);
    documentTemplateBuilderInspector.classList.toggle("is-excel-inspector", shouldShow && isExcelInspector);
    documentTemplateBuilderInspector.setAttribute("aria-hidden", String(!shouldShow));
  }
}

function closeDocumentTemplateInspectorModal({ render = false } = {}) {
  documentTemplateInspectorModalOpen = false;
  if (render) {
    renderDocumentTemplateFieldRows({ renderSupport: false });
    return;
  }
  syncDocumentTemplateInspectorModal();
}

function openDocumentTemplateInspectorModal(fieldId = "", { focus = false } = {}) {
  const normalizedFieldId = String(fieldId || "").trim();
  if (!normalizedFieldId) {
    return;
  }

  activeDocumentTemplateInspectorFieldId = normalizedFieldId;
  documentTemplateInspectorModalOpen = true;
  if (!isDocumentTemplateRuntimeFillMode()) {
    renderDocumentTemplateFieldRows({ renderSupport: false });
  } else {
    syncDocumentTemplateInspectorModal();
  }

  if (focus) {
    requestAnimationFrame(() => {
      const inspectorInput = documentTemplateFieldInspector?.querySelector("input, textarea, select");
      if (inspectorInput instanceof HTMLElement) {
        inspectorInput.focus({ preventScroll: true });
      }
    });
  }
}

function getDocumentTemplateBuilderWidthPercent(field = {}) {
  const widthValue = String(getDocumentTemplateRuntimeFieldLayoutWidth(field) || "9").trim().toLowerCase();
  if (widthValue === "full") {
    return "100%";
  }
  const numericWidth = Number.parseInt(widthValue, 10);
  if (!Number.isFinite(numericWidth) || numericWidth <= 0) {
    return "100%";
  }
  return `${Math.min(100, Math.max(1, (numericWidth / 9) * 100))}%`;
}

function getDocumentTemplateBuilderWidthMetaLabel(value = "", type = "text") {
  const normalizedWidth = normalizeDocumentTemplateFieldLayoutWidth(value, type);
  if (!isDocumentTemplateFieldWidthEditable(type) || normalizedWidth === "9") {
    return normalizedWidth === "9" ? "Puna širina" : `Širina ${normalizedWidth} / 9`;
  }
  return `Širina ${normalizedWidth} / 9`;
}

function isDocumentTemplateFieldHeightEditable(type = "text") {
  const normalizedType = String(type || "text").trim().toLowerCase();
  return normalizedType !== "chapter"
    && normalizedType !== "measurement_table"
    && normalizedType !== "page_break";
}

function getDocumentTemplateBuilderHeightConfig(type = "text") {
  const normalizedType = String(type || "text").trim().toLowerCase();
  if (normalizedType === "longtext") {
    return {
      min: 3,
      max: 18,
      defaultValue: 4,
      pixelStep: 28,
      baseHeight: 120,
      unitHeight: 28,
      labelSuffix: "reda",
    };
  }
  return {
    min: 0,
    max: 16,
    defaultValue: 4,
    pixelStep: 24,
    baseHeight: 64,
    unitHeight: 22,
    labelSuffix: "",
  };
}

function getDocumentTemplateBuilderFieldHeightValue(field = {}, { preserveAuto = false } = {}) {
  const type = String(field?.type || "text").trim().toLowerCase();
  if (!isDocumentTemplateFieldHeightEditable(type)) {
    return 0;
  }
  const normalizedValue = normalizeDocumentTemplateFieldHeight(field?.fieldHeight, type);
  if (preserveAuto && normalizedValue <= 0 && type !== "longtext") {
    return 0;
  }
  if (normalizedValue > 0) {
    return normalizedValue;
  }
  return getDocumentTemplateBuilderHeightConfig(type).defaultValue;
}

function getDocumentTemplateBuilderFieldHeightPx(field = {}, { preserveAuto = true } = {}) {
  const type = String(field?.type || "text").trim().toLowerCase();
  if (!isDocumentTemplateFieldHeightEditable(type)) {
    return 0;
  }
  const config = getDocumentTemplateBuilderHeightConfig(type);
  const units = getDocumentTemplateBuilderFieldHeightValue(field, { preserveAuto });
  if (units <= 0) {
    return 0;
  }
  return Math.max(config.baseHeight, units * config.unitHeight);
}

function isDocumentTemplatePreviewValueResizeEnabled(type = "text") {
  const normalizedType = String(type || "text").trim().toLowerCase();
  return normalizedType === "text"
    || normalizedType === "longtext"
    || normalizedType === "number"
    || normalizedType === "date";
}

function getDocumentTemplateBuilderPreviewValueHeightPx(field = {}, { preserveAuto = true } = {}) {
  const type = String(field?.type || "text").trim().toLowerCase();
  if (!isDocumentTemplatePreviewValueResizeEnabled(type)) {
    return 0;
  }
  const fieldHeight = getDocumentTemplateBuilderFieldHeightPx(field, { preserveAuto });
  if (fieldHeight <= 0) {
    return 0;
  }
  return Math.max(type === "longtext" ? 120 : 52, fieldHeight - 54);
}

function getDocumentTemplateBuilderHeightMetaLabel(field = {}) {
  const type = String(field?.type || "text").trim().toLowerCase();
  if (!isDocumentTemplateFieldHeightEditable(type)) {
    return "";
  }
  const normalizedValue = normalizeDocumentTemplateFieldHeight(field?.fieldHeight, type);
  if (normalizedValue <= 0 && type !== "longtext") {
    return "Auto visina";
  }
  const resolvedValue = normalizedValue > 0
    ? normalizedValue
    : getDocumentTemplateBuilderHeightConfig(type).defaultValue;
  const suffix = getDocumentTemplateBuilderHeightConfig(type).labelSuffix;
  return suffix ? `Visina ${resolvedValue} ${suffix}` : `Visina ${resolvedValue}`;
}

function getDocumentTemplateBuilderWidthValueFromRatio(ratio = 1, type = "text") {
  if (!isDocumentTemplateFieldWidthEditable(type)) {
    return "full";
  }

  const clampedRatio = Math.min(Math.max(Number(ratio) || 1, 1 / 9), 1);
  const candidateWidths = ["1", "2", "3", "4", "5", "6", "7", "8", "9"];
  let bestWidth = "9";
  let smallestDistance = Number.POSITIVE_INFINITY;

  candidateWidths.forEach((candidate) => {
    const candidateRatio = Number.parseFloat(
      getDocumentTemplateBuilderWidthPercent({
        type,
        layoutWidth: candidate,
      }),
    ) / 100;
    const distance = Math.abs((candidateRatio || 1) - clampedRatio);
    if (distance < smallestDistance) {
      smallestDistance = distance;
      bestWidth = candidate;
    }
  });

  return normalizeDocumentTemplateFieldLayoutWidth(bestWidth, type);
}

function cancelDocumentTemplateEditorSupportRefresh() {
  documentTemplateEditorSupportRefreshTimer = 0;
  if (documentTemplateEditorSupportRefreshFrame) {
    window.cancelAnimationFrame(documentTemplateEditorSupportRefreshFrame);
    documentTemplateEditorSupportRefreshFrame = 0;
  }
}

function invalidateDocumentTemplateDraftCache() {
  documentTemplateDraftCache = null;
  documentTemplateDraftCacheClearQueued = false;
}

function queueDocumentTemplateDraftCacheClear() {
  if (documentTemplateDraftCacheClearQueued) {
    return;
  }
  documentTemplateDraftCacheClearQueued = true;
  queueMicrotask(() => {
    documentTemplateDraftCache = null;
    documentTemplateDraftCacheClearQueued = false;
  });
}

function flushDocumentTemplateEditorSupportRefresh() {
  cancelDocumentTemplateEditorSupportRefresh();
  invalidateDocumentTemplateDraftCache();
  const template = buildDocumentTemplateDraft();
  const context = buildDocumentTemplatePreviewContext(template);
  renderDocumentTemplatePlaceholderPalette(template);
  renderDocumentTemplateHtmlBuilderCanvas();
  renderDocumentTemplateLinkSummary(template);
  renderDocumentTemplatePreviewContent(template, context);
}

function scheduleDocumentTemplateEditorSupportRefresh({ immediate = false } = {}) {
  cancelDocumentTemplateEditorSupportRefresh();
  invalidateDocumentTemplateDraftCache();
  invalidateDocumentTemplateDraftCache();

  if (immediate) {
    documentTemplateEditorSupportRefreshFrame = window.requestAnimationFrame(() => {
      documentTemplateEditorSupportRefreshFrame = 0;
      flushDocumentTemplateEditorSupportRefresh();
    });
    return;
  }

  documentTemplateEditorSupportRefreshTimer = window.setTimeout(() => {
    documentTemplateEditorSupportRefreshTimer = 0;
    documentTemplateEditorSupportRefreshFrame = window.requestAnimationFrame(() => {
      documentTemplateEditorSupportRefreshFrame = 0;
      flushDocumentTemplateEditorSupportRefresh();
    });
  }, 140);
}

async function copyDocumentTemplateToken(token = "") {
  const safeToken = String(token || "").trim();
  if (!safeToken) {
    return;
  }

  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(safeToken);
      setDocumentTemplateMessage("Placeholder je kopiran u clipboard.", { type: "success" });
      window.setTimeout(() => {
        if (documentTemplateError?.textContent === "Placeholder je kopiran u clipboard.") {
          setDocumentTemplateMessage("");
        }
      }, 1600);
      return;
    }
  } catch (error) {
    console.warn("Clipboard copy failed for document template token.", error);
  }

  insertTextIntoDocumentTemplateTarget(safeToken);
}

function rebuildDocumentTemplateCompanyOptions(selectedValue = "") {
  if (!documentTemplateCompanyIdInput) {
    return;
  }

  const options = [
    { value: "", label: "Bez primjerne tvrtke" },
    ...state.companies
      .slice()
      .sort((left, right) => left.name.localeCompare(right.name, "hr"))
      .map((company) => ({
        value: company.id,
        label: `${company.name} (${company.oib || "bez OIB-a"})`,
      })),
  ];

  replaceSelectOptions(documentTemplateCompanyIdInput, options, selectedValue || documentTemplateCompanyIdInput.value || "");
}

function rebuildDocumentTemplateLocationOptions(selectedValue = "") {
  if (!documentTemplateLocationIdInput) {
    return;
  }

  const companyId = documentTemplateCompanyIdInput?.value || "";
  const matchingLocations = (companyId ? state.locations.filter((item) => item.companyId === companyId) : state.locations)
    .slice()
    .sort((left, right) => left.name.localeCompare(right.name, "hr"));

  const options = [
    { value: "", label: "Bez primjerne lokacije" },
    ...matchingLocations.map((location) => ({
      value: location.id,
      label: `${location.name}${location.region ? ` | ${location.region}` : ""}`,
    })),
  ];

  replaceSelectOptions(documentTemplateLocationIdInput, options, selectedValue || documentTemplateLocationIdInput.value || "");
}

function getTemplateLinkedServiceCatalogIds(templateId = "", { organizationId = "" } = {}) {
  const normalizedTemplateId = String(templateId || "").trim();
  const normalizedOrganizationId = String(organizationId || "").trim();
  if (!normalizedTemplateId) {
    return [];
  }

  return sortServiceCatalogItems((state.serviceCatalog ?? []).filter((service) => (
    (!normalizedOrganizationId || String(service.organizationId) === normalizedOrganizationId)
    && (service.linkedTemplateIds ?? []).map(String).includes(normalizedTemplateId)
  ))).map((service) => String(service.id || "").trim()).filter(Boolean);
}

function getServiceDerivedLegalFrameworkIdsForTemplate(templateId = "", { organizationId = "" } = {}) {
  const linkedServiceIds = new Set(getTemplateLinkedServiceCatalogIds(templateId, { organizationId }));
  if (linkedServiceIds.size === 0) {
    return [];
  }

  return sortLegalFrameworks(state.legalFrameworks ?? [])
    .filter((item) => getLegalFrameworkLinkedServiceIds(item).some((serviceId) => linkedServiceIds.has(String(serviceId))))
    .map((item) => String(item.id || "").trim())
    .filter(Boolean);
}

function getServiceDerivedMeasurementEquipmentItemsForTemplate(templateId = "", { organizationId = "" } = {}) {
  const linkedServiceIds = new Set(getTemplateLinkedServiceCatalogIds(templateId, { organizationId }));
  if (linkedServiceIds.size === 0) {
    return [];
  }

  return sortMeasurementEquipmentItems(state.measurementEquipment ?? [])
    .filter((item) => getMeasurementEquipmentLinkedServiceIds(item).some((serviceId) => linkedServiceIds.has(String(serviceId))));
}

function getSelectedDocumentTemplateLegalFrameworkIds() {
  const activeTemplateId = String(state.activeDocumentTemplateId || documentTemplateIdInput?.value || "");
  const activeTemplate = activeTemplateId
    ? (state.documentTemplates.find((item) => String(item.id) === activeTemplateId) ?? null)
    : null;
  const derivedIds = activeTemplateId
    ? getServiceDerivedLegalFrameworkIdsForTemplate(activeTemplateId, {
      organizationId: activeTemplate?.organizationId || state.activeOrganizationId || "",
    })
    : [];

  if (!documentTemplateLegalFrameworkList) {
    const storedIds = activeTemplateId
      ? (activeTemplate?.selectedLegalFrameworkIds ?? [])
      : [];
    const linkedIds = activeTemplateId
      ? sortLegalFrameworks(state.legalFrameworks ?? [])
        .filter((item) => (item.linkedTemplateIds ?? []).map(String).includes(activeTemplateId))
        .map((item) => String(item.id))
      : [];
    return derivedIds.length > 0
      ? derivedIds
      : Array.from(new Set([...storedIds.map(String), ...linkedIds])).filter(Boolean);
  }

  return Array.from(
    documentTemplateLegalFrameworkList.querySelectorAll('input[name="document-template-legal-framework-id"]:checked'),
  ).map((input) => String(input.value || "")).filter(Boolean);
}

function isDocumentTemplateHtmlReferenceDocument(referenceDocument = {}) {
  const fileName = String(referenceDocument?.fileName || referenceDocument?.name || referenceDocument?.storageKey || "").trim().toLowerCase();
  const fileType = String(referenceDocument?.fileType || referenceDocument?.mimeType || "").trim().toLowerCase();
  return fileName.endsWith(".html")
    || fileName.endsWith(".htm")
    || fileType.startsWith("text/html");
}

function isDocumentTemplateWordReferenceDocument(referenceDocument = {}) {
  const fileName = String(referenceDocument?.fileName || referenceDocument?.name || referenceDocument?.storageKey || "").trim().toLowerCase();
  const fileType = String(referenceDocument?.fileType || referenceDocument?.mimeType || "").trim().toLowerCase();
  return fileName.endsWith(".docx")
    || fileName.endsWith(".dotx")
    || fileType.includes("wordprocessingml.document")
    || fileType.includes("wordprocessingml.template");
}

function normalizeDocumentTemplateHtmlBuilderDocumentPayload(value = []) {
  if (!Array.isArray(value)) {
    return [];
  }

  try {
    return JSON.parse(JSON.stringify(value)).filter((page) => (
      page && typeof page === "object" && String(page.type || "") === "page"
    ));
  } catch {
    return [];
  }
}

function normalizeDocumentTemplateReferenceDocument(referenceDocument = null) {
  if (!referenceDocument || typeof referenceDocument !== "object") {
    return null;
  }

  const isHtmlReference = isDocumentTemplateHtmlReferenceDocument(referenceDocument);
  const isWordReference = isDocumentTemplateWordReferenceDocument(referenceDocument);
  if (!isHtmlReference && !isWordReference) {
    return null;
  }

  const dataUrl = String(
    referenceDocument.dataUrl
    || referenceDocument.inlineDataUrl
    || referenceDocument.storageUrl
    || referenceDocument.url
    || "",
  ).trim();
  const builderDocument = normalizeDocumentTemplateHtmlBuilderDocumentPayload(
    referenceDocument.builderDocument ?? referenceDocument.builder_document,
  );
  if (!dataUrl && (!isHtmlReference || builderDocument.length === 0)) {
    return null;
  }

  return {
    fileName: String(
      referenceDocument.fileName
      || referenceDocument.name
      || (isWordReference ? "template-reference.docx" : "template-reference.html"),
    ).trim(),
    fileType: String(referenceDocument.fileType || referenceDocument.mimeType || (isWordReference
      ? "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
      : "text/html")).trim(),
    dataUrl,
    builderDocument: isHtmlReference ? builderDocument : [],
    inlineDataUrl: String(referenceDocument.inlineDataUrl || "").trim(),
    storageProvider: String(referenceDocument.storageProvider || "").trim(),
    storageBucket: String(referenceDocument.storageBucket || "").trim(),
    storageUrl: String(referenceDocument.storageUrl || "").trim(),
    storageKey: String(referenceDocument.storageKey || "").trim(),
    url: String(referenceDocument.url || "").trim(),
    fileSize: Number(referenceDocument.fileSize || 0) || 0,
    updatedAt: String(referenceDocument.updatedAt || new Date().toISOString()).trim(),
  };
}

function normalizeDocumentTemplateHtmlReferenceDocument(referenceDocument = null) {
  return normalizeDocumentTemplateReferenceDocument(referenceDocument);
}

function normalizeDocumentTemplateHtmlReferences(templates = []) {
  return (Array.isArray(templates) ? templates : []).map((template) => ({
    ...template,
    referenceDocument: normalizeDocumentTemplateReferenceDocument(template?.referenceDocument),
  }));
}

function getDocumentTemplateReferenceKind(referenceDocument = null) {
  if (isDocumentTemplateHtmlReferenceDocument(referenceDocument)) {
    return "html";
  }
  if (isDocumentTemplateWordReferenceDocument(referenceDocument)) {
    return "word";
  }
  return "";
}

function getDocumentTemplateReferenceLabel(referenceDocument = null) {
  const kind = getDocumentTemplateReferenceKind(referenceDocument);
  if (kind === "html") {
    return "HTML";
  }
  if (kind === "word") {
    return "Word";
  }
  return "Predložak";
}

function normalizeDocumentTemplateReferenceEngine(value = "") {
  return String(value || "").trim().toLowerCase() === "word" ? "word" : "html";
}

function getDocumentTemplateSelectedReferenceEngine() {
  if (documentTemplateEngineInput instanceof HTMLSelectElement) {
    return normalizeDocumentTemplateReferenceEngine(documentTemplateEngineInput.value || documentTemplateReferenceEngine);
  }
  return normalizeDocumentTemplateReferenceEngine(documentTemplateReferenceEngine || state.documentTemplateReferenceEngine);
}

function syncDocumentTemplateReferenceEngineChrome() {
  const selectedEngine = getDocumentTemplateSelectedReferenceEngine();
  documentTemplateReferenceEngine = selectedEngine;
  state.documentTemplateReferenceEngine = selectedEngine;

  if (documentTemplateEngineInput instanceof HTMLSelectElement && documentTemplateEngineInput.value !== selectedEngine) {
    documentTemplateEngineInput.value = selectedEngine;
  }
  documentTemplateEngineChoiceButtons.forEach((button) => {
    if (!(button instanceof HTMLButtonElement)) {
      return;
    }
    const isActive = normalizeDocumentTemplateReferenceEngine(button.dataset.documentTemplateEngineChoice || "") === selectedEngine;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-pressed", String(isActive));
  });
  if (documentTemplateEditorPanel instanceof HTMLElement) {
    documentTemplateEditorPanel.classList.toggle("is-document-template-word-engine", selectedEngine === "word");
  }
  if (documentTemplateReferenceFileInput instanceof HTMLInputElement) {
    documentTemplateReferenceFileInput.accept = selectedEngine === "word"
      ? ".docx,.dotx,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.wordprocessingml.template"
      : ".html,.htm,text/html,.docx,.dotx,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.openxmlformats-officedocument.wordprocessingml.template";
  }
  if (documentTemplateReferenceUploadButton instanceof HTMLButtonElement) {
    documentTemplateReferenceUploadButton.textContent = selectedEngine === "word" ? "Upload Word" : "Upload HTML / Word";
  }
  if (documentTemplateHtmlSaveButton instanceof HTMLButtonElement) {
    documentTemplateHtmlSaveButton.hidden = selectedEngine === "word";
  }
  if (documentTemplateExportPlaceholderButton instanceof HTMLButtonElement) {
    documentTemplateExportPlaceholderButton.hidden = selectedEngine === "word";
  }
}

function applyDocumentTemplateReferenceEngineChoice(value = "html") {
  const nextEngine = normalizeDocumentTemplateReferenceEngine(value);
  documentTemplateReferenceEngine = nextEngine;
  state.documentTemplateReferenceEngine = nextEngine;
  if (documentTemplateEngineInput instanceof HTMLSelectElement) {
    documentTemplateEngineInput.value = nextEngine;
  }

  const currentKind = getDocumentTemplateReferenceKind(documentTemplateReferenceDraft);
  if (currentKind && nextEngine !== currentKind) {
    setDocumentTemplateReferenceDocument(null);
  } else {
    syncDocumentTemplateReferenceEngineChrome();
    renderDocumentTemplateReferenceMeta();
  }

  setDocumentTemplateMessage(
    nextEngine === "word"
      ? "Odabrano je Word / PDF. Učitaj .docx/.dotx predložak za ovaj template."
      : "Odabrano je HTML / PDF. Učitaj .html ili klikni Spremi HTML kod za prebacivanje templatea.",
  );
}

function syncDocumentTemplateEngineInputFromReference(referenceDocument = documentTemplateReferenceDraft) {
  if (!(documentTemplateEngineInput instanceof HTMLSelectElement)) {
    syncDocumentTemplateReferenceEngineChrome();
    return;
  }
  const kind = getDocumentTemplateReferenceKind(referenceDocument);
  if (kind) {
    documentTemplateReferenceEngine = kind === "word" ? "word" : "html";
  } else {
    documentTemplateReferenceEngine = normalizeDocumentTemplateReferenceEngine(
      documentTemplateEngineInput.value || documentTemplateReferenceEngine || state.documentTemplateReferenceEngine,
    );
  }
  state.documentTemplateReferenceEngine = documentTemplateReferenceEngine;
  documentTemplateEngineInput.value = documentTemplateReferenceEngine;
  syncDocumentTemplateReferenceEngineChrome();
}

function syncDocumentTemplateHtmlCodeInputFromReference() {
  if (!documentTemplateHtmlCodeInput) {
    return;
  }

  const referenceDocument = documentTemplateReferenceDraft;
  syncDocumentTemplateEngineInputFromReference(referenceDocument);
  if (!referenceDocument) {
    documentTemplateHtmlCodeInput.value = "";
    documentTemplateHtmlCodeDirty = false;
    documentTemplateHtmlCodeInput.placeholder = "Zalijepi HTML s tokenima, npr. {{DOCUMENT_TITLE}} i {{BROJ_RADNOG_NALOGA}}";
    setDocumentTemplateHtmlBuilderBlocks([], { syncCode: false });
    return;
  }

  if (!isDocumentTemplateHtmlReferenceDocument(referenceDocument)) {
    documentTemplateHtmlCodeInput.value = "";
    documentTemplateHtmlCodeDirty = false;
    documentTemplateHtmlCodeInput.placeholder = "Ovaj template trenutno koristi Word/PDF. Za HTML varijantu odaberi HTML / PDF, zalijepi kod ili učitaj .html datoteku.";
    setDocumentTemplateHtmlBuilderBlocks([], { syncCode: false });
    return;
  }

  documentTemplateHtmlCodeInput.placeholder = "HTML je spremljen. Ako želiš izmjenu, zalijepi novu verziju i klikni Spremi HTML kod.";
  const builderDocument = normalizeDocumentTemplateHtmlBuilderDocumentPayload(referenceDocument.builderDocument);
  if (builderDocument.length > 0) {
    const htmlText = ensureHtmlUtf8Meta(buildBuilderHtmlFromDocument(builderDocument));
    documentTemplateHtmlCodeInput.value = htmlText;
    documentTemplateHtmlCodeDirty = false;
    const engine = ensureDocumentTemplateHtmlBuilderEngine();
    engine?.loadDocument(builderDocument);
    documentTemplateHtmlBuilderBlocks = createLegacyBlocksFromBuilderDocument(builderDocument);
    renderDocumentTemplateHtmlPreviewContent();
    return;
  }

  const dataUrl = String(referenceDocument.dataUrl || referenceDocument.inlineDataUrl || referenceDocument.storageUrl || referenceDocument.url || "").trim();
  if (!dataUrl) {
    return;
  }

  void readDataUrlAsText(dataUrl)
    .then((text) => {
      const currentDataUrl = String(
        documentTemplateReferenceDraft?.dataUrl
        || documentTemplateReferenceDraft?.inlineDataUrl
        || documentTemplateReferenceDraft?.storageUrl
        || documentTemplateReferenceDraft?.url
        || "",
      ).trim();
      if (currentDataUrl === dataUrl) {
        const htmlText = ensureHtmlUtf8Meta(text);
        documentTemplateHtmlCodeInput.value = htmlText;
        documentTemplateHtmlCodeDirty = false;
        hydrateDocumentTemplateHtmlBuilderFromCode(htmlText);
        renderDocumentTemplateHtmlPreviewContent();
      }
    })
    .catch(() => {});
}

function renderDocumentTemplateReferenceMeta() {
  if (!documentTemplateReferenceMeta) {
    return;
  }

  documentTemplateReferenceMeta.replaceChildren();
  const template = buildDocumentTemplateDraft();
  const fields = Array.isArray(template.customFields) ? template.customFields : [];
  const blockCount = fields.filter((field) => String(field?.type || "").trim().toLowerCase() === "chapter").length;
  const placeholderCount = fields.filter((field) => String(field?.type || "").trim().toLowerCase() !== "chapter").length;

  if (!documentTemplateReferenceDraft) {
    syncDocumentTemplateEngineInputFromReference(null);
    const selectedEngine = getDocumentTemplateSelectedReferenceEngine();
    const stateWrap = document.createElement("div");
    stateWrap.className = "document-template-reference-status";

    const stateBadge = document.createElement("span");
    stateBadge.className = "document-template-reference-state is-missing";
    stateBadge.textContent = selectedEngine === "word" ? "Word čeka upload" : "Predložak još nije učitan";

    const readiness = document.createElement("span");
    readiness.className = "document-template-reference-note";
    readiness.textContent = selectedEngine === "word"
      ? `${blockCount} blokova · ${placeholderCount} placeholdera spremno za Word`
      : `${blockCount} blokova · ${placeholderCount} placeholdera spremno za HTML ili Word`;

    stateWrap.append(stateBadge, readiness);

    const empty = document.createElement("strong");
    empty.textContent = selectedEngine === "word"
      ? "Učitaj .docx/.dotx Word predložak za ovaj template."
      : "Odaberi HTML / PDF ili Word / PDF, pa učitaj predložak za ovaj template.";

    const meta = document.createElement("span");
    meta.textContent = selectedEngine === "word"
      ? "Kod Word / PDF načina ovdje ostaje samo upload i preuzimanje Word predloška."
      : "HTML koristi builder ili ručni kod, a Word koristi .docx/.dotx s istim placeholderima.";

    documentTemplateReferenceMeta.append(stateWrap, empty, meta);
    if (documentTemplateReferenceDownloadButton) {
      documentTemplateReferenceDownloadButton.hidden = true;
    }
    if (documentTemplateReferenceRemoveButton) {
      documentTemplateReferenceRemoveButton.hidden = true;
    }
    if (documentTemplateReferenceDownloadButton) {
      documentTemplateReferenceDownloadButton.textContent = "Preuzmi predložak";
    }
    if (documentTemplateReferenceRemoveButton) {
      documentTemplateReferenceRemoveButton.textContent = "Makni predložak";
    }
    return;
  }

  const stateWrap = document.createElement("div");
  stateWrap.className = "document-template-reference-status";

  const referenceKind = getDocumentTemplateReferenceKind(documentTemplateReferenceDraft);
  const referenceLabel = getDocumentTemplateReferenceLabel(documentTemplateReferenceDraft);
  syncDocumentTemplateEngineInputFromReference(documentTemplateReferenceDraft);
  const stateBadge = document.createElement("span");
  stateBadge.className = `document-template-reference-state ${referenceKind ? "is-ready" : "is-missing"}`;
  stateBadge.textContent = referenceKind === "word" ? "Word povezan" : "HTML povezan";

  const readiness = document.createElement("span");
  readiness.className = "document-template-reference-note";
  readiness.textContent = `${blockCount} blokova · ${placeholderCount} placeholdera`;
  stateWrap.append(stateBadge, readiness);

  const title = document.createElement("strong");
  title.textContent = documentTemplateReferenceDraft.fileName || "reference.html";

  const meta = document.createElement("span");
  meta.textContent = [
    documentTemplateReferenceDraft.fileType || "datoteka",
    documentTemplateReferenceDraft.updatedAt ? `Ažurirano ${formatDateTime(documentTemplateReferenceDraft.updatedAt)}` : "",
  ].filter(Boolean).join(" · ");

  const note = document.createElement("span");
  note.textContent = referenceKind === "html"
    ? "Kasniji PDF zapisnici koriste ovaj HTML predložak."
    : "Kasniji PDF zapisnici koriste ovaj Word predložak i pretvaraju ga u PDF.";

  documentTemplateReferenceMeta.append(stateWrap, title, meta, note);

  if (documentTemplateReferenceDownloadButton) {
    documentTemplateReferenceDownloadButton.hidden = false;
    documentTemplateReferenceDownloadButton.textContent = `Preuzmi spremljeni ${referenceLabel}`;
  }
  if (documentTemplateReferenceRemoveButton) {
    documentTemplateReferenceRemoveButton.hidden = false;
    documentTemplateReferenceRemoveButton.textContent = `Makni ${referenceLabel}`;
  }
}

function setDocumentTemplateReferenceDocument(referenceDocument = null) {
  invalidateDocumentTemplateDraftCache();
  documentTemplateReferenceDraft = normalizeDocumentTemplateHtmlReferenceDocument(referenceDocument);
  documentTemplateHtmlCodeDirty = false;
  syncDocumentTemplateHtmlCodeInputFromReference();
  renderDocumentTemplateReferenceMeta();
  renderDocumentTemplatePreviewContent();
}

function getDocumentTemplateManualHtmlCode() {
  return ensureHtmlUtf8Meta(String(documentTemplateHtmlCodeInput?.value || "").trim());
}

function getBuilderDocumentFromHtmlCode(htmlCode = "") {
  const parsedBuilderDocument = parseBuilderDocumentFromHtml(htmlCode);
  return parsedBuilderDocument
    ? normalizeDocumentTemplateHtmlBuilderDocumentPayload(parsedBuilderDocument)
    : [];
}

function shouldPreferDocumentTemplateHtmlCodeForSave({ preferTextarea = false, htmlCode = "" } = {}) {
  if (preferTextarea || documentTemplateHtmlCodeDirty) {
    return true;
  }

  const previousReference = normalizeDocumentTemplateHtmlReferenceDocument(documentTemplateReferenceDraft);
  return Boolean(
    htmlCode
    && previousReference
    && isDocumentTemplateHtmlReferenceDocument(previousReference)
    && normalizeDocumentTemplateHtmlBuilderDocumentPayload(previousReference.builderDocument).length === 0
  );
}

function getCurrentDocumentTemplateHtmlCodeForSave({ preferTextarea = false } = {}) {
  const manualHtmlCode = getDocumentTemplateManualHtmlCode();
  if (shouldPreferDocumentTemplateHtmlCodeForSave({ preferTextarea, htmlCode: manualHtmlCode })) {
    if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement && documentTemplateHtmlCodeInput.value !== manualHtmlCode) {
      documentTemplateHtmlCodeInput.value = manualHtmlCode;
    }
    return manualHtmlCode;
  }

  if (documentTemplateHtmlBuilderEngine) {
    const builderDocument = documentTemplateHtmlBuilderEngine.getDocument?.();
    const htmlCode = ensureHtmlUtf8Meta(buildBuilderHtmlFromDocument(builderDocument));
    documentTemplateHtmlBuilderBlocks = createLegacyBlocksFromBuilderDocument(builderDocument);
    if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement && documentTemplateHtmlCodeInput.value !== htmlCode) {
      documentTemplateHtmlCodeInput.value = htmlCode;
      documentTemplateHtmlCodeDirty = false;
    }
    return String(htmlCode || "").trim();
  }
  const referenceBuilderDocument = normalizeDocumentTemplateHtmlBuilderDocumentPayload(documentTemplateReferenceDraft?.builderDocument);
  if (referenceBuilderDocument.length > 0 && !String(documentTemplateHtmlCodeInput?.value || "").trim()) {
    const htmlCode = ensureHtmlUtf8Meta(buildBuilderHtmlFromDocument(referenceBuilderDocument));
    if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement) {
      documentTemplateHtmlCodeInput.value = htmlCode;
      documentTemplateHtmlCodeDirty = false;
    }
    return String(htmlCode || "").trim();
  }
  return manualHtmlCode;
}

function getCurrentDocumentTemplateHtmlBuilderDocumentForSave(htmlCode = "", { preferTextarea = false } = {}) {
  if (shouldPreferDocumentTemplateHtmlCodeForSave({ preferTextarea, htmlCode })) {
    return getBuilderDocumentFromHtmlCode(htmlCode);
  }

  return documentTemplateHtmlBuilderEngine
    ? normalizeDocumentTemplateHtmlBuilderDocumentPayload(documentTemplateHtmlBuilderEngine.getDocument?.())
    : normalizeDocumentTemplateHtmlBuilderDocumentPayload(documentTemplateReferenceDraft?.builderDocument);
}

function syncDocumentTemplateReferenceDocumentFromCurrentHtml({ render = false, force = false, preferTextarea = false } = {}) {
  if (getDocumentTemplateSelectedReferenceEngine() === "word" && !force) {
    return false;
  }

  const previousKind = getDocumentTemplateReferenceKind(documentTemplateReferenceDraft);
  if (previousKind === "word" && !force) {
    return false;
  }

  const htmlCode = getCurrentDocumentTemplateHtmlCodeForSave({ preferTextarea });
  const builderDocument = getCurrentDocumentTemplateHtmlBuilderDocumentForSave(htmlCode, { preferTextarea });
  if (!htmlCode && builderDocument.length === 0) {
    return false;
  }

  const previousReference = normalizeDocumentTemplateHtmlReferenceDocument(documentTemplateReferenceDraft);
  const baseName = sanitizeDocumentTemplateFileName(
    documentTemplateTitleInput?.value || documentTemplateOutputFileNameInput?.value || previousReference?.fileName || "zapisnik-template",
    "zapisnik-template",
  ).replace(/\.(html?|docx?|pdf)$/i, "");
  const fileName = previousKind === "html" && previousReference?.fileName
    ? previousReference.fileName
    : `${baseName}.html`;
  const dataUrl = textToDataUrl(htmlCode);

  if (
    previousReference
    && String(previousReference.fileName || "") === fileName
    && String(previousReference.dataUrl || previousReference.inlineDataUrl || "") === dataUrl
    && JSON.stringify(previousReference.builderDocument || []) === JSON.stringify(builderDocument)
  ) {
    documentTemplateHtmlCodeDirty = false;
    return false;
  }

  invalidateDocumentTemplateDraftCache();
  documentTemplateReferenceDraft = normalizeDocumentTemplateHtmlReferenceDocument({
    fileName,
    fileType: "text/html",
    fileSize: new TextEncoder().encode(htmlCode).length,
    dataUrl,
    builderDocument,
    updatedAt: new Date().toISOString(),
  });
  documentTemplateHtmlCodeDirty = false;

  if (render) {
    renderDocumentTemplateReferenceMeta();
    renderDocumentTemplatePreviewContent();
  }
  return true;
}

function cloneDocumentTemplateBuilderDocument(document = []) {
  return normalizeDocumentTemplateHtmlBuilderDocumentPayload(document);
}

function captureDocumentTemplateEditorDraftForSnapshot() {
  if (!state.documentTemplateEditorOpen || isDocumentTemplateRuntimeFillMode()) {
    return null;
  }

  const referenceDraft = normalizeDocumentTemplateReferenceDocument(documentTemplateReferenceDraft);
  const referenceKind = getDocumentTemplateReferenceKind(referenceDraft);
  const manualHtmlCode = getDocumentTemplateManualHtmlCode();
  const preferHtmlCodeForSnapshot = getDocumentTemplateWorkspaceTab() === "html"
    && referenceKind !== "word"
    && Boolean(manualHtmlCode);
  const builderDocument = referenceKind === "word"
    ? []
    : (preferHtmlCodeForSnapshot
      ? getBuilderDocumentFromHtmlCode(manualHtmlCode)
      : documentTemplateHtmlBuilderEngine
      ? cloneDocumentTemplateBuilderDocument(documentTemplateHtmlBuilderEngine.getDocument?.())
      : cloneDocumentTemplateBuilderDocument(documentTemplateReferenceDraft?.builderDocument));
  const htmlCode = preferHtmlCodeForSnapshot
    ? manualHtmlCode
    : builderDocument.length > 0
    ? buildBuilderHtmlFromDocument(builderDocument)
    : (referenceKind === "word" ? "" : manualHtmlCode);

  return {
    templateId: String(documentTemplateIdInput?.value || state.activeDocumentTemplateId || "").trim(),
    title: String(documentTemplateTitleInput?.value || "").trim(),
    workspaceTab: state.documentTemplateWorkspaceTab || "builder",
    referenceEngine: getDocumentTemplateSelectedReferenceEngine(),
    htmlPreviewCollapsed: true,
    sidebarPanels: {
      referenceCollapsed: Boolean(state.documentTemplateSidebarPanels?.referenceCollapsed),
      placeholdersCollapsed: Boolean(state.documentTemplateSidebarPanels?.placeholdersCollapsed),
    },
    referenceDraft,
    builderDocument,
    htmlCode,
    editorScrollTop: Number(documentTemplateEditorBody?.scrollTop || 0),
  };
}

function restoreDocumentTemplateEditorDraftAfterSnapshot(capture = null) {
  if (!capture || !state.documentTemplateEditorOpen || isDocumentTemplateRuntimeFillMode()) {
    return;
  }

  const builderDocument = cloneDocumentTemplateBuilderDocument(capture.builderDocument);
  const htmlCode = builderDocument.length > 0
    ? buildBuilderHtmlFromDocument(builderDocument)
    : String(capture.htmlCode || "").trim();
  const referenceDraft = normalizeDocumentTemplateReferenceDocument(capture.referenceDraft);
  const referenceKind = getDocumentTemplateReferenceKind(referenceDraft);
  const baseName = sanitizeDocumentTemplateFileName(
    capture.title || documentTemplateTitleInput?.value || documentTemplateOutputFileNameInput?.value || referenceDraft?.fileName || "zapisnik-template",
    "zapisnik-template",
  ).replace(/\.(html?|docx?|pdf)$/i, "");

  if (capture.templateId && documentTemplateIdInput) {
    documentTemplateIdInput.value = capture.templateId;
    state.activeDocumentTemplateId = capture.templateId;
  }

  state.documentTemplateWorkspaceTab = capture.workspaceTab || "builder";
  documentTemplateReferenceEngine = normalizeDocumentTemplateReferenceEngine(capture.referenceEngine || referenceKind || "html");
  state.documentTemplateReferenceEngine = documentTemplateReferenceEngine;
  state.documentTemplateHtmlPreviewCollapsed = true;
  state.documentTemplateSidebarPanels = {
    referenceCollapsed: Boolean(capture.sidebarPanels?.referenceCollapsed),
    placeholdersCollapsed: Boolean(capture.sidebarPanels?.placeholdersCollapsed),
  };

  if (referenceKind === "word" && referenceDraft) {
    documentTemplateReferenceDraft = referenceDraft;
  } else if (builderDocument.length > 0 || htmlCode) {
    documentTemplateReferenceDraft = normalizeDocumentTemplateHtmlReferenceDocument({
      ...(referenceDraft ?? {}),
      fileName: referenceDraft?.fileName || `${baseName}.html`,
      fileType: "text/html",
      fileSize: new TextEncoder().encode(htmlCode).length,
      dataUrl: htmlCode ? textToDataUrl(htmlCode) : (referenceDraft?.dataUrl || referenceDraft?.inlineDataUrl || ""),
      builderDocument,
      updatedAt: referenceDraft?.updatedAt || new Date().toISOString(),
    });
  }

  documentTemplateHtmlBuilderBlocks = referenceKind === "word"
    ? []
    : (builderDocument.length > 0
      ? createLegacyBlocksFromBuilderDocument(builderDocument)
      : documentTemplateHtmlBuilderBlocks);
  if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement && referenceKind === "word") {
    documentTemplateHtmlCodeInput.value = "";
    documentTemplateHtmlCodeDirty = false;
  } else if (documentTemplateHtmlCodeInput instanceof HTMLTextAreaElement && htmlCode) {
    documentTemplateHtmlCodeInput.value = htmlCode;
    documentTemplateHtmlCodeDirty = false;
  }
  const engine = ensureDocumentTemplateHtmlBuilderEngine();
  if (engine && referenceKind === "word") {
    engine.loadDocument([]);
  } else if (engine && builderDocument.length > 0) {
    engine.loadDocument(builderDocument);
  }

  invalidateDocumentTemplateDraftCache();
  syncDocumentTemplateWorkspaceTabs();
  syncDocumentTemplateHtmlPreviewVisibility();
  renderDocumentTemplateReferenceMeta();
  renderDocumentTemplatePreviewContent();
  syncDocumentTemplateEditorChrome();
  if (documentTemplateEditorBody && Number.isFinite(capture.editorScrollTop)) {
    documentTemplateEditorBody.scrollTop = Math.max(0, capture.editorScrollTop);
    requestAnimationFrame(() => {
      documentTemplateEditorBody.scrollTop = Math.max(0, capture.editorScrollTop);
    });
    window.setTimeout(() => {
      documentTemplateEditorBody.scrollTop = Math.max(0, capture.editorScrollTop);
    }, 0);
  }
}

function buildDocumentTemplateDraft() {
  if (documentTemplateDraftCache) {
    return documentTemplateDraftCache;
  }

  const activeTemplate = (state.documentTemplates ?? []).find((item) => (
    String(item.id) === String(state.activeDocumentTemplateId || documentTemplateIdInput?.value || "")
  )) ?? null;
  documentTemplateFieldDrafts.forEach((field) => {
    ensureDocumentTemplateDatabaseLookupDraft(field);
  });

  const customFields = documentTemplateFieldDrafts
    .map((field, index) => ({
      id: field.id || crypto.randomUUID(),
      key: normalizeDocumentTemplateFieldKeyDraft(field.key || field.wordLabel || field.label, `FIELD_${index + 1}`),
      label: String(field.label || "").trim() || `Polje ${index + 1}`,
      wordLabel: String(field.wordLabel || field.label || "").trim() || `Polje ${index + 1}`,
      type: field.type || "text",
      required: Boolean(field.required),
      trackPeriodics: isDocumentTemplatePeriodicsTrackableField({
        ...field,
        type: field.type || "text",
        source: String(field.source || getDocumentTemplateDefaultFieldSource(field.type || "text")).trim().toUpperCase(),
      })
        ? Boolean(field.trackPeriodics ?? field.periodicsTracked)
        : false,
      layoutWidth: normalizeDocumentTemplateFieldLayoutWidth(field.layoutWidth, field.type || "text"),
      fieldHeight: normalizeDocumentTemplateFieldHeight(field.fieldHeight, field.type || "text"),
      htmlStyle: normalizeDocumentTemplateHtmlStyleDraft(field.htmlStyle),
      source: String(field.source || getDocumentTemplateDefaultFieldSource(field.type || "text")).trim().toUpperCase(),
      sourceTable: String(field.sourceTable || "").trim().toLowerCase(),
      lookupColumn: String(field.lookupColumn || "").trim().toLowerCase(),
      lookupValueSource: String(field.lookupValueSource || "").trim().toUpperCase() || "WORK_ORDER_NUMBER",
      lookupValue: String(field.lookupValue || "").trim(),
      valueColumn: String(field.valueColumn || "").trim().toLowerCase(),
      previousDocumentMode: String(field.previousDocumentMode || "NONE").trim().toUpperCase() || "NONE",
      defaultValue: String(field.defaultValue || "").trim(),
      helpText: String(field.helpText || "").trim(),
      toggleTrueLabel: String(field.toggleTrueLabel || "").trim().slice(0, 120),
      toggleFalseLabel: String(field.toggleFalseLabel || "").trim().slice(0, 120),
      toggleTrueText: String(field.toggleTrueText ?? field.toggleTrueDetailText ?? "").trim().slice(0, 500),
      toggleFalseText: String(field.toggleFalseText ?? field.toggleFalseDetailText ?? "").trim().slice(0, 500),
      textListStyle: isDocumentTemplateTextListStyleField(field.type)
        ? normalizeDocumentTemplateTextListStyleLocal(field.textListStyle ?? field.listStyle)
        : "none",
      ai: normalizeDocumentTemplateFieldAiConfig(field.ai ?? field.aiConfig, field),
      dropdownOptions: field.type === "dropdown"
        ? normalizeDocumentTemplateDropdownOptionsLocal(field.dropdownOptions ?? field.options ?? field.choices)
        : [],
      sectionSubtitle: String(field.sectionSubtitle || "").trim(),
      systemRows: normalizeDocumentTemplateSystemDescriptionRows(field.systemRows, {
        ensureOne: field.type === "system_description",
        fallbackRows: field.type === "system_description"
          ? createDefaultDocumentTemplateSystemDescriptionRows()
          : [],
      }),
      signatureArea: String(field.signatureArea || "elektro").trim().toLowerCase() || "elektro",
      signatureRole: normalizeDocumentTemplateSignatureRole(field.signatureRole || (field.type === "authorization_holder_signature" ? "authorize" : "inspect")),
      signatureMultiple: field.type === "authorization_holder_signature" || field.type === "inspector_signature"
        ? false
        : Boolean(field.signatureMultiple ?? true),
      signatureIncludeScan: Boolean(field.signatureIncludeScan),
      signatureMetaFields: normalizeDocumentTemplateSignatureMetaFieldsLocal(field.signatureMetaFields),
      legalFrameworkIds: (Array.isArray(field.legalFrameworkIds) ? field.legalFrameworkIds : [])
        .map((value) => String(value || "").trim())
        .filter(Boolean),
      defaultLegalFrameworkIds: (Array.isArray(field.defaultLegalFrameworkIds) ? field.defaultLegalFrameworkIds : [])
        .map((value) => String(value || "").trim())
        .filter(Boolean),
      columns: String(field.columns || "")
        .split(/[\n,]/)
        .map((entry) => entry.trim())
        .filter(Boolean)
        .slice(0, 16),
      rowCount: Math.max(4, Math.min(120, Math.round(parseTemplateLooseNumber(field.rowCount, 12)))),
      sheet: field.type === "measurement_table"
        ? (field.sheet ?? ensureDocumentTemplateMeasurementFieldSheet(field))
        : null,
    }))
    .map((field) => {
      if (field.type === "measurement_table") {
        const sheet = ensureDocumentTemplateMeasurementFieldSheet(field);
        return {
          ...field,
          source: "",
          sourceTable: "",
          lookupColumn: "",
          lookupValueSource: "WORK_ORDER_NUMBER",
          lookupValue: "",
          valueColumn: "",
          previousDocumentMode: "NONE",
          layoutWidth: "9",
          fieldHeight: 0,
          columns: sheet.columns.map((column) => column.label),
          rowCount: sheet.rows.length,
          sheet,
        };
      }

      if (isDocumentTemplateSpecialFieldType(field.type)) {
        const legalFrameworkIds = field.type === "legal_list"
          ? field.legalFrameworkIds
          : [];
        const defaultLegalFrameworkIds = field.type === "legal_list"
          ? field.defaultLegalFrameworkIds.filter((value) => legalFrameworkIds.includes(value))
          : [];
        return {
          ...field,
          source: "",
          sourceTable: "",
          lookupColumn: "",
          lookupValueSource: "WORK_ORDER_NUMBER",
          lookupValue: "",
          valueColumn: "",
          previousDocumentMode: "NONE",
          signatureArea: field.signatureArea || "elektro",
          signatureRole: normalizeDocumentTemplateSignatureRole(field.signatureRole || (field.type === "authorization_holder_signature" ? "authorize" : "inspect")),
          signatureMultiple: field.type === "authorization_holder_signature" || field.type === "inspector_signature"
            ? false
            : Boolean(field.signatureMultiple ?? true),
          signatureIncludeScan: Boolean(field.signatureIncludeScan),
          sectionSubtitle: field.type === "system_description"
            ? String(field.sectionSubtitle || "").trim()
            : "",
          systemRows: field.type === "system_description"
            ? normalizeDocumentTemplateSystemDescriptionRows(field.systemRows, {
              ensureOne: true,
              fallbackRows: createDefaultDocumentTemplateSystemDescriptionRows(),
            })
            : [],
          layoutWidth: getDocumentTemplateRuntimeFieldLayoutWidth(field),
          fieldHeight: normalizeDocumentTemplateFieldHeight(field.fieldHeight, field.type || "text"),
          legalFrameworkIds,
          defaultLegalFrameworkIds,
          columns: [],
          rowCount: 0,
          sheet: null,
        };
      }

        return {
          ...field,
          source: field.source || "CUSTOM_VALUE",
          layoutWidth: normalizeDocumentTemplateFieldLayoutWidth(field.layoutWidth, field.type || "text"),
          fieldHeight: normalizeDocumentTemplateFieldHeight(field.fieldHeight, field.type || "text"),
          sourceTable: field.source === "DATABASE_LOOKUP" ? field.sourceTable : "",
          lookupColumn: field.source === "DATABASE_LOOKUP" ? field.lookupColumn : "",
          lookupValueSource: field.source === "DATABASE_LOOKUP" ? field.lookupValueSource : "WORK_ORDER_NUMBER",
          lookupValue: field.source === "DATABASE_LOOKUP" ? field.lookupValue : "",
          valueColumn: field.source === "DATABASE_LOOKUP" ? field.valueColumn : "",
          previousDocumentMode: field.previousDocumentMode || "NONE",
          sectionSubtitle: "",
          systemRows: [],
          textListStyle: isDocumentTemplateTextListStyleField(field.type)
            ? normalizeDocumentTemplateTextListStyleLocal(field.textListStyle)
            : "none",
          dropdownOptions: field.type === "dropdown"
            ? normalizeDocumentTemplateDropdownOptionsLocal(field.dropdownOptions)
            : [],
          legalFrameworkIds: [],
          defaultLegalFrameworkIds: [],
          columns: [],
          rowCount: 0,
          sheet: null,
        };
    })
    .filter((field) => (
      isDocumentTemplateSpecialFieldType(field.type)
      || String(field.label || "").trim()
      || String(field.wordLabel || "").trim()
      || String(field.defaultValue || "").trim()
      || String(field.helpText || "").trim()
      || Boolean(field.required)
      || (Array.isArray(field.dropdownOptions) && field.dropdownOptions.length > 0)
      || String(field.previousDocumentMode || "NONE").trim().toUpperCase() !== "NONE"
      || (String(field.source || "").trim().toUpperCase() && String(field.source || "").trim().toUpperCase() !== "CUSTOM_VALUE")
    ));

  const equipmentItems = documentTemplateEquipmentDrafts.length > 0
    ? documentTemplateEquipmentDrafts
      .map((item, index) => ({
        id: item.id || crypto.randomUUID(),
        name: String(item.name || "").trim() || `Oprema ${index + 1}`,
        code: String(item.code || "").trim(),
        quantity: parseTemplateLooseNumber(item.quantity, 1),
        note: String(item.note || "").trim(),
      }))
      .filter((item) => item.name || item.code || item.note || item.quantity)
    : JSON.parse(JSON.stringify(activeTemplate?.equipmentItems ?? []));

  const sections = documentTemplateSectionDrafts.length > 0
    ? documentTemplateSectionDrafts
      .map((section, index) => ({
        id: section.id || crypto.randomUUID(),
        type: section.type || "rich_text",
        title: String(section.title || "").trim() || getDocumentTemplateSectionTypeLabel(section.type) || `Sekcija ${index + 1}`,
        body: String(section.body || "").trim(),
        columns: String(section.columns || "")
          .split(/[\n,]/)
          .map((entry) => entry.trim())
          .filter(Boolean)
          .slice(0, 16),
        rowCount: Math.max(4, Math.min(120, Math.round(parseTemplateLooseNumber(section.rowCount, 12)))),
        sheet: section.type === "measurement_table"
          ? (section.sheet ?? ensureDocumentTemplateMeasurementFieldSheet(section))
          : null,
      }))
      .map((section) => (
        section.type === "measurement_table"
          ? {
            ...section,
            columns: ensureDocumentTemplateMeasurementFieldSheet(section).columns.map((column) => column.label),
            rowCount: ensureDocumentTemplateMeasurementFieldSheet(section).rows.length,
            sheet: ensureDocumentTemplateMeasurementFieldSheet(section),
          }
          : {
            ...section,
            columns: [],
            rowCount: 0,
            sheet: null,
          }
      ))
    : [];

  documentTemplateDraftCache = {
    id: documentTemplateIdInput?.value || "",
    organizationId: state.activeOrganizationId || "",
    title: documentTemplateTitleInput?.value || "",
    documentType: documentTemplateTypeInput?.value || "Zapisnik",
    status: documentTemplateStatusInput?.value || "draft",
    outputFileName: documentTemplateOutputFileNameInput?.value || "",
    sampleCompanyId: documentTemplateCompanyIdInput?.value || "",
    sampleLocationId: documentTemplateLocationIdInput?.value || "",
    description: documentTemplateDescriptionInput?.value || "",
    selectedLegalFrameworkIds: getSelectedDocumentTemplateLegalFrameworkIds(),
    customFields,
    equipmentItems,
    sections,
    referenceDocument: documentTemplateReferenceDraft ? { ...documentTemplateReferenceDraft } : null,
    createdByUserId: state.user?.id || "",
    createdByLabel: state.user?.fullName || state.user?.email || "",
  };
  queueDocumentTemplateDraftCacheClear();
  return documentTemplateDraftCache;
}

function buildDocumentTemplatePayload() {
  return buildDocumentTemplateDraft();
}

function setDocumentTemplateMessage(message = "", { type = "error" } = {}) {
  if (!documentTemplateError) {
    return;
  }

  documentTemplateError.textContent = String(message || "");
  documentTemplateError.classList.toggle("is-success", type === "success" && Boolean(message));
}

function scrollDocumentTemplateMessageIntoView() {
  documentTemplateError?.scrollIntoView({ block: "nearest", behavior: "smooth" });
}

function resolveSavedDocumentTemplate({ currentId = "", title = "" } = {}) {
  if (currentId) {
    return (state.documentTemplates ?? []).find((item) => String(item.id) === String(currentId)) ?? null;
  }

  const normalizedTitle = String(title || "").trim().toLowerCase();
  if (!normalizedTitle) {
    return sortDocumentTemplates(state.documentTemplates ?? [])[0] ?? null;
  }

  return sortDocumentTemplates(state.documentTemplates ?? []).find((item) => (
    String(item.title || "").trim().toLowerCase() === normalizedTitle
  )) ?? null;
}

async function persistDocumentTemplateAiFieldConfig(
  fieldId = "",
  aiConfig = {},
  {
    successMessage = "AI postavke su spremljene.",
    scrollToTop = false,
  } = {},
) {
  if (!documentTemplateForm || isDocumentTemplateRuntimeFillMode()) {
    return false;
  }

  const normalizedFieldId = String(fieldId || "").trim();
  const fieldIndex = documentTemplateFieldDrafts.findIndex((field) => String(field?.id || "") === normalizedFieldId);
  if (fieldIndex < 0) {
    setDocumentTemplateMessage("Ne mogu pronaći polje za spremanje AI postavki.");
    scrollDocumentTemplateMessageIntoView();
    return false;
  }

  const currentField = documentTemplateFieldDrafts[fieldIndex];
  documentTemplateFieldDrafts[fieldIndex] = {
    ...currentField,
    ai: normalizeDocumentTemplateFieldAiConfig(aiConfig, currentField),
  };
  invalidateDocumentTemplateDraftCache();

  if (state.measurementSheet.ownerKind === "template_field") {
    if (state.measurementSheet.editingCell) {
      commitMeasurementEditMode();
    }
    persistMeasurementSheetToTemplateField({ rerenderFieldRows: false });
  }

  const templateId = String(documentTemplateIdInput?.value || state.activeDocumentTemplateId || "").trim();
  if (!templateId) {
    return persistDocumentTemplateDraft({
      successMessage,
      scrollToTop,
    });
  }

  const draft = buildDocumentTemplateDraft();
  setDocumentTemplateMessage("");

  if (documentTemplateSaveButton instanceof HTMLButtonElement) {
    documentTemplateSaveButton.disabled = true;
  }

  try {
    const success = await runMutation(() => apiRequest(`/document-templates/${encodeURIComponent(templateId)}`, {
      method: "PATCH",
      body: {
        customFields: draft.customFields,
      },
    }), documentTemplateError);
    if (!success) {
      scrollDocumentTemplateMessageIntoView();
      return false;
    }

    renderDocumentTemplateModule();
    const savedTemplate = resolveSavedDocumentTemplate({ currentId: templateId, title: draft.title });
    if (savedTemplate) {
      hydrateDocumentTemplateForm(savedTemplate, {
        preserveRuntimeContext: hasDocumentTemplateRuntimeContext(),
      });
    } else {
      syncDocumentTemplateEditorChrome();
    }
    setDocumentTemplateMessage(successMessage, { type: "success" });
    if (scrollToTop) {
      scrollDocumentTemplateEditorToTop({ behavior: "smooth" });
    }
    return true;
  } finally {
    if (documentTemplateSaveButton instanceof HTMLButtonElement) {
      documentTemplateSaveButton.disabled = false;
    }
  }
}

async function persistDocumentTemplateDraft({
  successMessage = "Template spremljen.",
  scrollToTop = true,
} = {}) {
  if (!documentTemplateForm) {
    return false;
  }

  if (isDocumentTemplateRuntimeFillMode()) {
    return false;
  }

  if (state.measurementSheet.ownerKind === "template_field") {
    if (state.measurementSheet.editingCell) {
      commitMeasurementEditMode();
    }
    persistMeasurementSheetToTemplateField({ rerenderFieldRows: true });
  }

  if (!documentTemplateForm.reportValidity()) {
    setDocumentTemplateMessage("Provjeri obavezna polja templatea prije spremanja.");
    scrollDocumentTemplateMessageIntoView();
    return false;
  }

  const shouldPreferVisibleHtmlCodeOnSave = getDocumentTemplateWorkspaceTab() === "html"
    && getDocumentTemplateReferenceKind(documentTemplateReferenceDraft) !== "word"
    && Boolean(getDocumentTemplateManualHtmlCode());
  syncDocumentTemplateReferenceDocumentFromCurrentHtml({ preferTextarea: shouldPreferVisibleHtmlCodeOnSave });

  const isEditing = Boolean(documentTemplateIdInput?.value);
  const path = isEditing ? `/document-templates/${documentTemplateIdInput.value}` : "/document-templates";
  const method = isEditing ? "PATCH" : "POST";
  const currentId = String(documentTemplateIdInput?.value || "");
  const currentTitle = String(documentTemplateTitleInput?.value || "").trim();
  const workspaceTabBeforeSave = state.documentTemplateWorkspaceTab || "builder";
  const sidebarPanelsBeforeSave = {
    referenceCollapsed: Boolean(state.documentTemplateSidebarPanels?.referenceCollapsed),
    placeholdersCollapsed: Boolean(state.documentTemplateSidebarPanels?.placeholdersCollapsed),
  };
  const referenceDraftBeforeSave = normalizeDocumentTemplateHtmlReferenceDocument(documentTemplateReferenceDraft);
  const editorDraftBeforeSnapshot = captureDocumentTemplateEditorDraftForSnapshot();

  setDocumentTemplateMessage("");

  if (documentTemplateSaveButton instanceof HTMLButtonElement) {
    documentTemplateSaveButton.disabled = true;
  }

  try {
    const success = await runMutation(() => apiRequest(path, {
      method,
      body: buildDocumentTemplatePayload(),
    }), documentTemplateError, {
      preserveDocumentTemplateEditorDraft: editorDraftBeforeSnapshot,
    });
    if (!success) {
      scrollDocumentTemplateMessageIntoView();
      return false;
    }

    renderDocumentTemplateModule();
    restoreDocumentTemplateEditorDraftAfterSnapshot(editorDraftBeforeSnapshot);
    const savedTemplate = resolveSavedDocumentTemplate({ currentId, title: currentTitle });
    if (savedTemplate) {
      state.activeDocumentTemplateId = String(savedTemplate.id || currentId || "");
      if (documentTemplateIdInput) {
        documentTemplateIdInput.value = state.activeDocumentTemplateId;
      }

      const savedReference = normalizeDocumentTemplateHtmlReferenceDocument(savedTemplate.referenceDocument);
      const localReference = normalizeDocumentTemplateHtmlReferenceDocument(documentTemplateReferenceDraft)
        ?? referenceDraftBeforeSave
        ?? editorDraftBeforeSnapshot?.referenceDraft;
      if (localReference || savedReference) {
        documentTemplateReferenceDraft = normalizeDocumentTemplateHtmlReferenceDocument({
          ...(savedReference ?? {}),
          ...(localReference ?? {}),
          builderDocument: editorDraftBeforeSnapshot?.builderDocument?.length
            ? editorDraftBeforeSnapshot.builderDocument
            : localReference?.builderDocument?.length
              ? localReference.builderDocument
              : (savedReference?.builderDocument ?? []),
        });
      }

      state.documentTemplateWorkspaceTab = workspaceTabBeforeSave;
      state.documentTemplateSidebarPanels = sidebarPanelsBeforeSave;
      restoreDocumentTemplateEditorDraftAfterSnapshot(editorDraftBeforeSnapshot);
      invalidateDocumentTemplateDraftCache();
      renderDocumentTemplateReferenceMeta();
      renderDocumentTemplatePreviewContent();
      syncDocumentTemplateEditorChrome();
    } else {
      syncDocumentTemplateEditorChrome();
    }
    setDocumentTemplateMessage(successMessage, { type: "success" });
    if (scrollToTop) {
      scrollDocumentTemplateEditorToTop({ behavior: "smooth" });
    }
    return true;
  } finally {
    if (documentTemplateSaveButton instanceof HTMLButtonElement) {
      documentTemplateSaveButton.disabled = false;
    }
  }
}

function saveDocumentTemplate() {
  if (!getCanManageDocumentTemplates()) {
    setDocumentTemplateMessage("Nemate pravo spremati templatee.");
    return;
  }
  void persistDocumentTemplateDraft();
}

function deleteDocumentTemplate(templateOrId = "", { closeEditorOnSuccess = false } = {}) {
  if (!getCanManageDocumentTemplates()) {
    setDocumentTemplateMessage("Nemate pravo brisati templatee.");
    return;
  }
  const templateId = String(typeof templateOrId === "object" ? templateOrId?.id : templateOrId || "").trim();
  if (!templateId) {
    return;
  }

  const template = typeof templateOrId === "object"
    ? templateOrId
    : ((state.documentTemplates ?? []).find((item) => String(item.id) === templateId) ?? null);
  const templateTitle = String(template?.title || "").trim() || "ovaj template";

  if (!window.confirm(`Obrisati template "${templateTitle}"?`)) {
    return;
  }

  const currentEditorTemplateId = String(documentTemplateIdInput?.value || "").trim();
  const shouldCloseEditor = closeEditorOnSuccess || currentEditorTemplateId === templateId;

  void runMutation(() => apiRequest(`/document-templates/${encodeURIComponent(templateId)}`, {
    method: "DELETE",
  }), state.documentTemplateEditorOpen ? documentTemplateError : null).then((success) => {
    if (!success) {
      return;
    }

    if (shouldCloseEditor) {
      closeDocumentTemplateEditor({ reset: true });
    }
    renderDocumentTemplateModule();
  });
}

function getDocumentTemplateSelectedLegalFrameworks(template = buildDocumentTemplateDraft()) {
  const templateId = String(template.id || "");
  const derivedIds = templateId
    ? getServiceDerivedLegalFrameworkIdsForTemplate(templateId, {
      organizationId: template.organizationId || state.activeOrganizationId || "",
    })
    : [];
  const selectedIds = new Set(
    (derivedIds.length > 0 ? derivedIds : (template.selectedLegalFrameworkIds ?? []))
      .map((value) => String(value)),
  );

  return sortLegalFrameworks(state.legalFrameworks ?? []).filter((item) => (
    selectedIds.has(String(item.id))
    || (derivedIds.length === 0 && (item.linkedTemplateIds ?? []).map(String).includes(templateId))
  ));
}

function getDocumentTemplateLegalFrameworkOptions() {
  return sortLegalFrameworks(state.legalFrameworks ?? []).map((item) => ({
    value: String(item.id),
    label: item.referenceCode
      ? `${item.title || "Propis"} | ${item.referenceCode}`
      : (item.title || "Propis"),
  }));
}

function getDocumentTemplateLegalFrameworksForField(
  template = buildDocumentTemplateDraft(),
  field = {},
  { selectedOnly = false, selectedIds: selectedIdsOverride = null } = {},
) {
  const allFrameworks = getDocumentTemplateSelectedLegalFrameworks(template);
  const visibleIds = new Set((field.legalFrameworkIds ?? []).map((value) => String(value)).filter(Boolean));
  const selectedIds = new Set(
    (selectedIdsOverride ?? field.defaultLegalFrameworkIds ?? [])
      .map((value) => String(value))
      .filter(Boolean),
  );
  const availableFrameworks = visibleIds.size > 0
    ? allFrameworks.filter((item) => visibleIds.has(String(item.id)))
    : allFrameworks;

  if (!selectedOnly) {
    return availableFrameworks;
  }

  const selectedFrameworks = selectedIds.size > 0
    ? availableFrameworks.filter((item) => selectedIds.has(String(item.id)))
    : [];

  return selectedFrameworks;
}

function getDocumentTemplateRuntimeSelectedLegalFrameworkIds(workOrderId, field = {}) {
  const runtimeValue = getDocumentTemplateRuntimeFieldValue(workOrderId, field.id);
  if (Array.isArray(runtimeValue)) {
    return runtimeValue.map((value) => String(value || "").trim()).filter(Boolean);
  }

  return (field.defaultLegalFrameworkIds ?? [])
    .map((value) => String(value || "").trim())
    .filter(Boolean);
}

function getDocumentTemplateLinkedEquipmentItems(template = buildDocumentTemplateDraft()) {
  const templateId = String(template.id || "");
  const linkedByServices = templateId
    ? getServiceDerivedMeasurementEquipmentItemsForTemplate(templateId, {
      organizationId: template.organizationId || state.activeOrganizationId || "",
    })
    : [];
  if (linkedByServices.length > 0) {
    return linkedByServices;
  }
  const linkedItems = sortMeasurementEquipmentItems(state.measurementEquipment ?? []).filter((item) => (
    templateId
      ? (item.linkedTemplateIds ?? []).map(String).includes(templateId)
      : false
  ));

  return linkedItems.length > 0 ? linkedItems : (template.equipmentItems ?? []);
}

function getDocumentTemplateEquipmentDeviceCode(item = {}) {
  return String(
    item?.deviceCode
      ?? item?.device_code
      ?? item?.oznaka
      ?? item?.code
      ?? "",
  ).trim();
}

function getDocumentTemplateRuntimeEquipmentCodeFieldId(field = {}) {
  return `${String(field?.id || field?.key || "equipment").trim() || "equipment"}::equipmentDeviceCode`;
}

function getDocumentTemplateRuntimeSelectedEquipmentIds(
  workOrderId,
  field = {},
  template = buildDocumentTemplateDraft(),
) {
  const availableItems = getDocumentTemplateLinkedEquipmentItems(template);
  const getSelectedEquipmentCode = () => String(
    getDocumentTemplateRuntimeFieldValue(
      workOrderId,
      getDocumentTemplateRuntimeEquipmentCodeFieldId(field),
    ) ?? "",
  ).trim();
  const runtimeValue = getDocumentTemplateRuntimeFieldValue(workOrderId, field.id);
  if (Array.isArray(runtimeValue)) {
    return runtimeValue.map((value) => String(value || "").trim()).filter(Boolean);
  }

  const selectedEquipmentCode = getSelectedEquipmentCode();
  if (selectedEquipmentCode) {
    return availableItems
      .filter((item) => getDocumentTemplateEquipmentDeviceCode(item) === selectedEquipmentCode)
      .map((item) => String(item?.id || "").trim())
      .filter(Boolean);
  }

  return availableItems
    .map((item) => String(item?.id || "").trim())
    .filter(Boolean);
}

function getDocumentTemplateEquipmentListFields(template = buildDocumentTemplateDraft()) {
  return (Array.isArray(template?.customFields) ? template.customFields : [])
    .filter((field) => String(field?.type || "").trim().toLowerCase() === "equipment_list")
    .filter((field) => String(field?.id || "").trim());
}

function applyWorkOrderDocumentWizardMeasurementEquipmentGroupDefaults(template = {}, workOrders = []) {
  const selectedGroup = String(
    state.documentTemplateRuntime.common?.measurementEquipmentGroup
      || state.workOrderDocumentWizard.common?.measurementEquipmentGroup
      || "",
  ).trim();
  if (!selectedGroup) {
    return 0;
  }

  const equipmentFields = getDocumentTemplateEquipmentListFields(template);
  if (equipmentFields.length === 0) {
    return 0;
  }

  const matchingEquipmentIds = getDocumentTemplateLinkedEquipmentItems(template)
    .filter((item) => getDocumentTemplateEquipmentDeviceCode(item) === selectedGroup)
    .map((item) => String(item?.id || "").trim())
    .filter(Boolean);

  const workOrderIds = (Array.isArray(workOrders) ? workOrders : [])
    .map((item) => String(item?.id || "").trim())
    .filter(Boolean);
  let appliedCount = 0;

  workOrderIds.forEach((workOrderId) => {
    equipmentFields.forEach((field) => {
      const fieldId = String(field?.id || "").trim();
      if (!fieldId) {
        return;
      }

      const currentValue = getDocumentTemplateRuntimeFieldValue(workOrderId, fieldId);
      const currentSource = getDocumentTemplateRuntimeFieldSource(workOrderId, fieldId);
      const equipmentCodeFieldId = getDocumentTemplateRuntimeEquipmentCodeFieldId(field);
      const currentCodeValue = getDocumentTemplateRuntimeFieldValue(workOrderId, equipmentCodeFieldId);
      const currentCodeSource = getDocumentTemplateRuntimeFieldSource(workOrderId, equipmentCodeFieldId);
      const currentCode = String(currentCodeValue ?? "").trim();
      const shouldApplySelectedGroup = currentCode !== selectedGroup;
      if (
        !shouldApplySelectedGroup
        && (
          currentValue !== undefined
          || currentSource === "blank"
          || currentSource === "manual"
          || currentCodeValue !== undefined
          || currentCodeSource === "blank"
          || currentCodeSource === "manual"
        )
      ) {
        return;
      }

      setDocumentTemplateRuntimeFieldValue(
        workOrderId,
        equipmentCodeFieldId,
        selectedGroup,
        { render: false, preserveBlank: false },
      );
      setDocumentTemplateRuntimeFieldValue(
        workOrderId,
        fieldId,
        matchingEquipmentIds,
        { render: false, preserveBlank: false },
      );
      appliedCount += 1;
    });
  });

  return appliedCount;
}

function getDocumentTemplateEquipmentItemsForField(
  template = buildDocumentTemplateDraft(),
  field = {},
  workOrderId = "",
) {
  const availableItems = getDocumentTemplateLinkedEquipmentItems(template);
  const normalizedWorkOrderId = String(workOrderId || "").trim();
  if (!normalizedWorkOrderId) {
    return availableItems;
  }

  const selectedEquipmentCode = String(
    getDocumentTemplateRuntimeFieldValue(
      normalizedWorkOrderId,
      getDocumentTemplateRuntimeEquipmentCodeFieldId(field),
    ) ?? "",
  ).trim();
  const scopedItems = selectedEquipmentCode
    ? availableItems.filter((item) => getDocumentTemplateEquipmentDeviceCode(item) === selectedEquipmentCode)
    : availableItems;
  const runtimeValue = getDocumentTemplateRuntimeFieldValue(normalizedWorkOrderId, field.id);
  if (Array.isArray(runtimeValue)) {
    const selectedIds = new Set(
      runtimeValue.map((value) => String(value || "").trim()).filter(Boolean),
    );
    const selectedItems = availableItems.filter((item) => selectedIds.has(String(item?.id || "").trim()));

    return selectedItems.length > 0 || selectedIds.size === 0
      ? selectedItems
      : scopedItems;
  }

  return scopedItems;
}

function getDocumentTemplatePreviewSampleWorkOrder(template = buildDocumentTemplateDraft()) {
  const runtimeWorkOrder = getDocumentTemplateRuntimeActiveWorkOrder();
  if (runtimeWorkOrder) {
    return runtimeWorkOrder;
  }

  const templateId = String(template.id || "");
  const sortedWorkOrders = sortWorkOrders(state.workOrders ?? []);

  if (templateId) {
    const linkedWorkOrder = sortedWorkOrders.find((item) => (
      (item.serviceItems ?? []).some((service) => (service.linkedTemplateIds ?? []).map(String).includes(templateId))
    ));

    if (linkedWorkOrder) {
      return linkedWorkOrder;
    }
  }

  return sortedWorkOrders[0] || null;
}

function getDocumentTemplatePreviewCompany(template = buildDocumentTemplateDraft(), sampleWorkOrder = null) {
  const companyId = sampleWorkOrder?.companyId || template.sampleCompanyId || state.companies[0]?.id || "";
  return getCompany(companyId);
}

function getDocumentTemplatePreviewLocation(template = buildDocumentTemplateDraft(), sampleWorkOrder = null) {
  const locationId = sampleWorkOrder?.locationId || template.sampleLocationId || state.locations[0]?.id || "";
  return getLocation(locationId);
}

function normalizePersonLookupValue(value = "") {
  return String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ");
}

function resolveQualifiedWorkOrderUser(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  const normalizedArea = String(signatureArea || "elektro").trim().toLowerCase() || "elektro";
  const executorNames = getWorkOrderExecutors(workOrder).map((entry) => normalizePersonLookupValue(entry)).filter(Boolean);
  const eligibleUsers = getQualifiedUsersForSignatureArea(capability, normalizedArea);

  const matchedExecutor = eligibleUsers.find((user) => (
    [
      getUserDocumentDisplayName(user),
      user.fullName,
      [user.firstName, user.lastName].filter(Boolean).join(" "),
      user.email,
      user.legacyUsername,
    ].map((value) => normalizePersonLookupValue(value)).filter(Boolean)
      .some((candidate) => executorNames.includes(candidate))
  ));

  return matchedExecutor || eligibleUsers[0] || null;
}

function normalizeQualificationAreaKey(signatureArea = "elektro") {
  const normalizedArea = String(signatureArea || "elektro").trim().toLowerCase();
  return normalizedArea || "elektro";
}

function createUserQualificationExamKey(value = "") {
  const safeId = String(value || "")
    .trim()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .toLowerCase();
  return safeId || "";
}

function normalizeQualificationSpecialRoles(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }
  return Object.fromEntries(
    Object.entries(value)
      .map(([key, flag]) => [String(key || "").trim(), Boolean(flag)])
      .filter(([key]) => key),
  );
}

function normalizeUserQualificationServiceIds(value = []) {
  let entries = [];
  if (Array.isArray(value)) {
    entries = value;
  } else if (value && typeof value === "object") {
    const objectEntries = Object.entries(value);
    entries = objectEntries.every(([, flag]) => typeof flag === "boolean")
      ? objectEntries.filter(([, flag]) => flag).map(([key]) => key)
      : Object.values(value);
  } else {
    const rawValue = String(value ?? "").trim();
    if (!rawValue) {
      return [];
    }
    try {
      const parsed = JSON.parse(rawValue);
      entries = Array.isArray(parsed) ? parsed : rawValue.split(",");
    } catch {
      entries = rawValue.split(",");
    }
  }

  return Array.from(new Set(
    entries
      .map((entry) => String(entry ?? "").trim())
      .filter(Boolean),
  ));
}

function normalizeQualificationExamKeyList(value = []) {
  let entries = [];
  if (Array.isArray(value)) {
    entries = value;
  } else if (value && typeof value === "object") {
    const objectEntries = Object.entries(value);
    entries = objectEntries.every(([, flag]) => typeof flag === "boolean")
      ? objectEntries.filter(([, flag]) => flag).map(([key]) => key)
      : Object.values(value);
  } else {
    const rawValue = String(value ?? "").trim();
    if (!rawValue) {
      return [];
    }
    try {
      const parsed = JSON.parse(rawValue);
      entries = Array.isArray(parsed) ? parsed : rawValue.split(",");
    } catch {
      entries = rawValue.split(",");
    }
  }

  return Array.from(new Set(
    entries
      .map((entry) => {
        const rawValue = String(entry ?? "").trim();
        if (!rawValue) {
          return "";
        }
        const normalizedValue = normalizeQualificationAreaKey(rawValue);
        return /[^a-z0-9_-]/i.test(normalizedValue)
          ? createUserQualificationExamKey(rawValue)
          : normalizedValue;
      })
      .filter(Boolean),
  ));
}

function getQualificationLinkedServiceIds(qualification = {}) {
  const source = qualification && typeof qualification === "object" ? qualification : {};
  for (const key of ["serviceIds", "linkedServiceCatalogIds", "linkedServiceIds", "serviceCatalogIds"]) {
    const ids = normalizeUserQualificationServiceIds(source[key]);
    if (ids.length > 0) {
      return ids;
    }
  }
  return [];
}

function getServiceCatalogDirectQualificationKeys(service = {}) {
  const source = service && typeof service === "object" ? service : {};
  for (const key of [
    "linkedQualificationKeys",
    "linkedQualificationExamKeys",
    "qualificationKeys",
    "peopleQualificationKeys",
    "linkedPeopleQualificationKeys",
  ]) {
    const keys = normalizeQualificationExamKeyList(source[key]);
    if (keys.length > 0) {
      return keys;
    }
  }
  return [];
}

function getLegacyQualificationKeysForService(serviceId = "") {
  const normalizedServiceId = String(serviceId || "").trim();
  if (!normalizedServiceId) {
    return [];
  }

  const keys = new Set();
  (state.users ?? []).forEach((user) => {
    const rootQualification = user?.electricalQualification ?? {};
    const entries = [
      [rootQualification.discipline || "elektro", rootQualification],
      ...Object.entries(rootQualification.additionalAreas || {}),
    ];
    entries.forEach(([key, qualification]) => {
      if (!qualification || typeof qualification !== "object") {
        return;
      }
      if (getQualificationLinkedServiceIds(qualification).includes(normalizedServiceId)) {
        keys.add(normalizeQualificationAreaKey(key || qualification.discipline || qualification.examKey || ""));
      }
    });
  });

  return [...keys].filter(Boolean);
}

function getServiceCatalogQualificationKeys(service = {}, { includeLegacy = true } = {}) {
  const directKeys = getServiceCatalogDirectQualificationKeys(service);
  const legacyKeys = includeLegacy
    ? getLegacyQualificationKeysForService(service?.id)
    : [];
  return Array.from(new Set([...directKeys, ...legacyKeys].map((key) => normalizeQualificationAreaKey(key)).filter(Boolean)));
}

function getServiceCatalogIdsForQualificationArea(signatureArea = "", { organizationId = "" } = {}) {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const normalizedOrganizationId = String(organizationId || state.activeOrganizationId || "").trim();
  return sortServiceCatalogItems((state.serviceCatalog ?? []).filter((service) => {
    if (String(service?.status || "active").trim().toLowerCase() === "inactive") {
      return false;
    }
    const serviceOrganizationId = String(service?.organizationId || "").trim();
    if (normalizedOrganizationId && serviceOrganizationId && serviceOrganizationId !== normalizedOrganizationId) {
      return false;
    }
    return getServiceCatalogQualificationKeys(service).includes(normalizedArea);
  })).map((service) => String(service.id || "").trim()).filter(Boolean);
}

function getQualificationServiceIdsForArea(signatureArea = "", qualification = {}, options = {}) {
  return Array.from(new Set([
    ...getQualificationLinkedServiceIds(qualification),
    ...getServiceCatalogIdsForQualificationArea(signatureArea, options),
  ]));
}

function hasQualificationSpecialRole(qualification = {}, capability = "") {
  const specialRoles = normalizeQualificationSpecialRoles(qualification.specialRoles);
  if (!Object.values(specialRoles).some(Boolean)) {
    return false;
  }
  const definition = getQualificationExamDefinition(qualification.discipline || qualification.examKey || "");
  const specialRoleOptions = Array.isArray(definition.specialRoleOptions) ? definition.specialRoleOptions : [];
  if (!capability) {
    return Object.values(specialRoles).some(Boolean);
  }
  return specialRoleOptions.some((option) => (
    option.capability === capability && specialRoles[option.key]
  ));
}

function hasQualificationContent(qualification = {}) {
  return Boolean(
    hasQualificationCapability(qualification)
    || qualification.examTitle
    || qualification.type
    || qualification.examType
    || qualification.data1
    || qualification.data2
    || qualification.data3
    || qualification.classCode
    || qualification.urbroj
    || qualification.eBroj
    || qualification.passedOn
    || qualification.validUntil
    || qualification.validForever
  );
}

function normalizeUserQualificationExamDefinition(definition = {}) {
  const rawTitle = String(definition.title || definition.label || definition.examTitle || "").trim();
  const key = normalizeQualificationAreaKey(definition.key || createUserQualificationExamKey(rawTitle));
  if (!key) {
    return null;
  }
  const title = rawTitle || key
    .split(/[_-]+/g)
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(" ") || key;
  return {
    ...definition,
    key,
    title,
    label: String(definition.label || title).trim() || title,
    specialRoleOptions: Array.isArray(definition.specialRoleOptions) ? definition.specialRoleOptions : [],
    serviceIds: getQualificationLinkedServiceIds(definition),
    linkedServiceCatalogIds: getQualificationLinkedServiceIds(definition),
  };
}

function addQualificationExamDefinition(definitions, definition = {}) {
  const normalized = normalizeUserQualificationExamDefinition(definition);
  if (!normalized) {
    return;
  }
  const previous = definitions.get(normalized.key) || {};
  const serviceIds = Array.from(new Set([
    ...getQualificationLinkedServiceIds(previous),
    ...getQualificationLinkedServiceIds(normalized),
  ]));
  definitions.set(normalized.key, {
    ...previous,
    ...normalized,
    specialRoleOptions: normalized.specialRoleOptions.length > 0
      ? normalized.specialRoleOptions
      : (previous.specialRoleOptions || []),
    serviceIds,
    linkedServiceCatalogIds: serviceIds,
    builtIn: Boolean(previous.builtIn || normalized.builtIn),
    legacy: Boolean(previous.legacy || normalized.legacy),
  });
}

function collectUserQualificationDefinitionFromArea(definitions, key = "", qualification = {}) {
  const normalizedKey = normalizeQualificationAreaKey(key);
  if (!normalizedKey || !hasQualificationContent(qualification)) {
    return;
  }
  const legacyDefinition = LEGACY_QUALIFICATION_EXAM_DEFINITIONS.find((entry) => entry.key === normalizedKey);
  const fallbackTitle = normalizedKey
    .split(/[_-]+/g)
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(" ") || normalizedKey;
  addQualificationExamDefinition(definitions, {
    ...(legacyDefinition || {}),
    key: normalizedKey,
    title: qualification.examTitle || legacyDefinition?.title || fallbackTitle,
    label: qualification.examTitle || legacyDefinition?.label || fallbackTitle,
    serviceIds: getQualificationLinkedServiceIds(qualification),
  });
}

function getQualificationExamDefinitions({ includeCustom = true } = {}) {
  const definitions = new Map(BUILTIN_QUALIFICATION_EXAM_DEFINITIONS.map((entry) => [
    entry.key,
    {
      ...entry,
    },
  ]));

  if (includeCustom) {
    LEGACY_QUALIFICATION_EXAM_DEFINITIONS.forEach((legacyDefinition) => {
      const hasLegacyData = (state.users ?? []).some((user) => {
        const qualification = getUserElectricalQualification(user, legacyDefinition.key);
        return hasQualificationContent(qualification);
      });
      if (hasLegacyData) {
        addQualificationExamDefinition(definitions, legacyDefinition);
      }
    });

    (state.users ?? []).forEach((user) => {
      const rootQualification = user?.electricalQualification ?? {};
      collectUserQualificationDefinitionFromArea(definitions, rootQualification.discipline || "elektro", rootQualification);
      Object.entries(rootQualification.additionalAreas || {}).forEach(([key, qualification]) => {
        collectUserQualificationDefinitionFromArea(definitions, key, qualification || {});
      });
    });

    userQualificationEditorDraftDefinitions.forEach((definition) => {
      addQualificationExamDefinition(definitions, definition);
    });

    (state.serviceCatalog ?? []).forEach((service) => {
      const serviceId = String(service?.id || "").trim();
      getServiceCatalogDirectQualificationKeys(service).forEach((key) => {
        const previous = definitions.get(key);
        const fallbackTitle = previous?.title || key
          .split(/[_-]+/g)
          .filter(Boolean)
          .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
          .join(" ") || key;
        addQualificationExamDefinition(definitions, {
          ...(previous || {}),
          key,
          title: fallbackTitle,
          label: previous?.label || fallbackTitle,
          serviceIds: serviceId ? [serviceId] : [],
        });
      });
    });
  }

  return Array.from(definitions.values());
}

function getQualificationExamDefinition(signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  return getQualificationExamDefinitions().find((entry) => entry.key === normalizedArea)
    || BUILTIN_QUALIFICATION_EXAM_DEFINITIONS.find((entry) => entry.key === normalizedArea)
    || LEGACY_QUALIFICATION_EXAM_DEFINITIONS.find((entry) => entry.key === normalizedArea)
    || { key: normalizedArea, label: normalizedArea, title: normalizedArea, specialRoleOptions: [] };
}

function getDocumentTemplateSignatureAreaOptions(selectedValue = "") {
  const selectedArea = normalizeQualificationAreaKey(selectedValue || "elektro");
  const options = getQualificationExamDefinitions().map((entry) => ({
    value: entry.key,
    label: entry.label || entry.title || entry.key,
  }));
  if (selectedArea && !options.some((option) => option.value === selectedArea)) {
    options.push({ value: selectedArea, label: getSignatureAreaLabel(selectedArea) });
  }
  return options;
}

function getUsersByIds(userIds = []) {
  const normalizedIds = normalizeQualifiedUserIdList(userIds);
  if (normalizedIds.length === 0) {
    return [];
  }

  return normalizedIds
    .map((userId) => state.users.find((user) => String(user?.id) === userId))
    .filter(Boolean);
}

function getSignatureAreaLabel(signatureArea = "elektro") {
  const definition = getQualificationExamDefinition(signatureArea);
  return String(definition.label || definition.title || definition.key || signatureArea || "ispit").trim();
}

function normalizeDocumentTemplateSignatureServiceCode(value = "") {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  const direct = text
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, " ")
    .trim();
  const known = ["SPR", "ZNR", "TZIN", "TIPKALO", "PANIK"];
  const knownMatch = known.find((code) => new RegExp(`\\b${code}\\b`, "i").test(direct));
  if (knownMatch) {
    return knownMatch === "PANIK" ? "SPR" : knownMatch;
  }
  if (/SIGURNOSNA\s+PANIK|PANIK\s+RASVJET/i.test(text)) {
    return "SPR";
  }
  const compact = direct.replace(/\s+/g, "");
  return compact.length > 0 && compact.length <= 10 ? compact : "";
}

function getDocumentTemplateSignatureServiceCode(field = {}, context = {}) {
  const workOrder = context.sampleWorkOrder || {};
  const template = context.template || {};
  const serviceItems = getDocumentTemplateRuntimeResolvedServiceItems(workOrder);
  const primaryService = getDocumentTemplateRuntimePrimaryServiceItem(workOrder, template)
    || serviceItems[0]
    || null;
  const candidates = [
    primaryService?.serviceCode,
    primaryService?.code,
    primaryService?.serviceId,
    primaryService?.name,
    primaryService?.serviceName,
    template.documentType,
    template.title,
    template.outputFileName,
    field.wordLabel,
    field.label,
    getSignatureAreaLabel(field.signatureArea || "elektro"),
  ];
  return candidates
    .map((value) => normalizeDocumentTemplateSignatureServiceCode(value))
    .find(Boolean) || "";
}

function normalizeDocumentTemplateSignatureRole(value = "inspect") {
  const normalizedRole = String(value || "inspect").trim().toLowerCase();
  return ["inspect", "authorize", "company_responsible", "all"].includes(normalizedRole)
    ? normalizedRole
    : "inspect";
}

function getDocumentTemplatePersonSignatureDisplayLabel(role = "inspect") {
  const normalizedRole = normalizeDocumentTemplateSignatureRole(role);
  if (normalizedRole === "authorize") {
    return "Nositelj ovlaštenja";
  }
  if (normalizedRole === "company_responsible") {
    return "Odgovorna osoba u tvrtki";
  }
  return "Ispitivač";
}

function buildDocumentTemplateSignatureRoleLabel(capability = "inspect", field = {}, context = {}) {
  const normalizedCapability = normalizeDocumentTemplateSignatureRole(capability);
  if (normalizedCapability === "company_responsible") {
    return "Odgovorna osoba u tvrtki";
  }
  const base = normalizedCapability === "authorize" ? "Odgovorna osoba" : "Ispitivač";
  const serviceCode = getDocumentTemplateSignatureServiceCode(field, context);
  return [base, serviceCode].filter(Boolean).join(" ");
}

function getDocumentTemplateSignatureAreas(template = {}) {
  const areas = new Set();
  (Array.isArray(template?.customFields) ? template.customFields : []).forEach((field) => {
    if (!["qualified_inspectors", "inspector_signature", "authorization_holder_signature", "digital_signature"].includes(field?.type)) {
      return;
    }

    areas.add(normalizeQualificationAreaKey(field?.signatureArea || "elektro"));
  });

  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getWorkOrderRelevantSignatureAreas(workOrder = {}) {
  const areas = new Set();
  getWorkOrderServiceItems(workOrder).forEach((service) => {
    getWorkOrderServiceQualificationKeys(service).forEach((area) => areas.add(area));
    getWorkOrderServiceTemplateIds(service).forEach((templateId) => {
      const template = getDocumentTemplateById(templateId);
      getDocumentTemplateSignatureAreas(template).forEach((area) => areas.add(area));
    });
  });

  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getBatchRelevantSignatureAreas(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const areas = new Set();
  (Array.isArray(workOrders) ? workOrders : []).forEach((workOrder) => {
    getWorkOrderRelevantSignatureAreas(workOrder).forEach((area) => areas.add(area));
  });
  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getActiveOrganizationUsers() {
  const organizationId = String(state.activeOrganizationId || "").trim();
  return (state.users ?? [])
    .filter((user) => Boolean(user?.isActive))
    .filter((user) => {
      if (!organizationId) {
        return true;
      }
      const directOrganizationId = String(user?.organizationId || "").trim();
      if (directOrganizationId && directOrganizationId === organizationId) {
        return true;
      }
      const organizationIds = Array.isArray(user?.organizationIds)
        ? user.organizationIds.map((value) => String(value || "").trim()).filter(Boolean)
        : [];
      return organizationIds.includes(organizationId);
    })
    .sort((left, right) => String(left.fullName || left.email || "").localeCompare(
      String(right.fullName || right.email || ""),
      "hr",
    ));
}

function renderCompanyPermissionModuleBlock(module, draftByKey, appDraftByKey = new Map()) {
  const isAppModule = module.type === "app";
  const blockKey = `${module.type || "company"}:${module.key || module.title || ""}`;
  const block = document.createElement("details");
  block.className = "dashboard-company-permission-block";
  block.open = dashboardCompanyPermissionBlockOpenState.has(blockKey)
    ? Boolean(dashboardCompanyPermissionBlockOpenState.get(blockKey))
    : true;
  block.addEventListener("toggle", () => {
    dashboardCompanyPermissionBlockOpenState.set(blockKey, block.open);
  });

  const summary = document.createElement("summary");
  summary.className = "dashboard-company-permission-block-summary";

  const summaryCopy = document.createElement("div");
  summaryCopy.className = "dashboard-company-permission-block-copy";
  const summaryTitle = document.createElement("strong");
  summaryTitle.textContent = module.title;
  const summaryDescription = document.createElement("span");
  summaryDescription.textContent = module.description;
  summaryCopy.append(summaryTitle, summaryDescription);

  const summaryMeta = document.createElement("div");
  summaryMeta.className = "dashboard-company-permission-block-meta";
  const summaryCount = document.createElement("span");
  summaryCount.className = "dashboard-company-permission-block-badge";
  summaryCount.textContent = `${module.rows.length} ovlastenja`;
  const summaryHint = document.createElement("span");
  summaryHint.className = "dashboard-company-permission-block-hint";
  summaryHint.textContent = "Klik za pregled";
  summaryMeta.append(summaryCount, summaryHint);

  summary.append(summaryCopy, summaryMeta);

  const blockBody = document.createElement("div");
  blockBody.className = "dashboard-company-permission-block-body";

  const grid = document.createElement("div");
  grid.className = "dashboard-company-permission-grid";
  grid.style.setProperty("--company-role-columns", String(USER_PROFILE_ROLE_OPTIONS.length));

  const headRow = document.createElement("div");
  headRow.className = "dashboard-company-permission-grid-row is-head";
  const actionHead = document.createElement("div");
  actionHead.className = "dashboard-company-permission-grid-cell is-action";
  actionHead.textContent = "Ovlastenje";
  headRow.append(actionHead);

  USER_PROFILE_ROLE_OPTIONS.forEach((role) => {
    const header = document.createElement("div");
    header.className = "dashboard-company-permission-grid-cell is-role-head";
    const headerTitle = document.createElement("strong");
    headerTitle.textContent = role.label;
    const headerMeta = document.createElement("span");
    headerMeta.textContent = role.value === "leand_user" ? "lead_user" : role.value;
    header.append(headerTitle, headerMeta);
    headRow.append(header);
  });
  grid.append(headRow);

  module.rows.forEach((permissionRow) => {
    const row = document.createElement("div");
    row.className = "dashboard-company-permission-grid-row";

    const actionCell = document.createElement("div");
    actionCell.className = "dashboard-company-permission-grid-cell is-action";
    const actionTitle = document.createElement("strong");
    actionTitle.textContent = permissionRow.label;
    actionCell.append(actionTitle);
    row.append(actionCell);

    USER_PROFILE_ROLE_OPTIONS.forEach((role) => {
      const isAdminRole = role.value === "admin";
      const permissionEntry = isAppModule
        ? appDraftByKey.get(createAppRolePermissionDraftKey(role.value))
        : draftByKey.get(createCompanyRolePermissionDraftKey(role.value));
      const cell = document.createElement("div");
      cell.className = "dashboard-company-permission-grid-cell";
      const label = document.createElement("label");
      label.className = "dashboard-company-permission-checkbox";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.checked = isAdminRole || Boolean(permissionEntry?.[permissionRow.key]);
      checkbox.disabled = isAdminRole;
      cell.classList.add(checkbox.checked ? "is-permission-on" : "is-permission-off");
      label.classList.add(checkbox.checked ? "is-checked" : "is-unchecked");
      if (isAdminRole) {
        cell.classList.add("is-permission-admin");
        label.classList.add("is-locked");
        label.title = "Admin rola je zakljucana.";
      }
      checkbox.addEventListener("change", () => {
        if (isAppModule) {
          setAppRolePermissionDraft(role.value, permissionRow.key, checkbox.checked);
        } else {
          setCompanyRolePermissionDraft(role.value, permissionRow.key, checkbox.checked);
        }
        if (dashboardCompanyPermissionsFeedback) {
          dashboardCompanyPermissionsFeedback.textContent = "";
        }
        renderDashboardCompanyPermissionsPanel();
      });
      const text = document.createElement("span");
      text.textContent = checkbox.checked ? "Da" : "Ne";
      label.append(checkbox, text);
      cell.append(label);
      row.append(cell);
    });

    grid.append(row);
  });

  blockBody.append(grid);
  block.append(summary, blockBody);
  return block;
}

function setDashboardCompanyPermissionsCollapsed(isCollapsed) {
  state.dashboardCompanyPermissionsCollapsed = Boolean(isCollapsed);
  renderDashboardCompanyPermissionsPanel();
}

function renderDashboardCompanyPermissionsPanel() {
  const canManageMasterData = getCanManageMasterData();
  if (dashboardCompanyPermissionsPanel) {
    dashboardCompanyPermissionsPanel.hidden = !canManageMasterData;
  }

  if (!canManageMasterData) {
    return;
  }

  const isCollapsed = Boolean(state.dashboardCompanyPermissionsCollapsed);
  if (dashboardCompanyPermissionsPanel) {
    dashboardCompanyPermissionsPanel.classList.toggle("is-collapsed", isCollapsed);
  }
  if (dashboardCompanyPermissionsHead) {
    dashboardCompanyPermissionsHead.setAttribute("aria-expanded", isCollapsed ? "false" : "true");
  }
  if (dashboardCompanyPermissionsContent) {
    dashboardCompanyPermissionsContent.hidden = isCollapsed;
  }
  if (dashboardCompanyPermissionsToggle) {
    dashboardCompanyPermissionsToggle.textContent = isCollapsed ? "Prikaži" : "Sakrij";
  }

  const rolePermissions = getCompanyRolePermissionsDraft();
  const appRolePermissions = getAppRolePermissionsDraft();
  const permissionModules = [
    ...COMPANY_PERMISSION_MODULES,
    ...APP_ROLE_PERMISSION_MODULES,
  ];
  if (dashboardCompanyPermissionsCount) {
    dashboardCompanyPermissionsCount.textContent = `${permissionModules.length} blokova`;
  }

  if (dashboardCompanyPermissionsSaveButton) {
    dashboardCompanyPermissionsSaveButton.hidden = false;
    dashboardCompanyPermissionsSaveButton.disabled = false;
  }

  if (!dashboardCompanyPermissionsBody) {
    return;
  }

  const draftByKey = new Map(
    rolePermissions.map((entry) => [
      createCompanyRolePermissionDraftKey(entry.profileRole),
      entry,
    ]),
  );
  const appDraftByKey = new Map(
    appRolePermissions.map((entry) => [
      createAppRolePermissionDraftKey(entry.profileRole),
      entry,
    ]),
  );
  const moduleList = document.createElement("div");
  moduleList.className = "dashboard-company-permission-block-list";
  moduleList.replaceChildren(
    ...permissionModules.map((module) => renderCompanyPermissionModuleBlock(module, draftByKey, appDraftByKey)),
  );

  dashboardCompanyPermissionsBody.replaceChildren(moduleList);
}

function getSignupRequestsByStatus(status = "") {
  const normalizedStatus = String(status || "").trim().toLowerCase();
  return (state.signupRequests ?? []).filter((request) => (
    !normalizedStatus || String(request.status || "").trim().toLowerCase() === normalizedStatus
  ));
}

function getSignupRequestOrganizationLabel(request = {}) {
  const matchedOrganization = (state.organizations ?? []).find((organization) => (
    String(organization.id) === String(request.organizationId || "")
    || (
      request.organizationOib
      && String(organization.oib || "").replace(/\D/g, "") === String(request.organizationOib || "").replace(/\D/g, "")
    )
  ));

  if (matchedOrganization?.name) {
    return matchedOrganization.name;
  }

  return request.organizationName || "Nova organizacija";
}

function getSignupRequestRequestedLabel(request = {}) {
  const requestedAt = String(request.requestedAt || "").trim();
  if (!requestedAt) {
    return "Bez datuma";
  }

  return requestedAt.includes("T")
    ? formatCompactDateTime(requestedAt)
    : formatCompactDate(requestedAt);
}

function getSignupRequestStatusLabel(status = "") {
  const normalizedStatus = String(status || "pending").trim().toLowerCase();
  if (normalizedStatus === "approved") {
    return "Odobren";
  }
  if (normalizedStatus === "rejected") {
    return "Odbijen";
  }
  return "Ceka odobrenje";
}

function createSignupRequestInfoItem(label, value, fallback = "Nije upisano") {
  const item = document.createElement("div");
  item.className = "signup-request-info-item";

  const labelNode = document.createElement("span");
  labelNode.textContent = label;

  const valueNode = document.createElement("strong");
  valueNode.textContent = String(value || "").trim() || fallback;

  item.append(labelNode, valueNode);
  return item;
}

function getSignupApprovalProfileRoleOptions() {
  return USER_PROFILE_ROLE_OPTIONS.filter((option) => (
    getIsSuperAdmin() || option.value !== "admin"
  ));
}

function getSignupApprovalSystemRole(profileRole = "") {
  return resolveUserSystemRoleFromProfileRole(profileRole || "new_user", {
    fallbackRole: "user",
  });
}

function createSignupRequestActions(request = {}, { compact = false } = {}) {
  const actions = document.createElement("div");
  actions.className = compact ? "signup-request-card-actions" : "signup-approval-actions";

  if (request.status !== "pending") {
    const status = document.createElement("span");
    status.className = "dashboard-control-chip";
    status.textContent = getSignupRequestStatusLabel(request.status);
    actions.append(status);
    return actions;
  }

  const isSuperAdmin = getIsSuperAdmin();
  let organizationSelect = null;
  const roleSelect = document.createElement("select");
  roleSelect.className = "signup-inline-select";
  roleSelect.title = "Rola korisnika nakon odobrenja";
  roleSelect.setAttribute("aria-label", "Rola korisnika nakon odobrenja");
  roleSelect.append(...getSignupApprovalProfileRoleOptions().map((option) => createOption(option.value, option.label, "new_user")));
  roleSelect.value = getSignupApprovalProfileRoleOptions().some((option) => option.value === request.profileRole)
    ? request.profileRole
    : "new_user";

  if (isSuperAdmin) {
    organizationSelect = document.createElement("select");
    organizationSelect.className = "signup-inline-select";
    organizationSelect.append(
      createOption("__new__", `Nova organizacija: ${request.organizationName || "bez naziva"}`, "__new__"),
      ...state.organizations.map((organization) => createOption(
        organization.id,
        [organization.name, organization.oib ? `OIB ${organization.oib}` : ""].filter(Boolean).join(" · "),
      )),
    );

    const matchedByOib = state.organizations.find((organization) => (
      request.organizationOib
      && String(organization.oib || "").replace(/\D/g, "") === String(request.organizationOib || "").replace(/\D/g, "")
    ));
    if (matchedByOib) {
      organizationSelect.value = String(matchedByOib.id);
    }
  }

  const inlineControls = document.createElement("div");
  inlineControls.className = "signup-approval-controls";
  if (organizationSelect) {
    inlineControls.append(organizationSelect);
  }
  inlineControls.append(roleSelect);
  actions.append(inlineControls);

  actions.append(
    createActionButton("Odobri", "card-button", () => {
      const profileRole = String(roleSelect?.value || "new_user");
      const body = isSuperAdmin
        ? {
          organizationId: organizationSelect?.value === "__new__" ? "" : String(organizationSelect?.value || ""),
          role: getSignupApprovalSystemRole(profileRole),
          profileRole,
        }
        : {
          role: "user",
          profileRole,
        };
      void runMutation(() => apiRequest(`/signup-requests/${request.id}/approve`, {
        method: "POST",
        body,
      }), syncError);
    }),
    createActionButton("Odbij", "card-button card-danger", () => {
      if (!window.confirm(`Odbiti signup zahtjev za ${request.email}?`)) {
        return;
      }

      void runMutation(() => apiRequest(`/signup-requests/${request.id}/reject`, {
        method: "POST",
        body: {},
      }), syncError);
    }),
  );

  return actions;
}

function renderDashboardOrganizationsPanel() {
  const isSuperAdmin = getIsSuperAdmin();

  if (dashboardOrganizationsPanel) {
    dashboardOrganizationsPanel.hidden = !isSuperAdmin;
  }

  if (dashboardOrganizationOpenFormButton) {
    dashboardOrganizationOpenFormButton.hidden = !isSuperAdmin;
  }

  if (!isSuperAdmin || !dashboardOrganizationsBody) {
    return;
  }

  const organizations = [...(state.organizations ?? [])].sort((left, right) => (
    String(left.name || "").localeCompare(String(right.name || ""), "hr")
  ));

  if (dashboardOrganizationsCount) {
    dashboardOrganizationsCount.textContent = `${organizations.length} tvrtki`;
  }

  if (organizations.length === 0) {
    dashboardOrganizationsBody.replaceChildren(createDashboardBuilderEmptyState("Nema organizacija za prikaz."));
    return;
  }

  const list = document.createElement("div");
  list.className = "dashboard-organization-list";

  organizations.forEach((organization) => {
    const isActive = String(organization.id) === String(state.activeOrganizationId);
    const card = document.createElement("article");
    card.className = "dashboard-organization-card";
    card.classList.toggle("is-active", isActive);

    const logo = document.createElement("div");
    logo.className = "dashboard-organization-logo";
    renderCompanyLogo(logo, {
      name: organization.name,
      logoDataUrl: organization.logoDataUrl,
    });

    const copy = document.createElement("div");
    copy.className = "dashboard-organization-copy";
    const title = document.createElement("strong");
    title.textContent = organization.name || "Bez naziva";
    const meta = document.createElement("span");
    meta.textContent = [
      organization.oib ? `OIB ${organization.oib}` : "Bez OIB-a",
      organization.city || organization.address || "",
    ].filter(Boolean).join(" · ");
    copy.append(title, meta);

    const status = document.createElement("span");
    status.className = `dashboard-organization-status ${organization.status === "active" ? "is-active" : "is-inactive"}`;
    status.textContent = organization.status === "active" ? "Aktivna" : "Neaktivna";

    const actions = document.createElement("div");
    actions.className = "dashboard-organization-actions";
    actions.append(
      createActionButton(isActive ? "Aktivna" : "Otvori", "card-button", () => {
        state.activeOrganizationId = String(organization.id);
        settingsOrganizationLogoDraftTouched = false;
        if (organizationSwitcher) {
          organizationSwitcher.value = state.activeOrganizationId;
        }
        populateOrganizationForm(organization);
        void withGlobalLoading("Učitavam podatke organizacije...", () => refreshSnapshot()).catch((error) => {
          setSyncError(error.message);
        });
      }),
      createActionButton("Uredi", "card-button card-button-light", () => {
        hydrateOrganizationForm(organization);
      }),
    );

    card.append(logo, copy, status, actions);
    list.append(card);
  });

  dashboardOrganizationsBody.replaceChildren(list);
}

function renderDashboardSignupRequestsPanel() {
  const canReviewRequests = getCanManageMasterData();

  if (dashboardSignupRequestsPanel) {
    dashboardSignupRequestsPanel.hidden = !canReviewRequests;
  }

  if (!canReviewRequests || !dashboardSignupRequestsBody) {
    return;
  }

  const requests = [...(state.signupRequests ?? [])].sort((left, right) => {
    const statusDelta = (String(left.status || "pending") === "pending" ? 0 : 1)
      - (String(right.status || "pending") === "pending" ? 0 : 1);
    if (statusDelta !== 0) {
      return statusDelta;
    }
    return String(right.requestedAt || "").localeCompare(String(left.requestedAt || ""));
  });
  const pendingRequests = getSignupRequestsByStatus("pending");

  if (dashboardSignupRequestsCount) {
    dashboardSignupRequestsCount.textContent = pendingRequests.length === 1
      ? "1 pending"
      : `${pendingRequests.length} pending`;
  }

  if (requests.length === 0) {
    dashboardSignupRequestsBody.replaceChildren(createDashboardBuilderEmptyState("Nema signup zahtjeva za aktivni opseg."));
    return;
  }

  const list = document.createElement("div");
  list.className = "dashboard-signup-request-list";

  requests.slice(0, 8).forEach((request) => {
    const card = document.createElement("article");
    card.className = "dashboard-signup-request-card";
    card.classList.toggle("is-pending", request.status === "pending");

    const marker = document.createElement("span");
    marker.className = `dashboard-signup-request-marker is-${request.status || "pending"}`;
    marker.setAttribute("aria-hidden", "true");

    const copy = document.createElement("div");
    copy.className = "dashboard-signup-request-copy";
    const title = document.createElement("strong");
    title.textContent = request.fullName || [request.firstName, request.lastName].filter(Boolean).join(" ") || request.email;
    const meta = document.createElement("span");
    meta.textContent = [
      request.email || "Bez emaila",
      request.phone || "",
    ].filter(Boolean).join(" · ");
    const org = document.createElement("small");
    org.textContent = [
      getSignupRequestOrganizationLabel(request),
      request.organizationOib ? `OIB ${request.organizationOib}` : "",
    ].filter(Boolean).join(" · ");
    const note = document.createElement("small");
    note.textContent = request.note ? `Napomena: ${request.note}` : `Zaprimljeno: ${getSignupRequestRequestedLabel(request)}`;
    copy.append(title, meta, org, note);

    const info = document.createElement("div");
    info.className = "signup-request-info-grid";
    info.append(
      createSignupRequestInfoItem("Tvrtka", getSignupRequestOrganizationLabel(request)),
      createSignupRequestInfoItem("OIB", request.organizationOib),
      createSignupRequestInfoItem("Zaprimljeno", getSignupRequestRequestedLabel(request), "Bez datuma"),
      createSignupRequestInfoItem("Email status", request.emailStatus || "nije poslano"),
    );

    const status = document.createElement("span");
    status.className = `dashboard-signup-request-status is-${request.status || "pending"}`;
    status.textContent = getSignupRequestStatusLabel(request.status);

    card.append(marker, copy, info, status, createSignupRequestActions(request, { compact: true }));
    list.append(card);
  });

  dashboardSignupRequestsBody.replaceChildren(list);
}

function renderDashboardControlPanelContent() {
  const canManageMasterData = getCanManageMasterData();
  const isSuperAdmin = getIsSuperAdmin();

  if (dashboardPeoplePanel) {
    dashboardPeoplePanel.hidden = true;
  }

  if (organizationPanel) {
    organizationPanel.hidden = !isSuperAdmin;
  }

  if (loginContentPanel) {
    loginContentPanel.hidden = !isSuperAdmin;
  }

  if (signupRequestsPanel) {
    signupRequestsPanel.hidden = !canManageMasterData;
  }

  renderDashboardOrganizationsPanel();
  renderDashboardSignupRequestsPanel();
  renderDashboardCompanyPermissionsPanel();
}

function createWorkOrderDocumentSafetySpecialistPicker() {
  const users = getActiveOrganizationUsers();
  const wrapper = document.createElement("div");
  wrapper.className = "work-order-document-safety-specialist-picker";

  const select = document.createElement("select");
  select.className = "input-like";
  select.append(createOption("", "Odaberi stručnjaka zaštite na radu", state.workOrderDocumentWizard.common.safetySpecialistUserId || ""));
  users.forEach((user) => {
    const label = String(user.fullName || user.email || user.username || "Korisnik").trim();
    select.append(createOption(String(user.id), label, state.workOrderDocumentWizard.common.safetySpecialistUserId || ""));
  });
  select.addEventListener("change", () => {
    state.workOrderDocumentWizard.common.safetySpecialistUserId = String(select.value || "").trim();
    renderWorkOrderDocumentWizardCommonSection();
    renderWorkOrderDocumentWizardWorkOrders(getAllSelectedWorkOrdersForDocumentWizard());
  });
  wrapper.append(select);
  return wrapper;
}

function getWorkOrderDocumentMeasurementEquipmentGroupOptions(selectedValue = "") {
  const standardGroups = Array.from({ length: 13 }, (_, index) => `Grupa ${String.fromCharCode(65 + index)}`);
  const selected = String(selectedValue || "").trim();
  const groups = new Set(standardGroups);

  (state.measurementEquipment ?? []).forEach((item) => {
    const group = getDocumentTemplateEquipmentDeviceCode(item);
    if (group) {
      groups.add(group);
    }
  });

  if (selected) {
    groups.add(selected);
  }

  return [
    { value: "", label: "Bez odabira" },
    ...Array.from(groups)
      .sort((left, right) => left.localeCompare(right, "hr", { sensitivity: "base", numeric: true }))
      .map((group) => ({
        value: group,
        label: group,
      })),
  ];
}

function syncWorkOrderDocumentMeasurementEquipmentGroupInput() {
  if (!(workOrderDocumentCommonMeasurementEquipmentGroupInput instanceof HTMLSelectElement)) {
    return;
  }

  const selected = String(state.workOrderDocumentWizard.common?.measurementEquipmentGroup || "").trim();
  replaceSelectOptions(
    workOrderDocumentCommonMeasurementEquipmentGroupInput,
    getWorkOrderDocumentMeasurementEquipmentGroupOptions(selected),
    selected,
  );
  state.workOrderDocumentWizard.common.measurementEquipmentGroup = String(
    workOrderDocumentCommonMeasurementEquipmentGroupInput.value || "",
  ).trim();
}

function getWorkOrderDocumentWizardLearningDraft(workOrderId = "", testId = "") {
  const normalizedWorkOrderId = String(workOrderId || "").trim();
  const normalizedTestId = String(testId || "").trim();
  if (!normalizedWorkOrderId || !normalizedTestId) {
    return {
      assigneeType: "external",
      userId: "",
      fullName: "",
      email: "",
      phone: "",
      company: "",
      oib: "",
    };
  }
  const workOrderDraft = state.workOrderDocumentWizard.learningDrafts?.[normalizedWorkOrderId] ?? {};
  const rawDraft = workOrderDraft?.[normalizedTestId];
  if (typeof rawDraft === "string") {
    return {
      assigneeType: "external",
      userId: String(rawDraft || "").trim(),
      fullName: "",
      email: "",
      phone: "",
      company: "",
      oib: "",
    };
  }
  const source = rawDraft && typeof rawDraft === "object" ? rawDraft : {};
  const assigneeType = "external";
  return {
    assigneeType,
    userId: String(source.userId || "").trim(),
    fullName: String(source.fullName || "").trim(),
    email: String(source.email || "").trim(),
    phone: String(source.phone || "").trim(),
    company: String(source.company || "").trim(),
    oib: String(source.oib || "").trim(),
  };
}

function setWorkOrderDocumentWizardLearningDraft(workOrderId = "", testId = "", draftPatch = {}) {
  const normalizedWorkOrderId = String(workOrderId || "").trim();
  const normalizedTestId = String(testId || "").trim();
  if (!normalizedWorkOrderId || !normalizedTestId) {
    return;
  }
  const current = getWorkOrderDocumentWizardLearningDraft(normalizedWorkOrderId, normalizedTestId);
  const patch = draftPatch && typeof draftPatch === "object"
    ? draftPatch
    : { userId: String(draftPatch || "").trim() };
  const assigneeType = "external";
  const nextDraft = {
    assigneeType,
    userId: String(patch.userId ?? current.userId ?? "").trim(),
    fullName: String(patch.fullName ?? current.fullName ?? "").trim(),
    email: String(patch.email ?? current.email ?? "").trim(),
    phone: String(patch.phone ?? current.phone ?? "").trim(),
    company: String(patch.company ?? current.company ?? "").trim(),
    oib: String(patch.oib ?? current.oib ?? "").trim(),
  };
  state.workOrderDocumentWizard.learningDrafts = {
    ...(state.workOrderDocumentWizard.learningDrafts ?? {}),
    [normalizedWorkOrderId]: {
      ...(state.workOrderDocumentWizard.learningDrafts?.[normalizedWorkOrderId] ?? {}),
      [normalizedTestId]: nextDraft,
    },
  };
}

function getLearningAssignmentsForWorkOrder(test = {}, workOrder = {}) {
  const normalizedWorkOrderId = String(workOrder?.id || "").trim();
  if (!normalizedWorkOrderId) {
    return [];
  }
  return (Array.isArray(test?.assignmentItems) ? test.assignmentItems : [])
    .filter((assignment) => String(assignment?.workOrderId || "").trim() === normalizedWorkOrderId);
}

async function assignLearningTestToWorkOrderPerson(workOrder = {}, test = {}, service = {}, assigneeDraft = {}) {
  const source = assigneeDraft && typeof assigneeDraft === "object"
    ? assigneeDraft
    : { userId: String(assigneeDraft || "").trim() };
  const assigneeType = "external";
  const normalizedUserId = String(source.userId || "").trim();

  const externalFullName = String(source.fullName || "").trim();
  const externalEmail = String(source.email || "").trim();
  const externalPhone = String(source.phone || "").trim();
  const externalCompany = String(source.company || "").trim();
  const externalOib = String(source.oib || "").trim();

  if (!externalFullName) {
    throw new Error("Upiši ime i prezime osobe.");
  }

  const specialistUserId = String(state.workOrderDocumentWizard.common.safetySpecialistUserId || "").trim();
  const specialist = specialistUserId
    ? (state.users ?? []).find((user) => String(user?.id) === specialistUserId)
    : null;

  const timestamp = new Date().toISOString();
  const assignmentItems = Array.isArray(test?.assignmentItems) ? test.assignmentItems : [];
  const identityKey = assigneeType === "external"
    ? `${externalEmail.toLowerCase()}::${externalFullName.toLowerCase()}`
    : normalizedUserId;
  const matchKey = `${String(workOrder?.id || "").trim()}::${assigneeType}::${identityKey}`;
  const existingAssignment = assignmentItems.find((item) => (
    `${String(item?.workOrderId || "").trim()}::${String(item?.assigneeType || "").trim() || "user"}::${
      String(item?.assigneeType || "").trim() === "external"
        ? `${String(item?.externalEmail || "").trim().toLowerCase()}::${String(item?.externalFullName || "").trim().toLowerCase()}`
        : String(item?.userId || "").trim()
    }` === matchKey
  ));

  const nextAssignment = {
    ...(existingAssignment ?? {}),
    id: String(existingAssignment?.id || crypto.randomUUID()),
    assigneeType,
    userId: "",
    userLabel: externalFullName,
    email: externalEmail,
    externalFullName,
    externalEmail,
    externalPhone,
    externalCompany,
    externalOib,
    accessToken: String(existingAssignment?.accessToken || crypto.randomUUID()),
    status: String(existingAssignment?.status || "pending"),
    assignedAt: String(existingAssignment?.assignedAt || timestamp),
    workOrderId: String(workOrder?.id || "").trim(),
    workOrderNumber: String(workOrder?.workOrderNumber || "").trim(),
    serviceId: String(service?.serviceId || service?.id || "").trim(),
    serviceName: String(service?.name || service?.serviceCode || "").trim(),
    assignedByUserId: String(state.user?.id || "").trim(),
    assignedByLabel: String(state.user?.fullName || state.user?.email || "").trim(),
    safetySpecialistUserId: specialistUserId,
    safetySpecialistLabel: specialist
      ? String(specialist.fullName || specialist.email || "").trim()
      : "",
  };

  const remaining = assignmentItems.filter((item) => (
    `${String(item?.workOrderId || "").trim()}::${String(item?.assigneeType || "").trim() || "user"}::${
      String(item?.assigneeType || "").trim() === "external"
        ? `${String(item?.externalEmail || "").trim().toLowerCase()}::${String(item?.externalFullName || "").trim().toLowerCase()}`
        : String(item?.userId || "").trim()
    }` !== matchKey
  ));
  const nextAssignmentItems = [...remaining, nextAssignment];

  const mutationSucceeded = await runMutation(() => apiRequest(`/learning-tests/${test.id}`, {
    method: "PATCH",
    body: {
      assignmentItems: nextAssignmentItems,
    },
  }), workOrderDocumentWizardError);

  if (!mutationSucceeded) {
    throw new Error(workOrderDocumentWizardError?.textContent || "Ispit se nije uspio dodijeliti.");
  }
}

