function getQualificationAreaFieldKey(signatureArea = "elektro") {
  return normalizeQualificationAreaKey(signatureArea)
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "elektro";
}

function getWorkOrderDocumentSignaturePersonFields() {
  const legacyFields = new Map(WORK_ORDER_DOCUMENT_SIGNATURE_PERSON_FIELDS.map((definition) => [
    `${definition.signatureArea}:${definition.capability}`,
    definition,
  ]));

  return getQualificationExamDefinitions().flatMap((definition) => {
    const area = normalizeQualificationAreaKey(definition.key);
    const fieldKey = getQualificationAreaFieldKey(area);
    const inspectLegacy = legacyFields.get(`${area}:inspect`);
    const authorizeLegacy = legacyFields.get(`${area}:authorize`);
    return [
      {
        listFieldName: inspectLegacy?.listFieldName || `${fieldKey}InspectorUserIds`,
        fieldName: inspectLegacy?.fieldName || `${fieldKey}InspectorUserId`,
        capability: "inspect",
        signatureArea: area,
        label: inspectLegacy?.label || `Ispitivači ${definition.label || definition.title || area}`,
        summaryLabel: inspectLegacy?.summaryLabel || `${definition.label || definition.title || area} ispitivači`,
        emptyLabel: inspectLegacy?.emptyLabel || "Odaberi ispitivače",
        multiple: true,
      },
      {
        fieldName: authorizeLegacy?.fieldName || `${fieldKey}AuthorizationHolderUserId`,
        capability: "authorize",
        signatureArea: area,
        label: authorizeLegacy?.label || `Odgovorna osoba ${definition.label || definition.title || area}`,
        summaryLabel: authorizeLegacy?.summaryLabel || `${definition.label || definition.title || area} odgovorna osoba`,
        emptyLabel: authorizeLegacy?.emptyLabel || "Odaberi odgovornu osobu",
      },
    ];
  });
}

function getWorkOrderDocumentSignatureAreaGroups() {
  const legacyGroups = new Map(WORK_ORDER_DOCUMENT_SIGNATURE_AREA_GROUPS.map((group) => [group.key, group]));
  return getQualificationExamDefinitions().map((definition) => {
    const legacyGroup = legacyGroups.get(definition.key);
    return {
      key: definition.key,
      title: legacyGroup?.title || definition.serviceLabel || definition.label || definition.title || definition.key,
    };
  });
}

const WORK_ORDER_DOCUMENT_COMMON_ENVIRONMENT_FIELDS = [
  ["outsideTemperature", "Vanjska temperatura"],
  ["relativeHumidity", "Relativna vlažnost"],
  ["airflowSpeed", "Brzina strujanja"],
  ["weather", "Vrijeme"],
  ["groundCondition", "Stanje tla"],
  ["groundResistance", "Otpor tla"],
];

const WORK_ORDER_DOCUMENT_RANDOMIZED_ENVIRONMENT_FIELDS = new Set([
  "outsideTemperature",
  "relativeHumidity",
  "airflowSpeed",
  "groundResistance",
]);

const WORK_ORDER_DOCUMENT_RANDOMIZED_ENVIRONMENT_FORMAT = {
  outsideTemperature: { decimals: 1 },
  relativeHumidity: { decimals: 1 },
  airflowSpeed: { decimals: 2 },
  groundResistance: { decimals: 1 },
};

function getStableStringHash(value = "") {
  const normalizedValue = String(value || "");
  let hash = 0;
  for (let index = 0; index < normalizedValue.length; index += 1) {
    hash = ((hash << 5) - hash) + normalizedValue.charCodeAt(index);
    hash |= 0;
  }
  return Math.abs(hash);
}

function applyDeterministicEnvironmentVariance(rawValue = "", seedKey = "", fieldName = "", spread = 0.02) {
  const normalizedRawValue = String(rawValue || "").trim();
  if (!normalizedRawValue) {
    return "";
  }

  const numericMatch = normalizedRawValue.match(/-?\d+(?:[.,]\d+)?/);
  if (!numericMatch) {
    return normalizedRawValue;
  }

  const originalNumber = Number(String(numericMatch[0]).replace(",", "."));
  if (!Number.isFinite(originalNumber)) {
    return normalizedRawValue;
  }

  const numericDecimals = (numericMatch[0].split(/[.,]/)[1] || "").length;
  const formatConfig = WORK_ORDER_DOCUMENT_RANDOMIZED_ENVIRONMENT_FORMAT[String(fieldName || "").trim()] || null;
  const targetDecimals = formatConfig ? Math.max(formatConfig.decimals, numericDecimals) : numericDecimals;
  const usesComma = numericMatch[0].includes(",") || (!numericMatch[0].includes(".") && targetDecimals > 0);
  const hash = getStableStringHash(seedKey);
  const ratio = (hash % 2001) / 1000 - 1;
  const nextNumber = originalNumber * (1 + (ratio * spread));
  const maxDelta = Math.abs(originalNumber * spread);
  const maxDisplayDecimals = Math.max(4, Math.min(targetDecimals, 6));
  let displayDecimals = Math.min(targetDecimals, maxDisplayDecimals);
  while (
    displayDecimals < maxDisplayDecimals
    && maxDelta > 0
    && (1 / (10 ** displayDecimals)) > maxDelta
  ) {
    displayDecimals += 1;
  }
  let roundedNumber = displayDecimals > 0
    ? Number(nextNumber.toFixed(displayDecimals))
    : Math.round(nextNumber);
  const displayUnit = displayDecimals > 0 ? 1 / (10 ** displayDecimals) : 1;
  if (maxDelta > 0 && roundedNumber === originalNumber && displayUnit <= maxDelta) {
    const direction = ratio === 0 ? (hash % 2 === 0 ? 1 : -1) : Math.sign(ratio);
    roundedNumber = originalNumber + (originalNumber < 0 ? -direction : direction) * displayUnit;
  }
  const roundedValue = displayDecimals > 0
    ? roundedNumber.toFixed(displayDecimals)
    : String(Math.round(roundedNumber));
  const localizedValue = usesComma ? roundedValue.replace(".", ",") : roundedValue;

  return `${normalizedRawValue.slice(0, numericMatch.index)}${localizedValue}${normalizedRawValue.slice((numericMatch.index ?? 0) + numericMatch[0].length)}`;
}

function getWorkOrderDocumentSignaturePersonFieldName(capability = "inspect", signatureArea = "elektro") {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  return getWorkOrderDocumentSignaturePersonFields().find((entry) => (
    entry.capability === normalizedCapability && entry.signatureArea === normalizedArea
  ))?.fieldName || (normalizedCapability === "authorize" ? "authorizationHolderUserId" : "inspectorUserId");
}

function getWorkOrderDocumentSignaturePersonListFieldName(capability = "inspect", signatureArea = "elektro") {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  return getWorkOrderDocumentSignaturePersonFields().find((entry) => (
    entry.capability === normalizedCapability
      && entry.signatureArea === normalizedArea
      && entry.listFieldName
  ))?.listFieldName || "";
}

function buildWorkOrderDocumentSignaturePersonPatch({
  capability = "inspect",
  signatureArea = "elektro",
  value = "",
  multiple = false,
} = {}) {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const normalizedValues = multiple
    ? normalizeQualifiedUserIdList(value)
    : normalizeQualifiedUserIdList([value]).slice(0, 1);
  const fieldName = getWorkOrderDocumentSignaturePersonFieldName(normalizedCapability, normalizedArea);
  const listFieldName = getWorkOrderDocumentSignaturePersonListFieldName(normalizedCapability, normalizedArea);
  const patch = {
    [fieldName]: normalizedValues[0] || "",
  };

  if (multiple && listFieldName) {
    patch[listFieldName] = normalizedValues;
  }

  if (normalizedCapability === "inspect") {
    patch.inspectorUserIds = normalizedValues;
    patch.inspectorUserId = normalizedValues[0] || "";
  } else {
    patch.authorizationHolderUserId = normalizedValues[0] || "";
  }

  return patch;
}

function applyWorkOrderDocumentWizardCommonSignaturePersonPatch({
  capability = "inspect",
  signatureArea = "elektro",
  value = "",
  multiple = false,
} = {}) {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const patch = buildWorkOrderDocumentSignaturePersonPatch({
    capability,
    signatureArea: normalizedArea,
    value,
    multiple,
  });

  state.workOrderDocumentWizard.common = {
    ...state.workOrderDocumentWizard.common,
    ...patch,
  };

  getAllSelectedWorkOrdersForDocumentWizard().forEach((workOrder) => {
    if (!workOrder?.id || !getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder).includes(normalizedArea)) {
      return;
    }
    setWorkOrderDocumentWizardOverride(workOrder.id, patch);
  });

  if (isDocumentTemplateRuntimeFillMode()) {
    updateDocumentTemplateRuntimeCommon(patch, { render: false });
    getDocumentTemplateRuntimeWorkOrders().forEach((workOrder) => {
      if (!workOrder?.id || !getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder).includes(normalizedArea)) {
        return;
      }
      updateDocumentTemplateRuntimeOverride(workOrder.id, patch, { render: false });
    });
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplatePreviewContent();
  }
}

function getWorkOrderDocumentSignaturePersonOptions(capability = "inspect", signatureArea = "elektro", options = {}) {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const definition = getWorkOrderDocumentSignaturePersonFields().find((entry) => (
    entry.capability === normalizedCapability
      && entry.signatureArea === normalizeQualificationAreaKey(signatureArea)
  )) || null;
  const resolvedOptions = getQualifiedUserOptionsForSignatureAreas(
    normalizedCapability,
    [normalizeQualificationAreaKey(signatureArea)],
    {
      includeEmpty: options.includeEmpty ?? true,
      emptyLabel: options.emptyLabel || definition?.emptyLabel || (
        normalizedCapability === "authorize" ? "Odaberi odgovornu osobu" : "Odaberi ispitivača"
      ),
    },
  );
  if (options.preserveAreaLabel) {
    return resolvedOptions;
  }
  return resolvedOptions.map((option, index) => (
    index === 0 && option.value === ""
      ? option
      : {
        ...option,
        label: (() => {
          const user = getUsersByIds([option.value])[0];
          return user ? getUserDocumentDisplayName(user) : option.label;
        })(),
      }
  ));
}

function getWorkOrderDocumentSignaturePersonName(source = {}, fieldName = "") {
  const value = String(source?.[fieldName] ?? "").trim();
  const user = getUsersByIds([value])[0];
  return user ? getUserDocumentDisplayName(user) : "";
}

function getWorkOrderDocumentSignaturePersonNames(source = {}, definition = {}) {
  if (definition.listFieldName) {
    const values = normalizeQualifiedUserIdList(source?.[definition.listFieldName] ?? []);
    return getUsersByIds(values)
      .map((user) => getUserDocumentDisplayName(user))
      .filter(Boolean);
  }
  const value = getWorkOrderDocumentSignaturePersonName(source, definition.fieldName);
  return value ? [value] : [];
}

function getWorkOrderDocumentSignaturePersonSummaryParts(source = {}, signatureAreas = null) {
  const areaSet = Array.isArray(signatureAreas)
    ? new Set(signatureAreas.map((area) => normalizeQualificationAreaKey(area)))
    : null;
  return getWorkOrderDocumentSignaturePersonFields()
    .filter((definition) => !areaSet || areaSet.has(definition.signatureArea))
    .map((definition) => {
      const names = getWorkOrderDocumentSignaturePersonNames(source, definition);
      return names.length > 0 ? `${definition.summaryLabel}: ${names.join(", ")}` : "";
    }).filter(Boolean);
}

function getWorkOrderDocumentSignaturePersonPickerOptions(capability = "inspect", signatureArea = "elektro") {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  return getQualifiedUsersForSignatureArea(normalizedCapability, normalizedArea).map((user) => ({
    value: String(user.id),
    label: getUserDocumentDisplayName(user),
    summary: getQualifiedUserSummaryValue(user, normalizedCapability, normalizedArea),
    user,
  }));
}

function matchesWorkOrderDocumentSignaturePersonSearch(option = {}, query = "") {
  const normalizedQuery = normalizeLooseName(query);
  if (!normalizedQuery) {
    return true;
  }

  const haystack = normalizeLooseName([
    option.label,
    option.summary,
    option.user?.email,
    option.user?.legacyUsername,
  ].filter(Boolean).join(" "));
  return haystack.includes(normalizedQuery);
}

function setWorkOrderDocumentSignaturePersonTriggerContent(
  trigger,
  selectedUserIds = [],
  {
    capability = "inspect",
    signatureArea = "elektro",
    multiple = false,
    emptyLabel = "",
  } = {},
) {
  if (!(trigger instanceof HTMLButtonElement)) {
    return;
  }

  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const values = multiple
    ? normalizeQualifiedUserIdList(selectedUserIds)
    : normalizeQualifiedUserIdList([selectedUserIds]);
  const selectedUsers = getQualifiedUsersByIds(values, normalizedCapability, signatureArea);
  const defaultEmptyLabel = emptyLabel || (
    normalizedCapability === "authorize"
      ? "Odaberi odgovornu osobu"
      : "Odaberi osobe"
  );
  const labelText = selectedUsers.length === 0
    ? defaultEmptyLabel
    : selectedUsers.map((user) => getUserDocumentDisplayName(user)).filter(Boolean).join(", ");

  trigger.replaceChildren();
  trigger.title = selectedUsers.length > 0
    ? selectedUsers.map((user) => getUserDocumentDisplayName(user)).join(", ")
    : defaultEmptyLabel;
  trigger.setAttribute("aria-label", trigger.title);

  const icon = createWorkOrderActionIcon(normalizedCapability === "authorize" ? "status" : "assignees");
  icon.classList.add("work-order-bulk-action-icon");
  trigger.append(icon);

  if (selectedUsers.length > 0) {
    const stack = document.createElement("span");
    stack.className = "work-order-bulk-executor-stack work-order-document-person-stack";
    selectedUsers.forEach((user) => {
      const avatar = createWorkOrderMiniExecutor({
        label: getUserDocumentDisplayName(user),
        user,
      }, {
        className: "work-order-mini-executor work-order-bulk-executor-avatar work-order-document-person-avatar",
      });
      avatar.removeAttribute("title");
      stack.append(avatar);
    });

    trigger.append(stack);
  }

  const label = document.createElement("span");
  label.className = "work-order-bulk-action-label work-order-document-person-trigger-label";
  label.textContent = labelText;
  trigger.append(label);
}

function createWorkOrderDocumentSignaturePersonPicker({
  capability = "inspect",
  signatureArea = "elektro",
  value = "",
  multiple = false,
  emptyLabel = "",
  onChange = null,
} = {}) {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const wrapper = document.createElement("div");
  wrapper.className = "work-order-calendar-executor-picker work-order-document-person-picker";
  wrapper.dataset.preventRowOpen = "true";

  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.className = "work-order-calendar-executor-trigger work-order-document-person-trigger";
  trigger.dataset.preventRowOpen = "true";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");

  const getCurrentValues = () => (
    multiple
      ? normalizeQualifiedUserIdList(Array.isArray(value) ? value : [value])
      : normalizeQualifiedUserIdList([value]).slice(0, 1)
  );

  const setCurrentValues = (values) => {
    setWorkOrderDocumentSignaturePersonTriggerContent(trigger, values, {
      capability: normalizedCapability,
      signatureArea: normalizedArea,
      multiple,
      emptyLabel,
    });
  };

  const positionMenuPortal = (menu) => {
    const triggerRect = trigger.getBoundingClientRect();
    const menuRect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let left = triggerRect.left;
    let top = triggerRect.bottom + 10;

    if (left + menuRect.width > viewportWidth - 12) {
      left = Math.max(12, viewportWidth - menuRect.width - 12);
    }

    if (top + menuRect.height > viewportHeight - 12) {
      top = Math.max(12, triggerRect.top - menuRect.height - 10);
    }

    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    menu.style.minWidth = `${Math.max(320, Math.round(triggerRect.width + 72))}px`;
  };

  const closeMenu = ({ commit = true } = {}) => {
    if (commit && typeof wrapper._commitPendingChange === "function") {
      wrapper._commitPendingChange();
    }
    wrapper._commitPendingChange = null;
    wrapper.classList.remove("is-open");
    trigger.setAttribute("aria-expanded", "false");
    if (wrapper._menuPortal) {
      wrapper._menuPortal.remove();
      wrapper._menuPortal = null;
    }
  };

  wrapper._closeMenu = closeMenu;

  const openMenu = () => {
    closeOpenWorkOrderStatusMenus(wrapper);

    if (wrapper._menuPortal) {
      return;
    }

    let draftValues = [...getCurrentValues()];
    let searchQuery = "";
    let hasPendingChange = false;

    const menu = document.createElement("div");
    menu.className = "work-item-status-menu work-item-status-menu-portal work-order-calendar-executor-menu-portal work-order-document-person-menu-portal";
    menu.setAttribute("role", "dialog");
    menu.setAttribute(
      "aria-label",
      normalizedCapability === "authorize"
        ? `Odabir odgovorne osobe za ${getSignatureAreaLabel(normalizedArea)}`
        : `Odabir osoba za ${getSignatureAreaLabel(normalizedArea)}`,
    );

    ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
      menu.addEventListener(eventName, (event) => {
        event.stopPropagation();
      });
    });
    menu.addEventListener("wheel", (event) => event.stopPropagation(), { passive: true });

    const searchWrap = document.createElement("div");
    searchWrap.className = "work-order-calendar-executor-search";

    const searchInput = document.createElement("input");
    searchInput.type = "search";
    searchInput.className = "work-order-calendar-executor-search-input";
    searchInput.placeholder = "Traži po imenu ili prezimenu";
    searchInput.autocomplete = "off";
    searchInput.spellcheck = false;
    searchWrap.append(searchInput);

    const selection = document.createElement("div");
    selection.className = "work-order-calendar-executor-selection work-order-document-person-selection";

    const helper = document.createElement("p");
    helper.className = "work-order-calendar-executor-helper";

    const optionsList = document.createElement("div");
    optionsList.className = "work-order-calendar-executor-options";

    const clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "ghost-button work-order-calendar-executor-clear";
    clearButton.textContent = "Očisti";

    const actions = document.createElement("div");
    actions.className = "work-order-calendar-executor-footer";

    const doneButton = document.createElement("button");
    doneButton.type = "button";
    doneButton.className = "primary-button work-order-calendar-executor-save";
    doneButton.textContent = multiple ? "Gotovo" : "Zatvori";

    const emitChange = (nextValues, meta = {}) => {
      const normalized = multiple
        ? normalizeQualifiedUserIdList(nextValues)
        : normalizeQualifiedUserIdList(nextValues).slice(0, 1);
      onChange?.(multiple ? normalized : (normalized[0] || ""), meta);
      return normalized;
    };

    const applyChange = (nextValues, { keepMenuOpen = false } = {}) => {
      const normalized = multiple
        ? normalizeQualifiedUserIdList(nextValues)
        : normalizeQualifiedUserIdList(nextValues).slice(0, 1);
      draftValues = [...normalized];
      setCurrentValues(draftValues);

      if (multiple && keepMenuOpen) {
        hasPendingChange = true;
        emitChange(normalized, { keepMenuOpen: true, live: true });
        syncMenuState();
        return;
      }

      hasPendingChange = false;
      closeOpenWorkOrderStatusMenus();
      emitChange(normalized, { keepMenuOpen: false, live: false });
    };

    wrapper._commitPendingChange = () => {
      if (!hasPendingChange) {
        return;
      }
      hasPendingChange = false;
      emitChange(draftValues, { keepMenuOpen: false, commit: true });
    };

    const renderSelection = () => {
      selection.replaceChildren();
      const selectedUsers = getQualifiedUsersByIds(draftValues, normalizedCapability, normalizedArea);

      if (selectedUsers.length === 0) {
        const empty = document.createElement("span");
        empty.className = "work-order-calendar-executor-selection-empty";
        empty.textContent = normalizedCapability === "authorize"
          ? "Nema odabrane odgovorne osobe."
          : "Odaberi jednu ili više osoba.";
        selection.append(empty);
        return;
      }

      selectedUsers.forEach((user) => {
        const label = user.fullName || user.email || "Korisnik";
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "work-order-calendar-executor-chip";
        chip.title = `Makni ${label}`;

        const avatar = createWorkOrderMiniExecutor({
          label,
          user,
        });
        avatar.removeAttribute("title");

        const text = document.createElement("span");
        text.className = "work-order-calendar-executor-chip-label";
        text.textContent = label;

        const remove = document.createElement("span");
        remove.className = "work-order-calendar-executor-chip-remove";
        remove.setAttribute("aria-hidden", "true");
        remove.textContent = "x";

        chip.append(avatar, text, remove);
        chip.addEventListener("click", (event) => {
          event.stopPropagation();
          applyChange(
            draftValues.filter((entry) => entry !== String(user.id)),
            { keepMenuOpen: multiple },
          );
        });
        selection.append(chip);
      });
    };

    const renderOptions = () => {
      optionsList.replaceChildren();
      const visibleOptions = getWorkOrderDocumentSignaturePersonPickerOptions(normalizedCapability, normalizedArea)
        .filter((option) => matchesWorkOrderDocumentSignaturePersonSearch(option, searchQuery));

      if (visibleOptions.length === 0) {
        const empty = document.createElement("p");
        empty.className = "work-order-calendar-executor-empty";
        empty.textContent = "Nema korisnika za ovaj pojam.";
        optionsList.append(empty);
        return;
      }

      visibleOptions.forEach((option) => {
        const isSelected = draftValues.includes(option.value);
        const optionButton = document.createElement("button");
        optionButton.type = "button";
        optionButton.className = "work-item-status-option work-order-calendar-executor-option work-order-document-person-option";
        optionButton.classList.toggle("is-selected", isSelected);
        optionButton.setAttribute("role", multiple ? "menuitemcheckbox" : "menuitemradio");
        optionButton.setAttribute("aria-checked", String(isSelected));

        const avatar = createWorkOrderMiniExecutor({
          label: option.label,
          user: option.user,
        }, {
          className: "work-order-calendar-executor-option-avatar work-order-document-person-option-avatar",
        });

        const copy = document.createElement("div");
        copy.className = "work-order-document-person-option-copy";

        const label = document.createElement("span");
        label.className = "work-order-calendar-executor-option-label";
        label.textContent = option.label;

        const meta = document.createElement("small");
        meta.className = "work-order-document-person-option-meta";
        meta.textContent = option.summary;

        copy.append(label, meta);

        const marker = document.createElement("span");
        marker.className = "work-order-calendar-executor-option-marker";
        marker.setAttribute("aria-hidden", "true");
        marker.textContent = isSelected ? "✓" : "+";

        optionButton.append(avatar, copy, marker);
        optionButton.addEventListener("click", (event) => {
          event.stopPropagation();
          if (multiple) {
            const nextValues = isSelected
              ? draftValues.filter((entry) => entry !== option.value)
              : [...draftValues, option.value];
            applyChange(nextValues, { keepMenuOpen: true });
            return;
          }

          applyChange(isSelected ? [] : [option.value]);
        });

        optionsList.append(optionButton);
      });
    };

    const syncMenuState = () => {
      renderSelection();
      renderOptions();
      clearButton.hidden = draftValues.length === 0;
      helper.textContent = multiple
        ? `Odaberi jednu ili više osoba za ${getSignatureAreaLabel(normalizedArea)}.`
        : `Odaberi jednu odgovornu osobu za ${getSignatureAreaLabel(normalizedArea)}.`;
    };

    searchInput.addEventListener("input", () => {
      searchQuery = searchInput.value.trim();
      renderOptions();
    });

    searchInput.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        closeMenu();
        trigger.focus({ preventScroll: true });
        return;
      }

      if (event.key !== "Enter") {
        return;
      }

      const visibleOptions = getWorkOrderDocumentSignaturePersonPickerOptions(normalizedCapability, normalizedArea)
        .filter((option) => matchesWorkOrderDocumentSignaturePersonSearch(option, searchQuery));

      if (visibleOptions.length !== 1) {
        return;
      }

      event.preventDefault();
      const nextOption = visibleOptions[0];
      if (multiple) {
        const nextValues = draftValues.includes(nextOption.value)
          ? draftValues.filter((entry) => entry !== nextOption.value)
          : [...draftValues, nextOption.value];
        applyChange(nextValues, { keepMenuOpen: true });
        return;
      }

      applyChange(draftValues.includes(nextOption.value) ? [] : [nextOption.value]);
    });

    clearButton.addEventListener("click", (event) => {
      event.stopPropagation();
      applyChange([], { keepMenuOpen: multiple });
    });

    doneButton.addEventListener("click", (event) => {
      event.stopPropagation();
      closeMenu();
      trigger.focus({ preventScroll: true });
    });

    actions.append(clearButton);
    menu.append(searchWrap, selection, helper, optionsList, actions);
    syncMenuState();

    document.body.append(menu);
    wrapper._menuPortal = menu;
    wrapper.classList.add("is-open");
    trigger.setAttribute("aria-expanded", "true");
    positionMenuPortal(menu);
    requestAnimationFrame(() => {
      positionMenuPortal(menu);
      searchInput.focus({ preventScroll: true });
      searchInput.select();
    });
  };

  ["pointerdown", "mousedown", "click", "keydown"].forEach((eventName) => {
    wrapper.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (wrapper.classList.contains("is-open")) {
      closeOpenWorkOrderStatusMenus();
      return;
    }
    openMenu();
  });

  setCurrentValues(getCurrentValues());
  wrapper.append(trigger);
  return wrapper;
}

function getDocumentTemplateFieldToken(field = {}, index = 0, suffix = "") {
  const tokenKey = getDocumentTemplateFieldTokenKey(field, index);
  const suffixKey = String(suffix || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return `{{${suffixKey ? `${tokenKey}_${suffixKey}` : tokenKey}}}`;
}

function getDocumentTemplateRuntimeServiceValidityMap(workOrderId = "") {
  const normalizedId = String(workOrderId || "").trim();
  const record = normalizedId ? getDocumentTemplateRuntimeOverrideRecord(normalizedId) : null;
  return {
    ...normalizeWorkOrderServiceValidityMap(state.workOrderDocumentWizard.common?.serviceValidityMonths ?? {}),
    ...normalizeWorkOrderServiceValidityMap(state.documentTemplateRuntime.common?.serviceValidityMonths ?? {}),
    ...normalizeWorkOrderServiceValidityMap(record?.serviceValidityMonths ?? {}),
  };
}

function resolveDocumentTemplateRuntimeServiceValidityMonthsByKey(workOrder = {}, serviceKey = "") {
  const normalizedKey = normalizeWorkOrderServiceValidityKey(serviceKey);
  if (!normalizedKey) {
    return "";
  }

  const workOrderId = String(workOrder?.id || "").trim();
  const validityMap = getDocumentTemplateRuntimeServiceValidityMap(workOrderId);
  if (Object.prototype.hasOwnProperty.call(validityMap, normalizedKey)) {
    return normalizeValidityMonthsValue(validityMap[normalizedKey]);
  }

  const service = findServiceItemByValidityKey(
    getDocumentTemplateRuntimeResolvedServiceItems(workOrder),
    normalizedKey,
  ) || getServiceCatalogItemByValidityKey(normalizedKey);
  return service ? getWorkOrderServiceValidityMonths(service) : "";
}

function resolveDocumentTemplateRuntimeServiceValidityMonthsForService(workOrder = {}, service = null) {
  const serviceKey = service ? getWorkOrderServiceValidityKey(service) : "";
  if (!serviceKey) {
    return "";
  }
  return resolveDocumentTemplateRuntimeServiceValidityMonthsByKey(workOrder, serviceKey)
    || getWorkOrderServiceValidityMonths(service);
}

function resolveDocumentTemplateRuntimeServiceValidityMonthsByLabel(workOrder = {}, needles = []) {
  const normalizedNeedles = (Array.isArray(needles) ? needles : [needles])
    .map((value) => normalizeLooseName(value))
    .filter(Boolean);
  if (normalizedNeedles.length === 0) {
    return "";
  }

  const definition = getWorkOrderServiceValidityDefinitionsFromServices(
    getDocumentTemplateRuntimeResolvedServiceItems(workOrder),
  ).find((item) => {
    const labelText = normalizeLooseName([item.code, item.name, item.label].filter(Boolean).join(" "));
    return normalizedNeedles.some((needle) => labelText.includes(needle));
  });

  return definition ? resolveDocumentTemplateRuntimeServiceValidityMonthsByKey(workOrder, definition.key) : "";
}

function resolveDocumentTemplateRuntimeValidityMonths(workOrder = {}) {
  const workOrderId = String(workOrder?.id || "").trim();
  const record = workOrderId ? getDocumentTemplateRuntimeOverrideRecord(workOrderId) : null;
  const explicitValue = record && Object.prototype.hasOwnProperty.call(record, "validityMonths")
    ? normalizeValidityMonthsValue(record.validityMonths)
    : "";
  if (explicitValue) {
    return explicitValue;
  }

  const serviceValue = getDocumentTemplateRuntimeResolvedServiceItems(workOrder)
    .map((item) => resolveDocumentTemplateRuntimeServiceValidityMonthsForService(workOrder, item))
    .find(Boolean);
  if (serviceValue) {
    return serviceValue;
  }

  const commonValue = workOrderId ? normalizeValidityMonthsValue(getDocumentTemplateRuntimeValue(workOrderId, "validityMonths")) : "";
  if (commonValue) {
    return commonValue;
  }

  const electricalValue = workOrderId
    ? normalizeValidityMonthsValue(getDocumentTemplateRuntimeValue(workOrderId, "electricalValidityMonths"))
    : "";
  const tipkaloValue = workOrderId
    ? normalizeValidityMonthsValue(getDocumentTemplateRuntimeValue(workOrderId, "tipkaloValidityMonths"))
    : "";

  return electricalValue || tipkaloValue || "12";
}

function resolveDocumentTemplateRuntimeValidUntil(workOrder = {}) {
  const workOrderId = String(workOrder?.id || "").trim();
  const inspectionDate = workOrderId ? getDocumentTemplateRuntimeValue(workOrderId, "inspectionDate") : "";
  return addMonthsToDateKey(inspectionDate, resolveDocumentTemplateRuntimeValidityMonths(workOrder));
}

function resolveDocumentTemplateRuntimeServiceValidityMonths(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const primaryService = getDocumentTemplateRuntimePrimaryServiceItem(workOrder, template)
    || getDocumentTemplateRuntimeResolvedServiceItems(workOrder)[0]
    || null;
  return resolveDocumentTemplateRuntimeServiceValidityMonthsForService(workOrder, primaryService)
    || resolveDocumentTemplateRuntimeValidityMonths(workOrder);
}

function resolveDocumentTemplateRuntimeServiceValidUntil(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const workOrderId = String(workOrder?.id || "").trim();
  const inspectionDate = workOrderId ? getDocumentTemplateRuntimeValue(workOrderId, "inspectionDate") : "";
  return addMonthsToDateKey(inspectionDate, resolveDocumentTemplateRuntimeServiceValidityMonths(workOrder, template));
}

function resolveDocumentTemplateRuntimeValidUntilForMonthsField(workOrder = {}, fieldName = "") {
  const workOrderId = String(workOrder?.id || "").trim();
  if (!workOrderId) {
    return "";
  }

  const inspectionDate = getDocumentTemplateRuntimeValue(workOrderId, "inspectionDate");
  const validityMonths = normalizeValidityMonthsValue(getDocumentTemplateRuntimeValue(workOrderId, fieldName))
    || resolveDocumentTemplateRuntimeValidityMonths(workOrder);
  return addMonthsToDateKey(inspectionDate, validityMonths);
}

function resolveDocumentTemplateRuntimeServiceValiditySourceValue(source = "", context = {}, { preview = false } = {}) {
  const parsedSource = parseDocumentTemplateServiceValiditySource(source);
  if (!parsedSource) {
    return "";
  }

  const workOrder = context.sampleWorkOrder || {};
  const workOrderId = String(workOrder?.id || "").trim();
  const service = findServiceItemByValidityKey(
    getDocumentTemplateRuntimeResolvedServiceItems(workOrder),
    parsedSource.key,
  ) || getServiceCatalogItemByValidityKey(parsedSource.key);
  const validityMonths = resolveDocumentTemplateRuntimeServiceValidityMonthsByKey(workOrder, parsedSource.key)
    || (service ? getWorkOrderServiceValidityMonths(service) : "");

  if (parsedSource.kind === "SERVICE_VALIDITY_MONTHS") {
    return validityMonths;
  }

  const inspectionDate = workOrderId ? getDocumentTemplateRuntimeValue(workOrderId, "inspectionDate") : "";
  const validUntil = addMonthsToDateKey(inspectionDate, validityMonths);
  return preview && validUntil ? formatCompactDate(validUntil) : validUntil;
}

function getDocumentTemplateLookupSourcePreviewValue(source, context = {}) {
  const safeSource = String(source || "").trim().toUpperCase();
  const serviceValiditySourceValue = resolveDocumentTemplateRuntimeServiceValiditySourceValue(safeSource, context, { preview: true });
  if (serviceValiditySourceValue) {
    return serviceValiditySourceValue;
  }
  const workOrder = context.sampleWorkOrder;
  const company = context.company;
  const location = context.location;
  const object = context.object;
  const documentNumber = getDocumentTemplateRuntimeDocumentNumber(workOrder, context.template);
  const runtimeInspectionDate = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "inspectionDate") : "";
  const runtimeIssuedDate = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "issuedDate") : "";
  const runtimeIssuedPlace = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "issuedPlace") : "";
  const runtimeNote = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "note") : "";
  const runtimeOutsideTemperature = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "outsideTemperature") : "";
  const runtimeRelativeHumidity = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "relativeHumidity") : "";
  const runtimeAirflowSpeed = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "airflowSpeed") : "";
  const runtimeWeather = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "weather") : "";
  const runtimeGroundCondition = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "groundCondition") : "";
  const runtimeGroundResistance = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "groundResistance") : "";
  const runtimeValidityMonths = resolveDocumentTemplateRuntimeValidityMonths(workOrder);
  const runtimeValidUntil = resolveDocumentTemplateRuntimeValidUntil(workOrder);
  const runtimeServiceValidityMonths = resolveDocumentTemplateRuntimeServiceValidityMonths(workOrder, context.template);
  const runtimeServiceValidUntil = resolveDocumentTemplateRuntimeServiceValidUntil(workOrder, context.template);
  const runtimeElectricalValidityMonths = resolveDocumentTemplateRuntimeServiceValidityMonthsByLabel(workOrder, ["panik", "rasvjet"])
    || (workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "electricalValidityMonths") : "");
  const runtimeTipkaloValidityMonths = resolveDocumentTemplateRuntimeServiceValidityMonthsByLabel(workOrder, ["tipkalo", "isklop"])
    || (workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, "tipkaloValidityMonths") : "");
  const runtimeElectricalValidUntil = addMonthsToDateKey(runtimeInspectionDate, runtimeElectricalValidityMonths)
    || resolveDocumentTemplateRuntimeValidUntilForMonthsField(workOrder, "electricalValidityMonths");
  const runtimeTipkaloValidUntil = addMonthsToDateKey(runtimeInspectionDate, runtimeTipkaloValidityMonths)
    || resolveDocumentTemplateRuntimeValidUntilForMonthsField(workOrder, "tipkaloValidityMonths");
  const executorNames = Array.isArray(workOrder?.executors) && workOrder.executors.length > 0
    ? workOrder.executors.join(", ")
    : [workOrder?.executor1, workOrder?.executor2].filter(Boolean).join(", ");
  const serviceSummary = getDocumentTemplateRuntimeResolvedServiceItems(workOrder)
    .map((item) => item.serviceName || item.name || item.serviceCode || "")
    .filter(Boolean)
    .join(", ");
  const qualifiedUserValue = getQualifiedUserSourcePreviewValue(safeSource, context);

  if (qualifiedUserValue) {
    return qualifiedUserValue;
  }

  const sourceMap = {
    CUSTOM_VALUE: "",
    DOCUMENT_TITLE: context.template?.title || "",
    DOCUMENT_TYPE: context.template?.documentType || "",
    TODAY: formatCompactDate(new Date().toISOString()),
    COMPANY_NAME: company?.name || "",
    COMPANY_OIB: company?.oib || "",
    COMPANY_HEADQUARTERS: company?.headquarters || "",
    LOCATION_NAME: location?.name || "",
    LOCATION_REGION: location?.region || "",
    LOCATION_COORDINATES: location?.coordinates || "",
    OBJECT_NAME: object?.name || "",
    OBJEKT: object?.name || "",
    OBJECT_CODE: object?.code || "",
    SIFRA_OBJEKTA: object?.code || "",
    OBJECT_DESCRIPTION: object?.description || "",
    OPIS_OBJEKTA: object?.description || "",
    WORK_ORDER_NUMBER: workOrder?.workOrderNumber || "",
    WORK_ORDER_DOCUMENT_NUMBER: documentNumber,
    WORK_ORDER_STATUS: workOrder?.status || "",
    WORK_ORDER_DUE_DATE: workOrder?.dueDate ? formatCompactDate(workOrder.dueDate) : "",
    WORK_ORDER_INSPECTION_DATE: runtimeInspectionDate ? formatCompactDate(runtimeInspectionDate) : "",
    WORK_ORDER_ISSUED_DATE: runtimeIssuedDate ? formatCompactDate(runtimeIssuedDate) : "",
    WORK_ORDER_VALID_UNTIL: runtimeValidUntil ? formatCompactDate(runtimeValidUntil) : "",
    WORK_ORDER_VALIDITY_MONTHS: runtimeValidityMonths,
    WORK_ORDER_SERVICE_VALID_UNTIL: runtimeServiceValidUntil ? formatCompactDate(runtimeServiceValidUntil) : "",
    WORK_ORDER_SERVICE_VALIDITY_MONTHS: runtimeServiceValidityMonths,
    WORK_ORDER_ISSUED_PLACE: runtimeIssuedPlace,
    WORK_ORDER_DOCUMENT_NOTE: runtimeNote,
    WORK_ORDER_OUTSIDE_TEMPERATURE: runtimeOutsideTemperature,
    WORK_ORDER_RELATIVE_HUMIDITY: runtimeRelativeHumidity,
    WORK_ORDER_AIRFLOW_SPEED: runtimeAirflowSpeed,
    WORK_ORDER_WEATHER: runtimeWeather,
    WORK_ORDER_GROUND_CONDITION: runtimeGroundCondition,
    WORK_ORDER_GROUND_RESISTANCE: runtimeGroundResistance,
    WORK_ORDER_PANIC_VALID_UNTIL: runtimeElectricalValidUntil ? formatCompactDate(runtimeElectricalValidUntil) : "",
    WORK_ORDER_PANIC_VALIDITY_MONTHS: runtimeElectricalValidityMonths,
    WORK_ORDER_TIPKALO_VALID_UNTIL: runtimeTipkaloValidUntil ? formatCompactDate(runtimeTipkaloValidUntil) : "",
    WORK_ORDER_TIPKALO_VALIDITY_MONTHS: runtimeTipkaloValidityMonths,
    WORK_ORDER_EXECUTORS: executorNames,
    WORK_ORDER_TEAM: workOrder?.assignedTeam || "",
    SERVICE_SUMMARY: serviceSummary,
    CONTACT_NAME: workOrder?.contactNameSnapshot || "",
    CONTACT_PHONE: workOrder?.contactPhone || "",
    CONTACT_EMAIL: workOrder?.contactEmail || "",
  };

  return sourceMap[safeSource] ?? "";
}

function getDocumentTemplateAdvancedLookupPreviewValue(field = {}, context = {}) {
  if (String(field?.source || "").trim().toUpperCase() !== "DATABASE_LOOKUP") {
    return "";
  }
  if (getDocumentTemplateLookupMode(field) === "PREVIOUS_DOCUMENT_LOCATION") {
    return "";
  }

  ensureDocumentTemplateDatabaseLookupDraft(field);
  const definition = getDocumentTemplateDatabaseTableDefinition(field.sourceTable || "");
  const lookupDefinition = getDocumentTemplateDatabaseColumnDefinition(field.sourceTable || "", field.lookupColumn || "");
  const valueDefinition = getDocumentTemplateDatabaseColumnDefinition(field.sourceTable || "", field.valueColumn || "");
  if (!definition || !lookupDefinition || !valueDefinition) {
    return "";
  }

  const lookupValue = String(
    String(field.lookupValueSource || "").trim().toUpperCase() === "CUSTOM_VALUE"
      ? field.lookupValue || ""
      : getDocumentTemplateLookupSourcePreviewValue(field.lookupValueSource || "WORK_ORDER_NUMBER", context),
  ).trim();
  if (!lookupValue) {
    return "";
  }

  const rows = Array.isArray(definition.rows?.()) ? definition.rows() : [];
  const normalizedLookup = normalizeDocumentTemplateLookupComparable(lookupValue);
  const match = rows.find((row) => (
    normalizeDocumentTemplateLookupComparable(lookupDefinition.getter(row)) === normalizedLookup
  ));

  if (!match) {
    return "";
  }

  return formatDocumentTemplateLookupResolvedValue(valueDefinition.getter(match));
}

