function getDocumentTemplatePlaceholderDefinitions(template = buildDocumentTemplateDraft()) {
  const context = buildDocumentTemplatePreviewContext(template);
  const placeholderLookup = buildDocumentTemplateInlinePlaceholderLookup(template, context);
  return [
    ...getDocumentTemplateSystemPlaceholderDefinitions(template, context),
    ...(template.customFields ?? []).flatMap((field, index) => {
      const label = field.wordLabel || field.label || `Polje ${index + 1}`;
      const baseDefinition = {
        token: getDocumentTemplateFieldToken(field, index),
        label,
        value: formatDocumentTemplateTextListValue(
          field,
          getDocumentTemplateFieldPreviewValue(field, context, index, { placeholderMode: false }),
        ),
      };

      if (String(field?.type || "").trim().toLowerCase() !== "toggle") {
        return [baseDefinition];
      }

      const toggleValues = buildDocumentTemplateToggleDerivedValues(field, context, placeholderLookup);
      return [
        baseDefinition,
        {
          token: getDocumentTemplateFieldToken(field, index, "DODATNI_TEKST"),
          label: `${label} - dodatni tekst po izboru`,
          value: toggleValues.extraText,
        },
        {
          token: getDocumentTemplateFieldToken(field, index, "PUNI_TEKST"),
          label: `${label} - status i dodatni tekst`,
          value: toggleValues.fullText,
        },
      ];
    }),
  ];
}

function buildDocumentTemplatePreviewContext(template = buildDocumentTemplateDraft(), {
  workOrder = null,
} = {}) {
  const sampleWorkOrder = workOrder || getDocumentTemplatePreviewSampleWorkOrder(template);
  const company = getDocumentTemplatePreviewCompany(template, sampleWorkOrder);
  const location = getDocumentTemplatePreviewLocation(template, sampleWorkOrder);
  const object = getDocumentTemplateRuntimeObjectForWorkOrder(sampleWorkOrder);
  const legalFrameworks = getDocumentTemplateSelectedLegalFrameworks(template);
  const equipmentItems = getDocumentTemplateLinkedEquipmentItems(template);
  const runtimeWorkOrders = getDocumentTemplateRuntimeWorkOrders();

  return {
    template,
    sampleWorkOrder,
    runtimeWorkOrders,
    signatureMethod: getDocumentTemplateContextSignatureMethod(),
    company,
    location,
    object,
    legalFrameworks,
    equipmentItems,
  };
}

function getMeasurementSheetPreviewCellRawValue(sheet, rowIndex, columnIndex, stack = new Set(), formulaContext = null) {
  const context = formulaContext || buildDocumentTemplateMeasurementFormulaContext({
    fields: [],
    currentFieldId: "",
    currentSheet: sheet,
  });
  return getMeasurementSheetFormulaComputedRawValue(
    sheet,
    rowIndex,
    columnIndex,
    stack,
    context,
    context.current,
  );
}

function getMeasurementSheetPreviewCellValue(sheet, rowIndex, columnIndex, formulaContext = null) {
  const row = sheet?.rows?.[rowIndex];
  const column = sheet?.columns?.[columnIndex];

  if (!row || !column) {
    return "";
  }

  if (column.computed === "average") {
    return formatMeasurementAverage(row);
  }

  const rawValue = row.cells?.[column.id] ?? "";
  const format = row.formats?.[column.id];

  if (!isMeasurementFormula(rawValue)) {
    return formatMeasurementLiteralDisplayValue(rawValue, format);
  }

  try {
    return formatMeasurementComputedDisplayValue(
      getMeasurementSheetPreviewCellRawValue(sheet, rowIndex, columnIndex, new Set(), formulaContext),
      format,
    );
  } catch {
    return "#ERR";
  }
}

function isMeasurementPreviewIndexColumn(column = {}, columnIndex = 0) {
  if (columnIndex !== 0) {
    return false;
  }

  const labelText = normalizeLooseName([
    column.label,
    column.placeholder,
    column.id,
  ].filter(Boolean).join(" "));

  return labelText === "r br"
    || labelText === "rbr"
    || labelText.includes("redni broj")
    || labelText.includes("r br")
    || labelText === "pozicija";
}

function getMeasurementSheetPreviewCellPrintableValue(sheet, rowIndex, columnIndex, formulaContext = null) {
  const row = sheet?.rows?.[rowIndex];
  const column = sheet?.columns?.[columnIndex];

  if (!row || !column || column.computed) {
    return "";
  }

  const rawValue = row.cells?.[column.id] ?? "";
  if (!isMeasurementFormula(rawValue)) {
    return rawValue;
  }

  try {
    return getMeasurementSheetPreviewCellRawValue(sheet, rowIndex, columnIndex, new Set(), formulaContext);
  } catch {
    return "";
  }
}

function isMeasurementSheetPreviewRowPopulated(sheet, rowIndex, { includeIndexColumns = true, formulaContext = null } = {}) {
  return (sheet?.columns ?? []).some((column, columnIndex) => {
    if (!includeIndexColumns && isMeasurementPreviewIndexColumn(column, columnIndex)) {
      return false;
    }

    return isMeasurementFillValuePresent(
      getMeasurementSheetPreviewCellPrintableValue(sheet, rowIndex, columnIndex, formulaContext),
    );
  });
}

function getMeasurementSheetPreviewLastPopulatedRowIndex(sheet = null, formulaContext = null) {
  if (!sheet?.rows?.length || !sheet?.columns?.length) {
    return -1;
  }

  const lastContentRowIndex = sheet.rows.reduce((lastIndex, row, rowIndex) => (
    isMeasurementSheetPreviewRowPopulated(sheet, rowIndex, { includeIndexColumns: false, formulaContext })
      ? rowIndex
      : lastIndex
  ), -1);

  if (lastContentRowIndex >= 0) {
    return lastContentRowIndex;
  }

  return sheet.rows.reduce((lastIndex, row, rowIndex) => (
    isMeasurementSheetPreviewRowPopulated(sheet, rowIndex, { includeIndexColumns: true, formulaContext })
      ? rowIndex
      : lastIndex
  ), -1);
}

function getMeasurementSheetPreviewCellVisualFormat(sheet, rowIndex, column = null, formulaContext = null) {
  if (!column || column.computed === "average") {
    return normalizeMeasurementCellFormat();
  }

  const row = sheet?.rows?.[rowIndex];
  const format = normalizeMeasurementCellFormat(row?.formats?.[column.id]);
  const rawValue = row?.cells?.[column.id] ?? "";
  let isFilled = false;

  if (isMeasurementFormula(rawValue)) {
    try {
      const sheetColumnIndex = (sheet?.columns ?? []).findIndex((entry) => String(entry?.id) === String(column.id));
      isFilled = isMeasurementFillValuePresent(
        getMeasurementSheetPreviewCellRawValue(sheet, rowIndex, sheetColumnIndex, new Set(), formulaContext),
      );
    } catch {
      isFilled = false;
    }
  } else {
    isFilled = isMeasurementFillValuePresent(rawValue);
  }

  return resolveMeasurementConditionalFormat(format, isFilled);
}

function buildMeasurementSheetPreviewTable(field = {}, context = {}) {
  const runtimeWorkOrderId = String(context.sampleWorkOrder?.id || "").trim();
  const directRuntimeSnapshot = runtimeWorkOrderId
    ? normalizeWorkOrderMeasurementSheet(getDocumentTemplateRuntimeOverrideRecord(runtimeWorkOrderId)?.fieldSheets?.[String(field?.id || "").trim()])
    : null;
  const runtimeSnapshot = runtimeWorkOrderId
    ? getDocumentTemplateRuntimeMeasurementSheet(runtimeWorkOrderId, field)
    : null;
  const fieldSnapshot = normalizeWorkOrderMeasurementSheet(field.sheet ?? field.measurementSheet);
  const snapshot = runtimeSnapshot
    || fieldSnapshot
    || normalizeWorkOrderMeasurementSheet(context.sampleWorkOrder?.measurementSheet);
  const runtimeSourceId = runtimeWorkOrderId
    ? getDocumentTemplateRuntimeFieldSource(runtimeWorkOrderId, field.id)
    : "";

  if (!snapshot?.columns?.length) {
    return null;
  }

  const formulaContext = buildDocumentTemplateMeasurementFormulaContext({
    fields: context.template?.customFields || documentTemplateFieldDrafts,
    currentFieldId: field.id,
    currentSheet: snapshot,
    workOrderId: runtimeWorkOrderId,
  });
  const lastMeaningfulRowIndex = getMeasurementSheetPreviewLastPopulatedRowIndex(snapshot, formulaContext);
  const fallbackRowCount = Math.max(1, Math.min(40, Number(field.rowCount) || 12));
  const visibleRows = snapshot.rows.slice(0, lastMeaningfulRowIndex >= 0 ? lastMeaningfulRowIndex + 1 : fallbackRowCount);
  const visibleRowIds = new Set(visibleRows.map((row) => String(row?.id || "").trim()).filter(Boolean));

  return {
    columns: snapshot.columns,
    rows: visibleRows.length > 0 ? visibleRows : [normalizeMeasurementSheetRowSnapshotLocal({}, snapshot.columns, 0)],
    formulaContext,
    merges: (snapshot.merges ?? [])
      .filter((merge) => visibleRowIds.has(String(merge?.rowId || "").trim()))
      .map((merge) => ({ ...merge })),
    headerRows: normalizeMeasurementSheetHeaderRowsSnapshotLocal(snapshot.headerRows, visibleRows),
    sourceLabel: directRuntimeSnapshot
      ? "Podaci iz ispunjenog Excel bloka"
      : runtimeSourceId === "template"
      ? "Početna tablica iz templatea"
      : runtimeSourceId.startsWith("record:")
      ? "Podaci iz prethodnog ispitivanja"
      : runtimeSnapshot
      ? "Podaci iz prethodnog ispitivanja"
      : fieldSnapshot
      ? "Podaci iz template Excel bloka"
      : (context.sampleWorkOrder?.workOrderNumber
      ? `Podaci iz RN ${context.sampleWorkOrder.workOrderNumber}`
      : "Podaci iz povezanog RN-a"),
  };
}

function buildMeasurementSheetPreviewCellInlineStyle(sheet, rowIndex, column, formulaContext = null) {
  if (!column) {
    return "";
  }

  if (column.computed === "average") {
    return "text-align:right";
  }

  const format = getMeasurementSheetPreviewCellVisualFormat(sheet, rowIndex, column, formulaContext);
  const styleConfig = getMeasurementCellStyleConfig(format);
  const styles = [];

  styles.push(`text-align:${styleConfig.textAlign}`);
  styles.push(`vertical-align:${styleConfig.verticalAlign}`);
  styles.push(`font-family:${styleConfig.fontFamily}`);
  styles.push(`font-size:${styleConfig.fontSize}`);
  styles.push(`font-weight:${styleConfig.fontWeight}`);
  styles.push(`font-style:${styleConfig.fontStyle}`);
  styles.push(`text-decoration:${styleConfig.textDecoration}`);
  if (styleConfig.fillColor) {
    styles.push(`background-color:${styleConfig.fillColor}`);
  }
  if (format.border.top) {
    styles.push("border-top:2px solid rgba(17,17,17,0.96)");
  }
  if (format.border.right) {
    styles.push("border-right:2px solid rgba(17,17,17,0.96)");
  }
  if (format.border.bottom) {
    styles.push("border-bottom:2px solid rgba(17,17,17,0.96)");
  }
  if (format.border.left) {
    styles.push("border-left:2px solid rgba(17,17,17,0.96)");
  }

  return styles.join("; ");
}

function buildMeasurementSheetPreviewMergeMaps(sheet = null) {
  const anchors = new Map();
  const covered = new Set();
  const merges = normalizeWorkOrderMeasurementSheet(sheet)?.merges ?? [];

  merges.forEach((merge) => {
    const anchorRowIndex = sheet?.rows?.findIndex?.((row) => row.id === merge.rowId) ?? -1;
    const anchorColumnIndex = sheet?.columns?.findIndex?.((column) => column.id === merge.columnId) ?? -1;

    if (anchorRowIndex < 0 || anchorColumnIndex < 0) {
      return;
    }

    const rowSpan = Math.max(1, Math.min(Number(merge.rowSpan) || 1, sheet.rows.length - anchorRowIndex));
    const colSpan = Math.max(1, Math.min(Number(merge.colSpan) || 1, sheet.columns.length - anchorColumnIndex));

    if (rowSpan <= 1 && colSpan <= 1) {
      return;
    }

    anchors.set(`${anchorRowIndex}:${anchorColumnIndex}`, {
      rowSpan,
      colSpan,
    });

    for (let rowIndex = anchorRowIndex; rowIndex < anchorRowIndex + rowSpan; rowIndex += 1) {
      for (let columnIndex = anchorColumnIndex; columnIndex < anchorColumnIndex + colSpan; columnIndex += 1) {
        if (rowIndex === anchorRowIndex && columnIndex === anchorColumnIndex) {
          continue;
        }

        covered.add(`${rowIndex}:${columnIndex}`);
      }
    }
  });

  return {
    anchors,
    covered,
  };
}

function buildDocumentTemplatePreviewPageMarkup(
  page,
  template,
  context,
  {
    placeholderMode = false,
    pageIndex = 0,
    pageCount = 1,
  } = {},
) {
  const pageTitle = escapeHtml(pageCount > 1 ? (page?.title || `Stranica ${pageIndex + 1}`) : "Raspored templatea");
  const pagePlaceholderChips = (page?.fields ?? []).length > 0
    ? (page.fields ?? []).map(({ field, index }) => (
      `<span class="document-template-preview-pill">${escapeHtml(getDocumentTemplateFieldToken(field, index))}</span>`
    )).join("")
    : '<span class="document-template-preview-empty">U templateu još nema placeholdera.</span>';
  const blocks = (page?.fields ?? []).length > 0
    ? (page.fields ?? []).map(({ field, index }) => buildDocumentTemplateFieldPreviewMarkup(field, context, index, { placeholderMode })).join("")
    : `
      <section class="document-template-preview-section">
        <h2>Prazan template</h2>
        <p class="document-template-preview-copy">Dodaj blokove da odmah vidiš raspored i placeholdere.</p>
      </section>
    `;

  return `
    <article class="document-template-preview-page" data-template-sheet-page="${pageIndex}">
      <header class="document-template-preview-header">
        <div>
          <p class="document-template-preview-eyebrow">${placeholderMode ? "{{DOCUMENT_TYPE}}" : escapeHtml(template.documentType || "Template")}</p>
          <h1>${placeholderMode ? "{{DOCUMENT_TITLE}}" : escapeHtml(template.title || "Bez naziva")}</h1>
          <p class="document-template-preview-lead">${escapeHtml(template.description || "HTML predložak je glavni izlaz, a ovdje se definira raspored placeholdera i blokova.")}</p>
        </div>
        <div class="document-template-preview-meta-grid">
          <div><span>${pageCount > 1 ? "Stranica" : "Raspored"}</span><strong>${pageTitle}</strong></div>
          <div><span>Blokova</span><strong>${(page?.fields ?? []).length}</strong></div>
          <div><span>Povezani propisi</span><strong>${context.legalFrameworks.length}</strong></div>
          <div><span>Povezana oprema</span><strong>${context.equipmentItems.length}</strong></div>
        </div>
      </header>
      <section class="document-template-preview-section">
        <div class="document-template-preview-field-head">
          <h2>Placeholderi</h2>
          ${pageCount > 1 ? `<span class="document-template-inline-token">${pageTitle}</span>` : ""}
        </div>
        <div class="document-template-preview-pill-row">${pagePlaceholderChips}</div>
      </section>
      ${blocks}
      ${template.referenceDocument?.fileName ? `
        <section class="document-template-preview-section">
          <h2>${escapeHtml(getDocumentTemplateReferenceLabel(template.referenceDocument))} reference</h2>
          <p class="document-template-preview-copy">Povezani predložak: <strong>${placeholderMode ? "{{REFERENCE_DOCUMENT_NAME}}" : escapeHtml(template.referenceDocument.fileName)}</strong>.</p>
        </section>
      ` : ""}
    </article>
  `;
}

function buildDocumentTemplateFieldPreviewMarkup(field = {}, context = {}, index = 0, { placeholderMode = false } = {}) {
  const token = getDocumentTemplateFieldToken(field, index);
  const title = escapeHtml(field.wordLabel || field.label || `Polje ${index + 1}`);
  const helpText = field.helpText
    ? `<p class="document-template-preview-muted">${escapeHtml(field.helpText)}</p>`
    : "";
  const customHeightPx = getDocumentTemplateBuilderFieldHeightPx(field);
  const sectionStyle = customHeightPx > 0 ? ` style="min-height:${customHeightPx}px"` : "";
  const previewValueHeightPx = getDocumentTemplateBuilderPreviewValueHeightPx(field);
  const fieldValueStyle = previewValueHeightPx > 0 ? ` style="min-height:${previewValueHeightPx}px"` : "";
  const htmlStyle = normalizeDocumentTemplateHtmlStyleDraft(field.htmlStyle);
  const sectionAttrs = (extraClass = "") => {
    const classes = [
      "document-template-preview-section",
      `is-align-${htmlStyle.align}`,
      `is-tone-${htmlStyle.tone}`,
      `is-text-${htmlStyle.textSize}`,
      extraClass,
    ].filter(Boolean).join(" ");
    return ` class="${classes}"${sectionStyle}`;
  };

  if (field.type === "chapter") {
    return `
      <section${sectionAttrs("is-chapter")}>
        <div class="document-template-preview-chapter">
          <span class="document-template-preview-chapter-line"></span>
          <div>
            <h2>${placeholderMode ? escapeHtml(token) : title}</h2>
            ${!placeholderMode ? `<p class="document-template-preview-muted">Blok vizualno odvaja i grupira sljedeće stavke u templateu.</p>` : ""}
          </div>
        </div>
      </section>
    `;
  }

  if (field.type === "system_description") {
    const model = normalizeDocumentTemplateSystemDescriptionRuntimeValue(
      field,
      getDocumentTemplateFieldPreviewValue(field, context, index, { placeholderMode }),
    );
    const blocksMarkup = model.blocks.map((block, blockIndex) => {
      const rowsMarkup = (Array.isArray(block.rows) ? block.rows : []).map((row) => {
        const subtitle = escapeHtml(row.subtitle || "");
        const description = escapeHtml(row.description || "").replace(/\n/g, "<br />");
        const hasSubtitle = Boolean(subtitle);
        const hasDescription = Boolean(String(row.description || "").trim());
        const rowValue = hasDescription
          ? description
          : `<span class="document-template-preview-system-placeholder">${escapeHtml(row.placeholder || (placeholderMode ? token : "Vrijednost se unosi u zapisniku."))}</span>`;
        return `
          <article class="document-template-preview-system-row ${hasSubtitle ? "" : "is-description-only"}">
            ${hasSubtitle ? `<div class="document-template-preview-system-row-label">${subtitle}</div>` : ""}
            <div
              class="document-template-preview-system-row-value"
              style="--document-template-system-lines:${normalizeDocumentTemplateSystemDescriptionLineCount(row.lineCount)}"
            >
              ${rowValue}
            </div>
          </article>
        `;
      }).join("");

      return `
        <div class="document-template-preview-system-block" data-system-block-index="${blockIndex}">
          <div class="document-template-preview-system-title">${escapeHtml(block.title || title)}</div>
          ${block.sectionSubtitle ? `<p class="document-template-preview-system-subtitle">${escapeHtml(block.sectionSubtitle)}</p>` : ""}
          <div class="document-template-preview-system-rows">
            ${rowsMarkup}
          </div>
        </div>
      `;
    }).join("");

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-system-stack">
          ${blocksMarkup}
        </div>
        ${helpText}
      </section>
    `;
  }

  if (isDocumentTemplateMediaFieldType(field.type)) {
    const runtimeWorkOrderId = String(context.sampleWorkOrder?.id || "").trim();
    const mediaValue = runtimeWorkOrderId
      ? normalizeDocumentTemplateMediaFieldValue(getDocumentTemplateRuntimeInitialValue(field, runtimeWorkOrderId))
      : null;
    const mediaUrl = getDocumentTemplateMediaFieldPreviewUrl(mediaValue);
    const mediaKind = getDocumentTemplateMediaFieldKindLabel(field.type);
    const isImage = Boolean(mediaUrl) && !/\.pdf($|\?)/i.test(mediaUrl) && !/application\/pdf/i.test(String(mediaValue?.fileType || ""));
    const mediaBody = placeholderMode
      ? `<div class="document-template-preview-media-placeholder">${escapeHtml(token)}</div>`
      : mediaValue
        ? (isImage
          ? `<div class="document-template-preview-media-frame"><img class="document-template-preview-media-image" src="${escapeHtml(mediaUrl)}" alt="${escapeHtml(mediaValue.fileName || mediaKind)}" loading="lazy" /></div>`
          : `<div class="document-template-preview-media-placeholder is-file">${escapeHtml(mediaValue.fileName || mediaKind)}</div>`)
        : `<div class="document-template-preview-media-placeholder">Klikni ili povuci ${escapeHtml(mediaKind.toLowerCase())} kod izrade zapisnika.</div>`;
    const mediaMeta = placeholderMode
      ? escapeHtml(token)
      : escapeHtml(getDocumentTemplateMediaFieldSummary(mediaValue, field));

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(mediaKind)}</span>
        </div>
        ${mediaBody}
        <p class="document-template-preview-muted">${mediaMeta}</p>
        ${helpText}
      </section>
    `;
  }

  if (isDocumentTemplatePersonSignatureFieldType(field.type)) {
    const areaLabel = getOptionLabel(
      getDocumentTemplateSignatureAreaOptions(field.signatureArea || "elektro"),
      field.signatureArea || "elektro",
    );
    const signatureMethod = getDocumentTemplateContextSignatureMethod(context);
    const { role, allowMultiple } = getDocumentTemplateSignatureFieldConfig(field);
    const roleLabel = getDocumentTemplatePersonSignatureDisplayLabel(role);
    const people = placeholderMode
      ? []
      : buildDocumentTemplateQualifiedInspectorEntries(field, context);
    const inspectorMarkup = people.length > 0
      ? people.map((entry, inspectorIndex) => {
        const isRightAligned = people.length % 2 === 1 && inspectorIndex === people.length - 1;
        const signatureScanUrl = entry.signatureImageUrl || "";
        const signatureImage = signatureScanUrl
          ? `<img class="document-template-preview-signature-image" src="${escapeHtml(signatureScanUrl)}" alt="${escapeHtml(entry.name || "Potpis")}" />`
          : `<div class="document-template-preview-signature-placeholder${signatureMethod === "digital" ? " is-digital" : ""}">${signatureMethod === "digital" ? "Digitalni potpis" : "Potpis"}</div>`;
        const metaMarkup = (entry.metaLines ?? []).map((line) => `<span>${escapeHtml(line)}</span>`).join("");

        return `
          <article class="document-template-preview-person-signature${isRightAligned ? " is-right-aligned" : ""}">
            <div class="document-template-preview-person-copy">
              <strong>${escapeHtml(entry.name || roleLabel)}</strong>
              <div class="document-template-preview-person-meta">${metaMarkup}</div>
            </div>
            <div class="document-template-preview-signature">
              ${signatureImage}
            </div>
          </article>
        `;
      }).join("")
      : `
        <article class="document-template-preview-person-signature is-right-aligned">
          <div class="document-template-preview-person-copy">
            <span class="document-template-preview-person-role">${escapeHtml(allowMultiple ? `${roleLabel}i` : roleLabel)}</span>
            <strong>${escapeHtml(token)}</strong>
          </div>
        </article>
      `;

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(areaLabel)}</span>
        </div>
        <p class="document-template-preview-muted">${escapeHtml(`${getDocumentTemplateSignatureMethodLabel(signatureMethod)} · ${allowMultiple ? "više osoba" : "jedna osoba"}`)}</p>
        <div class="document-template-preview-person-signature-grid">
          ${inspectorMarkup}
        </div>
        ${helpText}
      </section>
    `;
  }

  if (field.type === "digital_signature") {
    const areaLabel = getOptionLabel(
      getDocumentTemplateSignatureAreaOptions(field.signatureArea || "elektro"),
      field.signatureArea || "elektro",
    );
    const roleLabel = getDocumentTemplateDigitalSignatureRoleLabel(field.signatureRole || "inspect");
    const signatureMethod = getDocumentTemplateContextSignatureMethod(context);
    const entries = placeholderMode
      ? []
      : getDocumentTemplateDigitalSignatureEntries(field, context);
    const entryMarkup = entries.length > 0
      ? entries.map((entry, entryIndex) => {
        const metaMarkup = (entry.metaLines ?? []).map((line) => `<span>${escapeHtml(line)}</span>`).join("");
        const isRightAligned = entries.length % 2 === 1 && entryIndex === entries.length - 1;
        const entryName = entry.name || (entry.user ? getUserDocumentDisplayName(entry.user) : "") || entry.role || "Potpisnik";
        const signatureVisual = entry.signatureImageUrl
          ? `<img class="document-template-preview-signature-image" src="${escapeHtml(entry.signatureImageUrl)}" alt="${escapeHtml(entryName || "Digitalni potpis")}" />`
          : `<div class="document-template-preview-signature-placeholder${signatureMethod === "digital" ? " is-digital" : ""}">${signatureMethod === "digital" ? "Kvalificirani digitalni potpis" : "Potpis / scan"}</div>`;
        return `
          <article class="document-template-preview-person-signature${isRightAligned ? " is-right-aligned" : ""}">
            <div class="document-template-preview-person-copy">
              <strong>${escapeHtml(entryName)}</strong>
              <div class="document-template-preview-person-meta">${metaMarkup}</div>
            </div>
            <div class="document-template-preview-signature document-template-preview-signature--digital">
              <span class="document-template-inline-token">${escapeHtml(getDocumentTemplateSignatureMethodLabel(signatureMethod))}</span>
              ${signatureVisual}
            </div>
          </article>
        `;
      }).join("")
      : `
        <article class="document-template-preview-person-signature is-right-aligned">
          <div class="document-template-preview-person-copy">
            <span class="document-template-preview-person-role">${escapeHtml(roleLabel)}</span>
            <strong>${escapeHtml(token)}</strong>
          </div>
          <div class="document-template-preview-signature document-template-preview-signature--digital">
            <span class="document-template-inline-token">${escapeHtml(getDocumentTemplateSignatureMethodLabel(signatureMethod))}</span>
            <div class="document-template-preview-signature-placeholder${signatureMethod === "digital" ? " is-digital" : ""}">${signatureMethod === "digital" ? "Rezervirano za certifikat" : "Rezervirano za potpis"}</div>
          </div>
        </article>
      `;

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(areaLabel)}</span>
        </div>
        <p class="document-template-preview-muted">
          ${escapeHtml(`${getDocumentTemplateSignatureMethodLabel(signatureMethod)} · ${roleLabel}${field.signatureMultiple === false ? " · jedan potpisnik" : " · vise potpisnika"}`)}
        </p>
        <div class="document-template-preview-person-signature-grid">
          ${entryMarkup}
        </div>
        ${helpText}
      </section>
    `;
  }

  if (field.type === "legal_list") {
    const visibleFrameworks = getDocumentTemplateLegalFrameworksForField(context.template, field, { selectedOnly: false });
    const selectedFrameworkIds = placeholderMode || !context.sampleWorkOrder?.id
      ? null
      : getDocumentTemplateRuntimeSelectedLegalFrameworkIds(context.sampleWorkOrder.id, field);
    const selectedFrameworks = getDocumentTemplateLegalFrameworksForField(
      context.template,
      field,
      {
        selectedOnly: true,
        selectedIds: selectedFrameworkIds,
      },
    );
    const listHtml = placeholderMode
      ? `<div class="document-template-preview-pill-row"><span class="document-template-preview-pill">${escapeHtml(token)}</span></div>`
      : selectedFrameworks.length > 0
        ? `<ul class="document-template-preview-list">${selectedFrameworks.map((item) => (
          `<li><strong>${escapeHtml(item.title || "Propis")}</strong>${item.referenceCode ? ` | ${escapeHtml(item.referenceCode)}` : ""}</li>`
        )).join("")}</ul>`
        : '<span class="document-template-preview-empty">Nema odabranih propisa za ovaj blok.</span>';
    const legalMeta = !placeholderMode && visibleFrameworks.length > 0
      ? `<p class="document-template-preview-muted">Prikazuje ${visibleFrameworks.length} propisa, unaprijed označeno ${selectedFrameworks.length}.</p>`
      : "";

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(getDocumentTemplateFieldTypeLabel(field.type))}</span>
        </div>
        ${listHtml}
        ${legalMeta}
        ${helpText}
      </section>
    `;
  }

  if (field.type === "equipment_list") {
    const equipmentItems = placeholderMode || !context.sampleWorkOrder?.id
      ? context.equipmentItems
      : getDocumentTemplateEquipmentItemsForField(context.template, field, context.sampleWorkOrder.id);
    const rows = placeholderMode
      ? `<tbody><tr><td colspan="4">${escapeHtml(token)}</td></tr></tbody>`
      : equipmentItems.length > 0
        ? equipmentItems.map((item) => (
          `<tr><td>${escapeHtml(item.name || "")}</td><td>${escapeHtml(item.deviceType || item.code || "")}</td><td>${escapeHtml(item.inventoryNumber || "")}</td><td>${escapeHtml(item.note || "")}</td></tr>`
        )).join("")
        : '<tr><td colspan="4">Nema povezane opreme za ovaj template.</td></tr>';

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(getDocumentTemplateFieldTypeLabel(field.type))}</span>
        </div>
        <table class="document-template-preview-table">
          <thead>
            <tr>
              <th>Oprema</th>
              <th>Tip</th>
              <th>Inv. broj</th>
              <th>Napomena</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
        ${helpText}
      </section>
    `;
  }

  if (field.type === "measurement_table") {
    const fallbackColumns = (field.columns ?? []).length > 0 ? field.columns : ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"];
    const previewTable = placeholderMode ? null : buildMeasurementSheetPreviewTable(field, context);
    const columns = previewTable?.columns?.length
      ? previewTable.columns.map((column) => column.label || column.id)
      : fallbackColumns;
    const rowCount = Math.max(4, Math.min(40, Number(field.rowCount) || 12));
    const headerRowIds = previewTable?.headerRows ?? [];
    const headerRowIndexes = previewTable
      ? previewTable.rows.reduce((indexes, row, rowIndex) => {
        if (headerRowIds.includes(row.id)) {
          indexes.push(rowIndex);
        }
        return indexes;
      }, [])
      : [];
    const bodyRowIndexes = previewTable
      ? previewTable.rows.reduce((indexes, row, rowIndex) => {
        if (!headerRowIds.includes(row.id)) {
          indexes.push(rowIndex);
        }
        return indexes;
      }, [])
      : [];
    const head = headerRowIndexes.length > 0
      ? renderMeasurementSheetPreviewRows(previewTable, headerRowIndexes, { header: true, formulaContext: previewTable?.formulaContext })
      : `<tr>${columns.map((column) => `<th>${escapeHtml(column)}</th>`).join("")}</tr>`;
    const rows = placeholderMode
      ? `<tr><td colspan="${columns.length}">${escapeHtml(token)}</td></tr>`
      : previewTable
        ? renderMeasurementSheetPreviewRows(previewTable, bodyRowIndexes, { formulaContext: previewTable?.formulaContext })
        : Array.from({ length: rowCount }, (_, rowIndex) => (
          `<tr>${columns.map((column, columnIndex) => `<td>${columnIndex === 0 ? escapeHtml(String(rowIndex + 1)) : "&nbsp;"}</td>`).join("")}</tr>`
        )).join("");
    const previewSource = !placeholderMode && previewTable?.sourceLabel
      ? `<p class="document-template-preview-muted">${escapeHtml(previewTable.sourceLabel)}</p>`
      : "";

    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(getDocumentTemplateFieldTypeLabel(field.type))}</span>
        </div>
        <table class="document-template-preview-table">
          <thead>${head}</thead>
          <tbody>${rows}</tbody>
        </table>
        ${previewSource}
        ${helpText}
      </section>
    `;
  }

  if (field.type === "inspector_signature" || field.type === "authorization_holder_signature") {
    const signaturePreview = getDocumentTemplateSignaturePreviewData(field, context);
    const areaLabel = getOptionLabel(
      getDocumentTemplateSignatureAreaOptions(field.signatureArea || "elektro"),
      field.signatureArea || "elektro",
    );
    const signatureVisual = placeholderMode
      ? `<strong>${escapeHtml(token)}</strong>`
      : signaturePreview.signatureImageUrl
        ? `<img class="document-template-preview-signature-image" src="${escapeHtml(signaturePreview.signatureImageUrl)}" alt="${escapeHtml(signaturePreview.displayName)}" />`
        : `<strong>${escapeHtml(signaturePreview.displayName)}</strong>`;
    const signatureMeta = !placeholderMode && signaturePreview.user
      ? `<p class="document-template-preview-muted">${escapeHtml(signaturePreview.summary)}</p>`
      : "";
    return `
      <section${sectionAttrs()}>
        <div class="document-template-preview-field-head">
          <h2>${title}</h2>
          <span class="document-template-inline-token">${escapeHtml(areaLabel)}</span>
        </div>
        <div class="document-template-preview-signature">
          ${signatureVisual}
          ${signatureMeta}
          <div class="document-template-preview-signature-line"></div>
        </div>
        ${helpText}
      </section>
    `;
  }

  const value = getDocumentTemplateFieldPreviewValue(field, context, index, { placeholderMode });
  const valueHtml = renderDocumentTemplateTextValueHtml(field, value);

  return `
    <section${sectionAttrs()}>
      <div class="document-template-preview-field-head">
        <h2>${title}</h2>
        <span class="document-template-inline-token">${escapeHtml(getDocumentTemplateFieldTypeLabel(field.type))}</span>
      </div>
      <div class="document-template-preview-field-value is-${slugifyValue(field.type || "text")}"${fieldValueStyle}>${valueHtml}</div>
      <p class="document-template-preview-muted">
        ${placeholderMode ? escapeHtml(token) : escapeHtml(getDocumentTemplateFieldSourceLabel(field.source || "CUSTOM_VALUE"))}
      </p>
      ${helpText}
    </section>
  `;
}

function buildDocumentTemplatePreviewMarkup(
  template = buildDocumentTemplateDraft(),
  {
    placeholderMode = false,
    sheetTabs = false,
    context = null,
  } = {},
) {
  const previewContext = context || buildDocumentTemplatePreviewContext(template);
  const pages = buildDocumentTemplateSheetGroups(template.customFields ?? []);
  const safePageIndex = Math.max(0, Math.min(activeDocumentTemplateSheetIndex, pages.length - 1));
  const pageMarkup = pages.map((page, pageIndex) => buildDocumentTemplatePreviewPageMarkup(
    page,
    template,
    previewContext,
    {
      placeholderMode,
      pageIndex,
      pageCount: pages.length,
    },
  ));

  if (!sheetTabs || pages.length <= 1) {
    return pageMarkup.join("");
  }

  const tabs = pages.map((page, index) => `
    <button
      type="button"
      class="document-template-sheet-tab ${index === safePageIndex ? "is-active" : ""}"
      data-template-sheet-tab="${index}"
      data-template-sheet-context="preview"
    >
      <strong>${escapeHtml(page.title)}</strong>
      <span>${(page.fields ?? []).length} bloka</span>
    </button>
  `).join("");

  return `
    <div class="document-template-preview-shell">
      <div class="document-template-sheet-tabs is-preview">${tabs}</div>
      ${pageMarkup[safePageIndex] || ""}
    </div>
  `;
}

function buildDocumentTemplatePlaceholderHtmlMarkup(template = buildDocumentTemplateDraft()) {
  const pages = buildDocumentTemplateSheetGroups(template.customFields ?? []);
  const systemTokens = getDocumentTemplateSystemPlaceholderDefinitions(template)
    .map((entry) => entry.token)
    .filter(Boolean);
  const systemMarkup = systemTokens.length > 0
    ? `<div class="placeholder-page">${systemTokens.map((token) => `<p>${escapeHtml(token)}</p>`).join("")}</div>`
    : "";
  const customMarkup = pages.map((page) => {
    const tokens = (page.fields ?? [])
      .filter(({ field }) => field?.type !== "chapter")
      .flatMap(({ field, index }) => {
        const baseTokens = [getDocumentTemplateFieldToken(field, index)];
        if (String(field?.type || "").trim().toLowerCase() === "toggle") {
          baseTokens.push(
            getDocumentTemplateFieldToken(field, index, "DODATNI_TEKST"),
            getDocumentTemplateFieldToken(field, index, "PUNI_TEKST"),
          );
        }
        return baseTokens;
      })
      .filter(Boolean);

    if (tokens.length === 0) {
      return '<div class="placeholder-page"></div>';
    }

    const body = tokens.map((token) => `<p>${escapeHtml(token)}</p>`).join("");
    return `<div class="placeholder-page">${body}</div>`;
  }).join('<div style="page-break-after: always;"></div>');

  return [systemMarkup, customMarkup].filter(Boolean).join('<div style="page-break-after: always;"></div>');
}

function getDocumentTemplateFieldTokenKey(field = {}, index = 0) {
  return normalizeDocumentTemplateFieldKeyDraft(
    field.key || field.wordLabel || field.label,
    `FIELD_${index + 1}`,
  );
}

function buildDocumentTemplateExportBlockGroups(fields = []) {
  const blocks = [];
  let currentBlock = null;

  (Array.isArray(fields) ? fields : []).forEach((field, index) => {
    if (!field || String(field.type || "").trim().toLowerCase() === "page_break") {
      return;
    }

    if (String(field.type || "").trim().toLowerCase() === "chapter") {
      currentBlock = {
        chapter: field,
        chapterIndex: index,
        items: [],
      };
      blocks.push(currentBlock);
      return;
    }

    if (!currentBlock) {
      currentBlock = {
        chapter: null,
        chapterIndex: -1,
        items: [],
      };
      blocks.push(currentBlock);
    }

    currentBlock.items.push({ field, index });
  });

  return blocks;
}

function buildDocumentTemplateMeasurementTableExportModel(field = {}, context = {}) {
  const previewTable = buildMeasurementSheetPreviewTable(field, context);
  if (!previewTable) {
    const fallbackColumns = (field.columns ?? []).length > 0
      ? field.columns
      : ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"];
    return {
      title: field.label || field.wordLabel || "Excel tablica",
      columns: fallbackColumns,
      columnWidths: fallbackColumns.map(() => 140),
      headerRows: [fallbackColumns],
      rows: [],
      landscape: fallbackColumns.length > 5,
    };
  }

  const rowIndexById = new Map(previewTable.rows.map((row, rowIndex) => [row.id, rowIndex]));
  const headerRows = (previewTable.headerRows ?? [])
    .map((rowId) => {
      const rowIndex = rowIndexById.get(rowId);
      if (!Number.isInteger(rowIndex)) {
        return null;
      }

      return previewTable.columns.map((column, columnIndex) => (
        getMeasurementSheetPreviewCellValue(previewTable, rowIndex, columnIndex, previewTable.formulaContext)
      ));
    })
    .filter(Boolean);
  const bodyRows = previewTable.rows
    .filter((row) => !(previewTable.headerRows ?? []).includes(row.id))
    .map((row) => {
      const rowIndex = rowIndexById.get(row.id);
      return previewTable.columns.map((column, columnIndex) => (
        getMeasurementSheetPreviewCellValue(previewTable, rowIndex, columnIndex, previewTable.formulaContext)
      ));
    });

  return {
    title: field.label || field.wordLabel || "Excel tablica",
    columns: previewTable.columns.map((column) => column.label || column.id),
    columnWidths: previewTable.columns.map((column) => Math.max(MEASUREMENT_COLUMN_MIN_WIDTH, Number(column.width) || 140)),
    headerRows: headerRows.length > 0
      ? headerRows
      : [previewTable.columns.map((column) => column.label || column.id)],
    rows: bodyRows,
    landscape: previewTable.columns.length > 5,
  };
}

function buildDocumentTemplateMeasurementTableWordPlaceholder(field = {}, context = {}) {
  const previewTable = buildMeasurementSheetPreviewTable(field, context);
  if (!previewTable?.columns?.length) {
    const fallbackColumns = (field.columns ?? []).length > 0
      ? field.columns
      : ["Pozicija", "Opis", "Vrijednost", "Granica", "Napomena"];
    return {
      __docxBlockType: "table",
      columns: fallbackColumns.map((label, index) => ({
        id: `column-${index + 1}`,
        label,
        width: 140,
      })),
      rows: [
        {
          id: "row-1",
          header: true,
          cells: fallbackColumns.map((label) => ({
            text: label,
            format: normalizeMeasurementCellFormat({
              bold: true,
              fillColor: "#F1F7F4",
              border: "all",
            }),
          })),
        },
      ],
      headerRows: ["row-1"],
      merges: [],
    };
  }

  const headerRowIds = normalizeMeasurementSheetHeaderRowsSnapshotLocal(previewTable.headerRows, previewTable.rows);

  return {
    __docxBlockType: "table",
    columns: previewTable.columns.map((column, index) => ({
      id: column.id || `column-${index + 1}`,
      label: column.label || column.id || `Kolona ${index + 1}`,
      width: Math.max(MEASUREMENT_COLUMN_MIN_WIDTH, Number(column.width) || 140),
    })),
    rows: previewTable.rows.map((row, rowIndex) => ({
      id: row.id || `row-${rowIndex + 1}`,
      header: headerRowIds.includes(row.id),
      cells: previewTable.columns.map((column, columnIndex) => ({
        text: getMeasurementSheetPreviewCellValue(previewTable, rowIndex, columnIndex, previewTable.formulaContext),
        format: normalizeMeasurementCellFormat(row.formats?.[column.id]),
      })),
    })),
    headerRows: headerRowIds,
    merges: (previewTable.merges ?? []).map((merge) => ({
      rowId: merge.rowId,
      columnId: merge.columnId,
      rowSpan: Math.max(1, Number(merge.rowSpan) || 1),
      colSpan: Math.max(1, Number(merge.colSpan) || 1),
    })),
  };
}

function buildDocumentTemplateMeasurementTableText(field = {}, context = {}) {
  const model = buildDocumentTemplateMeasurementTableExportModel(field, context);
  return [...(model.headerRows ?? []), ...(model.rows ?? [])]
    .map((row) => (Array.isArray(row) ? row : [])
      .map((cell) => String(cell ?? "").trim())
      .join(" | "))
    .filter(Boolean)
    .join("\n");
}

function buildDocumentTemplateLegalExportItems(template = buildDocumentTemplateDraft(), field = {}, workOrder = null) {
  const selectedIds = workOrder?.id
    ? getDocumentTemplateRuntimeSelectedLegalFrameworkIds(workOrder.id, field)
    : [];
  const selectedItems = getDocumentTemplateLegalFrameworksForField(template, field, {
    selectedOnly: true,
    selectedIds,
  });
  const visibleItems = getDocumentTemplateLegalFrameworksForField(template, field, {
    selectedOnly: false,
  });

  return (selectedItems.length > 0 ? selectedItems : visibleItems).map((item) => (
    item.referenceCode
      ? `${item.title || "Propis"} | ${item.referenceCode}`
      : (item.title || "Propis")
  ));
}

function buildDocumentTemplateEquipmentExportRows(field = {}, context = {}) {
  const items = context.sampleWorkOrder?.id
    ? getDocumentTemplateEquipmentItemsForField(context.template, field, context.sampleWorkOrder.id)
    : (Array.isArray(context.equipmentItems) ? context.equipmentItems : []);

  return items.map((item) => ([
    item.name || "",
    item.deviceType || item.code || "",
    item.inventoryNumber || "",
    item.note || "",
  ]));
}

function buildDocumentTemplateEquipmentExportItems(field = {}, context = {}) {
  return buildDocumentTemplateEquipmentExportRows(field, context)
    .map((row) => {
      const [name, deviceType, inventoryNumber, note] = row;
      return [
        String(name || "").trim(),
        String(deviceType || "").trim(),
        String(inventoryNumber ? `Inv. broj: ${inventoryNumber}` : "").trim(),
        String(note || "").trim(),
      ]
        .filter(Boolean)
        .join(" · ");
    })
    .filter(Boolean);
}

function buildDocumentTemplateCompanyResponsibleEntry(field = {}, context = {}) {
  const workOrder = context.sampleWorkOrder || {};
  const roleLabel = buildDocumentTemplateSignatureRoleLabel("company_responsible", field, context);
  const name = String(
    workOrder?.contactNameSnapshot
    || workOrder?.contactName
    || "",
  ).replace(/\s+/g, " ").trim();
  const signerEmail = String(workOrder?.contactEmail || "").trim();
  const signerPhone = String(workOrder?.contactPhone || "").trim();
  const signerOrganization = String(
    workOrder?.companyName
    || context.companyName
    || "",
  ).replace(/\s+/g, " ").trim();
  const displayName = name || roleLabel;

  return {
    role: roleLabel,
    capability: "company_responsible",
    user: null,
    name: displayName,
    metaLines: [signerOrganization, signerPhone, signerEmail].filter(Boolean),
    signatureImageUrl: "",
    signatureMode: getDocumentTemplateContextSignatureMethod(context),
    signerUserId: "",
    signerEmail,
    signerOib: "",
    signerTitle: "",
    signerOrganization,
    signatureFieldRole: "",
    signatureFieldOib: "",
    digitalAnchor: signerEmail || displayName,
    summary: [displayName, signerOrganization, signerPhone || signerEmail].filter(Boolean).join(" | "),
  };
}

function buildDocumentTemplateQualifiedInspectorEntries(field = {}, context = {}) {
  const signatureMethod = getDocumentTemplateContextSignatureMethod(context);
  const { role, allowMultiple } = getDocumentTemplateSignatureFieldConfig(field);
  if (role === "company_responsible") {
    return [buildDocumentTemplateCompanyResponsibleEntry(field, context)];
  }
  const capability = role === "authorize" ? "authorize" : "inspect";
  const roleLabel = buildDocumentTemplateSignatureRoleLabel(capability, field, context);
  const users = getWorkOrderDocumentQualifiedUsers(
    context.sampleWorkOrder,
    capability,
    field.signatureArea || "elektro",
  );
  return (allowMultiple ? users : users.slice(0, 1)).map((user) => {
    const signerOib = String(user?.oib || "").trim();
    const signerEmail = String(user?.email || "").trim();
    const displayName = getUserDocumentDisplayName(user);
    const signerTitle = getUserDocumentTitle(user);
    const signerOrganization = getUserDocumentOrganizationName(user);
    return {
      role: roleLabel,
      name: displayName || roleLabel,
      metaLines: getQualifiedUserDocumentMetaLines(
        user,
        capability,
        field.signatureArea || "elektro",
        field.signatureMetaFields,
      ),
      signatureImageUrl: signatureMethod === "scan" ? getUserSignatureScanDataUrl(user) : "",
      signatureMode: signatureMethod,
      signerUserId: String(user?.id || "").trim(),
      signerEmail,
      signerOib,
      signerTitle,
      signerOrganization,
      signatureFieldRole: "ZNR",
      signatureFieldOib: signerOib,
      digitalAnchor: signerOib || signerEmail || displayName,
    };
  });
}

function buildDocumentTemplateSignatureEntry(field = {}, context = {}) {
  const signaturePreview = getDocumentTemplateSignaturePreviewData(field, context);
  const signerOib = String(signaturePreview.user?.oib || "").trim();
  const signerEmail = String(signaturePreview.user?.email || "").trim();
  const signerTitle = getUserDocumentTitle(signaturePreview.user);
  const signerOrganization = getUserDocumentOrganizationName(signaturePreview.user);
  const roleLabel = buildDocumentTemplateSignatureRoleLabel(
    field.type === "authorization_holder_signature" ? "authorize" : "inspect",
    field,
    context,
  );
  return {
    role: roleLabel,
    name: signaturePreview.displayName || "Potpis",
    metaLines: signaturePreview.metaLines?.length > 0
      ? signaturePreview.metaLines
      : (signaturePreview.summary ? [signaturePreview.summary] : []),
    signatureImageUrl: signaturePreview.signatureImageUrl || "",
    signatureMode: signaturePreview.signatureMethod || "scan",
    signerUserId: String(signaturePreview.user?.id || "").trim(),
    signerEmail,
    signerOib,
    signerTitle,
    signerOrganization,
    signatureFieldRole: "ZNR",
    signatureFieldOib: signerOib,
    digitalAnchor: signerOib || signerEmail || String(signaturePreview.displayName || "").trim(),
  };
}

function buildDocumentTemplateDigitalSignatureEntries(field = {}, context = {}) {
  return getDocumentTemplateDigitalSignatureEntries(field, context).map((entry) => {
    const signerOib = String(entry.signerOib || entry.user?.oib || "").trim();
    const signerEmail = String(entry.signerEmail || entry.user?.email || "").trim();
    const signerTitle = String(entry.signerTitle || getUserDocumentTitle(entry.user)).trim();
    const signerOrganization = String(entry.signerOrganization || getUserDocumentOrganizationName(entry.user)).trim();
    const displayName = String(entry.name || (entry.user ? getUserDocumentDisplayName(entry.user) : "")).trim();
    return {
      role: entry.role,
      name: displayName || entry.role || "Potpisnik",
      metaLines: entry.metaLines ?? [],
      signatureImageUrl: entry.signatureImageUrl || "",
      signatureMode: entry.signatureMode || getDocumentTemplateContextSignatureMethod(context),
      signerUserId: String(entry.signerUserId || entry.user?.id || "").trim(),
      signerEmail,
      signerOib,
      signerTitle,
      signerOrganization,
      signatureFieldRole: entry.signatureFieldRole || "ZNR",
      signatureFieldOib: signerOib,
      digitalAnchor: entry.digitalAnchor || signerOib || signerEmail || displayName,
    };
  });
}

function buildDocumentTemplateSystemDescriptionWordPlaceholder(field = {}, context = {}, index = 0) {
  const value = getDocumentTemplateFieldPreviewValue(field, context, index, { placeholderMode: false });
  const model = normalizeDocumentTemplateSystemDescriptionRuntimeValue(field, value);
  return {
    __docxBlockType: "system_description",
    blocks: model.blocks.map((block, blockIndex) => ({
      id: block.id || `system-description-block-${blockIndex + 1}`,
      title: block.title || field.label || field.wordLabel || "Opis sustava",
      subtitle: block.sectionSubtitle || "",
      rows: (Array.isArray(block.rows) ? block.rows : []).map((row, rowIndex) => ({
        id: row.id || `system-description-row-${blockIndex + 1}-${rowIndex + 1}`,
        subtitle: row.subtitle || "",
        description: row.description || "",
        lineCount: normalizeDocumentTemplateSystemDescriptionLineCount(row.lineCount),
      })),
    })),
  };
}

function buildDocumentTemplateFieldWordPlaceholderValue(field = {}, context = {}, index = 0) {
  if (field.type === "measurement_table") {
    return buildDocumentTemplateMeasurementTableWordPlaceholder(field, context);
  }

  if (field.type === "system_description") {
    return buildDocumentTemplateSystemDescriptionWordPlaceholder(field, context, index);
  }

  if (isDocumentTemplateMediaFieldType(field.type)) {
    const mediaText = buildDocumentTemplateFieldExportText(field, context, index);
    return mediaText || {
      __docxBlockType: "optional_empty",
    };
  }

  if (isDocumentTemplatePersonSignatureFieldType(field.type)) {
    return {
      __docxBlockType: "signature_group",
      items: buildDocumentTemplateQualifiedInspectorEntries(field, context),
    };
  }

  if (field.type === "digital_signature") {
    return {
      __docxBlockType: "signature_group",
      items: buildDocumentTemplateDigitalSignatureEntries(field, context),
    };
  }

  const exportText = getDocumentTemplateFieldExportTextValue(field, context, index);
  if (isRichTextHtml(exportText)) {
    return {
      __docxBlockType: "rich_text",
      html: sanitizeRichTextHtml(exportText),
      text: richTextHtmlToPlainText(exportText),
    };
  }

  return buildDocumentTemplateFieldExportText(field, context, index);
}

function buildDocumentTemplateFieldExportText(field = {}, context = {}, index = 0) {
  if (field.type === "system_description") {
    return buildDocumentTemplateSystemDescriptionSummaryText(
      getDocumentTemplateFieldPreviewValue(field, context, index, { placeholderMode: false }),
    );
  }

  if (field.type === "measurement_table") {
    return buildDocumentTemplateMeasurementTableText(field, context);
  }

  if (isDocumentTemplateMediaFieldType(field.type)) {
    const runtimeWorkOrderId = String(context.sampleWorkOrder?.id || "").trim();
    const mediaValue = runtimeWorkOrderId
      ? normalizeDocumentTemplateMediaFieldValue(getDocumentTemplateRuntimeInitialValue(field, runtimeWorkOrderId))
      : null;
    return mediaValue?.fileName || "";
  }

  if (field.type === "legal_list") {
    return buildDocumentTemplateLegalExportItems(context.template, field, context.sampleWorkOrder).join("\n");
  }

  if (field.type === "equipment_list") {
    return buildDocumentTemplateEquipmentExportItems(field, context).join("\n");
  }

  if (isDocumentTemplatePersonSignatureFieldType(field.type)) {
    return buildDocumentTemplateQualifiedInspectorEntries(field, context)
      .map((entry) => [entry.name, ...(entry.metaLines ?? [])].filter(Boolean).join("\n"))
      .join("\n\n");
  }

  if (field.type === "digital_signature") {
    return buildDocumentTemplateDigitalSignatureText(field, context);
  }

  return formatDocumentTemplateTextListValue(
    field,
    getDocumentTemplateFieldExportTextValue(field, context, index),
  );
}

function buildDocumentTemplateRuntimeExportFileBaseName(template = buildDocumentTemplateDraft(), workOrder = null) {
  const documentNumber = getDocumentTemplateRuntimeDocumentNumber(workOrder, template);
  if (documentNumber) {
    return sanitizeDocumentTemplateFileName(documentNumber, "zapisnik");
  }

  const parts = [
    String(template.outputFileName || template.title || template.documentType || "zapisnik").trim(),
    String(workOrder?.workOrderNumber || "").trim(),
  ].filter(Boolean);

  return sanitizeDocumentTemplateFileName(parts.join(" "), "zapisnik");
}

function getDocumentTemplateRuntimeWorkOrderById(workOrderId = "") {
  const normalizedId = String(workOrderId || "").trim();
  if (!normalizedId) {
    return null;
  }

  return (state.workOrders ?? []).find((item) => String(item.id) === normalizedId) ?? null;
}

function getDocumentTemplateRuntimeActiveSequenceEntry() {
  const sequenceState = getDocumentTemplateRuntimeSequenceState();
  if (!sequenceState || sequenceState.isSummary) {
    return null;
  }

  return sequenceState.entries[sequenceState.index] ?? null;
}

function getDocumentTemplateRuntimeSequenceObjectNumber(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const activeEntry = getDocumentTemplateRuntimeActiveSequenceEntry();
  if (
    activeEntry
    && String(activeEntry.workOrderId || "") === String(workOrder?.id || "")
    && String(activeEntry.templateId || "") === String(getDocumentTemplateRuntimeTemplateId(template))
  ) {
    const sequenceNumber = Number.parseInt(activeEntry.objectSequence, 10);
    return Number.isFinite(sequenceNumber) && sequenceNumber > 0 ? sequenceNumber : 0;
  }

  return 0;
}

function getDocumentTemplateRuntimeSelectedObjectId(workOrder = getDocumentTemplateRuntimeActiveWorkOrder()) {
  const normalizedWorkOrderId = String(workOrder?.id || "").trim();
  if (!normalizedWorkOrderId) {
    return "";
  }

  const activeEntry = getDocumentTemplateRuntimeActiveSequenceEntry();
  if (activeEntry && String(activeEntry.workOrderId || "") === normalizedWorkOrderId) {
    return String(activeEntry.objectId || "").trim();
  }

  return String(state.documentTemplateRuntime.objectSelections?.[normalizedWorkOrderId] || "").trim();
}

function getDocumentTemplateRuntimeObjectForWorkOrder(workOrder = getDocumentTemplateRuntimeActiveWorkOrder()) {
  const objectId = getDocumentTemplateRuntimeSelectedObjectId(workOrder);
  const locationObject = getLocationObject(objectId);
  if (
    !locationObject
    || String(locationObject.companyId || "") !== String(workOrder?.companyId || "")
    || String(locationObject.locationId || "") !== String(workOrder?.locationId || "")
  ) {
    return null;
  }

  return locationObject;
}

function setDocumentTemplateRuntimeObjectSelection(workOrderId = "", objectId = "", { render = false } = {}) {
  const normalizedWorkOrderId = String(workOrderId || "").trim();
  const normalizedObjectId = String(objectId || "").trim();
  if (!normalizedWorkOrderId) {
    return;
  }

  const locationObject = getLocationObject(normalizedObjectId);
  state.documentTemplateRuntime.objectSelections = {
    ...(state.documentTemplateRuntime.objectSelections ?? {}),
    [normalizedWorkOrderId]: normalizedObjectId,
  };

  const sequenceState = getDocumentTemplateRuntimeSequenceState();
  if (sequenceState && !sequenceState.isSummary) {
    const activeIndex = sequenceState.index;
    state.documentTemplateRuntime.sequenceEntries = sequenceState.entries.map((entry, index) => (
      index === activeIndex && String(entry.workOrderId || "") === normalizedWorkOrderId
        ? {
          ...entry,
          objectId: normalizedObjectId,
          objectName: locationObject?.name || "",
        }
        : entry
    ));
  }

  const objectSourceFieldIds = (Array.isArray(documentTemplateFieldDrafts) ? documentTemplateFieldDrafts : [])
    .filter(isDocumentTemplateObjectSourceField)
    .map((field) => String(field?.id || "").trim())
    .filter(Boolean);
  if (objectSourceFieldIds.length > 0) {
    const record = getDocumentTemplateRuntimeOverrideRecord(normalizedWorkOrderId);
    if (record) {
      const nextFieldValues = { ...(record.fieldValues ?? {}) };
      const nextFieldSources = { ...(record.fieldSources ?? {}) };
      const nextFieldAiMeta = { ...(record.fieldAiMeta ?? {}) };
      objectSourceFieldIds.forEach((fieldId) => {
        delete nextFieldValues[fieldId];
        delete nextFieldSources[fieldId];
        delete nextFieldAiMeta[fieldId];
      });
      state.documentTemplateRuntime.overrides = {
        ...(state.documentTemplateRuntime.overrides ?? {}),
        [normalizedWorkOrderId]: {
          ...record,
          fieldValues: nextFieldValues,
          fieldSources: nextFieldSources,
          fieldAiMeta: nextFieldAiMeta,
        },
      };
    }
  }

  saveDocumentTemplateRuntimeLocalDraft({ syncButton: true });
  if (render) {
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplateFieldRows();
    renderDocumentTemplatePreviewContent();
  }
}

function syncDocumentTemplateRuntimeObjectSelectionFromEntry(entry = null) {
  const workOrderId = String(entry?.workOrderId || "").trim();
  if (!workOrderId) {
    return;
  }

  state.documentTemplateRuntime.objectSelections = {
    ...(state.documentTemplateRuntime.objectSelections ?? {}),
    [workOrderId]: String(entry?.objectId || "").trim(),
  };
}

function buildDocumentTemplateRuntimePlaceholderPayload(template = buildDocumentTemplateDraft(), context = buildDocumentTemplatePreviewContext(template)) {
  const placeholders = {
    ...buildDocumentTemplateSystemPlaceholderValues(template, context),
  };

  const placeholderLookup = buildDocumentTemplateInlinePlaceholderLookup(template, context);

  (Array.isArray(template.customFields) ? template.customFields : []).forEach((field, index) => {
    if (!field || String(field.type || "").trim().toLowerCase() === "chapter") {
      return;
    }

    const fieldKey = getDocumentTemplateFieldTokenKey(field, index);
    placeholders[fieldKey] = buildDocumentTemplateFieldWordPlaceholderValue(field, context, index);
    if (String(field.type || "").trim().toLowerCase() === "toggle") {
      const toggleValues = buildDocumentTemplateToggleDerivedValues(field, context, placeholderLookup);
      placeholders[`${fieldKey}_DODATNI_TEKST`] = toggleValues.extraText;
      placeholders[`${fieldKey}_PUNI_TEKST`] = toggleValues.fullText;
    }
  });

  return placeholders;
}

const DOCUMENT_TEMPLATE_HANDOVER_FIELD_KEY = "PRIMOPREDAJNI_ZAPISNIK";
const DOCUMENT_TEMPLATE_HANDOVER_TITLE = "PRIMOPREDAJNI ZAPISNIK";
const DOCUMENT_TEMPLATE_HANDOVER_SUBTITLE = "O OBAVLJENIM USLUGAMA IZ PODRUČJA ZAŠTITE NA RADU I ZAŠTITE OD POŽARA";

function normalizeDocumentTemplateHandoverRow(row = {}, index = 0) {
  const source = row && typeof row === "object" ? row : {};
  const service = String(source.service || source.serviceName || source.name || source.title || "").trim();
  const documentNumber = String(source.documentNumber || source.recordNumber || source.number || "").trim();
  const quantity = String(
    source.quantity
    || source.measurementPlaces
    || source.measurementPlaceCount
    || source.count
    || "1"
  ).trim() || "1";
  const note = String(source.note || source.remark || source.description || "").trim();

  if (!service && !documentNumber && !note) {
    return null;
  }

  return {
    id: String(source.id || `handover-row-${index + 1}`).trim(),
    service: service || "Usluga",
    documentNumber,
    quantity,
    note,
  };
}

function normalizeDocumentTemplateHandoverProtocol(value = {}) {
  const source = value && typeof value === "object" ? value : {};
  return {
    type: "handover_protocol",
    __docxBlockType: "handover_protocol",
    title: String(source.title || DOCUMENT_TEMPLATE_HANDOVER_TITLE).trim() || DOCUMENT_TEMPLATE_HANDOVER_TITLE,
    subtitle: String(source.subtitle || DOCUMENT_TEMPLATE_HANDOVER_SUBTITLE).trim() || DOCUMENT_TEMPLATE_HANDOVER_SUBTITLE,
    workOrderNumber: String(source.workOrderNumber || "").trim(),
    customerName: String(source.customerName || source.customer?.name || "").trim(),
    customerAddress: String(source.customerAddress || source.customer?.address || source.customer?.headquarters || "").trim(),
    customerOib: String(source.customerOib || source.customer?.oib || "").trim(),
    executorName: String(source.executorName || source.executor?.name || "").trim(),
    executorAddress: String(source.executorAddress || source.executor?.address || source.executor?.headquarters || "").trim(),
    executorOib: String(source.executorOib || source.executor?.oib || "").trim(),
    location: String(source.location || source.locationName || source.testingLocation || "").trim(),
    contractType: String(source.contractType || source.contract || "").trim(),
    rows: (Array.isArray(source.rows) ? source.rows : [])
      .map((row, index) => normalizeDocumentTemplateHandoverRow(row, index))
      .filter(Boolean),
    customerSignatureLabel: String(source.customerSignatureLabel || "Ovjerio naručitelj:").trim(),
    executorSignatureLabel: String(source.executorSignatureLabel || "Ovjerio izvršitelj:").trim(),
  };
}

function getDocumentTemplateRuntimeOrganizationForHandover() {
  return state.organizations.find((item) => String(item.id) === String(state.activeOrganizationId))
    ?? state.organizations[0]
    ?? null;
}

function getDocumentTemplateHandoverServiceQuantity(service = {}) {
  return String(
    service.measurementPlaces
    || service.measurementPlaceCount
    || service.measurementPoints
    || service.measurementPointCount
    || service.quantity
    || service.count
    || service.amount
    || "1"
  ).trim() || "1";
}

function getDocumentTemplateHandoverServiceNote(service = {}) {
  return String(
    service.note
    || service.remark
    || service.remarks
    || service.measurementSummary
    || service.description
    || ""
  ).trim();
}

function getDocumentTemplateHandoverServiceCode(service = {}, fallbackIndex = 0) {
  const raw = String(
    service.serviceCode
    || service.code
    || service.shortLabel
    || service.name
    || service.serviceName
    || `USLUGA-${fallbackIndex + 1}`
  ).trim();
  const slug = raw
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .replace(/[^A-Za-z0-9_-]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return slug || `USLUGA-${fallbackIndex + 1}`;
}

function getDocumentTemplateHandoverServiceKey(service = {}, index = 0) {
  return [
    service.serviceId,
    service.id,
    service.serviceCode,
    service.code,
    service.name,
    service.serviceName,
    index,
  ].map((value) => String(value ?? "").trim().toLowerCase()).find(Boolean) || String(index);
}

function buildDocumentTemplateRuntimeServiceDocumentNumber(service = {}, workOrder = {}, template = buildDocumentTemplateDraft(), index = 0) {
  const currentNumber = getDocumentTemplateRuntimeDocumentNumber(workOrder, template);
  const matchedServices = getDocumentTemplateRuntimeMatchedServiceItems(workOrder, template);
  const serviceKey = getDocumentTemplateHandoverServiceKey(service, index);
  const matchesCurrentTemplate = matchedServices.some((item, matchedIndex) => (
    getDocumentTemplateHandoverServiceKey(item, matchedIndex) === serviceKey
  ));
  if (matchesCurrentTemplate && currentNumber) {
    return currentNumber;
  }

  const workOrderNumber = String(workOrder?.workOrderNumber || "").trim();
  const serviceCode = getDocumentTemplateHandoverServiceCode(service, index);
  return [workOrderNumber, serviceCode].filter(Boolean).join("-");
}

function buildDocumentTemplateRuntimeHandoverDefaultRows(template = buildDocumentTemplateDraft(), workOrder = {}) {
  const normalizedServices = getDocumentTemplateRuntimeResolvedServiceItems(workOrder);
  const override = workOrder?.id ? getDocumentTemplateRuntimeOverrideRecord(workOrder.id) : null;
  const rawServices = Array.isArray(override?.serviceItems)
    ? override.serviceItems
    : (Array.isArray(workOrder?.serviceItems) ? workOrder.serviceItems : []);
  const rows = normalizedServices.map((service, index) => {
    const rawService = rawServices[index] && typeof rawServices[index] === "object" ? rawServices[index] : {};
    const mergedService = { ...rawService, ...service };
    return {
      id: getDocumentTemplateHandoverServiceKey(mergedService, index),
      service: String(mergedService.name || mergedService.serviceName || mergedService.serviceCode || "Usluga").trim(),
      documentNumber: buildDocumentTemplateRuntimeServiceDocumentNumber(mergedService, workOrder, template, index),
      quantity: getDocumentTemplateHandoverServiceQuantity(mergedService),
      note: getDocumentTemplateHandoverServiceNote(mergedService),
    };
  });

  if (rows.length > 0) {
    return rows;
  }

  return [{
    id: "default-service",
    service: String(template?.title || template?.documentType || "Zapisnik").trim(),
    documentNumber: getDocumentTemplateRuntimeDocumentNumber(workOrder, template),
    quantity: "1",
    note: "",
  }];
}

function mergeDocumentTemplateHandoverRows(defaultRows = [], overrideRows = []) {
  const defaults = (Array.isArray(defaultRows) ? defaultRows : [])
    .map((row, index) => normalizeDocumentTemplateHandoverRow(row, index))
    .filter(Boolean);
  const overrides = (Array.isArray(overrideRows) ? overrideRows : [])
    .map((row, index) => normalizeDocumentTemplateHandoverRow(row, index))
    .filter(Boolean);
  if (overrides.length === 0) {
    return defaults;
  }

  const overrideKeys = new Set(overrides.map((row) => String(row.id || "").trim()).filter(Boolean));
  return [
    ...overrides,
    ...defaults.filter((row) => !overrideKeys.has(String(row.id || "").trim())),
  ];
}

function buildDocumentTemplateRuntimeHandoverProtocolModel(
  template = buildDocumentTemplateDraft(),
  context = buildDocumentTemplatePreviewContext(template),
  workOrder = context.sampleWorkOrder,
) {
  const company = context.company || getCompany(workOrder?.companyId) || {};
  const location = getLocation(workOrder?.locationId) || {};
  const organization = getDocumentTemplateRuntimeOrganizationForHandover() || {};
  const override = workOrder?.id
    ? normalizeDocumentTemplateHandoverProtocol(getDocumentTemplateRuntimeOverrideRecord(workOrder.id)?.handoverProtocol)
    : null;
  const defaultRows = buildDocumentTemplateRuntimeHandoverDefaultRows(template, workOrder);
  const defaultLocation = [
    workOrder?.locationName || location.name || "",
    workOrder?.locationAddressSnapshot && workOrder.locationAddressSnapshot !== workOrder.locationName
      ? workOrder.locationAddressSnapshot
      : "",
    location.address || "",
    [location.postalCode, location.city].filter(Boolean).join(" "),
    workOrder?.region || location.region || "",
  ].map((value) => String(value || "").trim()).filter(Boolean);
  const uniqueDefaultLocation = Array.from(new Set(defaultLocation));
  const defaults = normalizeDocumentTemplateHandoverProtocol({
    workOrderNumber: workOrder?.workOrderNumber || "",
    customerName: workOrder?.companyName || company.name || "",
    customerAddress: workOrder?.headquarters || company.headquarters || company.address || "",
    customerOib: workOrder?.companyOib || company.oib || "",
    executorName: organization.name || "SafeWork",
    executorAddress: [
      organization.address || "",
      [organization.postalCode, organization.city].filter(Boolean).join(" "),
    ].filter(Boolean).join(", "),
    executorOib: organization.oib || "",
    location: uniqueDefaultLocation.join(", "),
    contractType: workOrder?.contractType || company.contractType || "",
    rows: defaultRows,
  });

  if (!override) {
    return defaults;
  }

  return normalizeDocumentTemplateHandoverProtocol({
    ...defaults,
    ...Object.fromEntries(
      Object.entries(override)
        .filter(([key, value]) => key === "rows" || String(value ?? "").trim() !== ""),
    ),
    rows: mergeDocumentTemplateHandoverRows(defaults.rows, override.rows),
  });
}

function buildDocumentTemplateRuntimeExportEntry(
  template = buildDocumentTemplateDraft(),
  workOrder = getDocumentTemplateRuntimeActiveWorkOrder(),
) {
  const runtimeTemplateId = getDocumentTemplateRuntimeTemplateId(template);
  if (!runtimeTemplateId || !workOrder) {
    return null;
  }

  const context = buildDocumentTemplatePreviewContext(template, { workOrder });
  const baseFileName = buildDocumentTemplateRuntimeExportFileBaseName(template, workOrder);
  const systemPlaceholderValues = buildDocumentTemplateSystemPlaceholderValues(template, context);
  const handoverProtocol = buildDocumentTemplateRuntimeHandoverProtocolModel(template, context, workOrder);
  const placeholders = buildDocumentTemplateRuntimePlaceholderPayload(template, context);
  placeholders[DOCUMENT_TEMPLATE_HANDOVER_FIELD_KEY] = handoverProtocol;

  return {
    templateId: runtimeTemplateId,
    workOrderId: String(workOrder.id || "").trim(),
    baseFileName,
    templateReferenceKind: getDocumentTemplateReferenceKind(template.referenceDocument),
    htmlFileName: `${baseFileName}.html`,
    pdfFileName: `${baseFileName}.pdf`,
    placeholders,
    appendBlocks: [handoverProtocol],
    documentRecord: buildDocumentTemplateRuntimeDocumentRecordPayload(template, workOrder),
    renderModel: {
      title: String(template.title || template.documentType || "Zapisnik").trim(),
      documentType: String(template.documentType || "Zapisnik").trim(),
      workOrderNumber: String(workOrder.workOrderNumber || "").trim(),
      serviceCode: String(systemPlaceholderValues.SIFRA_USLUGE || "").trim(),
      status: String(workOrder.status || "").trim(),
      company: {
        name: String(context.company?.name || "").trim(),
        headquarters: String(context.company?.headquarters || "").trim(),
        oib: String(context.company?.oib || "").trim(),
        logoUrl: String(
          context.company?.logoDataUrl
          || context.company?.logoStorageUrl
          || context.company?.logoUrl
          || ""
        ).trim(),
      },
      location: {
        name: String(context.location?.name || "").trim(),
        region: String(context.location?.region || "").trim(),
        coordinates: String(context.location?.coordinates || "").trim(),
      },
      object: {
        name: String(context.object?.name || "").trim(),
        code: String(context.object?.code || "").trim(),
        description: String(context.object?.description || "").trim(),
      },
      blocks: [
        ...buildDocumentTemplateRuntimePdfBlocks(template, context),
        handoverProtocol,
      ],
    },
  };
}

async function ensureDocumentTemplateRuntimePreviousLookupState(
  template = buildDocumentTemplateDraft(),
  workOrder = getDocumentTemplateRuntimeActiveWorkOrder(),
) {
  if (!template || !workOrder) {
    return;
  }

  const hasPreviousDocumentFields = (Array.isArray(template.customFields) ? template.customFields : [])
    .some((field) => isDocumentTemplateRuntimePersistedField(field));

  if (!hasPreviousDocumentFields) {
    return;
  }

  await ensureDocumentTemplatePreviousRecordOptions(template, workOrder);
}

async function buildDocumentTemplateRuntimeExportEntryAsync(
  template = buildDocumentTemplateDraft(),
  workOrder = getDocumentTemplateRuntimeActiveWorkOrder(),
) {
  await ensureDocumentTemplateRuntimePreviousLookupState(template, workOrder);
  return buildDocumentTemplateRuntimeExportEntry(template, workOrder);
}

function buildDocumentTemplateRuntimePdfBlocks(template = buildDocumentTemplateDraft(), context = buildDocumentTemplatePreviewContext(template)) {
  return buildDocumentTemplateExportBlockGroups(template.customFields ?? []).map((block, blockIndex) => ({
    title: block.chapter?.label || `Blok ${blockIndex + 1}`,
    description: block.chapter?.helpText || "",
    items: block.items.map(({ field, index }) => {
      const title = field.label || field.wordLabel || `Polje ${index + 1}`;

      if (isDocumentTemplateMediaFieldType(field.type)) {
        const mediaValue = normalizeDocumentTemplateMediaFieldValue(
          context.sampleWorkOrder?.id
            ? getDocumentTemplateRuntimeInitialValue(field, context.sampleWorkOrder.id)
            : null,
        );
        return {
          type: "image",
          title,
          imageUrl: getDocumentTemplateMediaFieldPreviewUrl(mediaValue),
          fileName: mediaValue?.fileName || "",
          caption: getDocumentTemplateMediaFieldSummary(mediaValue, field),
          imageKind: getDocumentTemplateMediaFieldKindLabel(field.type),
          onePage: true,
        };
      }

      if (field.type === "measurement_table") {
        return {
          type: "table",
          title,
          ...buildDocumentTemplateMeasurementTableExportModel(field, context),
        };
      }

      if (field.type === "legal_list") {
        return {
          type: "list",
          title,
          items: buildDocumentTemplateLegalExportItems(template, field, context.sampleWorkOrder),
        };
      }

      if (field.type === "equipment_list") {
        return {
          type: "list",
          title,
          items: buildDocumentTemplateEquipmentExportItems(field, context),
        };
      }

      if (isDocumentTemplatePersonSignatureFieldType(field.type)) {
        return {
          type: "signature_group",
          title,
          items: buildDocumentTemplateQualifiedInspectorEntries(field, context),
        };
      }

      if (field.type === "digital_signature") {
        return {
          type: "signature_group",
          title,
          items: buildDocumentTemplateDigitalSignatureEntries(field, context),
        };
      }

      if (field.type === "system_description") {
        const value = normalizeDocumentTemplateSystemDescriptionRuntimeValue(
          field,
          getDocumentTemplateFieldPreviewValue(field, context, index, { placeholderMode: false }),
        );
        return {
          type: "system_description",
          blocks: value.blocks.map((block, blockIndex) => ({
            id: block.id || `system-description-block-${blockIndex + 1}`,
            title: block.title || title,
            subtitle: block.sectionSubtitle || "",
            rows: (Array.isArray(block.rows) ? block.rows : []).map((row, rowIndex) => ({
              id: row.id || `system-description-row-${blockIndex + 1}-${rowIndex + 1}`,
              subtitle: row.subtitle || "",
              description: row.description || "",
              lineCount: normalizeDocumentTemplateSystemDescriptionLineCount(row.lineCount),
            })),
          })),
        };
      }

      const value = buildDocumentTemplateFieldExportText(field, context, index);
      return {
        type: "field",
        title,
        value,
        multiline: String(field.type || "").trim().toLowerCase() === "longtext" || String(value || "").includes("\n"),
      };
    }),
  }));
}

function buildDocumentTemplateRuntimePdfPayloadFromEntry(exportEntry = null) {
  if (!exportEntry) {
    return null;
  }

  const templateEngine = exportEntry.templateReferenceKind === "word"
    ? "word"
    : (exportEntry.templateReferenceKind === "html" ? "html" : "native");
  const usesTemplateDocument = templateEngine === "html" || templateEngine === "word";
  return {
    fileName: exportEntry.pdfFileName,
    fastPdf: usesTemplateDocument ? false : true,
    useTemplatePdf: usesTemplateDocument,
    pdfEngine: templateEngine,
    placeholders: exportEntry.placeholders,
    appendBlocks: exportEntry.appendBlocks ?? [],
    documentRecord: exportEntry.documentRecord,
    renderModel: exportEntry.renderModel,
  };
}

function getDocumentTemplatePdfLoadingPhases({ batch = false } = {}) {
  return [
    {
      label: "Podaci",
      detail: batch ? "Spremam odabrane RN-ove" : "Spremam vrijednosti zapisnika",
      progress: 12,
    },
    {
      label: "Tokeni",
      detail: "Punim placeholdere iz radnog naloga",
      progress: 30,
    },
    {
      label: "Template",
      detail: "Slažem HTML/Word predložak",
      progress: 48,
    },
    {
      label: "PDF engine",
      detail: "Renderiram dokument u PDF",
      progress: 72,
    },
    {
      label: batch ? "Documents" : "Preuzimanje",
      detail: batch ? "Spremam PDF zapisnike u RN Documents" : "Pripremam datoteku za preuzimanje",
      progress: 92,
    },
    {
      label: "Gotovo",
      detail: "Dokument je spreman",
      progress: 100,
    },
  ];
}

async function exportDocumentTemplatePdf() {
  const template = buildDocumentTemplateDraft();
  const templateId = getDocumentTemplateRuntimeTemplateId(template);
  const workOrder = getDocumentTemplateRuntimeActiveWorkOrder();

  if (!templateId || !workOrder) {
    setDocumentTemplateMessage("Odaberi aktivni zapisnik i RN prije PDF exporta.");
    return;
  }

  const loading = createGlobalLoadingController({
    message: "Izrađujem PDF zapisnik...",
    phases: getDocumentTemplatePdfLoadingPhases(),
  });

  try {
    loading.setPhase(0, { message: "Spremam unesene podatke prije PDF exporta..." });
    await persistActiveDocumentTemplateRuntimeRecord();
  } catch (error) {
    console.error("Ne mogu spremiti runtime zapisnik prije PDF exporta.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu spremiti vrijednosti zapisnika prije PDF exporta.");
    loading.close();
    return;
  }

  let payload = null;
  try {
    loading.setPhase(1, { message: "Punim placeholdere podacima iz RN-a..." });
    const exportEntry = await buildDocumentTemplateRuntimeExportEntryAsync(template, workOrder);
    payload = buildDocumentTemplateRuntimePdfPayloadFromEntry(exportEntry);
    if (!payload) {
      setDocumentTemplateMessage("PDF payload nije ispravno pripremljen.");
      loading.close();
      return;
    }
  } catch (error) {
    console.error("Ne mogu pripremiti PDF payload zapisnika.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu pripremiti PDF payload zapisnika.");
    loading.close();
    return;
  }

  try {
    loading.setPhase(3, { message: "PDF engine radi dokument, ovo može potrajati par sekundi..." });
    const response = await apiBinaryRequest(`/document-templates/${encodeURIComponent(templateId)}/export-pdf`, {
      method: "POST",
      body: {
        ...payload,
        signatureSettings: getPdfSignatureExportSettings(),
      },
    });
    loading.setPhase(4, { message: "PDF je vraćen, pripremam preuzimanje..." });
    triggerBlobDownload(response.blob, response.fileName || payload.fileName || "zapisnik.pdf");
    loading.complete({ message: "PDF zapisnik je spreman." });
    setDocumentTemplateMessage("PDF zapisnik je generiran.", { type: "success" });
  } catch (error) {
    console.error("Ne mogu generirati PDF zapisnik.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu generirati PDF zapisnik.");
  } finally {
    window.setTimeout(() => {
      loading.close();
    }, 320);
  }
}

