function buildDocumentTemplateHtmlPreviewEmptyDocument(template = buildDocumentTemplateDraft()) {
  const title = escapeHtml(template.title || "HTML/PDF preview");
  return `<!doctype html>
    <html lang="hr">
      <head>
        <meta charset="utf-8" />
        <title>${title}</title>
        ${buildDocumentTemplateHtmlPreviewDefaultStyles()}
      </head>
      <body>
        <main class="safe-nexus-preview-page">
          <section class="safe-nexus-preview-empty">
            <strong>HTML predložak još nije postavljen</strong>
            <span>Zalijepi HTML kod ili učitaj .html datoteku za preview gotovog PDF dokumenta.</span>
          </section>
        </main>
      </body>
    </html>`;
}

function buildDocumentTemplateHtmlPreviewTable(value = {}) {
  const rows = Array.isArray(value.rows) ? value.rows : [];
  if (rows.length === 0) {
    return "";
  }

  return `
    <table class="safe-nexus-preview-table">
      <tbody>
        ${rows.map((row) => {
          const tagName = row?.header ? "th" : "td";
          const cells = Array.isArray(row?.cells) ? row.cells : [];
          return `<tr>${cells.map((cell) => `<${tagName}>${escapeHtml(cell?.text || "").replace(/\n/g, "<br>") || "&nbsp;"}</${tagName}>`).join("")}</tr>`;
        }).join("")}
      </tbody>
    </table>`;
}

function buildDocumentTemplateHtmlPreviewSignatureGroup(value = {}) {
  const items = Array.isArray(value.items) ? value.items : [];
  if (items.length === 0) {
    return "";
  }

  return `
    <div class="safe-nexus-preview-signatures">
      ${items.map((item) => {
        const metaLines = Array.isArray(item?.metaLines) ? item.metaLines : [];
        return `
          <section class="safe-nexus-preview-signature">
            <strong>${escapeHtml(item?.name || "Potpisnik")}</strong>
            ${metaLines.map((line) => `<small>${escapeHtml(line)}</small>`).join("")}
            <div class="safe-nexus-preview-signature-line">${item?.signatureMode === "digital" ? "Digitalni potpis" : "Potpis"}</div>
          </section>`;
      }).join("")}
    </div>`;
}

function buildDocumentTemplateHtmlPreviewSystemDescription(value = {}) {
  const blocks = Array.isArray(value.blocks) ? value.blocks : [];
  if (blocks.length === 0) {
    return "";
  }

  return blocks.map((block) => {
    const rows = Array.isArray(block?.rows) ? block.rows : [];
    const rowHtml = rows.length > 0
      ? rows.map((row) => `
        <p class="safe-nexus-preview-system-row">
          ${row?.subtitle ? `<strong>${escapeHtml(`${row.subtitle}: `)}</strong>` : ""}
          ${escapeHtml(row?.description || "").replace(/\n/g, "<br>")}
        </p>`).join("")
      : '<p class="safe-nexus-preview-system-row">&nbsp;</p>';
    return `
      <section class="safe-nexus-preview-system-block">
        <h3>${escapeHtml(block?.title || "Opis sustava")}</h3>
        ${block?.subtitle ? `<p><em>${escapeHtml(block.subtitle)}</em></p>` : ""}
        ${rowHtml}
      </section>`;
  }).join("");
}

function formatDocumentTemplateHtmlPreviewPlaceholderValue(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const blockType = String(value.__docxBlockType || value.type || "").trim().toLowerCase();
    if (blockType === "optional_empty") {
      return "";
    }
    if (blockType === "table") {
      return buildDocumentTemplateHtmlPreviewTable(value);
    }
    if (blockType === "signature_group") {
      return buildDocumentTemplateHtmlPreviewSignatureGroup(value);
    }
    if (blockType === "system_description") {
      return buildDocumentTemplateHtmlPreviewSystemDescription(value);
    }
    try {
      return escapeHtml(JSON.stringify(value, null, 2)).replace(/\n/g, "<br>");
    } catch {
      return "";
    }
  }

  if (Array.isArray(value)) {
    return value.map((entry) => formatDocumentTemplateHtmlPreviewPlaceholderValue(entry)).join("<br>");
  }

  return escapeHtml(String(value ?? "")).replace(/\n/g, "<br>");
}

function buildDocumentTemplateHtmlPreviewDocument(html = "", template = buildDocumentTemplateDraft()) {
  const source = ensureHtmlUtf8Meta(String(html || "").trim());
  if (!source) {
    return buildDocumentTemplateHtmlPreviewEmptyDocument(template);
  }

  const title = escapeHtml(template.title || "HTML/PDF preview");
  const defaultStyles = buildDocumentTemplateHtmlPreviewDefaultStyles();
  if (/<!doctype\s+html|<html[\s>]/i.test(source)) {
    if (/<head\b[^>]*>/i.test(source)) {
      return source.replace(/<head\b([^>]*)>/i, `<head$1><meta charset="utf-8" />${defaultStyles}`);
    }
    return source.replace(/<html\b([^>]*)>/i, `<html$1><head><meta charset="utf-8" /><title>${title}</title>${defaultStyles}</head>`);
  }

  return `<!doctype html>
    <html lang="hr">
      <head>
        <meta charset="utf-8" />
        <title>${title}</title>
        ${defaultStyles}
      </head>
      <body>
        <main class="safe-nexus-preview-page">${source}</main>
      </body>
    </html>`;
}

function renderDocumentTemplateHtmlPreviewContent(template = buildDocumentTemplateDraft()) {
  if (!(documentTemplateHtmlPreviewFrame instanceof HTMLIFrameElement)) {
    return;
  }
  if (state.documentTemplateHtmlPreviewCollapsed) {
    return;
  }

  const htmlCode = String(documentTemplateHtmlCodeInput?.value || "").trim();
  if (!htmlCode) {
    documentTemplateHtmlPreviewFrame.srcdoc = buildDocumentTemplateHtmlPreviewEmptyDocument(template);
    return;
  }

  documentTemplateHtmlPreviewFrame.srcdoc = buildDocumentTemplateHtmlPreviewDocument(htmlCode, template);
}

function renderDocumentTemplatePreviewContent(template = buildDocumentTemplateDraft(), context = null) {
  clampDocumentTemplateSheetIndex();
  const runtimeWorkOrder = isDocumentTemplateRuntimeFillMode()
    ? getDocumentTemplateRuntimeActiveWorkOrder()
    : null;
  const previewContext = context || buildDocumentTemplatePreviewContext(
    template,
    runtimeWorkOrder ? { workOrder: runtimeWorkOrder } : {},
  );
  renderDocumentTemplateHtmlPreviewContent(template, previewContext);

  if (!documentTemplatePreview) {
    return;
  }

  documentTemplatePreview.innerHTML = buildDocumentTemplatePreviewMarkup(template, {
    placeholderMode: true,
    sheetTabs: true,
    context: previewContext,
  });
}

function buildMeasurementSheetSectionMergeMaps(sheet, rowIndexes = []) {
  const anchors = new Map();
  const covered = new Set();
  const localRowIndexByGlobal = new Map(rowIndexes.map((rowIndex, localIndex) => [rowIndex, localIndex]));

  (sheet?.merges ?? []).forEach((merge) => {
    const anchorRowIndex = sheet?.rows?.findIndex?.((row) => row.id === merge.rowId) ?? -1;
    const anchorColumnIndex = sheet?.columns?.findIndex?.((column) => column.id === merge.columnId) ?? -1;

    if (anchorRowIndex < 0 || anchorColumnIndex < 0 || !localRowIndexByGlobal.has(anchorRowIndex)) {
      return;
    }

    const rowSpan = Math.max(1, Math.min(Number(merge.rowSpan) || 1, sheet.rows.length - anchorRowIndex));
    const colSpan = Math.max(1, Math.min(Number(merge.colSpan) || 1, sheet.columns.length - anchorColumnIndex));
    const coveredGlobalRows = Array.from({ length: rowSpan }, (_, offset) => anchorRowIndex + offset);

    if (!coveredGlobalRows.every((globalIndex) => localRowIndexByGlobal.has(globalIndex))) {
      return;
    }

    const localAnchorRowIndex = localRowIndexByGlobal.get(anchorRowIndex);
    anchors.set(`${localAnchorRowIndex}:${anchorColumnIndex}`, {
      rowSpan,
      colSpan,
    });

    coveredGlobalRows.forEach((globalRowIndex) => {
      const localRowIndex = localRowIndexByGlobal.get(globalRowIndex);
      for (let columnIndex = anchorColumnIndex; columnIndex < anchorColumnIndex + colSpan; columnIndex += 1) {
        if (localRowIndex === localAnchorRowIndex && columnIndex === anchorColumnIndex) {
          continue;
        }
        covered.add(`${localRowIndex}:${columnIndex}`);
      }
    });
  });

  return { anchors, covered };
}

function renderMeasurementSheetPreviewRows(sheet, rowIndexes = [], options = {}) {
  const { header = false, formulaContext = sheet?.formulaContext || null } = options;
  const merges = buildMeasurementSheetSectionMergeMaps(sheet, rowIndexes);

  return rowIndexes.map((globalRowIndex, localRowIndex) => {
    const row = sheet.rows[globalRowIndex];
    const cells = sheet.columns.map((column, columnIndex) => {
      if (merges.covered.has(`${localRowIndex}:${columnIndex}`)) {
        return "";
      }

      const merge = merges.anchors.get(`${localRowIndex}:${columnIndex}`) ?? null;
      const value = getMeasurementSheetPreviewCellValue(sheet, globalRowIndex, columnIndex, formulaContext);
      const inlineStyle = buildMeasurementSheetPreviewCellInlineStyle(sheet, globalRowIndex, column, formulaContext);
      const safeValue = value ? escapeHtml(value) : "&nbsp;";
      const rowSpanAttr = merge?.rowSpan > 1 ? ` rowspan="${merge.rowSpan}"` : "";
      const colSpanAttr = merge?.colSpan > 1 ? ` colspan="${merge.colSpan}"` : "";
      const cellTag = header ? "th" : "td";
      return `<${cellTag}${rowSpanAttr}${colSpanAttr}${inlineStyle ? ` style="${escapeHtml(inlineStyle)}"` : ""}>${safeValue}</${cellTag}>`;
    }).join("");
    return `<tr>${cells}</tr>`;
  }).join("");
}

function openDocumentTemplatePreviewWindow({ placeholderMode = false } = {}) {
  const template = buildDocumentTemplateDraft();
  const previewWindow = window.open("", "_blank", "noopener,noreferrer");

  if (!previewWindow) {
    setDocumentTemplateMessage("Browser je blokirao preview prozor.");
    return;
  }

  const title = template.title || "Template preview";
  const html = buildDocumentTemplatePreviewMarkup(template, { placeholderMode });

  previewWindow.document.open();
  previewWindow.document.write(`<!DOCTYPE html>
  <html lang="hr">
    <head>
      <meta charset="utf-8" />
      <title>${escapeHtml(title)}</title>
      <style>
        body { margin: 0; font-family: "Segoe UI", Arial, sans-serif; background: #eef4f1; color: #24362e; }
        .toolbar { position: sticky; top: 0; z-index: 5; display: flex; justify-content: space-between; gap: 12px; padding: 16px 22px; background: rgba(255,255,255,0.94); border-bottom: 1px solid rgba(47,104,84,0.12); }
        .toolbar button { border: 1px solid rgba(47,104,84,0.16); border-radius: 999px; background: #fff; color: #255848; padding: 10px 16px; cursor: pointer; }
        .page-wrap { padding: 28px; display: grid; justify-items: center; }
        .document-template-preview-page { width: min(920px, 100%); background: #fff; border: 1px solid rgba(47,104,84,0.12); border-radius: 28px; padding: 32px; box-shadow: 0 22px 54px rgba(24, 48, 39, 0.12); }
        .document-template-preview-page + .document-template-preview-page { margin-top: 24px; page-break-before: always; }
        .document-template-preview-header { display: grid; gap: 18px; margin-bottom: 24px; }
        .document-template-preview-eyebrow { margin: 0 0 8px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.12em; color: #557166; }
        .document-template-preview-header h1 { margin: 0; font-size: 32px; }
        .document-template-preview-lead { margin: 12px 0 0; color: #60796f; }
        .document-template-preview-meta-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
        .document-template-preview-meta-grid div { border: 1px solid rgba(47,104,84,0.12); border-radius: 18px; padding: 12px 14px; background: #f7faf8; display: grid; gap: 4px; }
        .document-template-preview-meta-grid span { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #557166; }
        .document-template-preview-section { margin-top: 26px; }
        .document-template-preview-field-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
        .document-template-preview-cover { border: 1px solid rgba(47,104,84,0.12); border-radius: 24px; padding: 24px; background: linear-gradient(180deg, rgba(247,250,248,0.98), rgba(255,255,255,0.98)); }
        .document-template-preview-copy { color: #42584f; }
        .document-template-preview-list { padding-left: 20px; }
        .document-template-preview-text-list { margin: 0; padding-left: 1.2rem; color: inherit; line-height: 1.55; }
        .document-template-preview-text-list li + li { margin-top: 0.25rem; }
        .document-template-preview-text-list.is-dash { list-style: none; padding-left: 0; }
        .document-template-preview-text-list.is-dash li { position: relative; padding-left: 1rem; }
        .document-template-preview-text-list.is-dash li::before { content: "-"; position: absolute; left: 0; color: currentColor; }
        .document-template-preview-table { width: 100%; border-collapse: collapse; margin-top: 14px; }
        .document-template-preview-table th, .document-template-preview-table td { border: 1px solid rgba(47,104,84,0.14); padding: 9px 10px; text-align: left; vertical-align: top; }
        .document-template-preview-table th { background: #f1f7f4; }
        .document-template-preview-field-value { border: 1px solid rgba(47,104,84,0.12); border-radius: 18px; padding: 14px 16px; background: #f7faf8; color: #26493d; line-height: 1.55; }
        .document-template-preview-field-value.is-checkbox, .document-template-preview-field-value.is-toggle { display: inline-flex; align-items: center; width: fit-content; min-width: 96px; justify-content: center; font-weight: 700; }
        .document-template-preview-pill-row { display: flex; flex-wrap: wrap; gap: 8px; }
        .document-template-preview-pill { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; border: 1px solid rgba(47,104,84,0.14); background: #f7faf8; font-size: 13px; }
        .document-template-preview-empty { color: #60796f; }
        .document-template-preview-signatures { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; margin-top: 18px; }
        .document-template-preview-signature { display: grid; gap: 10px; }
        .document-template-preview-signature-line { height: 52px; border-bottom: 1px solid rgba(47,104,84,0.24); }
        .document-template-preview-page-break { border: 1px dashed rgba(47,104,84,0.3); border-radius: 18px; padding: 16px; background: rgba(247,250,248,0.88); display: grid; gap: 6px; text-align: center; }
        @media print {
          body { background: #fff; }
          .toolbar { display: none; }
          .page-wrap { padding: 0; }
          .document-template-preview-page { width: 100%; border: none; border-radius: 0; box-shadow: none; padding: 0; }
        }
      </style>
    </head>
    <body>
      <div class="toolbar">
        <strong>${escapeHtml(title)}</strong>
        <div>
          <button type="button" onclick="window.print()">Ispis / PDF</button>
          <button type="button" onclick="window.close()">Zatvori</button>
        </div>
      </div>
      <div class="page-wrap">${html}</div>
    </body>
  </html>`);
  previewWindow.document.close();
}

function exportDocumentTemplatePlaceholderHtml() {
  const template = buildDocumentTemplateDraft();
  const fileName = `${sanitizeDocumentTemplateFileName(template.title || "template-dokument")}-placeholder.html`;
  const html = buildDocumentTemplatePlaceholderHtmlMarkup(template);
  triggerBlobDownload(
    createStandaloneHtmlBlob(template.title || "Template", html),
    fileName,
  );
}

function renderDocumentTemplateRuntimeSummaryIfVisible() {
  const sequenceState = getDocumentTemplateRuntimeSequenceState();
  if (!sequenceState?.isSummary) {
    return;
  }

  syncDocumentTemplateEditorChrome();
  renderDocumentTemplateRuntimeContext();
  renderDocumentTemplateFieldRows();
  renderDocumentTemplatePreviewContent();
}

function getDocumentTemplateRuntimeSequenceEntryIndex(targetEntry = {}, entries = getDocumentTemplateRuntimeSequenceEntries()) {
  const targetKey = getDocumentTemplateRuntimeSequenceEntryKey(targetEntry);
  if (!targetKey) {
    return -1;
  }

  return (Array.isArray(entries) ? entries : [])
    .findIndex((entry) => getDocumentTemplateRuntimeSequenceEntryKey(entry) === targetKey);
}

function buildDocumentTemplateRuntimeBatchSequenceEntries() {
  const sequenceEntries = getDocumentTemplateRuntimeSequenceEntries();
  if (sequenceEntries.length > 0) {
    return getDocumentTemplateRuntimeExportableSequenceEntries(sequenceEntries);
  }

  const activeTemplate = buildDocumentTemplateDraft();
  const activeTemplateId = getDocumentTemplateRuntimeTemplateId(activeTemplate);
  const activeWorkOrder = getDocumentTemplateRuntimeActiveWorkOrder();
  if (
    !activeTemplateId
    || !activeWorkOrder
    || !isDocumentTemplateRuntimeWorkOrderReadyForExport(activeWorkOrder.id)
  ) {
    return [];
  }

  return [{
    templateId: activeTemplateId,
    workOrderId: String(activeWorkOrder.id || "").trim(),
    templateTitle: String(activeTemplate.title || activeTemplate.documentType || "Zapisnik").trim(),
    workOrderNumber: String(activeWorkOrder.workOrderNumber || "").trim(),
  }];
}

async function exportDocumentTemplateBatchPdf({ print = true } = {}) {
  const sequenceEntries = buildDocumentTemplateRuntimeBatchSequenceEntries();
  if (sequenceEntries.length === 0) {
    setDocumentTemplateMessage("Nema odabranih RN-ova za PDF. Vrati preskočene RN-ove ili odaberi zapisnike za spremanje.");
    return;
  }

  clearDocumentTemplateRuntimeExportStatuses(sequenceEntries);
  renderDocumentTemplateRuntimeSummaryIfVisible();

  const exportEntries = [];
  let failureCount = 0;
  let generatedCount = 0;
  const exportFailureDetails = [];
  const allSequenceEntries = getDocumentTemplateRuntimeSequenceEntries();
  const previousRuntimeView = {
    sequenceIndex: state.documentTemplateRuntime.sequenceIndex,
    activeWorkOrderId: state.documentTemplateRuntime.activeWorkOrderId,
  };
  const loading = createGlobalLoadingController({
    message: `Pripremam ${sequenceEntries.length} odabranih zapisnika za PDF...`,
    phases: getDocumentTemplatePdfLoadingPhases({ batch: true }),
  });
  const restorePreviousRuntimeView = ({ render = false } = {}) => {
    state.documentTemplateRuntime.sequenceIndex = previousRuntimeView.sequenceIndex;
    state.documentTemplateRuntime.activeWorkOrderId = previousRuntimeView.activeWorkOrderId;
    if (render) {
      renderDocumentTemplateRuntimeSummaryIfVisible();
    }
  };
  const pushExportFailureDetail = (sequenceEntry = {}, error = null, fallback = "Ne mogu spremiti zapisnik.") => {
    const workOrderLabel = `RN ${sequenceEntry?.workOrderNumber || sequenceEntry?.workOrderId || "?"}`;
    const message = String(error?.message || fallback || "").trim() || "Ne mogu spremiti zapisnik.";
    exportFailureDetails.push(`${workOrderLabel}: ${message}`);
  };

  try {
    loading.setPhase(0, { message: `Spremam ${sequenceEntries.length} označenih zelenih zapisnika...` });
    for (const [index, sequenceEntry] of sequenceEntries.entries()) {
      const template = getDocumentTemplateById(sequenceEntry.templateId);
      const workOrder = getDocumentTemplateRuntimeWorkOrderById(sequenceEntry.workOrderId);
      const workOrderLabel = `RN ${sequenceEntry.workOrderNumber || workOrder?.workOrderNumber || index + 1}`;

      if (!template || !workOrder) {
        failureCount += 1;
        pushExportFailureDetail(sequenceEntry, null, "Template ili RN više nije dostupan.");
        setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
          status: "error",
          message: "Template ili RN više nije dostupan.",
        }, { render: true });
        continue;
      }

      try {
        setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
          status: "running",
          message: `Spremam vrijednosti za ${workOrderLabel}.`,
        }, { render: true });
        loading.setPhase(1, {
          message: `Punim placeholdere ${index + 1}/${sequenceEntries.length}: ${workOrderLabel}...`,
          progress: Math.min(42, 18 + Math.round(((index + 1) / sequenceEntries.length) * 20)),
        });

        const entryIndex = getDocumentTemplateRuntimeSequenceEntryIndex(sequenceEntry, allSequenceEntries);
        if (entryIndex >= 0) {
          state.documentTemplateRuntime.sequenceIndex = entryIndex;
        }
        state.documentTemplateRuntime.activeWorkOrderId = String(sequenceEntry.workOrderId || "").trim();
        syncDocumentTemplateRuntimeObjectSelectionFromEntry(sequenceEntry);
        await persistDocumentTemplateRuntimeServiceProgress(workOrder, template, "in_progress");

        await persistDocumentTemplateRuntimeRecordFor(template, workOrder);
        const exportEntry = await buildDocumentTemplateRuntimeExportEntryAsync(template, workOrder);
        const payload = buildDocumentTemplateRuntimePdfPayloadFromEntry(exportEntry);
        if (!exportEntry || !payload) {
          throw new Error("PDF payload nije ispravno pripremljen.");
        }

        exportEntries.push({
          sequenceEntry,
          exportEntry,
          payload,
        });
        restorePreviousRuntimeView();
        setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
          status: "pending",
          message: `${workOrderLabel} čeka spremanje u Documents.`,
        }, { render: true });
      } catch (error) {
        failureCount += 1;
        restorePreviousRuntimeView();
        console.error("Ne mogu pripremiti zapisnik za PDF.", error);
        pushExportFailureDetail(sequenceEntry, error, "Ne mogu pripremiti zapisnik za PDF.");
        setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
          status: "error",
          message: error?.message || "Ne mogu pripremiti zapisnik za PDF.",
        }, { render: true });
      }
    }
  } catch (error) {
    console.error("Ne mogu pripremiti batch zapisnike za ispis.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu pripremiti batch zapisnike za ispis.");
    restorePreviousRuntimeView({ render: true });
    loading.close();
    return;
  }

  if (exportEntries.length === 0) {
    restorePreviousRuntimeView({ render: true });
    setDocumentTemplateMessage("Nema nijednog pripremljenog zapisnika za PDF.");
    loading.close();
    return;
  }

  try {
    const batchEntries = exportEntries.map(({ sequenceEntry, exportEntry, payload }) => ({
      ...payload,
      templateId: exportEntry.templateId,
      workOrderId: sequenceEntry.workOrderId || exportEntry.workOrderId,
      objectId: sequenceEntry.objectId || "",
      objectSequence: sequenceEntry.objectSequence || 0,
      fileName: exportEntry.pdfFileName,
    }));

    exportEntries.forEach(({ sequenceEntry, exportEntry }, index) => {
      const workOrderLabel = `RN ${sequenceEntry.workOrderNumber || exportEntry.renderModel?.workOrderNumber || index + 1}`;
      setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
        status: "running",
        message: `Spremam DOCX/PDF zapisnik za ${workOrderLabel} u Documents.`,
      }, { render: true });
    });

    const savedItems = [];
    loading.setPhase(2, {
      message: `Pripremam DOCX predloške i brzi PDF batch...`,
      progress: 52,
    });
    const hasWordTemplateEntries = exportEntries.some(({ exportEntry }) => (
      String(exportEntry?.templateReferenceKind || "").trim().toLowerCase() === "word"
    ));
    const handleSavedEntry = async (savedEntry, sequenceEntry, exportEntry, index = 0) => {
      const workOrderLabel = `RN ${sequenceEntry?.workOrderNumber || exportEntry?.renderModel?.workOrderNumber || index + 1}`;
      const rawSavedDocuments = Array.isArray(savedEntry?.documents) && savedEntry.documents.length > 0
        ? savedEntry.documents
        : [savedEntry?.item].filter(Boolean);
      const savedDocuments = rawSavedDocuments
        .filter((item) => item && typeof item === "object" && String(item.id || "").trim());
      const primaryDocument = savedEntry?.item
        || savedDocuments.find((item) => String(item?.fileExtension || "").toLowerCase() === "pdf")
        || savedDocuments[0]
        || null;

      if (!primaryDocument) {
        throw new Error("Server nije vratio spremljeni zapisnik.");
      }
      savedItems.push({
        ...savedEntry,
        item: primaryDocument,
        documents: savedDocuments,
      });

      try {
        upsertDocumentsExplorerWorkOrderDocuments(savedDocuments);
        if (savedEntry?.record) {
          upsertDocumentsExplorerRecord(savedEntry.record);
        }
        renderNotifications();
      } catch (syncError) {
        console.warn("Zapisnik je spremljen, ali lokalni prikaz Documentsa nije odmah osvježen.", syncError);
      }

      const savedTypes = new Set(savedDocuments.map((item) => String(item?.fileExtension || "").toLowerCase()));
      const savedLabel = savedTypes.has("docx") && savedTypes.has("pdf") ? "DOCX i PDF" : "PDF";
      try {
        await persistDocumentTemplateRuntimeServiceProgress(
          getDocumentTemplateRuntimeWorkOrderById(sequenceEntry?.workOrderId) || { id: sequenceEntry?.workOrderId },
          getDocumentTemplateById(sequenceEntry?.templateId || exportEntry?.templateId),
          "completed",
        );
      } catch (progressError) {
        console.warn("Zapisnik je spremljen, ali status usluge nije automatski ažuriran.", progressError);
      }

      try {
        setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
          status: "done",
          message: `${workOrderLabel}: spremljen ${savedLabel} u Documents.`,
          document: primaryDocument,
          documents: savedDocuments,
        }, { render: true });
      } catch (statusError) {
        console.warn("Zapisnik je spremljen, ali status prikaza nije odmah osvježen.", statusError);
      }
    };

    loading.setPhase(2, {
      message: hasWordTemplateEntries
        ? "Spremam zapisnike u malim paketima da LibreOffice ostane stabilan..."
        : "Spremam zapisnike u malim paketima za brži Documents upload...",
      progress: 52,
    });

    const retryableExportStatusCodes = new Set([502, 503, 504]);
    const exportRetryDelays = [2000, 4000, 7000, 10000, 15000, 20000, 25000, 30000, 30000];
    const isRetryableExportError = (error = null) => {
      const message = String(error?.message || "");
      return retryableExportStatusCodes.has(Number(error?.statusCode))
        || /no_healthy_upstream|upstream_reset|connection_termination|failed to forward|networkerror|failed to fetch/i.test(message);
    };
    const waitBeforeRetry = (attemptIndex = 0) => new Promise((resolve) => {
      window.setTimeout(resolve, exportRetryDelays[Math.min(attemptIndex, exportRetryDelays.length - 1)]);
    });
    const postExportPdfDocumentsWithRetry = async (chunkEntries, chunkStartIndex, label = "") => {
      const maxAttempts = exportRetryDelays.length + 1;
      for (let attemptIndex = 0; attemptIndex < maxAttempts; attemptIndex += 1) {
        try {
          return await apiRequest("/document-templates/export-pdf-documents", {
            method: "POST",
            body: {
              entries: chunkEntries,
              signatureSettings: getPdfSignatureExportSettings(),
            },
          });
        } catch (error) {
          if (!isRetryableExportError(error) || attemptIndex >= maxAttempts - 1) {
            throw error;
          }
          loading.setPhase(3, {
            message: `Server se upravo vraća online, pokušavam ponovno ${attemptIndex + 2}/${maxAttempts}: ${label || "spremanje zapisnika"}...`,
            progress: Math.min(90, 62 + Math.round(((chunkStartIndex + chunkEntries.length) / batchEntries.length) * 24)),
          });
          await waitBeforeRetry(attemptIndex);
        }
      }
      throw new Error("Spremanje zapisnika nije uspjelo nakon ponovnih pokušaja.");
    };
    const saveBatchChunk = async (chunkEntries, chunkStartIndex, { allowSplit = true } = {}) => {
      const chunkLabel = chunkEntries
        .map((entry, offset) => `RN ${entry?.renderModel?.workOrderNumber || entry?.workOrderNumber || chunkStartIndex + offset + 1}`)
        .join(", ");
      try {
        return await postExportPdfDocumentsWithRetry(chunkEntries, chunkStartIndex, chunkLabel);
      } catch (error) {
        if (allowSplit && chunkEntries.length > 1 && isRetryableExportError(error)) {
          loading.setPhase(3, {
            message: "Server još nije stabilan za veći paket, prebacujem na sigurno pojedinačno spremanje...",
            progress: Math.min(90, 62 + Math.round(((chunkStartIndex + 1) / batchEntries.length) * 24)),
          });
          const splitItems = [];
          const splitFailures = [];
          for (const [offset, singleEntry] of chunkEntries.entries()) {
            try {
              const singleResponse = await saveBatchChunk([singleEntry], chunkStartIndex + offset, { allowSplit: false });
              splitItems.push(...(Array.isArray(singleResponse?.items) ? singleResponse.items : []));
            } catch (singleError) {
              splitFailures.push({ offset, error: singleError });
            }
          }
          if (splitFailures.length > 0) {
            const partialError = new Error("Dio zapisnika iz paketa nije spremljen.");
            partialError.partialItems = splitItems;
            partialError.partialFailures = splitFailures;
            throw partialError;
          }
          return {
            items: splitItems,
            generatedCount: splitItems.length,
          };
        }
        throw error;
      }
    };
    const saveChunkSize = hasWordTemplateEntries ? 2 : 3;

    for (let startIndex = 0; startIndex < batchEntries.length; startIndex += saveChunkSize) {
      const chunkEntries = batchEntries.slice(startIndex, startIndex + saveChunkSize);
      const chunkMetas = exportEntries.slice(startIndex, startIndex + saveChunkSize);
      const chunkLabel = chunkMetas
        .map((meta, offset) => `RN ${meta?.sequenceEntry?.workOrderNumber || meta?.exportEntry?.renderModel?.workOrderNumber || startIndex + offset + 1}`)
        .join(", ");
      const hasWordChunk = chunkMetas.some((meta) => (
        String(meta?.exportEntry?.templateReferenceKind || "").trim().toLowerCase() === "word"
      ));
      loading.setPhase(3, {
        message: `${hasWordChunk ? "LibreOffice" : "PDF engine"} sprema ${Math.min(startIndex + chunkEntries.length, batchEntries.length)}/${batchEntries.length}: ${chunkLabel} u Documents...`,
        progress: Math.min(88, 58 + Math.round(((startIndex + chunkEntries.length) / batchEntries.length) * 26)),
      });

      try {
        const response = await saveBatchChunk(chunkEntries, startIndex);
        const responseItems = Array.isArray(response?.items) ? response.items : [];
        for (const [offset, meta] of chunkMetas.entries()) {
          const sequenceEntry = meta?.sequenceEntry;
          const runtimeExportEntry = meta?.exportEntry;
          const savedEntry = responseItems.find((item) => (
            String(item?.workOrderId || "") === String(sequenceEntry?.workOrderId || "")
            && (!item?.templateId || !runtimeExportEntry?.templateId || String(item.templateId) === String(runtimeExportEntry.templateId))
          )) || responseItems[offset] || null;
          await handleSavedEntry(savedEntry, sequenceEntry, runtimeExportEntry, startIndex + offset);
        }
      } catch (error) {
        const partialItems = Array.isArray(error?.partialItems) ? error.partialItems : [];
        const partialFailures = Array.isArray(error?.partialFailures) ? error.partialFailures : [];
        const handledOffsets = new Set();
        if (partialItems.length > 0) {
          for (const [offset, meta] of chunkMetas.entries()) {
            const sequenceEntry = meta?.sequenceEntry;
            const runtimeExportEntry = meta?.exportEntry;
            const savedEntry = partialItems.find((item) => (
              String(item?.workOrderId || "") === String(sequenceEntry?.workOrderId || "")
              && (!item?.templateId || !runtimeExportEntry?.templateId || String(item.templateId) === String(runtimeExportEntry.templateId))
            )) || null;
            if (savedEntry) {
              handledOffsets.add(offset);
              await handleSavedEntry(savedEntry, sequenceEntry, runtimeExportEntry, startIndex + offset);
            }
          }
        }
        const failureByOffset = new Map(partialFailures.map((entry) => [entry.offset, entry.error]));
        for (const [offset, meta] of chunkMetas.entries()) {
          if (handledOffsets.has(offset)) {
            continue;
          }
          const sequenceEntry = meta?.sequenceEntry;
          const runtimeExportEntry = meta?.exportEntry;
          const workOrderLabel = `RN ${sequenceEntry?.workOrderNumber || runtimeExportEntry?.renderModel?.workOrderNumber || startIndex + offset + 1}`;
          const itemError = failureByOffset.get(offset) || error;
          failureCount += 1;
          console.error(`Ne mogu spremiti zapisnik za ${workOrderLabel}.`, itemError);
          pushExportFailureDetail(sequenceEntry, itemError, `Ne mogu spremiti zapisnik za ${workOrderLabel}.`);
          setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
            status: "error",
            message: itemError?.message || `Ne mogu spremiti zapisnik za ${workOrderLabel}.`,
          }, { render: true });
        }
      }
    }

    loading.setPhase(4, {
      message: "Spremanje u Documents je završilo. Preuzimanje je dostupno po RN-u.",
      progress: 94,
    });
    generatedCount = savedItems.length;

    if (failureCount > 0) {
      const failureDetail = exportFailureDetails.length > 0
        ? ` Detalj: ${exportFailureDetails.slice(0, 3).join(" | ")}`
        : "";
      setDocumentTemplateMessage(
        `${generatedCount} zapisnika je spremljeno u Documents, ${failureCount} nije spremljeno.${failureDetail}`,
      );
    } else {
      loading.complete({
        message: "Gotovo: svi označeni zapisnici su spremljeni u Documents.",
      });
      setDocumentTemplateMessage(
        hasWordTemplateEntries
          ? "Gotovo: svaki označeni RN ima svoj DOCX i PDF zapisnik spremljen u Documents."
          : "Gotovo: svaki označeni RN ima svoj PDF zapisnik spremljen u Documents.",
        { type: "success" },
      );
    }
  } catch (error) {
    console.error("Ne mogu generirati batch PDF zapisnike.", error);
    failureCount += exportEntries.length;
    exportEntries.forEach(({ sequenceEntry }) => {
      pushExportFailureDetail(sequenceEntry, error, "Ne mogu generirati PDF paket.");
      setDocumentTemplateRuntimeExportStatus(sequenceEntry, {
        status: "error",
        message: error?.message || "Ne mogu generirati PDF paket.",
      }, { render: true });
    });
    setDocumentTemplateMessage(error?.message || "Ne mogu generirati batch PDF zapisnike.");
  } finally {
    restorePreviousRuntimeView({ render: true });
    saveDocumentTemplateRuntimeLocalDraft({ syncButton: true });
    window.setTimeout(() => {
      loading.close();
    }, 320);
  }
}

async function downloadDocumentTemplateSavedPdfDocument(documentItem = {}) {
  const workOrderId = String(documentItem?.workOrderId || "").trim();
  const documentId = String(documentItem?.id || "").trim();

  if (!workOrderId || !documentId) {
    if (documentItem?.dataUrl || documentItem?.storageUrl) {
      triggerModuleAttachmentDownload(documentItem);
      return true;
    }
    setDocumentTemplateMessage("Spremljeni PDF nema dovoljno podataka za preuzimanje.");
    return false;
  }

  try {
    const response = await apiBinaryRequest(
      `/work-orders/${encodeURIComponent(workOrderId)}/documents/${encodeURIComponent(documentId)}/download`,
      { method: "GET" },
    );
    triggerBlobDownload(response.blob, response.fileName || documentItem.fileName || "zapisnik.pdf");
    return true;
  } catch (error) {
    console.error("Ne mogu preuzeti spremljeni zapisnik.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu preuzeti spremljeni zapisnik.");
    return false;
  }
}

async function queueDocumentTemplateForDigitalSignature() {
  const template = buildDocumentTemplateDraft();
  const workOrder = getDocumentTemplateRuntimeActiveWorkOrder();
  if (!isDocumentTemplateRuntimeFillMode() || !workOrder) {
    setDocumentTemplateMessage("Prvo otvori aktivni zapisnik za digitalni potpis.");
    return;
  }

  try {
    await persistActiveDocumentTemplateRuntimeRecord();
  } catch (error) {
    console.error("Ne mogu spremiti zapisnik prije digitalnog potpisa.", error);
    setDocumentTemplateMessage(error?.message || "Ne mogu pripremiti zapisnik za digitalni potpis.");
    return;
  }

  const signers = getDocumentTemplateRuntimeSignatureEntriesFor(template, workOrder);
  if (signers.length === 0) {
    setDocumentTemplateMessage("Nema odabranih potpisnika za digitalni potpis.");
    return;
  }

  const signerLabel = signers
    .map((entry) => [String(entry.name || "").trim(), String(entry.role || "").trim()].filter(Boolean).join(" · "))
    .filter(Boolean)
    .join(", ");

  setDocumentTemplateMessage(
    `Zapisnik je pripremljen za digitalni potpis. Potpisnici: ${signerLabel}. Ovaj korak sada koristi rezervirane slotove i spreman je za buduću Java/Fina/eOI integraciju.`,
    { type: "success" },
  );
}

function getCheckedValues(container, inputName) {
  return Array.from(container?.querySelectorAll(`input[name="${inputName}"]:checked`) ?? [])
    .map((input) => String(input.value || "").trim())
    .filter(Boolean);
}

function getTemplateTitlesByIds(ids = []) {
  return (ids ?? [])
    .map((templateId) => state.documentTemplates.find((item) => String(item.id) === String(templateId))?.title ?? "")
    .filter(Boolean);
}

function getServiceCatalogItemsByIds(ids = [], { organizationId = "" } = {}) {
  const normalizedOrganizationId = String(organizationId || "").trim();
  const servicesById = new Map(
    (state.serviceCatalog ?? [])
      .filter((item) => !normalizedOrganizationId || String(item.organizationId) === normalizedOrganizationId)
      .map((item) => [String(item.id), item]),
  );

  return Array.from(new Set(
    (ids ?? [])
      .map((value) => String(value ?? "").trim())
      .filter(Boolean),
  ))
    .map((serviceId) => servicesById.get(String(serviceId)) ?? null)
    .filter(Boolean);
}

function getServiceCatalogTitlesByIds(ids = [], { organizationId = "" } = {}) {
  return getServiceCatalogItemsByIds(ids, { organizationId })
    .map((item) => String(item?.name || item?.serviceCode || "Usluga").trim())
    .filter(Boolean);
}

function getUserQualificationServiceCatalogOptions(selectedIds = [], { organizationId = "" } = {}) {
  const normalizedSelectedIds = normalizeUserQualificationServiceIds(selectedIds);
  const selectedSet = new Set(normalizedSelectedIds);
  const normalizedOrganizationId = String(organizationId || state.activeOrganizationId || "").trim();
  const services = sortServiceCatalogItems((state.serviceCatalog ?? []).filter((item) => {
    const serviceId = String(item?.id || "").trim();
    if (!serviceId) {
      return false;
    }
    const serviceOrganizationId = String(item?.organizationId || "").trim();
    const isSelected = selectedSet.has(serviceId);
    const isSameOrganization = !normalizedOrganizationId || !serviceOrganizationId || serviceOrganizationId === normalizedOrganizationId;
    const isInactive = String(item?.status || "active").trim().toLowerCase() === "inactive";
    return isSelected || (isSameOrganization && !isInactive);
  }));
  const knownIds = new Set(services.map((item) => String(item?.id || "").trim()).filter(Boolean));
  const missingSelectedServices = normalizedSelectedIds
    .filter((serviceId) => !knownIds.has(serviceId))
    .map((serviceId) => ({
      id: serviceId,
      name: serviceId,
      serviceCode: "",
      status: "active",
      serviceType: "other",
      isMissingReference: true,
    }));
  return [...services, ...missingSelectedServices];
}

function renderUserQualificationServiceChecklist(container, {
  selectedIds = [],
  inputName = "user-qualification-service-id",
  organizationId = "",
  emptyText = "Prvo dodaj usluge u List Of Services pa ih ovdje poveži.",
} = {}) {
  if (!container) {
    return;
  }

  const selectedSet = new Set(normalizeUserQualificationServiceIds(selectedIds));
  const services = getUserQualificationServiceCatalogOptions(selectedIds, { organizationId });
  const canManagePeople = getCanManagePeople();
  if (services.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy user-qualification-service-empty";
    empty.textContent = emptyText;
    container.replaceChildren(empty);
    return;
  }

  container.replaceChildren(...services.map((service) => {
    const serviceId = String(service?.id || "").trim();
    const label = document.createElement("label");
    label.className = "service-catalog-template-option user-qualification-service-option";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.name = inputName;
    checkbox.value = serviceId;
    checkbox.checked = selectedSet.has(serviceId);
    checkbox.disabled = !canManagePeople;
    checkbox.dataset.userQualificationServiceId = serviceId;

    const copy = document.createElement("div");
    copy.className = "service-catalog-template-option-copy";

    const title = document.createElement("strong");
    title.textContent = service.name || service.serviceCode || "Usluga";

    const meta = document.createElement("span");
    meta.textContent = [
      service.serviceCode || "",
      service.isMissingReference ? "Nije u aktivnom katalogu" : getServiceCatalogTypeLabel(service.serviceType || (service.isTraining ? "znr" : "inspection")),
      service.isMissingReference ? "" : getOptionLabel(SERVICE_CATALOG_STATUS_OPTIONS, service.status || "active"),
    ].filter(Boolean).join(" | ");

    copy.append(title, meta);
    label.append(checkbox, copy);
    return label;
  }));
}

function getLinkedServiceCatalogIdsForItem(item = {}, { legacyTemplateIds = [], organizationId = "" } = {}) {
  const normalizedOrganizationId = String(organizationId || item?.organizationId || "").trim();
  const explicitIds = Array.isArray(item?.linkedServiceCatalogIds)
    ? item.linkedServiceCatalogIds.map((value) => String(value ?? "").trim()).filter(Boolean)
    : [];
  const explicitServices = getServiceCatalogItemsByIds(explicitIds, { organizationId: normalizedOrganizationId });

  if (explicitServices.length > 0 || explicitIds.length > 0) {
    return explicitServices.map((service) => String(service.id || "").trim()).filter(Boolean);
  }

  const templateIdSet = new Set(
    (legacyTemplateIds ?? [])
      .map((value) => String(value ?? "").trim())
      .filter(Boolean),
  );

  if (templateIdSet.size === 0) {
    return [];
  }

  return sortServiceCatalogItems((state.serviceCatalog ?? []).filter((service) => (
    (!normalizedOrganizationId || String(service.organizationId) === normalizedOrganizationId)
    && (service.linkedTemplateIds ?? []).some((templateId) => templateIdSet.has(String(templateId)))
  ))).map((service) => String(service.id || "").trim()).filter(Boolean);
}

function getLinkedServiceCatalogTitlesForItem(item = {}, options = {}) {
  const serviceIds = getLinkedServiceCatalogIdsForItem(item, options);
  return getServiceCatalogTitlesByIds(serviceIds, {
    organizationId: options.organizationId || item?.organizationId || "",
  });
}

function renderServiceCatalogUsageChecklist(container, {
  selectedIds = [],
  inputName = "service-catalog-usage-id",
  emptyText = "Prvo dodaj usluge u List Of Services pa ih ovdje poveži.",
} = {}) {
  if (!container) {
    return;
  }

  const canManageMasterData = getCanManageSafetyAuthorizations();
  const selectedSet = new Set(selectedIds.map((value) => String(value)));
  const services = sortServiceCatalogItems((state.serviceCatalog ?? []).filter((item) => (
    String(item.serviceType || (item.isTraining ? "znr" : "inspection")) === "inspection"
    && (!state.activeOrganizationId || String(item.organizationId) === String(state.activeOrganizationId))
  )));

  if (services.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = emptyText;
    container.replaceChildren(empty);
    return;
  }

  container.replaceChildren(...services.map((service) => {
    const label = document.createElement("label");
    label.className = "service-catalog-template-option";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.name = inputName;
    checkbox.value = service.id;
    checkbox.checked = selectedSet.has(String(service.id));
    checkbox.disabled = !canManageMasterData;

    const copy = document.createElement("div");
    copy.className = "service-catalog-template-option-copy";

    const title = document.createElement("strong");
    title.textContent = service.name || service.serviceCode || "Usluga";

    const meta = document.createElement("span");
    meta.textContent = [
      service.serviceCode || "",
      getOptionLabel(SERVICE_CATALOG_STATUS_OPTIONS, service.status || "active"),
      (service.linkedTemplateTitles ?? []).length > 0 ? `${(service.linkedTemplateTitles ?? []).length} zapisnika` : "Bez zapisnika",
    ].filter(Boolean).join(" | ");

    copy.append(title, meta);
    label.append(checkbox, copy);
    return label;
  }));
}

function getLegalFrameworkLinkedTemplateIds(item = {}) {
  if (Array.isArray(item?.linkedTemplateIds) && item.linkedTemplateIds.length > 0) {
    return item.linkedTemplateIds.map((value) => String(value ?? "").trim()).filter(Boolean);
  }

  if (!item?.id) {
    return [];
  }

  return sortDocumentTemplates(state.documentTemplates ?? [])
    .filter((template) => (template.selectedLegalFrameworkIds ?? []).some((entryId) => String(entryId) === String(item.id)))
    .map((template) => String(template.id))
    .filter(Boolean);
}

function getLegalFrameworkLinkedTemplateTitles(item = {}) {
  if (Array.isArray(item?.linkedTemplateTitles) && item.linkedTemplateTitles.length > 0) {
    return item.linkedTemplateTitles.map((value) => String(value ?? "").trim()).filter(Boolean);
  }

  return getTemplateTitlesByIds(getLegalFrameworkLinkedTemplateIds(item));
}

function getLegalFrameworkLinkedServiceIds(item = {}) {
  return getLinkedServiceCatalogIdsForItem(item, {
    legacyTemplateIds: getLegalFrameworkLinkedTemplateIds(item),
    organizationId: item?.organizationId || state.activeOrganizationId || "",
  });
}

function getLegalFrameworkLinkedServiceTitles(item = {}) {
  return getLinkedServiceCatalogTitlesForItem(item, {
    legacyTemplateIds: getLegalFrameworkLinkedTemplateIds(item),
    organizationId: item?.organizationId || state.activeOrganizationId || "",
  });
}

function isLegalFrameworkDocumentFileAllowed(file) {
  const fileName = String(file?.name || "").trim().toLowerCase();
  const fileType = String(file?.type || "").trim().toLowerCase();
  return fileName.endsWith(".pdf") || fileType.includes("pdf");
}

function formatLegalFrameworkDocumentCountLabel(count = 0) {
  const safeCount = Math.max(0, Number(count) || 0);

  if (safeCount === 1) {
    return "1 PDF dokument";
  }

  if (safeCount >= 2 && safeCount <= 4) {
    return `${safeCount} PDF dokumenta`;
  }

  return `${safeCount} PDF dokumenata`;
}

function formatLegalFrameworkTemplateCountLabel(count = 0) {
  const safeCount = Math.max(0, Number(count) || 0);

  if (safeCount === 0) {
    return "Bez povezanih usluga";
  }

  if (safeCount === 1) {
    return "1 povezana usluga";
  }

  if (safeCount >= 2 && safeCount <= 4) {
    return `${safeCount} povezane usluge`;
  }

  return `${safeCount} povezanih usluga`;
}

function setLegalFrameworkDocumentDrafts(items = []) {
  legalFrameworkDocumentDrafts = (Array.isArray(items) ? items : [])
    .map((item) => createModuleAttachmentDraft({
      ...item,
      documentCategory: item?.documentCategory || "pdf",
    }))
    .filter((item) => item.fileName && (item.dataUrl || item.storageUrl));
}

function createLegalFrameworkCardDocumentActions(item = {}) {
  const documents = (Array.isArray(item.documents) ? item.documents : [])
    .map((entry) => createModuleAttachmentDraft(entry))
    .filter((entry) => entry.fileName && (entry.dataUrl || entry.storageUrl));

  if (documents.length === 0) {
    return null;
  }

  const actions = document.createElement("div");
  actions.className = "legal-framework-card-actions";

  documents.slice(0, 3).forEach((entry) => {
    const downloadButton = createIconActionButton(
      `Preuzmi ${entry.fileName || "PDF dokument"}`,
      "download",
      "",
      (event) => {
        event.preventDefault();
        event.stopPropagation();
        triggerModuleAttachmentDownload(entry);
      },
    );
    downloadButton.classList.add("legal-framework-card-download-button");
    actions.append(downloadButton);
  });

  if (documents.length > 3) {
    actions.append(createBadge(`+${documents.length - 3}`, "legal-framework-meta-badge"));
  }

  return actions;
}

function renderLegalFrameworkDocuments() {
  if (!legalFrameworkDocumentsList) {
    return;
  }

  if (legalFrameworkDocumentDrafts.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Još nema dodanih PDF dokumenata za ovaj propis.";
    legalFrameworkDocumentsList.replaceChildren(empty);
    return;
  }

  legalFrameworkDocumentsList.replaceChildren(...legalFrameworkDocumentDrafts.map((entry) => {
    const row = document.createElement("article");
    row.className = "module-attachment-row legal-framework-document-row";

    const copy = document.createElement("div");
    copy.className = "module-attachment-copy";

    const title = document.createElement("strong");
    title.textContent = entry.fileName || "PDF dokument";

    const meta = document.createElement("span");
    meta.textContent = [
      "PDF",
      formatFileSize(entry.fileSize),
      entry.updatedAt ? formatCompactDateTime(entry.updatedAt) : "",
    ].filter(Boolean).join(" | ");

    copy.append(title, meta);

    if (entry.description) {
      const description = document.createElement("p");
      description.className = "module-attachment-description";
      description.textContent = entry.description;
      copy.append(description);
    }

    const actions = document.createElement("div");
    actions.className = "module-attachment-actions";
    actions.append(
      createIconActionButton("Preuzmi PDF", "download", "", () => {
        triggerModuleAttachmentDownload(entry);
      }),
      createIconActionButton("Makni PDF", "trash", "card-danger", () => {
        legalFrameworkDocumentDrafts = legalFrameworkDocumentDrafts.filter((item) => String(item.id) !== String(entry.id));
        renderLegalFrameworkDocuments();
      }),
    );

    row.append(copy, actions);
    return row;
  }));
}

async function queueLegalFrameworkDocuments(files) {
  const uploadFiles = Array.from(files ?? []).filter((file) => file instanceof File);

  if (!uploadFiles.length) {
    return;
  }

  for (const file of uploadFiles) {
    if (!isLegalFrameworkDocumentFileAllowed(file)) {
      throw new Error(`Format ${file.name} nije podrzan. Dozvoljen je samo PDF.`);
    }

    if (file.size > WORK_ORDER_DOCUMENT_MAX_SIZE_BYTES) {
      throw new Error(`Datoteka ${file.name} mora biti manja od 12 MB.`);
    }
  }

  const nextDocuments = await Promise.all(uploadFiles.map(async (file) => createModuleAttachmentDraft({
    fileName: file.name,
    fileType: file.type || "application/pdf",
    fileSize: file.size || 0,
    documentCategory: "pdf",
    dataUrl: await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`),
    updatedAt: new Date().toISOString(),
  })));

  legalFrameworkDocumentDrafts = [
    ...legalFrameworkDocumentDrafts,
    ...nextDocuments,
  ];
  renderLegalFrameworkDocuments();
}

function renderTemplateSelectionChecklist(
  container,
  {
    selectedIds = [],
    inputName = "linked-template-id",
    emptyText = "Prvo dodaj templatee u Template Development.",
  } = {},
) {
  if (!container) {
    return;
  }

  const selectedSet = new Set((selectedIds ?? []).map((value) => String(value)));
  const templates = sortDocumentTemplates(state.documentTemplates ?? []);

  if (templates.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = emptyText;
    container.replaceChildren(empty);
    return;
  }

  container.replaceChildren(...templates.map((template) => {
    const label = document.createElement("label");
    label.className = "service-catalog-template-option";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.name = inputName;
    checkbox.value = String(template.id);
    checkbox.checked = selectedSet.has(String(template.id));

    const copy = document.createElement("div");
    copy.className = "service-catalog-template-option-copy";

    const title = document.createElement("strong");
    title.textContent = template.title || "Template";

    const meta = document.createElement("span");
    meta.textContent = [
      getDocumentTemplateTypeLabel(template.documentType),
      getDocumentTemplateStatusLabel(template.status),
      template.referenceDocument?.fileName ? `${getDocumentTemplateReferenceLabel(template.referenceDocument)} ref` : "",
    ].filter(Boolean).join(" | ");

    copy.append(title, meta);
    label.append(checkbox, copy);
    return label;
  }));
}

function createModuleAttachmentDraft(document = {}) {
  const documentCategory = String(document.documentCategory || document.category || "").trim();
  return {
    id: String(document.id || crypto.randomUUID()),
    fileName: String(document.fileName || "").trim(),
    fileType: String(document.fileType || "").trim(),
    fileSize: Number(document.fileSize || 0) || 0,
    documentCategory,
    sourceDocumentId: String(document.sourceDocumentId || document.parentDocumentId || "").trim(),
    previewStatus: String(document.previewStatus || "").trim(),
    previewError: String(document.previewError || "").trim(),
    documentCategoryLocked: Boolean(document.documentCategoryLocked) || (Boolean(document.isPersisted || document.persisted) && Boolean(documentCategory)),
    description: String(document.description || "").trim(),
    dataUrl: String(document.dataUrl || document.storageUrl || "").trim(),
    storageProvider: String(document.storageProvider || "").trim(),
    storageBucket: String(document.storageBucket || "").trim(),
    storageKey: String(document.storageKey || "").trim(),
    storageUrl: String(document.storageUrl || document.dataUrl || "").trim(),
    createdAt: String(document.createdAt || new Date().toISOString()),
    updatedAt: String(document.updatedAt || document.createdAt || new Date().toISOString()),
  };
}

function normalizeDocumentTemplateMediaFieldValue(value = null) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  const draft = createModuleAttachmentDraft(value);
  return draft.fileName && (draft.dataUrl || draft.storageUrl) ? draft : null;
}

function getDocumentTemplateMediaFieldSummary(value = null, field = {}) {
  const mediaValue = normalizeDocumentTemplateMediaFieldValue(value);
  if (!mediaValue) {
    return `Nema dodane datoteke za ${getDocumentTemplateMediaFieldKindLabel(field?.type)}.`;
  }

  return [
    mediaValue.fileName,
    mediaValue.fileType || "",
    formatFileSize(mediaValue.fileSize),
  ].filter(Boolean).join(" · ");
}

function getDocumentTemplateMediaFieldPreviewUrl(value = null) {
  const mediaValue = normalizeDocumentTemplateMediaFieldValue(value);
  if (!mediaValue) {
    return "";
  }

  return String(mediaValue.storageUrl || mediaValue.dataUrl || "").trim();
}

async function createDocumentTemplateMediaDraftFromFile(file, field = {}) {
  if (!isDocumentTemplateMediaFileAllowed(field?.type, file)) {
    throw new Error(`${getDocumentTemplateMediaFieldKindLabel(field?.type)} prihvaća samo podržane slike${String(field?.type || "").trim().toLowerCase() === "sketch_upload" ? " ili PDF skicu" : ""}.`);
  }

  const dataUrl = await readFileAsDataUrl(file, "Ne mogu učitati datoteku.");
  return createModuleAttachmentDraft({
    fileName: file.name,
    fileType: file.type || "application/octet-stream",
    fileSize: file.size || 0,
    documentCategory: getDocumentTemplateMediaFieldKindLabel(field?.type),
    dataUrl,
    updatedAt: new Date().toISOString(),
  });
}

function getUserElectricalQualification(user = {}, signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const rootQualification = user?.electricalQualification ?? {};
  const qualification = normalizedArea === "elektro"
    ? rootQualification
    : rootQualification?.additionalAreas?.[normalizedArea] ?? {};
  const inheritedSignatureDataUrl = String(
    rootQualification.signatureDataUrl
    || rootQualification.signatureStorageUrl
    || rootQualification.storageUrl
    || "",
  ).trim();
  const serviceIds = getQualificationServiceIdsForArea(normalizedArea, qualification, {
    organizationId: user?.organizationId || state.activeOrganizationId || "",
  });
  return {
    discipline: String(qualification.discipline || normalizedArea || "elektro").trim().toLowerCase() || "elektro",
    examTitle: String(qualification.examTitle || qualification.title || "").trim(),
    type: String(qualification.examType || qualification.type || qualification.equipmentType || qualification.kind || "").trim(),
    examType: String(qualification.examType || qualification.type || qualification.equipmentType || qualification.kind || "").trim(),
    canInspect: Boolean(qualification.canInspect),
    canAuthorize: Boolean(qualification.canAuthorize),
    canResponsible: Boolean(qualification.canResponsible || qualification.canBeResponsible),
    data1: String(qualification.data1 || qualification.classCode || "").trim(),
    data2: String(qualification.data2 || qualification.urbroj || "").trim(),
    data3: String(qualification.data3 || qualification.eBroj || "").trim(),
    classCode: String(qualification.data1 || qualification.classCode || "").trim(),
    urbroj: String(qualification.data2 || qualification.urbroj || "").trim(),
    eBroj: String(qualification.data3 || qualification.eBroj || "").trim(),
    passedOn: String(qualification.passedOn || qualification.examDate || "").trim(),
    validUntil: String(qualification.validUntil || "").trim(),
    validForever: Boolean(qualification.validForever),
    specialRoles: normalizeQualificationSpecialRoles(qualification.specialRoles),
    serviceIds,
    linkedServiceCatalogIds: serviceIds,
    linkedServiceCatalogTitles: getServiceCatalogTitlesByIds(serviceIds, {
      organizationId: user?.organizationId || state.activeOrganizationId || "",
    }),
    signatureDataUrl: String(
      qualification.signatureDataUrl
      || qualification.signatureStorageUrl
      || inheritedSignatureDataUrl
      || qualification.storageUrl
      || "",
    ).trim(),
    signatureStorageProvider: String(qualification.signatureStorageProvider || "").trim(),
    signatureStorageBucket: String(qualification.signatureStorageBucket || "").trim(),
    signatureStorageKey: String(qualification.signatureStorageKey || "").trim(),
    signatureStorageUrl: String(qualification.signatureStorageUrl || "").trim(),
    documents: Array.isArray(qualification.documents) ? qualification.documents : [],
  };
}

function getUserQualificationAreaDefinitions(user = null) {
  const definitions = new Map(getQualificationExamDefinitions().map((definition) => [definition.key, definition]));
  Object.keys(user?.electricalQualification?.additionalAreas || {}).forEach((area) => {
    const key = normalizeQualificationAreaKey(area);
    if (!key || definitions.has(key)) {
      return;
    }
    definitions.set(key, {
      key,
      title: getSignatureAreaLabel(key),
      label: getSignatureAreaLabel(key),
      specialRoleOptions: [],
    });
  });
  return Array.from(definitions.values());
}

function getUserQualificationInput(area = "", field = "") {
  if (!userQualificationAreasContainer) {
    return null;
  }
  const areaKey = normalizeQualificationAreaKey(area);
  return userQualificationAreasContainer.querySelector(
    `[data-user-qualification-area="${CSS.escape(areaKey)}"] [data-user-qualification-field="${CSS.escape(field)}"]`,
  );
}

function getUserQualificationSpecialRoleInputs(area = "") {
  if (!userQualificationAreasContainer) {
    return [];
  }
  const areaKey = normalizeQualificationAreaKey(area);
  return Array.from(userQualificationAreasContainer.querySelectorAll(
    `[data-user-qualification-area="${CSS.escape(areaKey)}"] [data-user-qualification-special-role]`,
  ));
}

function getUserQualificationServiceInputs(area = "") {
  if (!userQualificationAreasContainer) {
    return [];
  }
  const areaKey = normalizeQualificationAreaKey(area);
  return Array.from(userQualificationAreasContainer.querySelectorAll(
    `[data-user-qualification-area="${CSS.escape(areaKey)}"] [data-user-qualification-service-id]`,
  ));
}

function readUserQualificationAreaPayload(definition = {}) {
  const area = normalizeQualificationAreaKey(definition.key || "elektro");
  const validForever = Boolean(getUserQualificationInput(area, "validForever")?.checked);
  const currentRecord = getCurrentUserEditorRecord() || {};
  const currentRootQualification = currentRecord?.electricalQualification ?? {};
  const currentQualification = area === "elektro"
    ? currentRootQualification
    : currentRootQualification?.additionalAreas?.[area] ?? {};
  const existingServiceIds = getQualificationLinkedServiceIds(currentQualification);
  const specialRoles = Object.fromEntries(
    getUserQualificationSpecialRoleInputs(area).map((input) => [
      String(input.dataset.userQualificationSpecialRole || "").trim(),
      Boolean(input.checked),
    ]).filter(([key]) => key),
  );
  const specialRoleOptions = Array.isArray(definition.specialRoleOptions) ? definition.specialRoleOptions : [];
  const hasSpecialCapability = (capability) => specialRoleOptions.some((option) => (
    option.capability === capability && specialRoles[option.key]
  ));
  const examType = String(getUserQualificationInput(area, "type")?.value || "").trim();
  const data1 = String(getUserQualificationInput(area, "data1")?.value || "").trim();
  const data2 = String(getUserQualificationInput(area, "data2")?.value || "").trim();
  const data3 = String(getUserQualificationInput(area, "data3")?.value || "").trim();
  return {
    discipline: area,
    examTitle: String(definition.title || definition.label || area).trim(),
    type: examType,
    examType,
    canInspect: Boolean(getUserQualificationInput(area, "canInspect")?.checked || hasSpecialCapability("inspect")),
    canAuthorize: Boolean(getUserQualificationInput(area, "canAuthorize")?.checked || hasSpecialCapability("authorize")),
    canResponsible: Boolean(getUserQualificationInput(area, "canResponsible")?.checked || hasSpecialCapability("responsible")),
    data1,
    data2,
    data3,
    classCode: data1,
    urbroj: data2,
    eBroj: data3,
    passedOn: normalizePeopleTrainingDate(getUserQualificationInput(area, "passedOn")?.value || ""),
    validUntil: validForever ? "" : normalizePeopleTrainingDate(getUserQualificationInput(area, "validUntil")?.value || ""),
    validForever,
    specialRoles,
    serviceIds: existingServiceIds,
    linkedServiceCatalogIds: existingServiceIds,
  };
}

function createUserQualificationField(labelText = "", control, fieldName = "") {
  const field = document.createElement("label");
  field.className = "field";
  if (fieldName) {
    field.classList.add(`user-qualification-field-${fieldName}`);
  }
  const label = document.createElement("span");
  label.textContent = labelText;
  if (fieldName) {
    control.dataset.userQualificationField = fieldName;
  }
  field.append(label, control);
  return field;
}

function createUserQualificationCheckbox(labelText = "", checked = false, fieldName = "") {
  const label = document.createElement("label");
  label.className = "checkbox-field user-qualification-checkbox";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = Boolean(checked);
  if (fieldName) {
    input.dataset.userQualificationField = fieldName;
  }
  const copy = document.createElement("span");
  copy.textContent = labelText;
  label.append(input, copy);
  return label;
}

function createUserQualificationDateInput(value = "") {
  const input = document.createElement("input");
  input.type = "text";
  input.inputMode = "numeric";
  input.maxLength = 10;
  input.placeholder = "dd.mm.yyyy";
  input.value = formatDateInputDisplayValue(normalizePeopleTrainingDate(value));
  input.addEventListener("input", () => {
    input.value = normalizeLiveDateTypingValue(input.value);
  });
  input.addEventListener("blur", () => {
    const normalizedValue = normalizePeopleTrainingDate(input.value);
    input.value = normalizedValue ? formatDateInputDisplayValue(normalizedValue) : String(input.value || "").trim();
  });
  return input;
}

function renderUserQualificationAreas(user = getCurrentUserEditorRecord() || {}) {
  if (!userQualificationAreasContainer) {
    return;
  }

  const definitions = getUserQualificationAreaDefinitions(user);
  if (definitions.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Nema definiranih ispita. Dodaj novi ispit u People pa će se nuditi i na drugim osobama.";
    userQualificationAreasContainer.replaceChildren(empty);
    return;
  }

  userQualificationAreasContainer.replaceChildren(...definitions.map((definition) => {
    const area = normalizeQualificationAreaKey(definition.key);
    const qualification = getUserElectricalQualification(user, area);
    const block = document.createElement("section");
    block.className = "service-catalog-template-block user-editor-module user-electrical-qualification-block";
    block.dataset.userManagementScope = "people";
    block.dataset.userQualificationArea = area;

    const heading = document.createElement("div");
    heading.className = "section-heading offers-section-heading";
    const headingCopy = document.createElement("div");
    const kicker = document.createElement("p");
    kicker.className = "section-kicker";
    kicker.textContent = definition.defaultExam ? "Default ispit" : "Ispit";
    const title = document.createElement("h3");
    title.textContent = definition.title || definition.label || area;
    headingCopy.append(kicker, title);
    heading.append(headingCopy);

    const grid = document.createElement("div");
    grid.className = "form-grid user-electrical-grid";

    const typeInput = document.createElement("input");
    typeInput.type = "text";
    typeInput.maxLength = 160;
    typeInput.value = qualification.type || "";
    typeInput.placeholder = "npr. Opći ispit iz zaštite na radu";
    const data1Input = document.createElement("input");
    data1Input.type = "text";
    data1Input.maxLength = 160;
    data1Input.value = qualification.data1 || "";
    const data2Input = document.createElement("input");
    data2Input.type = "text";
    data2Input.maxLength = 160;
    data2Input.value = qualification.data2 || "";
    const data3Input = document.createElement("input");
    data3Input.type = "text";
    data3Input.maxLength = 160;
    data3Input.value = qualification.data3 || "";
    const passedOnInput = createUserQualificationDateInput(qualification.passedOn);
    const validUntilInput = createUserQualificationDateInput(qualification.validUntil);
    const validForeverInput = document.createElement("input");
    validForeverInput.type = "checkbox";
    validForeverInput.checked = Boolean(qualification.validForever);

    const validForeverField = document.createElement("div");
    validForeverField.className = "field qualification-validity-field";
    const validForeverLabel = document.createElement("span");
    validForeverLabel.textContent = "Vrijedi trajno";
    const checkboxLabel = document.createElement("label");
    checkboxLabel.className = "checkbox-field";
    const checkboxCopy = document.createElement("span");
    checkboxCopy.textContent = "Bez isteka";
    validForeverInput.dataset.userQualificationField = "validForever";
    checkboxLabel.append(validForeverInput, checkboxCopy);
    validForeverField.append(validForeverLabel, checkboxLabel);

    validForeverInput.addEventListener("change", () => {
      syncQualificationValidityInput(validUntilInput, validForeverInput);
    });

    const genericRoles = document.createElement("div");
    genericRoles.className = "field field-span-full user-qualification-role-group";
    const genericRoleLabel = document.createElement("span");
    genericRoleLabel.textContent = "Razina osobe";
    const genericRoleOptions = document.createElement("div");
    genericRoleOptions.className = "user-qualification-role-options";
    genericRoleOptions.append(
      createUserQualificationCheckbox("Ispitivač", qualification.canInspect, "canInspect"),
      createUserQualificationCheckbox("Ovlaštena osoba", qualification.canAuthorize, "canAuthorize"),
      createUserQualificationCheckbox("Odgovorna osoba", qualification.canResponsible, "canResponsible"),
    );
    genericRoles.append(genericRoleLabel, genericRoleOptions);

    const specialRoleOptions = Array.isArray(definition.specialRoleOptions) ? definition.specialRoleOptions : [];
    if (specialRoleOptions.length > 0) {
      block.classList.add("has-special-roles");
    }
    const specialRoles = normalizeQualificationSpecialRoles(qualification.specialRoles);
    const specialRoleField = document.createElement("div");
    specialRoleField.className = "field field-span-full user-qualification-role-group is-special";
    const specialRoleLabel = document.createElement("span");
    specialRoleLabel.textContent = "Dodatne razine";
    const specialRoleOptionWrap = document.createElement("div");
    specialRoleOptionWrap.className = "user-qualification-role-options";
    specialRoleOptions.forEach((option) => {
      const optionLabel = createUserQualificationCheckbox(option.label, specialRoles[option.key], "");
      const input = optionLabel.querySelector("input");
      if (input) {
        input.dataset.userQualificationSpecialRole = option.key;
      }
      specialRoleOptionWrap.append(optionLabel);
    });
    specialRoleField.append(specialRoleLabel, specialRoleOptionWrap);

    grid.append(
      genericRoles,
      ...(specialRoleOptions.length > 0 ? [specialRoleField] : []),
      createUserQualificationField("Vrsta ispita", typeInput, "type"),
      createUserQualificationField("Podatak 1", data1Input, "data1"),
      createUserQualificationField("Podatak 2", data2Input, "data2"),
      createUserQualificationField("Podatak 3", data3Input, "data3"),
      createUserQualificationField("Datum polaganja", passedOnInput, "passedOn"),
      createUserQualificationField("Vrijedi do", validUntilInput, "validUntil"),
      validForeverField,
    );

    block.append(heading, grid);
    syncQualificationValidityInput(validUntilInput, validForeverInput);
    return block;
  }));
}

function buildUserElectricalQualificationPayload() {
  const currentRecord = getCurrentUserEditorRecord();
  const definitions = getUserQualificationAreaDefinitions(currentRecord || {});
  const renderedAreas = new Set(definitions.map((definition) => normalizeQualificationAreaKey(definition.key)));
  const rootDefinition = definitions.find((definition) => normalizeQualificationAreaKey(definition.key) === "elektro");
  const currentRoot = getUserElectricalQualification(currentRecord || {}, "elektro");
  const root = {
    ...(rootDefinition ? readUserQualificationAreaPayload(rootDefinition) : currentRoot),
    discipline: "elektro",
    signatureDataUrl: userElectricalSignatureDataUrlInput?.value || "",
    documents: [],
    additionalAreas: {},
  };

  definitions
    .filter((definition) => normalizeQualificationAreaKey(definition.key) !== "elektro")
    .forEach((definition) => {
      const area = normalizeQualificationAreaKey(definition.key);
      root.additionalAreas[area] = readUserQualificationAreaPayload(definition);
    });

  Object.entries(currentRecord?.electricalQualification?.additionalAreas || {}).forEach(([area, value]) => {
    const normalizedArea = normalizeQualificationAreaKey(area);
    if (!normalizedArea || renderedAreas.has(normalizedArea)) {
      return;
    }
    root.additionalAreas[normalizedArea] = value;
  });

  return root;
}

function getQualifiedUsersForSignatureArea(capability = "inspect", signatureArea = "elektro") {
  const normalizedCapability = capability === "authorize" ? "authorize" : "inspect";
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  return (state.users ?? [])
    .filter((user) => Boolean(user?.isActive))
    .filter((user) => {
      const qualification = getUserElectricalQualification(user, normalizedArea);
      if (qualification.discipline !== normalizedArea) {
        return false;
      }

      return normalizedCapability === "authorize"
        ? qualification.canAuthorize
        : qualification.canInspect;
    })
    .sort((left, right) => String(left.fullName || left.email || "").localeCompare(
      String(right.fullName || right.email || ""),
      "hr",
    ));
}

function getQualifiedUserSelectLabel(user = {}, capability = "inspect", signatureArea = "elektro") {
  const qualification = getUserElectricalQualification(user, signatureArea);
  const summaryParts = [
    qualification.type ? `Vrsta ispita ${qualification.type}` : "",
    qualification.data1 ? `Podatak 1 ${qualification.data1}` : "",
    qualification.data2 ? `Podatak 2 ${qualification.data2}` : "",
    qualification.data3 ? `Podatak 3 ${qualification.data3}` : "",
    qualification.passedOn ? `Položeno ${formatCompactDate(qualification.passedOn)}` : "",
  ].filter(Boolean);
  const roleLabel = capability === "authorize" ? "nositelj" : "ispitivač";
  const areaLabel = getSignatureAreaLabel(signatureArea);
  const fallback = `${roleLabel} · ${areaLabel}`;
  return [
    String(user.fullName || user.email || fallback).trim(),
    summaryParts.join(" · "),
  ].filter(Boolean).join(" | ");
}

function getQualifiedUserSelectOptions(capability = "inspect", signatureArea = "elektro") {
  const emptyLabel = capability === "authorize"
    ? "Odaberi nositelja"
    : "Odaberi ispitivača";
  return [
    { value: "", label: emptyLabel },
    ...getQualifiedUsersForSignatureArea(capability, signatureArea).map((user) => ({
      value: String(user.id),
      label: getQualifiedUserSelectLabel(user, capability, signatureArea),
    })),
  ];
}

function getQualifiedUserOptionsForSignatureAreas(
  capability = "inspect",
  signatureAreas = [],
  { includeEmpty = false, emptyLabel = "" } = {},
) {
  const normalizedAreas = Array.from(new Set(
    (Array.isArray(signatureAreas) ? signatureAreas : [signatureAreas])
      .map((area) => normalizeQualificationAreaKey(area))
      .filter(Boolean),
  ));
  const areas = normalizedAreas.length > 0 ? normalizedAreas : ["elektro"];
  const merged = new Map();

  areas.forEach((area) => {
    getQualifiedUsersForSignatureArea(capability, area).forEach((user) => {
      const key = String(user.id);
      const existing = merged.get(key) ?? {
        user,
        areas: new Set(),
      };
      existing.areas.add(area);
      merged.set(key, existing);
    });
  });

  const options = [...merged.values()]
    .sort((left, right) => String(left.user.fullName || left.user.email || "").localeCompare(
      String(right.user.fullName || right.user.email || ""),
      "hr",
    ))
    .map(({ user, areas: userAreas }) => {
      const labels = [...userAreas].map((area) => getSignatureAreaLabel(area));
      return {
        value: String(user.id),
        label: [
          String(user.fullName || user.email || "").trim(),
          labels.join(", "),
        ].filter(Boolean).join(" | "),
      };
    });

  if (!includeEmpty) {
    return options;
  }

  return [
    { value: "", label: emptyLabel || (capability === "authorize" ? "Odaberi nositelja" : "Odaberi ispitivača") },
    ...options,
  ];
}

function findQualifiedUserById(userId = "", capability = "inspect", signatureArea = "elektro") {
  const normalizedId = String(userId || "").trim();
  if (!normalizedId) {
    return null;
  }

  return getQualifiedUsersForSignatureArea(capability, signatureArea)
    .find((user) => String(user.id) === normalizedId) || null;
}

function getQualifiedUserSummaryValue(user = null, capability = "inspect", signatureArea = "elektro") {
  if (!user) {
    const roleLabel = capability === "authorize" ? "Nositelj ovlaštenja" : "Ispitivač";
    return `${roleLabel} (${getSignatureAreaLabel(signatureArea)})`;
  }

  const qualification = getUserElectricalQualification(user, signatureArea);
  return [
    getUserDocumentDisplayName(user),
    qualification.type ? `Vrsta ispita ${qualification.type}` : "",
    qualification.data1 ? `Podatak 1 ${qualification.data1}` : "",
    qualification.data2 ? `Podatak 2 ${qualification.data2}` : "",
    qualification.data3 ? `Podatak 3 ${qualification.data3}` : "",
    qualification.passedOn ? `Položeno ${formatCompactDate(qualification.passedOn)}` : "",
  ].filter(Boolean).join(" | ");
}

function getQualifiedUserDocumentMetaLines(
  user = null,
  capability = "inspect",
  signatureArea = "elektro",
  metaFields = undefined,
) {
  if (!user) {
    return [];
  }

  const qualification = getUserElectricalQualification(user, signatureArea);
  const visibleFields = new Set(normalizeDocumentTemplateSignatureMetaFieldsLocal(metaFields));
  return [
    visibleFields.has("title") && user.title ? String(user.title).trim() : "",
    visibleFields.has("oib") && user.oib ? `OIB ${String(user.oib).trim()}` : "",
    visibleFields.has("type") && qualification.type ? String(qualification.type).trim() : "",
    (visibleFields.has("data1") || visibleFields.has("classCode")) && qualification.data1 ? String(qualification.data1).trim() : "",
    (visibleFields.has("data2") || visibleFields.has("urbroj")) && qualification.data2 ? String(qualification.data2).trim() : "",
    (visibleFields.has("data3") || visibleFields.has("eBroj")) && qualification.data3 ? String(qualification.data3).trim() : "",
    visibleFields.has("passedOn") && qualification.passedOn ? formatCompactDate(qualification.passedOn) : "",
  ].filter(Boolean);
}

function normalizeQualifiedUserIdList(values = []) {
  const source = Array.isArray(values)
    ? values
    : String(values || "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean);

  return Array.from(new Set(source.map((value) => String(value || "").trim()).filter(Boolean)));
}

function getQualifiedUsersByIds(userIds = [], capability = "inspect", signatureArea = "elektro") {
  const normalizedIds = normalizeQualifiedUserIdList(userIds);
  if (normalizedIds.length === 0) {
    return [];
  }

  const eligibleUsers = new Map(
    getQualifiedUsersForSignatureArea(capability, signatureArea)
      .map((user) => [String(user.id), user]),
  );

  return normalizedIds
    .map((id) => eligibleUsers.get(String(id)) || null)
    .filter(Boolean);
}

function resolveQualifiedWorkOrderUsers(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const executorNames = getWorkOrderExecutors(workOrder).map((entry) => normalizePersonLookupValue(entry)).filter(Boolean);
  const eligibleUsers = getQualifiedUsersForSignatureArea(capability, normalizedArea);

  return eligibleUsers.filter((user) => (
    [
      getUserDocumentDisplayName(user),
      user.fullName,
      [user.firstName, user.lastName].filter(Boolean).join(" "),
      user.email,
      user.legacyUsername,
    ].map((value) => normalizePersonLookupValue(value)).filter(Boolean)
      .some((candidate) => executorNames.includes(candidate))
  ));
}

function getWorkOrderDocumentQualifiedUsers(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  const areaSpecificListFieldName = getWorkOrderDocumentSignaturePersonListFieldName(capability, signatureArea);
  const areaSpecificUsers = getQualifiedUsersByIds(
    workOrder?.id && areaSpecificListFieldName
      ? getDocumentTemplateRuntimeArrayValue(workOrder.id, areaSpecificListFieldName)
      : [],
    capability,
    signatureArea,
  );

  if (areaSpecificUsers.length > 0) {
    return areaSpecificUsers;
  }

  const listFieldName = capability === "authorize" ? "authorizationHolderUserIds" : "inspectorUserIds";
  const explicitUsers = getQualifiedUsersByIds(
    workOrder?.id ? getDocumentTemplateRuntimeArrayValue(workOrder.id, listFieldName) : [],
    capability,
    signatureArea,
  );

  if (explicitUsers.length > 0) {
    return explicitUsers;
  }

  const areaSpecificFieldName = getWorkOrderDocumentSignaturePersonFieldName(capability, signatureArea);
  const areaSpecificUserId = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, areaSpecificFieldName) : "";
  const areaSpecificUser = findQualifiedUserById(areaSpecificUserId, capability, signatureArea);
  if (areaSpecificUser) {
    return [areaSpecificUser];
  }

  const singleFieldName = capability === "authorize" ? "authorizationHolderUserId" : "inspectorUserId";
  const explicitSingleUserId = workOrder?.id ? getDocumentTemplateRuntimeValue(workOrder.id, singleFieldName) : "";
  const explicitSingleUser = findQualifiedUserById(explicitSingleUserId, capability, signatureArea);
  if (explicitSingleUser) {
    return [explicitSingleUser];
  }

  return resolveQualifiedWorkOrderUsers(workOrder, capability, signatureArea);
}

function getWorkOrderDocumentQualifiedUser(workOrder = {}, capability = "inspect", signatureArea = "elektro") {
  return getWorkOrderDocumentQualifiedUsers(workOrder, capability, signatureArea)[0]
    || resolveQualifiedWorkOrderUser(workOrder, capability, signatureArea);
}

function getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder = {}) {
  const resolvedServiceItems = getWorkOrderDocumentWizardResolvedServiceItems(workOrder);
  return getWorkOrderRelevantSignatureAreas({
    ...workOrder,
    serviceItems: resolvedServiceItems,
  });
}

function getWorkOrderDocumentWizardRelevantAreasForBatch(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const areas = new Set();
  (Array.isArray(workOrders) ? workOrders : []).forEach((workOrder) => {
    getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder).forEach((area) => areas.add(area));
  });
  return areas.size > 0 ? [...areas] : ["elektro"];
}

function getWorkOrderDocumentSignatureAreaGroupsForAreas(areas = []) {
  const normalizedAreas = Array.from(new Set(
    (Array.isArray(areas) ? areas : [areas])
      .map((area) => normalizeQualificationAreaKey(area))
      .filter(Boolean),
  ));
  const areaList = normalizedAreas.length > 0 ? normalizedAreas : ["elektro"];
  const areaGroups = getWorkOrderDocumentSignatureAreaGroups();
  return areaList.map((area) => (
    areaGroups.find((group) => group.key === area) || {
      key: area,
      title: getSignatureAreaLabel(area),
    }
  ));
}

function findPreferredWorkOrderDocumentWizardPerson(workOrder = {}, capability = "inspect", signatureArea = "elektro", fallbackIds = []) {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const executorMatch = resolveQualifiedWorkOrderUsers(workOrder, capability, normalizedArea)[0] || null;
  if (executorMatch) {
    return executorMatch;
  }

  const fallbackMatch = normalizeQualifiedUserIdList(fallbackIds)
    .map((userId) => findQualifiedUserById(userId, capability, normalizedArea))
    .find(Boolean);
  if (fallbackMatch) {
    return fallbackMatch;
  }

  return getQualifiedUsersForSignatureArea(capability, normalizedArea)[0] || null;
}

function buildWorkOrderDocumentWizardPersonDefaults(workOrder = {}, signatureArea = "elektro") {
  const normalizedArea = normalizeQualificationAreaKey(signatureArea);
  const inspectorFieldName = getWorkOrderDocumentSignaturePersonFieldName("inspect", normalizedArea);
  const inspectorListFieldName = getWorkOrderDocumentSignaturePersonListFieldName("inspect", normalizedArea);
  const authorizationFieldName = getWorkOrderDocumentSignaturePersonFieldName("authorize", normalizedArea);
  const inspectorUsers = resolveQualifiedWorkOrderUsers(workOrder, "inspect", normalizedArea);
  const inspectorIds = normalizeQualifiedUserIdList(inspectorUsers.map((user) => user.id));
  const authorizationUser = findPreferredWorkOrderDocumentWizardPerson(
    workOrder,
    "authorize",
    normalizedArea,
    inspectorIds,
  );
  const patch = {};

  if (inspectorIds.length > 0) {
    if (inspectorListFieldName) {
      patch[inspectorListFieldName] = inspectorIds;
    }
    patch[inspectorFieldName] = inspectorIds[0];
  }

  if (authorizationUser?.id) {
    patch[authorizationFieldName] = String(authorizationUser.id);
  }

  return patch;
}

function ensureWorkOrderDocumentWizardPersonDefaults(workOrders = getAllSelectedWorkOrdersForDocumentWizard()) {
  const selectedWorkOrders = Array.isArray(workOrders) ? workOrders : [];
  if (selectedWorkOrders.length === 0 || state.workOrderDocumentWizard.mode === "znr") {
    return;
  }

  const commonPatch = {};
  getWorkOrderDocumentWizardRelevantAreasForBatch(selectedWorkOrders).forEach((area) => {
    const normalizedArea = normalizeQualificationAreaKey(area);
    const inspectorFieldName = getWorkOrderDocumentSignaturePersonFieldName("inspect", normalizedArea);
    const inspectorListFieldName = getWorkOrderDocumentSignaturePersonListFieldName("inspect", normalizedArea);
    const authorizationFieldName = getWorkOrderDocumentSignaturePersonFieldName("authorize", normalizedArea);
    const commonInspectorIds = inspectorListFieldName
      ? normalizeQualifiedUserIdList(state.workOrderDocumentWizard.common?.[inspectorListFieldName] ?? [])
      : normalizeQualifiedUserIdList([state.workOrderDocumentWizard.common?.[inspectorFieldName] ?? ""]);
    const executorInspectorIds = normalizeQualifiedUserIdList(
      selectedWorkOrders.flatMap((workOrder) => (
        resolveQualifiedWorkOrderUsers(workOrder, "inspect", normalizedArea).map((user) => user.id)
      )),
    );

    if (commonInspectorIds.length === 0 && executorInspectorIds.length > 0) {
      if (inspectorListFieldName) {
        commonPatch[inspectorListFieldName] = executorInspectorIds;
      }
      commonPatch[inspectorFieldName] = executorInspectorIds[0];
    }

    if (!String(state.workOrderDocumentWizard.common?.[authorizationFieldName] ?? "").trim()) {
      const authorizationUser = selectedWorkOrders
        .map((workOrder) => findPreferredWorkOrderDocumentWizardPerson(
          workOrder,
          "authorize",
          normalizedArea,
          executorInspectorIds,
        ))
        .find(Boolean);
      if (authorizationUser?.id) {
        commonPatch[authorizationFieldName] = String(authorizationUser.id);
      }
    }
  });

  if (Object.keys(commonPatch).length > 0) {
    state.workOrderDocumentWizard.common = {
      ...state.workOrderDocumentWizard.common,
      ...commonPatch,
    };
  }

  selectedWorkOrders.forEach((workOrder) => {
    const override = getWorkOrderDocumentWizardOverride(workOrder.id);
    const patch = {};
    getWorkOrderDocumentWizardRelevantAreasForWorkOrder(workOrder).forEach((area) => {
      const defaults = buildWorkOrderDocumentWizardPersonDefaults(workOrder, area);
      Object.entries(defaults).forEach(([fieldName, value]) => {
        if (Object.prototype.hasOwnProperty.call(override, fieldName)) {
          return;
        }
        if (Array.isArray(value)) {
          if (value.length > 0) {
            patch[fieldName] = value;
          }
          return;
        }
        if (String(value || "").trim()) {
          patch[fieldName] = String(value || "").trim();
        }
      });
    });

    if (Object.keys(patch).length > 0) {
      setWorkOrderDocumentWizardOverride(workOrder.id, patch);
    }
  });
}

function getDocumentTemplateRuntimeResolvedServiceItems(workOrder = {}) {
  const normalizedId = String(workOrder?.id || "").trim();
  const record = normalizedId ? getDocumentTemplateRuntimeOverrideRecord(normalizedId) : null;
  if (record && Object.prototype.hasOwnProperty.call(record, "serviceItems")) {
    return getWorkOrderServiceItems({ serviceItems: record.serviceItems });
  }
  return getWorkOrderServiceItems(workOrder);
}

function setDocumentTemplateRuntimeServiceItemCompleted(workOrderId = "", serviceIndex = -1, isCompleted = false, { render = true } = {}) {
  setDocumentTemplateRuntimeServiceItemStatus(workOrderId, serviceIndex, isCompleted ? "completed" : "pending", { render });
}

function setDocumentTemplateRuntimeServiceItemStatus(workOrderId = "", serviceIndex = -1, status = "pending", { render = true } = {}) {
  const normalizedId = String(workOrderId || "").trim();
  const workOrder = getDocumentTemplateRuntimeWorkOrderById(normalizedId);
  if (!normalizedId || !workOrder) {
    return;
  }

  const currentItems = getDocumentTemplateRuntimeResolvedServiceItems(workOrder);
  if (serviceIndex < 0 || serviceIndex >= currentItems.length) {
    return;
  }

  const nextItems = currentItems.map((item, index) => (
    index === serviceIndex
      ? withWorkOrderServiceProgressStatus(item, status)
      : item
  ));

  updateDocumentTemplateRuntimeOverride(normalizedId, { serviceItems: nextItems }, { render: false });
  state.documentTemplateRuntime.exportStatuses = Object.fromEntries(
    Object.entries(getDocumentTemplateRuntimeExportStatusMap())
      .filter(([key]) => !String(key).startsWith(`${normalizedId}::`)),
  );

  if (render) {
    syncDocumentTemplateEditorChrome();
    renderDocumentTemplateRuntimeContext();
    renderDocumentTemplateFieldRows();
    renderDocumentTemplatePreviewContent();
  }
}

function buildDocumentTemplateRuntimeServiceProgressPatch(workOrder = {}, template = null, status = "in_progress") {
  const workOrderId = String(workOrder?.id || "").trim();
  const currentItems = getDocumentTemplateRuntimeResolvedServiceItems(workOrder);
  if (!workOrderId || currentItems.length === 0) {
    return null;
  }

  const normalizedTemplateId = getDocumentTemplateRuntimeTemplateId(template);
  const normalizedTemplateTitle = String(template?.title || "").trim().toLowerCase();
  let matchedCount = 0;
  const nextItems = currentItems.map((service) => {
    const templateIds = getWorkOrderServiceTemplateIds(service).map((value) => String(value || "").trim());
    const templateTitles = getResolvedWorkOrderServiceTemplateTitles(service)
      .map((value) => String(value || "").trim().toLowerCase());
    const matchesTemplate = (
      (normalizedTemplateId && templateIds.includes(normalizedTemplateId))
      || (normalizedTemplateTitle && templateTitles.includes(normalizedTemplateTitle))
      || currentItems.length === 1
    );

    if (!matchesTemplate) {
      return service;
    }

    matchedCount += 1;
    return withWorkOrderServiceProgressStatus(service, status);
  });

  return matchedCount > 0 ? nextItems : null;
}

async function persistDocumentTemplateRuntimeServiceProgress(workOrder = {}, template = null, status = "in_progress") {
  const workOrderId = String(workOrder?.id || "").trim();
  const nextItems = buildDocumentTemplateRuntimeServiceProgressPatch(workOrder, template, status);
  if (!workOrderId || !nextItems) {
    return false;
  }

  updateDocumentTemplateRuntimeOverride(workOrderId, { serviceItems: nextItems }, { render: false });
  const stateItem = state.workOrders.find((item) => String(item.id) === workOrderId);
  if (stateItem) {
    stateItem.serviceItems = nextItems;
    stateItem.serviceLine = getWorkOrderServiceSummary({ serviceItems: nextItems });
  }

  try {
    await apiRequest(`/work-orders/${encodeURIComponent(workOrderId)}`, {
      method: "PATCH",
      body: { serviceItems: nextItems },
    });
    return true;
  } catch (error) {
    console.warn("Ne mogu automatski ažurirati status usluge na RN-u.", error);
    return false;
  }
}

function getDocumentTemplateRuntimeMatchedServiceItems(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const runtimeTemplateId = getDocumentTemplateRuntimeTemplateId(template);
  const normalizedTemplateTitle = String(template?.title || "").trim().toLowerCase();

  return getDocumentTemplateRuntimeResolvedServiceItems(workOrder).filter((service) => {
    const templateIds = getWorkOrderServiceTemplateIds(service).map((value) => String(value || "").trim());
    if (runtimeTemplateId && templateIds.includes(runtimeTemplateId)) {
      return true;
    }

    if (!normalizedTemplateTitle) {
      return false;
    }

    return getResolvedWorkOrderServiceTemplateTitles(service)
      .map((value) => String(value || "").trim().toLowerCase())
      .includes(normalizedTemplateTitle);
  });
}

function getDocumentTemplateRuntimePrimaryServiceItem(workOrder = {}, template = buildDocumentTemplateDraft()) {
  return getDocumentTemplateRuntimeMatchedServiceItems(workOrder, template)[0] ?? null;
}

function getDocumentTemplateRuntimeDocumentNumber(workOrder = {}, template = buildDocumentTemplateDraft()) {
  const workOrderNumber = String(workOrder?.workOrderNumber || "").trim();
  const primaryService = getDocumentTemplateRuntimePrimaryServiceItem(workOrder, template);
  const serviceCode = String(
    primaryService?.serviceCode
    || primaryService?.name
    || template?.title
    || ""
  ).trim();

  const baseNumber = [workOrderNumber, serviceCode].filter(Boolean).join("-");
  const objectSequence = getDocumentTemplateRuntimeSequenceObjectNumber(workOrder, template);
  return objectSequence > 0 && baseNumber ? `${baseNumber}-${objectSequence}` : baseNumber;
}

function formatQualifiedInspectorNameWithTitle(user = {}) {
  const name = String(user?.fullName || user?.email || "").trim();
  const title = String(user?.title || "").trim();
  return [name, title].filter(Boolean).join(", ");
}

function getWorkOrderDocumentOrderedQualifiedInspectors(workOrder = {}) {
  const orderedInspectors = [];
  const seenUserIds = new Set();

  getWorkOrderDocumentSignaturePersonFields()
    .filter((definition) => definition.capability === "inspect")
    .forEach((definition) => {
      getWorkOrderDocumentQualifiedUsers(workOrder, "inspect", definition.signatureArea).forEach((user) => {
        const key = String(user?.id || user?.email || user?.fullName || "").trim();
        if (!key || seenUserIds.has(key)) {
          return;
        }
        seenUserIds.add(key);
        orderedInspectors.push(user);
      });
    });

  return orderedInspectors;
}

function getWorkOrderDocumentQualifiedInspectorNames(workOrder = {}) {
  return getWorkOrderDocumentOrderedQualifiedInspectors(workOrder)
    .map((user) => getUserDocumentDisplayName(user))
    .filter(Boolean)
    .join(", ");
}

function getWorkOrderDocumentQualifiedInspectorsWithTitles(workOrder = {}) {
  return getWorkOrderDocumentOrderedQualifiedInspectors(workOrder)
    .map((user) => formatQualifiedInspectorNameWithTitle(user))
    .filter(Boolean)
    .join(", ");
}

function getQualifiedUserSourcePreviewValue(source, context = {}) {
  const workOrder = context.sampleWorkOrder;
  const normalizedSource = String(source || "").trim().toUpperCase();
  if (!workOrder) {
    return "";
  }

  if (normalizedSource === "QUALIFIED_INSPECTOR_LIST_WITH_TITLES") {
    return getWorkOrderDocumentQualifiedInspectorsWithTitles(workOrder);
  }
  if (normalizedSource === "QUALIFIED_INSPECTOR_LIST_NAMES") {
    return getWorkOrderDocumentQualifiedInspectorNames(workOrder);
  }

  const sourceMap = {
    QUALIFIED_INSPECTOR_NAME: { capability: "inspect", field: "name" },
    QUALIFIED_INSPECTOR_TYPE: { capability: "inspect", field: "type" },
    QUALIFIED_INSPECTOR_DATA_1: { capability: "inspect", field: "data1" },
    QUALIFIED_INSPECTOR_DATA_2: { capability: "inspect", field: "data2" },
    QUALIFIED_INSPECTOR_DATA_3: { capability: "inspect", field: "data3" },
    QUALIFIED_INSPECTOR_PASSED_ON: { capability: "inspect", field: "passedOn" },
    QUALIFIED_INSPECTOR_CLASS_CODE: { capability: "inspect", field: "classCode" },
    QUALIFIED_INSPECTOR_URBROJ: { capability: "inspect", field: "urbroj" },
    QUALIFIED_INSPECTOR_E_BROJ: { capability: "inspect", field: "eBroj" },
    QUALIFIED_INSPECTOR_SUMMARY: { capability: "inspect", field: "summary" },
    QUALIFIED_AUTHORIZATION_HOLDER_NAME: { capability: "authorize", field: "name" },
    QUALIFIED_AUTHORIZATION_HOLDER_TYPE: { capability: "authorize", field: "type" },
    QUALIFIED_AUTHORIZATION_HOLDER_DATA_1: { capability: "authorize", field: "data1" },
    QUALIFIED_AUTHORIZATION_HOLDER_DATA_2: { capability: "authorize", field: "data2" },
    QUALIFIED_AUTHORIZATION_HOLDER_DATA_3: { capability: "authorize", field: "data3" },
    QUALIFIED_AUTHORIZATION_HOLDER_PASSED_ON: { capability: "authorize", field: "passedOn" },
    QUALIFIED_AUTHORIZATION_HOLDER_CLASS_CODE: { capability: "authorize", field: "classCode" },
    QUALIFIED_AUTHORIZATION_HOLDER_URBROJ: { capability: "authorize", field: "urbroj" },
    QUALIFIED_AUTHORIZATION_HOLDER_E_BROJ: { capability: "authorize", field: "eBroj" },
    QUALIFIED_AUTHORIZATION_HOLDER_SUMMARY: { capability: "authorize", field: "summary" },
  };
  const mapping = sourceMap[normalizedSource];
  if (!mapping) {
    return "";
  }

  const user = getWorkOrderDocumentQualifiedUser(workOrder, mapping.capability, "elektro");
  if (!user) {
    return "";
  }

  const qualification = getUserElectricalQualification(user);
  if (mapping.field === "summary") {
    return getQualifiedUserSummaryValue(user, mapping.capability, "elektro");
  }
  if (mapping.field === "name") {
    return getUserDocumentDisplayName(user);
  }

  return String(qualification[mapping.field] || "").trim();
}

function getUserDocuments(user = {}) {
  return Array.isArray(user?.documents) ? user.documents : [];
}

function getUserSignatureScanDataUrl(user = {}) {
  const rootQualification = user?.electricalQualification ?? {};
  return String(
    user?.signatureDataUrl
    || user?.signatureStorageUrl
    || rootQualification.signatureDataUrl
    || rootQualification.signatureStorageUrl
    || rootQualification.storageUrl
    || "",
  ).trim();
}

function clearUserElectricalSignaturePad({ preserveValue = false } = {}) {
  if (!preserveValue && userElectricalSignatureDataUrlInput) {
    userElectricalSignatureDataUrlInput.value = "";
  }

  if (userElectricalSignatureFileInput) {
    userElectricalSignatureFileInput.value = "";
  }

  if (userElectricalSignaturePreview) {
    userElectricalSignaturePreview.replaceChildren();
    userElectricalSignaturePreview.classList.add("is-empty");
  }
}

function renderUserElectricalSignaturePad(signatureValue = "") {
  const safeValue = String(signatureValue || "").trim();

  if (userElectricalSignatureDataUrlInput) {
    userElectricalSignatureDataUrlInput.value = safeValue;
  }

  if (userElectricalSignatureFileInput) {
    userElectricalSignatureFileInput.value = "";
  }

  if (!userElectricalSignaturePreview) {
    return;
  }

  userElectricalSignaturePreview.replaceChildren();
  userElectricalSignaturePreview.classList.toggle("is-empty", !safeValue);

  if (!safeValue) {
    return;
  }

  const previewImage = document.createElement("img");
  previewImage.src = safeValue;
  previewImage.alt = "Potpis korisnika";
  previewImage.loading = "lazy";

  userElectricalSignaturePreview.append(previewImage);
}

async function queueUserElectricalSignatureFile(file) {
  if (!file) {
    return;
  }

  const dataUrl = await readFileAsDataUrl(file, `Ne mogu učitati datoteku ${file.name}.`);
  renderUserElectricalSignaturePad(dataUrl);
}

function setUserDocumentDrafts(items = []) {
  userDocumentDrafts = (Array.isArray(items) ? items : [])
    .map((item) => createModuleAttachmentDraft(item))
    .filter((item) => item.fileName && item.dataUrl);
}

function updateUserDocumentDraft(documentId, patch = {}) {
  userDocumentDrafts = userDocumentDrafts.map((item) => (
    item.id === documentId
      ? {
        ...item,
        ...patch,
      }
      : item
  ));
}

function focusUserDocumentCategory(documentId = "") {
  if (!documentId || !userDocumentsList) {
    return;
  }

  requestAnimationFrame(() => {
    const target = Array.from(
      userDocumentsList.querySelectorAll(".module-attachment-category-select"),
    ).find((input) => input.dataset.documentId === String(documentId));

    target?.focus({ preventScroll: false });
  });
}

function focusUserDocumentCustomCategory(documentId = "") {
  if (!documentId || !userDocumentsList) {
    return;
  }

  requestAnimationFrame(() => {
    const target = Array.from(
      userDocumentsList.querySelectorAll(".module-attachment-custom-category-input"),
    ).find((input) => input.dataset.documentId === String(documentId));

    target?.focus({ preventScroll: false });
  });
}

function finalizeUserDocumentCustomCategory(documentId = "", rawValue = "") {
  const nextValue = String(rawValue || "").trim();
  if (!documentId || !nextValue) {
    return false;
  }

  updateUserDocumentDraft(documentId, {
    documentCategory: nextValue,
    documentCategoryMode: "",
  });
  renderUserDocuments();
  focusUserDocumentCategory(documentId);
  return true;
}

function renderUserDocuments() {
  if (!userDocumentsList) {
    return;
  }

  if (userDocumentDrafts.length === 0) {
    const empty = document.createElement("div");
    empty.className = "module-attachment-empty";
    empty.setAttribute("aria-label", "Nema dokumenata za korisnika");
    userDocumentsList.replaceChildren(empty);
    return;
  }

  userDocumentsList.replaceChildren(...userDocumentDrafts.map((entry) => {
    const row = document.createElement("article");
    row.className = "module-attachment-row";
    row.classList.toggle("is-unclassified", !entry.documentCategory);

    const copy = document.createElement("div");
    copy.className = "module-attachment-copy";

    const meta = document.createElement("span");
    meta.className = "module-attachment-meta";
    meta.textContent = [
      entry.fileType || "",
      formatFileSize(entry.fileSize),
      entry.updatedAt ? formatCompactDate(entry.updatedAt) : "",
    ].filter(Boolean).join(" | ");

    const fieldWrap = document.createElement("div");
    fieldWrap.className = "module-attachment-fields";

    const nameField = document.createElement("label");
    nameField.className = "module-attachment-field";

    const nameLabel = document.createElement("span");
    nameLabel.className = "module-attachment-field-label";
    nameLabel.textContent = "Naziv";

    const nameInput = document.createElement("input");
    nameInput.type = "text";
    nameInput.value = entry.fileName;
    nameInput.maxLength = 220;
    nameInput.placeholder = "Naziv dokumenta";
    nameInput.addEventListener("input", () => {
      updateUserDocumentDraft(entry.id, { fileName: nameInput.value });
    });

    nameField.append(nameLabel, nameInput);

    const categoryField = document.createElement("label");
    categoryField.className = "module-attachment-field";

    const categoryLabel = document.createElement("span");
    categoryLabel.className = "module-attachment-field-label";
    categoryLabel.textContent = "Vrsta";

    const categorySelect = document.createElement("select");
    categorySelect.className = "module-attachment-category-select";
    categorySelect.dataset.documentId = entry.id;
    const categoryOptions = buildDraftCategoryOptions(
      USER_DOCUMENT_CATEGORY_OPTIONS,
      userDocumentDrafts,
      entry.documentCategory || "",
    );
    const usesCustomCategory = entry.documentCategoryMode === "custom";
    replaceSelectOptions(
      categorySelect,
      categoryOptions,
      entry.documentCategory || "",
    );
    categorySelect.addEventListener("change", () => {
      const nextValue = categorySelect.value || "";
      if (nextValue === "__custom__") {
        updateUserDocumentDraft(entry.id, {
          documentCategory: "",
          documentCategoryMode: "custom",
        });
        renderUserDocuments();
        focusUserDocumentCustomCategory(entry.id);
        return;
      }
      updateUserDocumentDraft(entry.id, {
        documentCategory: nextValue,
        documentCategoryMode: "",
      });
      row.classList.toggle("is-unclassified", !nextValue);
      if (usesCustomCategory) {
        renderUserDocuments();
      }
    });

    categoryField.append(categoryLabel, categorySelect);
    fieldWrap.append(nameField, categoryField);
    if (usesCustomCategory) {
      const customCategoryField = document.createElement("label");
      customCategoryField.className = "module-attachment-field is-custom-category";

      const customCategoryLabel = document.createElement("span");
      customCategoryLabel.className = "module-attachment-field-label";
      customCategoryLabel.textContent = "Nova vrsta";

      const customCategoryInput = document.createElement("input");
      customCategoryInput.type = "text";
      customCategoryInput.value = entry.documentCategory || "";
      customCategoryInput.maxLength = 64;
      customCategoryInput.placeholder = "Upiši vrstu dokumenta";
      customCategoryInput.className = "module-attachment-custom-category-input";
      customCategoryInput.dataset.documentId = entry.id;
      customCategoryInput.addEventListener("input", () => {
        const customValue = customCategoryInput.value;
        updateUserDocumentDraft(entry.id, {
          documentCategory: customValue,
          documentCategoryMode: "custom",
        });
        row.classList.toggle("is-unclassified", !String(customValue || "").trim());
      });
      customCategoryInput.addEventListener("blur", () => {
        finalizeUserDocumentCustomCategory(entry.id, customCategoryInput.value);
      });
      customCategoryInput.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          finalizeUserDocumentCustomCategory(entry.id, customCategoryInput.value);
          return;
        }

        if (event.key === "Escape") {
          event.preventDefault();
          updateUserDocumentDraft(entry.id, {
            documentCategory: "",
            documentCategoryMode: "",
          });
          renderUserDocuments();
          focusUserDocumentCategory(entry.id);
        }
      });

      customCategoryField.append(customCategoryLabel, customCategoryInput);
      fieldWrap.append(customCategoryField);
    }

    copy.append(meta, fieldWrap);

    const actions = document.createElement("div");
    actions.className = "module-attachment-actions";

    const openButton = createActionButton("Preuzmi", "card-button", () => {
      triggerModuleAttachmentDownload({
        ...entry,
        fileName: nameInput.value || entry.fileName,
      });
    });
    const removeButton = createActionButton("Makni", "card-button card-danger", () => {
      userDocumentDrafts = userDocumentDrafts.filter((item) => item.id !== entry.id);
      renderUserDocuments();
    });

    actions.append(openButton, removeButton);
    row.append(copy, actions);
    return row;
  }));
}

