function renderClientPortalPreview() {
  const companyId = getClientPortalSelectedCompanyId();
  const company = getCompany(companyId);
  const selectedLocationIds = getClientPortalSelectedLocationIdsForPreview();
  const allLocations = Boolean(clientPortalAllLocationsInput?.checked);
  const companyLocations = companyId ? getCompanyLocations(companyId) : [];
  ensureClientPortalDocumentRecordsLoaded(companyId);
  const selectedLocationNames = selectedLocationIds
    .map((locationId) => getLocation(locationId)?.name || "")
    .filter(Boolean);
  const scopeLabel = allLocations
    ? "Sve lokacije"
    : (selectedLocationNames.length > 0 ? `${selectedLocationNames.length} odabrane lokacije` : "Odaberi lokacije");

  if (clientPortalPreviewScope) {
    clientPortalPreviewScope.textContent = scopeLabel;
  }
  if (clientPortalPreviewCompany) {
    clientPortalPreviewCompany.textContent = company?.name || "Odaberi tvrtku";
  }
  if (clientPortalPreviewLocation) {
    clientPortalPreviewLocation.textContent = allLocations
      ? (companyLocations.length > 0 ? `Sve lokacije tvrtke (${companyLocations.length})` : "Sve sadašnje i buduće lokacije")
      : (selectedLocationNames.join(", ") || "Odaberi jednu ili više lokacija");
  }

  if (!clientPortalPreviewList) {
    return;
  }

  const scopedWorkOrders = sortWorkOrders(filterClientPortalRecordsByScope(state.workOrders, companyId, selectedLocationIds));
  const scopedDocumentRecords = getClientPortalDocumentRecordPreviews(companyId, selectedLocationIds);
  const scopedTrainingRecords = sortPersonTrainingRecords(filterClientPortalRecordsByScope(
    state.peopleTrainingRecords,
    companyId,
    selectedLocationIds,
  ));
  const scopedRiskAssessments = sortRiskAssessments(filterClientPortalRecordsByScope(
    state.riskAssessments,
    companyId,
    selectedLocationIds,
  ));

  const workOrderRows = scopedWorkOrders.map(createClientPortalWorkOrderPreviewRow);
  const documentRows = scopedDocumentRecords.map(createClientPortalDocumentPreviewRow);
  const trainingRows = scopedTrainingRecords.map(createClientPortalTrainingPreviewRow);
  const riskAssessmentRows = scopedRiskAssessments.map(createClientPortalRiskAssessmentPreviewRow);
  const documentsLoading = Boolean(companyId && state.documentsExplorer.loading);
  const recordsCopy = documentsLoading
    ? "Ucitavam spremljene zapisnike za odabrani opseg."
    : "Spremljeni zapisnici koje klijent vidi u Documents.";

  const workOrdersSection = createClientPortalPreviewSection({
    key: "workOrders",
    title: "Radni nalozi",
    subtitle: "Klijent vidi RN pregled prema odabranoj tvrtki i lokacijama.",
    rows: workOrderRows,
    emptyMessage: companyId ? "Nema radnih naloga za odabranu tvrtku i lokacije." : "Odaberi tvrtku za preview radnih naloga.",
  });
  const documentsSection = createClientPortalPreviewSection({
    key: "documents",
    title: "Zapisnici",
    subtitle: recordsCopy,
    rows: documentRows,
    emptyMessage: documentsLoading ? "Ucitavanje zapisnika..." : "Nema spremljenih zapisnika za odabrani opseg.",
  });
  const trainingsSection = createClientPortalPreviewSection({
    key: "trainings",
    title: "Osposobljavanja i pregledi",
    subtitle: "Klijent vidi važenja za svoje ljude: ZNR, požar, ADR, liječnički i stručna osposobljavanja.",
    rows: trainingRows,
    emptyMessage: companyId ? "Nema evidentiranih osposobljavanja za odabrani opseg." : "Odaberi tvrtku za preview osposobljavanja.",
  });
  const riskAssessmentSection = createClientPortalPreviewSection({
    key: "riskAssessments",
    title: "Procjene rizika",
    subtitle: "Klijent vidi procjene rizika i može vratiti napomenu kroz isti zapis.",
    rows: riskAssessmentRows,
    emptyMessage: companyId ? "Nema procjena rizika za odabrani opseg." : "Odaberi tvrtku za preview procjena rizika.",
  });

  clientPortalPreviewList.replaceChildren(workOrdersSection, documentsSection, trainingsSection, riskAssessmentSection);
}

function renderClientPortalModule() {
  if (!clientPortalModule) {
    return;
  }

  if (!getCanManageClientPortal()) {
    if (clientPortalOpenAccessButton) {
      clientPortalOpenAccessButton.hidden = true;
      clientPortalOpenAccessButton.disabled = true;
    }
    if (clientPortalCreateUserButton) {
      clientPortalCreateUserButton.disabled = true;
    }
    if (clientPortalOpenCompanyButton) {
      clientPortalOpenCompanyButton.disabled = true;
    }
    clientPortalUsersList?.replaceChildren();
    if (clientPortalUsersEmpty) {
      clientPortalUsersEmpty.hidden = false;
      clientPortalUsersEmpty.textContent = "Nemas ovlastenje za klijentski portal.";
    }
    [clientPortalTotalUsers, clientPortalCompanyCount, clientPortalLocationScopedCount, clientPortalAllLocationsCount, clientPortalSelectedUsersCount]
      .forEach((element) => {
        if (element) {
          element.textContent = "0";
        }
      });
    closeClientPortalAccessModal();
    return;
  }

  if (clientPortalOpenAccessButton) {
    clientPortalOpenAccessButton.hidden = false;
  }

  const companyId = rebuildClientPortalCompanyOptions();
  rebuildClientPortalLocationOptions(getSelectedMultiSelectValues(clientPortalLocationIdsInput));

  const clientUsers = getClientPortalUsers();
  const companyIdsWithAccess = new Set(clientUsers.flatMap((user) => normalizeClientScopeIdsClient(user.clientCompanyIds)));
  const allLocationUsers = clientUsers.filter((user) => user.clientAccessAllLocations !== false);
  const locationScopedUsers = clientUsers.filter((user) => user.clientAccessAllLocations === false);

  if (clientPortalTotalUsers) {
    clientPortalTotalUsers.textContent = String(clientUsers.length);
  }
  if (clientPortalCompanyCount) {
    clientPortalCompanyCount.textContent = String(companyIdsWithAccess.size);
  }
  if (clientPortalLocationScopedCount) {
    clientPortalLocationScopedCount.textContent = String(locationScopedUsers.length);
  }
  if (clientPortalAllLocationsCount) {
    clientPortalAllLocationsCount.textContent = String(allLocationUsers.length);
  }

  const queryNeedle = normalizeLooseName(clientPortalSearchInput?.value || "");
  const visibleUsers = getClientPortalUsers(companyId).filter((user) => (
    !queryNeedle || getClientPortalUserSearchText(user).includes(queryNeedle)
  ));

  if (clientPortalSelectedUsersCount) {
    clientPortalSelectedUsersCount.textContent = String(visibleUsers.length);
  }
  if (clientPortalUsersEmpty) {
    clientPortalUsersEmpty.hidden = visibleUsers.length > 0;
    clientPortalUsersEmpty.textContent = companyId
      ? "Nema klijentskih pristupa za odabranu tvrtku."
      : "Odaberi tvrtku za pregled pristupa.";
  }
  if (clientPortalUsersList) {
    clientPortalUsersList.replaceChildren(...visibleUsers.map(createClientPortalUserCard));
  }

  if (clientPortalCreateUserButton) {
    clientPortalCreateUserButton.disabled = !companyId || !getCanEditCompany(companyId);
  }
  if (clientPortalOpenAccessButton) {
    clientPortalOpenAccessButton.disabled = !companyId || !getCanEditCompany(companyId);
  }
  if (clientPortalOpenCompanyButton) {
    clientPortalOpenCompanyButton.disabled = !companyId || !getCompany(companyId);
  }

  syncClientPortalAccessModal();
  renderClientPortalPreview();
}

function getCompanyTemplateAssignmentServices() {
  const serviceRows = sortServiceCatalogItems(state.serviceCatalog ?? []).map((service) => ({
    key: `service:${String(service.id || service.serviceCode || service.name || "").trim()}`,
    kind: "service",
    serviceId: String(service.id || ""),
    serviceCode: String(service.serviceCode || "").trim(),
    serviceName: String(service.name || service.serviceCode || "Usluga").trim(),
    label: [service.serviceCode, service.name].filter(Boolean).join(" · ") || "Usluga",
  })).filter((entry) => entry.key !== "service:");
  return [
    ...serviceRows,
    {
      key: "kind:is_znr",
      kind: "is_znr",
      serviceId: "",
      serviceCode: "IS ZNR",
      serviceName: "IS ZNR",
      label: "IS ZNR",
    },
  ];
}

function getCompanyTemplateAssignmentTemplateOptions() {
  return sortDocumentTemplates(state.documentTemplates ?? []).filter((template) => {
    const document = template.referenceDocument ?? {};
    return isDocumentTemplateHtmlReferenceDocument(document) || isDocumentTemplateWordReferenceDocument(document);
  }).map((template) => {
    const documentName = template.referenceDocument?.fileName || "";
    return {
      value: String(template.id || ""),
      label: [
        template.title || template.documentType || "Template",
        documentName ? `(${documentName})` : "",
      ].filter(Boolean).join(" "),
      template,
    };
  }).filter((option) => option.value);
}

function findCompanyTemplateAssignment(assignments = [], serviceRow = {}) {
  const normalized = Array.isArray(assignments) ? assignments : [];
  if (serviceRow.kind === "is_znr") {
    return normalized.find((entry) => String(entry?.kind || "") === "is_znr") ?? null;
  }
  return normalized.find((entry) => (
    (serviceRow.serviceId && String(entry?.serviceId || "") === serviceRow.serviceId)
    || (serviceRow.serviceCode && normalizeLooseName(entry?.serviceCode || "") === normalizeLooseName(serviceRow.serviceCode))
    || (serviceRow.serviceName && normalizeLooseName(entry?.serviceName || "") === normalizeLooseName(serviceRow.serviceName))
  )) ?? null;
}

function renderCompanyTemplateAssignments(assignments = []) {
  if (!companyTemplateMapList) {
    return;
  }

  const services = getCompanyTemplateAssignmentServices();
  const templateOptions = getCompanyTemplateAssignmentTemplateOptions();

  if (services.length === 0) {
    const empty = document.createElement("p");
    empty.className = "helper-copy module-copy";
    empty.textContent = "Nema usluga u List of Services.";
    companyTemplateMapList.replaceChildren(empty);
    return;
  }

  const rows = services.map((serviceRow) => {
    const assignment = findCompanyTemplateAssignment(assignments, serviceRow);
    const row = document.createElement("div");
    row.className = "company-template-map-row";
    row.dataset.companyTemplateServiceKind = serviceRow.kind;
    row.dataset.companyTemplateServiceId = serviceRow.serviceId;
    row.dataset.companyTemplateServiceCode = serviceRow.serviceCode;
    row.dataset.companyTemplateServiceName = serviceRow.serviceName;

    const service = document.createElement("div");
    service.className = "company-template-map-service";
    const code = document.createElement("strong");
    code.textContent = serviceRow.serviceCode || "Usluga";
    const name = document.createElement("span");
    name.textContent = serviceRow.serviceName || serviceRow.label;
    service.append(code, name);

    const field = document.createElement("label");
    field.className = "field company-template-map-select-field";
    const label = document.createElement("span");
    label.textContent = "Word dokument";
    const select = document.createElement("select");
    select.dataset.companyTemplateSelect = "true";
    replaceSelectOptions(
      select,
      [
        { value: "", label: templateOptions.length ? "Koristi opći template za ovu uslugu" : "Nema spremljenih templatea" },
        ...templateOptions.map((option) => ({ value: option.value, label: option.label })),
      ],
      assignment?.templateId || "",
    );
    field.append(label, select);
    row.append(service, field);
    return row;
  });

  companyTemplateMapList.replaceChildren(...rows);
}

function collectCompanyTemplateAssignments() {
  if (!companyTemplateMapList) {
    return [];
  }

  const templatesById = new Map(getCompanyTemplateAssignmentTemplateOptions().map((option) => [option.value, option]));
  return Array.from(companyTemplateMapList.querySelectorAll(".company-template-map-row"))
    .map((row) => {
      const select = row.querySelector("[data-company-template-select]");
      const templateId = String(select?.value || "").trim();
      if (!templateId) {
        return null;
      }
      const template = templatesById.get(templateId)?.template ?? null;
      return {
        kind: row.dataset.companyTemplateServiceKind === "is_znr" ? "is_znr" : "service",
        serviceId: row.dataset.companyTemplateServiceId || "",
        serviceCode: row.dataset.companyTemplateServiceCode || "",
        serviceName: row.dataset.companyTemplateServiceName || "",
        templateId,
        templateTitle: template?.title || template?.documentType || "",
      };
    })
    .filter(Boolean);
}

