    organizationEditorStatusPill.textContent = isActive ? "Aktivna" : "Neaktivna";
    organizationEditorStatusPill.classList.toggle("is-active", isActive);
    organizationEditorStatusPill.classList.toggle("is-inactive", !isActive);
