async function handleLoginSubmit(event) {
  event.preventDefault();

  const email = String(loginEmailInput?.value ?? "").trim();
  const password = String(loginPasswordInput?.value ?? "");

  setInlineMessage(loginError, "");

  if (!email || !password) {
    setInlineMessage(loginError, "Unesi email i lozinku.");
    return;
  }

  setLoginBusy(true);

  try {
    await withGlobalLoading("Otvaram SafeNexus...", async () => {
      await apiRequest("/auth/login", {
        method: "POST",
        body: {
          email,
          password,
        },
      });

      const user = await refreshSession();
      if (!user) {
        const sessionError = new Error("Prijava je uspjela, ali sesija nije spremljena. Omoguci cookies za safe-nexus.org i pokusaj ponovno.");
        sessionError.code = "SESSION_NOT_PERSISTED";
        throw sessionError;
      }

      sessionLastActivityAtMs = Date.now();
      if (user.mustChangePassword) {
        state.authView = "password-reset";
        state.authResetEmail = user.email || email;
        if (loginPasswordInput) {
          loginPasswordInput.value = "";
        }
        renderAuthState();
        return;
      }

      document.body.classList.add("is-auth-leaving");
      await refreshSnapshot();
      loginForm?.reset();
      state.authResetEmail = "";
    }, { immediate: true });
  } catch (error) {
    if (error?.code === "SESSION_NOT_PERSISTED") {
      setInlineMessage(loginError, error.message);
    } else if (error?.statusCode === 401) {
      setInlineMessage(loginError, "Neispravan email ili lozinka.");
    } else {
      setInlineMessage(loginError, error?.message || "Prijava trenutno nije uspjela. Pokusaj ponovno.");
    }
    document.body.classList.remove("is-auth-leaving");
    renderAuthState();
  } finally {
    setLoginBusy(false);
  }
}

function getRiskAssessmentStatusOption(status = "") {
  const normalized = String(status || "").trim().toLowerCase();
  return RISK_ASSESSMENT_STATUS_OPTIONS.find((option) => option.value === normalized)
    ?? RISK_ASSESSMENT_STATUS_OPTIONS[0];
}

function buildRiskAssessmentCompanyOptions(includeAll = false) {
  const companyOptions = [...(state.companies ?? [])]
    .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr", { sensitivity: "base" }))
    .map((company) => ({
      value: String(company.id),
      label: company.name || `Tvrtka ${company.id}`,
    }));

  return includeAll
    ? [{ value: "all", label: "Sve tvrtke" }, ...companyOptions]
    : [{ value: "", label: "Odaberi tvrtku" }, ...companyOptions];
}

function buildRiskAssessmentLocationOptions(companyId = "") {
  const options = (state.locations ?? [])
    .filter((location) => String(location.companyId) === String(companyId))
    .sort((left, right) => String(left.name || "").localeCompare(String(right.name || ""), "hr", { sensitivity: "base" }))
    .map((location) => ({
      value: String(location.id),
      label: location.name || `Lokacija ${location.id}`,
    }));

  return [{ value: "", label: "Sve lokacije / nije vezano" }, ...options];
}

function getRiskAssessmentEditorBlocks() {
  return Array.from(riskAssessmentForm?.querySelectorAll("[data-risk-assessment-block]") ?? []);
}

function setRiskAssessmentDockActive(blockKey = "basic") {
  const buttons = Array.from(riskAssessmentDock?.querySelectorAll("[data-risk-assessment-jump]") ?? []);
  buttons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.riskAssessmentJump === blockKey);
  });
}

function setRiskAssessmentActiveBlock(blockKey = "basic", { resetScroll = false } = {}) {
  const blocks = getRiskAssessmentEditorBlocks();
  if (!blocks.length) {
    setRiskAssessmentDockActive("basic");
    return;
  }
  const knownKeys = new Set(blocks.map((block) => block.dataset.riskAssessmentBlock).filter(Boolean));
  const activeKey = knownKeys.has(blockKey) ? blockKey : "basic";
  riskAssessmentActiveBlock = activeKey;
  blocks.forEach((block) => {
    const isActive = block.dataset.riskAssessmentBlock === activeKey;
    block.hidden = !isActive;
    block.classList.toggle("is-active", isActive);
  });
  setRiskAssessmentDockActive(activeKey);
  if (resetScroll && riskAssessmentEditorBody) {
    riskAssessmentEditorBody.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function getRiskAssessmentRichEditor(key = "") {
  if (key === "intro") {
    return riskAssessmentIntroEditor;
  }
  if (key === "process") {
    return riskAssessmentWorkProcessEditor;
  }
  return riskAssessmentForm?.querySelector(`[data-risk-rich-editor="${String(key).replace(/["\\]/g, "\\$&")}"]`) ?? null;
}

function getRiskAssessmentRichInput(key = "") {
  if (key === "intro") {
    return riskAssessmentIntroInput;
  }
  if (key === "process") {
    return riskAssessmentWorkProcessInput;
  }
  return null;
}

function looksLikeRiskAssessmentRichHtml(value = "") {
  return /<\/?(p|div|br|ul|ol|li|strong|b|em|i|u|h[1-6]|img)\b/i.test(String(value || ""));
}

function sanitizeRiskAssessmentImageSrc(value = "") {
  const src = String(value || "").trim();
  if (/^data:image\/(?:png|jpe?g|gif|webp|svg\+xml);base64,/i.test(src)) {
    return src;
  }
  if (/^https?:\/\//i.test(src)) {
    return src;
  }
  return "";
}

function normalizeRiskAssessmentRichHtml(value = "") {
  const raw = String(value || "").trim();
  if (!raw) {
    return "";
  }
  const source = looksLikeRiskAssessmentRichHtml(raw)
    ? raw
    : raw
      .split(/\r?\n/)
      .map((line) => line.trim() ? `<p>${escapeHtml(line)}</p>` : "<p><br></p>")
      .join("");
  const parser = new DOMParser();
  const documentFragment = parser.parseFromString(`<div>${source}</div>`, "text/html").body.firstElementChild;
  const allowedTags = new Set(["P", "DIV", "BR", "UL", "OL", "LI", "STRONG", "B", "EM", "I", "U", "H3", "H4", "IMG"]);

  const sanitizeNode = (node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      return document.createTextNode(node.textContent || "");
    }
    if (node.nodeType !== Node.ELEMENT_NODE) {
      return document.createDocumentFragment();
    }

    const tagName = node.tagName.toUpperCase();
    if (!allowedTags.has(tagName)) {
      const fragment = document.createDocumentFragment();
      Array.from(node.childNodes).forEach((childNode) => {
        fragment.appendChild(sanitizeNode(childNode));
      });
      return fragment;
    }

    if (tagName === "IMG") {
      const src = sanitizeRiskAssessmentImageSrc(node.getAttribute("src") || "");
      if (!src) {
        return document.createDocumentFragment();
      }
      const image = document.createElement("img");
      image.src = src;
      image.alt = String(node.getAttribute("alt") || "Slika procjene rizika").slice(0, 160);
      image.loading = "lazy";
      return image;
    }

    const nextNode = document.createElement(tagName.toLowerCase());
    Array.from(node.childNodes).forEach((childNode) => {
      nextNode.appendChild(sanitizeNode(childNode));
    });
    return nextNode;
  };

  const cleanRoot = document.createElement("div");
  Array.from(documentFragment?.childNodes ?? []).forEach((childNode) => {
    cleanRoot.appendChild(sanitizeNode(childNode));
  });
  return cleanRoot.innerHTML.trim();
}

function setRiskAssessmentRichValue(key = "", value = "") {
  const editor = getRiskAssessmentRichEditor(key);
  const input = getRiskAssessmentRichInput(key);
  const html = normalizeRiskAssessmentRichHtml(value);
  if (input) {
    input.value = html;
  }
  if (editor) {
    editor.innerHTML = html;
  }
}

function syncRiskAssessmentRichValue(key = "") {
  const editor = getRiskAssessmentRichEditor(key);
  const input = getRiskAssessmentRichInput(key);
  if (!editor || !input) {
    return "";
  }
  const html = normalizeRiskAssessmentRichHtml(editor.innerHTML);
  input.value = html;
  return html;
}

function syncRiskAssessmentRichValues() {
  syncRiskAssessmentRichValue("intro");
  syncRiskAssessmentRichValue("process");
}

function rememberRiskAssessmentRichEditorSelection(editor = null) {
  if (!(editor instanceof HTMLElement)) {
    return;
  }
  const key = editor.dataset.riskRichEditor || "";
  const selection = window.getSelection?.();
  if (!key || !selection || selection.rangeCount === 0 || !editor.contains(selection.anchorNode)) {
    return;
  }
  riskAssessmentActiveRichEditorKey = key;
  riskAssessmentRichEditorSelection = selection.getRangeAt(0).cloneRange();
}

function restoreRiskAssessmentRichEditorSelection(key = "") {
  const editor = getRiskAssessmentRichEditor(key || riskAssessmentActiveRichEditorKey);
  if (!editor) {
    return null;
  }
  editor.focus({ preventScroll: true });
  if (riskAssessmentRichEditorSelection && editor.contains(riskAssessmentRichEditorSelection.commonAncestorContainer)) {
    const selection = window.getSelection?.();
    selection?.removeAllRanges();
    selection?.addRange(riskAssessmentRichEditorSelection);
  }
  return editor;
}

function insertRiskAssessmentRichHtml(key = "", html = "") {
  const editor = restoreRiskAssessmentRichEditorSelection(key);
  if (!editor || !html) {
    return;
  }
  document.execCommand("insertHTML", false, html);
  rememberRiskAssessmentRichEditorSelection(editor);
  syncRiskAssessmentRichValue(editor.dataset.riskRichEditor || key);
}

function handleRiskAssessmentRichEditorInput(event) {
  const editor = event.target?.closest?.("[data-risk-rich-editor]");
  if (!editor) {
    return;
  }
  rememberRiskAssessmentRichEditorSelection(editor);
  syncRiskAssessmentRichValue(editor.dataset.riskRichEditor || "");
}

function handleRiskAssessmentRichEditorSelectionChange(event) {
  const editor = event.target?.closest?.("[data-risk-rich-editor]");
  if (editor) {
    rememberRiskAssessmentRichEditorSelection(editor);
  }
}

function handleRiskAssessmentRichEditorClick(event) {
  const commandButton = event.target?.closest?.("[data-risk-rich-command]");
  if (commandButton) {
    event.preventDefault();
    const toolbar = commandButton.closest("[data-risk-rich-toolbar]");
    const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
    const editor = restoreRiskAssessmentRichEditorSelection(key);
    if (!editor) {
      return;
    }
    const command = commandButton.dataset.riskRichCommand || "";
    const value = commandButton.dataset.riskRichValue || null;
    document.execCommand(command, false, value);
    rememberRiskAssessmentRichEditorSelection(editor);
    syncRiskAssessmentRichValue(key);
    return;
  }

  const imageButton = event.target?.closest?.("[data-risk-rich-image]");
  if (!imageButton) {
    return;
  }
  event.preventDefault();
  const toolbar = imageButton.closest("[data-risk-rich-toolbar]");
  const key = toolbar?.dataset.riskRichToolbar || riskAssessmentActiveRichEditorKey || "intro";
  restoreRiskAssessmentRichEditorSelection(key);
  if (imageButton.dataset.riskRichImage === "file") {
    toolbar?.querySelector(`[data-risk-rich-file="${key}"]`)?.click();
    return;
  }
  const src = sanitizeRiskAssessmentImageSrc(window.prompt("URL slike za umetanje u tekst") || "");
  if (src) {
    insertRiskAssessmentRichHtml(key, `<img src="${escapeHtml(src)}" alt="Slika procjene rizika">`);
  }
}

async function handleRiskAssessmentRichEditorFileChange(event) {
  const input = event.target?.closest?.("[data-risk-rich-file]");
  if (!input || !(input instanceof HTMLInputElement)) {
    return;
  }
  const key = input.dataset.riskRichFile || riskAssessmentActiveRichEditorKey || "intro";
  const file = input.files?.[0];
  input.value = "";
  if (!file) {
    return;
  }
  if (!String(file.type || "").startsWith("image/")) {
    if (riskAssessmentError) {
      riskAssessmentError.textContent = "Možeš umetnuti samo sliku.";
    }
    return;
  }
  try {
    const dataUrl = await readFileAsDataUrl(file, `Ne mogu učitati sliku ${file.name}.`);
    insertRiskAssessmentRichHtml(key, `<img src="${escapeHtml(dataUrl)}" alt="${escapeHtml(file.name || "Slika procjene rizika")}">`);
  } catch (error) {
    if (riskAssessmentError) {
      riskAssessmentError.textContent = error?.message || "Ne mogu učitati sliku.";
    }
  }
}

function setRiskAssessmentEditorOpen(open) {
  state.riskAssessmentEditorOpen = Boolean(open);
  document.body.classList.toggle("is-offer-editor-open", Boolean(open));
  if (riskAssessmentEditorBackdrop) {
    riskAssessmentEditorBackdrop.hidden = !open;
  }
  if (riskAssessmentEditorPanel) {
    riskAssessmentEditorPanel.hidden = !open;
    riskAssessmentEditorPanel.classList.toggle("is-modal-open", Boolean(open));
  }
  if (open) {
    ensureRiskAssessmentModuleInModuleView();
    requestAnimationFrame(() => {
      if (riskAssessmentEditorBody) {
        riskAssessmentEditorBody.scrollTop = 0;
      }
      riskAssessmentEditorBody?.focus({ preventScroll: true });
      setRiskAssessmentActiveBlock(riskAssessmentActiveBlock || "basic");
    });
  }
}

function resetRiskAssessmentForm() {
  if (!riskAssessmentForm) {
    return;
  }

  riskAssessmentForm.reset();
  state.activeRiskAssessmentId = "";
  riskAssessmentMeasureDrafts = [];
  riskAssessmentOrganizationUnitDrafts = [];
  riskAssessmentJobDrafts = [];
  riskAssessmentRiskTemplateDrafts = [];
  replaceSelectOptions(riskAssessmentCompanyInput, buildRiskAssessmentCompanyOptions(false), "");
  replaceSelectOptions(riskAssessmentLocationInput, buildRiskAssessmentLocationOptions(""), "");
  replaceSelectOptions(riskAssessmentStatusInput, RISK_ASSESSMENT_STATUS_OPTIONS, "draft");
  if (riskAssessmentDateInput) {
    riskAssessmentDateInput.value = new Date().toISOString().slice(0, 10);
  }
  if (riskAssessmentNumberInput) {
    riskAssessmentNumberInput.value = "";
  }
  if (riskAssessmentEditorTitle) {
    riskAssessmentEditorTitle.textContent = "Nova procjena";
  }
  if (riskAssessmentError) {
    riskAssessmentError.textContent = "";
  }
  if (riskAssessmentDeleteButton) {
    riskAssessmentDeleteButton.hidden = true;
  }
  setRiskAssessmentRichValue("intro", "");
  setRiskAssessmentRichValue("process", "");
  renderRiskAssessmentMeasures();
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  setRiskAssessmentActiveBlock("basic");
  syncRiskAssessmentEditorAccess();
}

function hydrateRiskAssessmentForm(item = {}) {
  if (!riskAssessmentForm) {
    return;
  }

  state.activeRiskAssessmentId = String(item.id || "");
  replaceSelectOptions(riskAssessmentCompanyInput, buildRiskAssessmentCompanyOptions(false), item.companyId || "");
  replaceSelectOptions(riskAssessmentLocationInput, buildRiskAssessmentLocationOptions(item.companyId || ""), item.locationId || "");
  replaceSelectOptions(riskAssessmentStatusInput, RISK_ASSESSMENT_STATUS_OPTIONS, item.status || "draft");
  riskAssessmentIdInput.value = item.id || "";
  riskAssessmentNumberInput.value = item.assessmentNumber || "";
  riskAssessmentTitleInput.value = item.title || "";
  riskAssessmentDateInput.value = item.assessmentDate || "";
  riskAssessmentRevisionDateInput.value = item.revisionDate || "";
  riskAssessmentTeamLeadInput.value = item.teamLead || "";
  riskAssessmentCollaboratorsInput.value = item.collaborators || "";
  setRiskAssessmentRichValue("intro", item.intro || "");
  setRiskAssessmentRichValue("process", item.workProcessDescription || "");
  riskAssessmentGeneralDataInput.value = item.generalData || "";
  riskAssessmentComputerWorkplacesInput.value = item.computerWorkplaces || "";
  riskAssessmentBasicRulesInput.value = item.basicRules || "";
  riskAssessmentSpecialRulesInput.value = item.specialRules || "";
  riskAssessmentOmissionsBasicInput.value = item.omissionsBasic || "";
  riskAssessmentOmissionsSpecialInput.value = item.omissionsSpecial || "";
  riskAssessmentConclusionInput.value = item.conclusion || "";
  riskAssessmentClientNoteInput.value = item.clientNote || "";
  riskAssessmentMeasureDrafts = (item.measures ?? []).map((entry) => ({ ...entry }));
  riskAssessmentOrganizationUnitDrafts = (item.organizationUnits ?? []).map((entry) => createRiskAssessmentOrganizationUnitDraft(entry));
  riskAssessmentJobDrafts = (item.jobs ?? []).map((entry) => createRiskAssessmentJobDraft(entry));
  riskAssessmentRiskTemplateDrafts = (item.riskTemplates ?? []).map((entry) => ({
    ...entry,
    riskRows: (entry.riskRows ?? []).map((risk) => createRiskAssessmentRiskRowDraft(risk)),
    ppeItems: (entry.ppeItems ?? []).map((ppe) => createRiskAssessmentPpeDraft(ppe)),
  }));
  if (riskAssessmentEditorTitle) {
    riskAssessmentEditorTitle.textContent = item.title || "Procjena rizika";
  }
  if (riskAssessmentDeleteButton) {
    riskAssessmentDeleteButton.hidden = false;
  }
  renderRiskAssessmentMeasures();
  renderRiskAssessmentOrganizationUnits();
  renderRiskAssessmentJobs();
  renderRiskAssessmentOverview();
  setRiskAssessmentActiveBlock("basic");
  setRiskAssessmentEditorOpen(true);
  syncRiskAssessmentEditorAccess();
}

function createRiskAssessmentMeasureDraft() {
  return {
    id: crypto.randomUUID(),
    measure: "",
    deadline: "",
    responsiblePerson: "",
    controlMethod: "",
    status: "open",
  };
}

