function runLogoutFlow(message = "") {
  if (logoutInProgress) {
    return;
  }

  logoutInProgress = true;
  void apiRequest("/auth/logout", {
    method: "POST",
  })
    .catch(() => {})
    .finally(() => {
      resetAuthenticatedWorkspaceState();
      if (message) {
        setInlineMessage(loginError, message);
      }
      logoutInProgress = false;
    });
}

